-- Quizora quiz library seed: 109 live quizzes, 1469 questions (truefalse, choice, multi, text, number, order).
-- Idempotent: upserts games by slug and questions by (game_slug, item). Each line is one self-contained statement guarded by an md5 check; run the whole file or line by line in the Supabase SQL editor.
do $q$ declare d text := $d$[{"slug":"capital-clash","title":"Capital Clash","tagline":"Canberra or Sydney? Ottawa or Toronto? Pick the real capitals.","emoji":"\ud83c\udfdb\ufe0f","gradient":["#0ea5e9","#4f46e5"],"categories":["capitals","geo","travel"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":200,"items":[{"k":"choice","i":"What is the capital of Australia?","t":"Oceania","e":"\ud83e\udd98","f":"Canberra was purpose-built as the capital, a compromise between rivals Sydney and Melbourne.","o":["Sydney","Melbourne","Canberra","Perth"],"s":{"index":2}},{"k":"choice","i":"What is the capital of Canada?","t":"North America","e":"\ud83c\udf41","f":"Queen Victoria chose Ottawa as the capital of the Province of Canada in 1857.","o":["Ottawa","Toronto","Montreal","Vancouver"],"s":{"index":0}},{"k":"choice","i":"What is the capital of Brazil?","t":"South America","e":"\ud83c\udde7\ud83c\uddf7","f":"Bras\u00edlia was built from scratch in the interior and inaugurated as the capital in 1960.","o":["Rio de Janeiro","S\u00e3o Paulo","Salvador","Bras\u00edlia"],"s":{"index":3}},{"k":"choice","i":"What is the capital of Turkey?","t":"Europe & Asia","e":"\ud83c\uddf9\ud83c\uddf7","f":"Ankara became Turkey's capital in 1923, taking over from Istanbul.","o":["Istanbul","Ankara","Izmir","Antalya"],"s":{"index":1}},{"k":"choice","i":"What is the capital of Japan?","t":"Asia","e":"\ud83d\uddfe","f":"Kyoto served as Japan's imperial capital for over a thousand years before Tokyo took the role.","o":["Osaka","Kyoto","Tokyo","Yokohama"],"s":{"index":2}},{"k":"choice","i":"What is the capital of Switzerland?","t":"Europe","e":"\ud83c\udde8\ud83c\udded","f":"Officially Bern is the Swiss 'federal city', as the constitution names no capital.","o":["Zurich","Geneva","Basel","Bern"],"s":{"index":3}},{"k":"choice","i":"What is the capital of Morocco?","t":"Africa","e":"\ud83c\uddf2\ud83c\udde6","f":"Rabat is the capital, while Casablanca is Morocco's largest city.","o":["Rabat","Casablanca","Marrakesh","Fez"],"s":{"index":0}},{"k":"choice","i":"What is the capital of New Zealand?","t":"Oceania","e":"\ud83e\udd5d","f":"Wellington is the southernmost capital city of any sovereign state.","o":["Auckland","Wellington","Christchurch","Queenstown"],"s":{"index":1}},{"k":"choice","i":"What is the capital of Nigeria?","t":"Africa","e":"\ud83c\uddf3\ud83c\uddec","f":"Abuja officially replaced Lagos as Nigeria's capital in 1991.","o":["Lagos","Kano","Abuja","Ibadan"],"s":{"index":2}},{"k":"text","i":"What is the capital of Italy?","t":"Europe","e":"\ud83c\uddee\ud83c\uddf9","f":"Rome completely surrounds Vatican City, the smallest country in the world.","s":{"accepted":["Rome","Roma"]}},{"k":"text","i":"What is the capital of Norway?","t":"Europe","e":"\ud83c\uddf3\ud83c\uddf4","f":"The Nobel Peace Prize is awarded in Oslo; the other Nobel Prizes are presented in Stockholm.","s":{"accepted":["Oslo"]}},{"k":"text","i":"What is the capital of Hungary?","t":"Europe","e":"\ud83c\udded\ud83c\uddfa","f":"Budapest was created in 1873 by uniting the cities of Buda, \u00d3buda and Pest.","s":{"accepted":["Budapest"]}},{"k":"multi","i":"Select all the capitals in South America.","t":"South America","e":"\ud83c\udf0e","f":"Quito sits about 2,850 m above sea level, making it one of the highest capitals in the world.","o":["Lima","Bogot\u00e1","Nairobi","Quito","Manila"],"s":{"indices":[0,1,3]}},{"k":"multi","i":"Select all the European capitals.","t":"Europe","e":"\ud83c\udff0","f":"Helsinki became Finland's capital in 1812, replacing the older city of Turku.","o":["Vienna","Barcelona","Helsinki","Milan","Dublin"],"s":{"indices":[0,2,4]}}]},{"slug":"german-engineering","title":"Made in Germany?","tagline":"Diesel engines, gummy bears or blue jeans? Spot the true German inventions.","emoji":"\u2699\ufe0f","gradient":["#b91c1c","#d97706"],"categories":["tech","cars","history"],"countries":["DE"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"Was it invented in Germany?","yes_label":"Germany","no_label":"Not","sort":201,"items":[{"k":"truefalse","i":"Diesel engine","t":"Engines","e":"\ud83d\udee0\ufe0f","f":"Rudolf Diesel built his first successful engine in Augsburg in 1897.","a":true},{"k":"truefalse","i":"Aspirin","t":"Medicine","e":"\ud83d\udc8a","f":"Bayer chemist Felix Hoffmann made a stable form of acetylsalicylic acid in 1897; Bayer named it Aspirin in 1899.","a":true},{"k":"truefalse","i":"MP3 audio format","t":"Tech","e":"\ud83c\udfa7","f":"The MP3 format was developed largely at Germany's Fraunhofer Institute in Erlangen.","a":true},{"k":"truefalse","i":"Gummy bears","t":"Sweets","e":"\ud83e\uddf8","f":"Hans Riegel of Bonn created the first gummy bears in 1922; his company name Haribo comes from HAns RIegel BOnn.","a":true},{"k":"truefalse","i":"Kindergarten","t":"Education","e":"\ud83e\uddd2","f":"Friedrich Fr\u00f6bel coined the word Kindergarten, 'children's garden', for his school for young children in 1840.","a":true},{"k":"truefalse","i":"Paper coffee filter","t":"Kitchen","e":"\u2615","f":"Dresden housewife Melitta Bentz patented the paper coffee filter in 1908 and founded the Melitta company.","a":true},{"k":"truefalse","i":"Petrol-powered car","t":"Cars","e":"\ud83d\ude97","f":"Karl Benz patented his Motorwagen in 1886; it is widely regarded as the first practical automobile.","a":true},{"k":"truefalse","i":"Blue jeans","t":"Fashion","e":"\ud83d\udc56","f":"Levi Strauss was born in Bavaria, but he patented riveted jeans with Jacob Davis in San Francisco in 1873.","a":false},{"k":"truefalse","i":"Telescope","t":"Optics","e":"\ud83d\udd2d","f":"The first known telescope patent was filed in 1608 by Hans Lipperhey in the Netherlands.","a":false},{"k":"truefalse","i":"Rubik's Cube","t":"Toys","e":"\ud83e\uddca","f":"Ern\u0151 Rubik, a Hungarian architecture professor, invented the cube in Budapest in 1974.","a":false},{"k":"truefalse","i":"LEGO bricks","t":"Toys","e":"\ud83e\uddf1","f":"LEGO comes from Billund, Denmark; the name is from the Danish 'leg godt', meaning 'play well'.","a":false},{"k":"truefalse","i":"Velcro","t":"Materials","e":"\ud83c\udf3f","f":"Swiss engineer George de Mestral invented Velcro after noticing burrs stuck to his dog's fur.","a":false},{"k":"truefalse","i":"Espresso machine","t":"Coffee","e":"\ud83c\uddee\ud83c\uddf9","f":"Angelo Moriondo of Turin, Italy, patented an early espresso machine in 1884.","a":false},{"k":"truefalse","i":"World Wide Web","t":"Internet","e":"\ud83c\udf10","f":"Tim Berners-Lee proposed the World Wide Web in 1989 while working at CERN near Geneva.","a":false}]},{"slug":"usa-or-canada","title":"USA or Canada?","tagline":"Hawaiian pizza, Jim Carrey, buffalo wings: which side of the border?","emoji":"\ud83c\udf41","gradient":["#2563eb","#dc2626"],"categories":["celebs","food","culture"],"countries":["US","CA"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"Where does it come from?","yes_label":"USA","no_label":"Canada","sort":202,"items":[{"k":"truefalse","i":"Chocolate chip cookie","t":"Food","e":"\ud83c\udf6a","f":"Ruth Wakefield created chocolate chip cookies at the Toll House Inn in Massachusetts around 1938.","a":true},{"k":"truefalse","i":"Buffalo wings","t":"Food","e":"\ud83c\udf57","f":"Spicy chicken wings were first served at the Anchor Bar in Buffalo, New York, in 1964.","a":true},{"k":"truefalse","i":"German chocolate cake","t":"Food","e":"\ud83c\udf70","f":"It is named after American baker Samuel German, who developed a sweet baking chocolate in 1852.","a":true},{"k":"truefalse","i":"Monopoly","t":"Games","e":"\ud83c\udfb2","f":"Monopoly grew out of Lizzie Magie's 1904 'Landlord's Game' and was published by Parker Brothers in 1935.","a":true},{"k":"truefalse","i":"Volleyball","t":"Sports","e":"\ud83c\udfd0","f":"William G. Morgan invented volleyball in 1895 in Holyoke, Massachusetts.","a":true},{"k":"truefalse","i":"Dolly Parton","t":"Music","e":"\ud83c\udfa4","f":"Dolly Parton was born in Tennessee in 1946 and later opened the Dollywood theme park there.","a":true},{"k":"truefalse","i":"Tom Hanks","t":"Movies","e":"\ud83c\udfac","f":"Tom Hanks was born in Concord, California, in 1956.","a":true},{"k":"truefalse","i":"Poutine","t":"Food","e":"\ud83c\udf5f","f":"Fries topped with cheese curds and gravy, poutine originated in rural Quebec in the 1950s.","a":false},{"k":"truefalse","i":"Hawaiian pizza","t":"Food","e":"\ud83c\udf4d","f":"Greek-Canadian cook Sam Panopoulos first put pineapple on pizza in Chatham, Ontario, in 1962.","a":false},{"k":"truefalse","i":"Nanaimo bar","t":"Food","e":"\ud83c\udf6b","f":"This no-bake layered dessert is named after the city of Nanaimo in British Columbia.","a":false},{"k":"truefalse","i":"Trivial Pursuit","t":"Games","e":"\u2753","f":"Chris Haney and Scott Abbott came up with Trivial Pursuit in Montreal in 1979.","a":false},{"k":"truefalse","i":"Celine Dion","t":"Music","e":"\ud83c\udfb6","f":"Celine Dion was born in Charlemagne, Quebec, the youngest of 14 children.","a":false},{"k":"truefalse","i":"Ryan Gosling","t":"Movies","e":"\ud83c\udfa5","f":"Born in London, Ontario, Ryan Gosling began his career on Disney's Mickey Mouse Club.","a":false},{"k":"truefalse","i":"Jim Carrey","t":"Movies","e":"\ud83e\udd2a","f":"Jim Carrey was born in Newmarket, Ontario, in 1962.","a":false}]},{"slug":"spain-or-portugal","title":"Spain or Portugal?","tagline":"Fado or flamenco, turr\u00f3n or nata: can you tell the Iberian neighbours apart?","emoji":"\ud83e\udd58","gradient":["#c2410c","#15803d"],"categories":["food","culture"],"countries":["ES","PT"],"difficulty":"Hard","minutes":4,"questions":10,"prompt":"Spanish or Portuguese?","yes_label":"Spain","no_label":"Portugal","sort":203,"items":[{"k":"truefalse","i":"Flamenco","t":"Music & dance","e":"\ud83d\udc83","f":"Flamenco song, dance and guitar come from Andalusia and were listed by UNESCO in 2010.","a":true},{"k":"truefalse","i":"Gazpacho","t":"Soups","e":"\ud83c\udf45","f":"Gazpacho is a chilled tomato and vegetable soup from Andalusia in southern Spain.","a":true},{"k":"truefalse","i":"Turr\u00f3n","t":"Sweets","e":"\ud83c\udf6c","f":"Turr\u00f3n, a nougat of almonds and honey, is famously made in Jijona near Alicante.","a":true},{"k":"truefalse","i":"Fabada asturiana","t":"Stews","e":"\ud83e\uded8","f":"Fabada is a hearty white bean stew with chorizo and morcilla from Asturias in northern Spain.","a":true},{"k":"truefalse","i":"Pimientos de Padr\u00f3n","t":"Tapas","e":"\ud83c\udf36\ufe0f","f":"These small green peppers from Galicia are mostly mild, but the odd one is surprisingly hot.","a":true},{"k":"truefalse","i":"Castells (human towers)","t":"Traditions","e":"\ud83e\uddd7","f":"Catalonia's human towers, built by teams called colles, were listed by UNESCO in 2010.","a":true},{"k":"truefalse","i":"La Tomatina","t":"Festivals","e":"\ud83c\udf45","f":"Every August, thousands pelt each other with tomatoes at La Tomatina in Bu\u00f1ol, near Valencia.","a":true},{"k":"truefalse","i":"Pastel de nata","t":"Sweets","e":"\ud83e\udd67","f":"These custard tarts are linked to the monks of the Jer\u00f3nimos Monastery in Bel\u00e9m, Lisbon.","a":false},{"k":"truefalse","i":"Fado","t":"Music","e":"\ud83c\udfb8","f":"Fado, Lisbon's soulful song style about longing, was added to UNESCO's heritage list in 2011.","a":false},{"k":"truefalse","i":"Francesinha","t":"Sandwiches","e":"\ud83e\udd6a","f":"Porto's Francesinha ('little French girl') is a meaty sandwich smothered in melted cheese and a tomato-beer sauce.","a":false},{"k":"truefalse","i":"Caldo verde","t":"Soups","e":"\ud83e\udd6c","f":"Caldo verde is a kale and potato soup from the Minho region, often served with a slice of chouri\u00e7o.","a":false},{"k":"truefalse","i":"Rooster of Barcelos (Galo de Barcelos)","t":"Symbols","e":"\ud83d\udc13","f":"The colourful rooster from the town of Barcelos in northern Portugal is an unofficial national symbol.","a":false},{"k":"truefalse","i":"Ovos moles de Aveiro","t":"Sweets","e":"\ud83d\udc1a","f":"These sweet egg-yolk treats from Aveiro are wrapped in thin wafer shaped like shells and fish.","a":false},{"k":"truefalse","i":"Cataplana","t":"Seafood","e":"\ud83e\udd90","f":"This Algarve seafood stew is named after the clam-shaped copper pan it is cooked in.","a":false}]},{"slug":"czech-it-out","title":"Czech It Out","tagline":"Robots, sugar cubes and soft contact lenses: discover Czech ingenuity.","emoji":"\ud83c\udff0","gradient":["#1d4ed8","#be123c"],"categories":["tech","food","culture"],"countries":["CZ"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"Czech or not?","yes_label":"Czech","no_label":"Not","sort":204,"items":[{"k":"truefalse","i":"Soft contact lenses","t":"Inventions","e":"\ud83d\udc41\ufe0f","f":"Chemist Otto Wichterle made the first soft contact lenses in 1961 using a children's building set.","a":true},{"k":"truefalse","i":"The word 'robot'","t":"Language","e":"\ud83e\udd16","f":"'Robot' debuted in Karel \u010capek's 1920 play R.U.R.; his brother Josef suggested the word.","a":true},{"k":"truefalse","i":"Sugar cubes","t":"Inventions","e":"\ud83e\uddc2","f":"Jakub Kry\u0161tof Rad patented the sugar cube in 1843 at a sugar refinery in Da\u010dice.","a":true},{"k":"truefalse","i":"Polka dance","t":"Music & dance","e":"\ud83d\udc83","f":"The polka emerged in Bohemia in the 1830s before sweeping through Europe's ballrooms.","a":true},{"k":"truefalse","i":"Tetris","t":"Games","e":"\ud83c\udfae","f":"Tetris was created by Alexey Pajitnov in Moscow in 1984.","a":false},{"k":"truefalse","i":"Matryoshka dolls","t":"Toys","e":"\ud83e\ude86","f":"Russian nesting dolls date from the 1890s, when the first set was carved near Moscow.","a":false},{"k":"truefalse","i":"Sachertorte","t":"Sweets","e":"\ud83c\udf6b","f":"Franz Sacher created this chocolate and apricot cake in Vienna, Austria, in 1832.","a":false},{"k":"choice","i":"Which river flows through Prague?","t":"Places","e":"\ud83c\udf09","f":"The Vltava is the longest river in the Czech Republic and inspired a famous piece by Smetana.","o":["Danube","Vltava","Elbe","Morava"],"s":{"index":1}},{"k":"choice","i":"Which Czech composer wrote the 'New World Symphony'?","t":"Music","e":"\ud83c\udfbb","f":"Dvo\u0159\u00e1k wrote his Symphony No. 9 in 1893 while living in the United States.","o":["Bed\u0159ich Smetana","Leo\u0161 Jan\u00e1\u010dek","Anton\u00edn Dvo\u0159\u00e1k","Bohuslav Martin\u016f"],"s":{"index":2}},{"k":"choice","i":"Which Czech spa town hosts a famous international film festival?","t":"Places","e":"\ud83c\udfac","f":"The Karlovy Vary film festival was first held in 1946, making it one of the oldest in the world.","o":["Brno","Olomouc","Plze\u0148","Karlovy Vary"],"s":{"index":3}},{"k":"choice","i":"What are knedl\u00edky, a staple of Czech cooking?","t":"Food","e":"\ud83e\udd5f","f":"Czech bread dumplings are sliced and served with sauces such as sv\u00ed\u010dkov\u00e1, beef in creamy vegetable sauce.","o":["Dumplings","Pancakes","Sausages","Pickled vegetables"],"s":{"index":0}},{"k":"number","i":"In what year did construction of Prague's Charles Bridge begin?","t":"History","e":"\ud83c\udf09","f":"Emperor Charles IV laid the foundation stone of the stone bridge in 1357.","s":{"value":1357,"tolerance":0,"min":1290,"max":1420,"unit":""}},{"k":"number","i":"How many countries share a border with the Czech Republic?","t":"Geography","e":"\ud83d\uddfa\ufe0f","f":"The Czech Republic borders Germany, Poland, Slovakia and Austria.","s":{"value":4,"tolerance":0,"min":1,"max":9,"unit":""}},{"k":"text","i":"What is the name of Prague's famous medieval astronomical clock?","t":"Landmarks","e":"\ud83d\udd70\ufe0f","f":"First installed in 1410, the Prague Orloj is the oldest astronomical clock still in operation.","s":{"accepted":["Orloj","Prague Orloj","The Orloj","Pra\u017esk\u00fd orloj","Prague astronomical clock"]}}]},{"slug":"serbian-stories","title":"Serbian Legends","tagline":"From Tesla to Djokovic, \u0107evapi to kolo: meet the legends of Serbia.","emoji":"\ud83c\uddf7\ud83c\uddf8","gradient":["#b91c1c","#1e3a8a"],"categories":["celebs","culture","sports"],"countries":["RS"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":205,"items":[{"k":"choice","i":"In which city was tennis star Novak Djokovic born?","t":"Tennis","e":"\ud83c\udfbe","f":"Djokovic won Olympic singles gold at Paris 2024, completing a career Golden Slam.","o":["Novi Sad","Belgrade","Ni\u0161","Kragujevac"],"s":{"index":1}},{"k":"text","i":"The SI unit of magnetic flux density is named after which Serbian-American inventor?","t":"Inventors","e":"\u26a1","f":"Tesla's work on alternating current motors helped shape the modern electric grid.","s":{"accepted":["Nikola Tesla","Tesla"]}},{"k":"number","i":"In what year was Nikola Tesla born?","t":"Inventors","e":"\ud83d\udca1","f":"Tesla was born on 10 July 1856 and moved to the United States in 1884.","s":{"value":1856,"tolerance":0,"min":1800,"max":1900,"unit":""}},{"k":"truefalse","i":"Nikola Tesla received the first patent for the telephone.","t":"Inventors","e":"\u260e\ufe0f","f":"The first telephone patent went to Alexander Graham Bell in 1876; Tesla is famed for AC power.","a":false},{"k":"choice","i":"What are \u0107evapi?","t":"Food","e":"\ud83c\udf62","f":"\u0106evapi are usually served in a soft lepinja flatbread with chopped raw onion.","o":["Stuffed cabbage rolls","A flaky cheese pie","A white bean soup","Small grilled minced-meat sausages"],"s":{"index":3}},{"k":"choice","i":"Ajvar, a favourite Serbian relish, is made mainly from which vegetable?","t":"Food","e":"\ud83e\uded1","f":"Families often roast big batches of peppers in autumn to make ajvar for the winter.","o":["Red peppers","Tomatoes","Cabbage","Beetroot"],"s":{"index":0}},{"k":"truefalse","i":"Sarma is made by rolling minced meat and rice in cabbage leaves.","t":"Food","e":"\ud83e\udd6c","f":"Sarma is often made with soured cabbage leaves and is a favourite at winter feasts.","a":true},{"k":"choice","i":"What is the kolo?","t":"Traditions","e":"\ud83d\udc83","f":"Kolo, danced in a linked circle, was added to UNESCO's Intangible Cultural Heritage list in 2017.","o":["A string instrument","A woollen hat","A circle folk dance","A honey pastry"],"s":{"index":2}},{"k":"choice","i":"Belgrade sits where the Sava river flows into which larger river?","t":"Geography","e":"\ud83c\udf0a","f":"Belgrade Fortress stands on a ridge overlooking the meeting of the two rivers.","o":["Drina","Morava","Tisza","Danube"],"s":{"index":3}},{"k":"truefalse","i":"Nikola Joki\u0107 led the Denver Nuggets to their first NBA championship in 2023.","t":"Basketball","e":"\ud83c\udfc0","f":"Joki\u0107, who grew up in Sombor in northern Serbia, was also named 2023 NBA Finals MVP.","a":true},{"k":"number","i":"How many letters are in the Serbian Cyrillic alphabet?","t":"Language","e":"\ud83d\udd24","f":"Vuk Karad\u017ei\u0107's reform gave one letter per sound; Serbian also uses an equivalent Latin alphabet.","s":{"value":30,"tolerance":0,"min":15,"max":40,"unit":""}},{"k":"truefalse","i":"Serbia has a coastline on the Adriatic Sea.","t":"Geography","e":"\ud83c\udfde\ufe0f","f":"Serbia is landlocked, but the Danube links it by river all the way to the Black Sea.","a":false},{"k":"choice","i":"The village of Gu\u010da hosts a famous festival dedicated to which instrument?","t":"Music","e":"\ud83c\udfba","f":"The Draga\u010devo Trumpet Festival in Gu\u010da has drawn brass bands since 1961.","o":["Accordion","Trumpet","Violin","Drum"],"s":{"index":1}},{"k":"text","i":"What is the name of the creamy dairy spread, similar to clotted cream, loved in Serbia?","t":"Food","e":"\ud83e\uddc8","f":"Kajmak is made from the cream that rises on boiled milk, which is salted and left to mature.","s":{"accepted":["Kajmak","Kaymak","Kajmac"]}}]},{"slug":"flag-frenzy","title":"Flag Frenzy","tagline":"Lookalike flags and tiny details: only true flag fanatics survive this one.","emoji":"\ud83d\udea9","gradient":["#7c3aed","#db2777"],"categories":["flags","geo"],"countries":null,"difficulty":"Hard","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":206,"items":[{"k":"choice","i":"Which country does this flag belong to? \ud83c\uddf3\ud83c\uddf5","t":"Asia","e":"\ud83c\uddf3\ud83c\uddf5","f":"Nepal's flag of two stacked pennants is the only non-rectangular national flag.","o":["Nepal","Bhutan","Sri Lanka","Bangladesh"],"s":{"index":0}},{"k":"choice","i":"Which country does this flag belong to? \ud83c\uddee\ud83c\uddea","t":"Europe","e":"\ud83c\uddee\ud83c\uddea","f":"Ireland's flag has green at the hoist; C\u00f4te d'Ivoire's is a mirror image with orange at the hoist.","o":["C\u00f4te d'Ivoire","Italy","Ireland","Niger"],"s":{"index":2}},{"k":"choice","i":"Which country does this flag belong to? \ud83c\udde8\ud83c\uddf4","t":"South America","e":"\ud83c\udde8\ud83c\uddf4","f":"Colombia's yellow band fills the top half; Ecuador and Venezuela share its Gran Colombia colours.","o":["Venezuela","Ecuador","Bolivia","Colombia"],"s":{"index":3}},{"k":"choice","i":"Which country does this flag belong to? \ud83c\uddf8\ud83c\uddee","t":"Europe","e":"\ud83c\uddf8\ud83c\uddee","f":"The coat of arms on Slovenia's flag shows Triglav, the country's highest mountain.","o":["Slovakia","Slovenia","Russia","Serbia"],"s":{"index":1}},{"k":"choice","i":"Which country does this flag belong to? \ud83c\uddf3\ud83c\uddff","t":"Oceania","e":"\ud83c\uddf3\ud83c\uddff","f":"New Zealand shows the Southern Cross as four red stars; Australia's flag has six white stars.","o":["Australia","Fiji","New Zealand","Tuvalu"],"s":{"index":2}},{"k":"choice","i":"Which country does this flag belong to? \ud83c\uddf8\ud83c\uddf3","t":"Africa","e":"\ud83c\uddf8\ud83c\uddf3","f":"Senegal's flag has the same green, yellow and red bands as Mali's but adds a green star.","o":["Senegal","Mali","Guinea","Cameroon"],"s":{"index":0}},{"k":"choice","i":"Which country does this flag belong to? \ud83c\udded\ud83c\uddf3","t":"Central America","e":"\ud83c\udded\ud83c\uddf3","f":"Its five stars stand for the five nations of the former Federal Republic of Central America.","o":["Nicaragua","El Salvador","Guatemala","Honduras"],"s":{"index":3}},{"k":"choice","i":"Which country does this flag belong to? \ud83c\uddf5\ud83c\uddf1","t":"Europe","e":"\ud83c\uddf5\ud83c\uddf1","f":"Poland's flag is white over red, the reverse of the red-over-white flags of Indonesia and Monaco.","o":["Indonesia","Poland","Monaco","Singapore"],"s":{"index":1}},{"k":"choice","i":"Which country does this flag belong to? \ud83c\uddf0\ud83c\uddfc","t":"Middle East","e":"\ud83c\uddf0\ud83c\uddfc","f":"Kuwait adopted its flag in 1961, using the pan-Arab colours green, white, red and black.","o":["United Arab Emirates","Jordan","Kuwait","Sudan"],"s":{"index":2}},{"k":"multi","i":"Select all the countries whose flag shows the Southern Cross constellation.","t":"Stars","e":"\u2b50","f":"Brazil's flag depicts the sky over Rio de Janeiro on 15 November 1889, Southern Cross included.","o":["Australia","Brazil","Canada","Japan","New Zealand"],"s":{"indices":[0,1,4]}},{"k":"multi","i":"Select all the countries whose flag has a Nordic (off-centre) cross.","t":"Crosses","e":"\ud83c\uddf8\ud83c\uddea","f":"Denmark's flag introduced the off-centre Nordic cross, later adopted by its Nordic neighbours.","o":["Sweden","Greece","Finland","Switzerland","Iceland"],"s":{"indices":[0,2,4]}},{"k":"multi","i":"Select all the countries whose flag features a sun.","t":"Symbols","e":"\u2600\ufe0f","f":"Argentina and Uruguay both show the 'Sun of May', a golden sun with a human face.","o":["Argentina","Chile","Kazakhstan","Brazil","Uruguay"],"s":{"indices":[0,2,4]}},{"k":"text","i":"Which country has this square national flag? \ud83c\udde8\ud83c\udded","t":"Europe","e":"\ud83c\udde8\ud83c\udded","f":"Switzerland and Vatican City are the only countries with square national flags.","s":{"accepted":["Switzerland","Swiss Confederation"]}},{"k":"text","i":"Which country's flag features this white thunder dragon? \ud83c\udde7\ud83c\uddf9","t":"Asia","e":"\ud83c\udde7\ud83c\uddf9","f":"In Dzongkha, Bhutan is called Druk Yul, the 'Land of the Thunder Dragon'.","s":{"accepted":["Bhutan"]}}]},{"slug":"dish-detective","title":"Dish Detective","tagline":"Follow your taste buds around the world and match each dish to its home.","emoji":"\ud83c\udf5c","gradient":["#ea580c","#be185d"],"categories":["food","culture","travel"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":207,"items":[{"k":"choice","i":"Which country is Pad Thai from?","t":"Asia","e":"\ud83c\udf5c","f":"Pad Thai means 'Thai-style stir-fry': rice noodles with egg, tamarind and peanuts.","o":["Vietnam","Thailand","Malaysia","Indonesia"],"s":{"index":1}},{"k":"choice","i":"Which country is paella from?","t":"Europe","e":"\ud83e\udd58","f":"Paella comes from Valencia and is named after the wide, shallow pan it is cooked in.","o":["Italy","Mexico","Portugal","Spain"],"s":{"index":3}},{"k":"choice","i":"Which country is kimchi from?","t":"Asia","e":"\ud83e\udd6c","f":"Kimjang, the Korean tradition of making kimchi together for winter, is on UNESCO's heritage list.","o":["Korea","Japan","China","Vietnam"],"s":{"index":0}},{"k":"choice","i":"Which country is goulash from?","t":"Europe","e":"\ud83c\udf72","f":"Goulash takes its name from the guly\u00e1s, the Hungarian cattle herders who cooked it.","o":["Austria","Czech Republic","Hungary","Poland"],"s":{"index":2}},{"k":"choice","i":"Which country is fish and chips from?","t":"Europe","e":"\ud83d\udc1f","f":"The first fish and chip shops opened in England in the 1860s.","o":["United Kingdom","Ireland","USA","Australia"],"s":{"index":0}},{"k":"choice","i":"Which country is pho from?","t":"Asia","e":"\ud83c\udf5c","f":"Pho, a fragrant noodle soup, emerged in northern Vietnam in the early 20th century.","o":["Thailand","Cambodia","Vietnam","Laos"],"s":{"index":2}},{"k":"choice","i":"Which country is butter chicken from?","t":"Asia","e":"\ud83c\udf5b","f":"Butter chicken, or murgh makhani, was created at a restaurant in Delhi.","o":["India","Pakistan","Bangladesh","Sri Lanka"],"s":{"index":0}},{"k":"choice","i":"Which country is Wiener schnitzel from?","t":"Europe","e":"\ud83e\udd69","f":"'Wiener' means 'Viennese', and a true Wiener schnitzel must be made from veal.","o":["Germany","Austria","Switzerland","Hungary"],"s":{"index":1}},{"k":"choice","i":"Which country is ratatouille from?","t":"Europe","e":"\ud83c\udf46","f":"Ratatouille is a stewed vegetable dish from Nice in Provence.","o":["Italy","Spain","Greece","France"],"s":{"index":3}},{"k":"choice","i":"Which country is sm\u00f8rrebr\u00f8d from?","t":"Europe","e":"\ud83e\udd6a","f":"Sm\u00f8rrebr\u00f8d are open sandwiches on dark rye bread, piled high with toppings.","o":["Norway","Sweden","Denmark","Finland"],"s":{"index":2}},{"k":"multi","i":"Select all the dishes from Italy.","t":"Europe","e":"\ud83c\uddee\ud83c\uddf9","f":"Tiramisu means 'pick me up' in Italian, a nod to its coffee and cocoa.","o":["Risotto","Lasagna","Bratwurst","Tiramisu","Churros"],"s":{"indices":[0,1,3]}},{"k":"multi","i":"Select all the dishes from Mexico.","t":"Americas","e":"\ud83c\udf2e","f":"Guacamole goes back to the Aztecs, who made a sauce of mashed avocado.","o":["Enchiladas","Tamales","Gazpacho","Guacamole","Pierogi"],"s":{"indices":[0,1,3]}},{"k":"text","i":"Which country is sushi from?","t":"Asia","e":"\ud83c\udf63","f":"Sushi began as a way of preserving fish in fermented rice.","s":{"accepted":["Japan","Nippon"]}},{"k":"text","i":"Which country is Peking duck from?","t":"Asia","e":"\ud83e\udd86","f":"Peking is the old English name for Beijing, where the crispy roast duck became famous.","s":{"accepted":["China"]}}]},{"slug":"year-it-happened","title":"The Year It Happened","tagline":"From Magna Carta to the first iPhone: pin history to the exact year.","emoji":"\u23f3","gradient":["#0f766e","#1e40af"],"categories":["history","general"],"countries":null,"difficulty":"Hard","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":208,"items":[{"k":"number","i":"In what year was Magna Carta sealed by King John of England?","t":"Medieval","e":"\ud83d\udcdc","f":"King John sealed Magna Carta at Runnymede, beside the River Thames, in June 1215.","s":{"value":1215,"tolerance":0,"min":1150,"max":1270,"unit":""}},{"k":"number","i":"In what year did Christopher Columbus first reach the Americas?","t":"Exploration","e":"\u26f5","f":"Columbus landed in the Bahamas in October 1492 after sailing from Spain.","s":{"value":1492,"tolerance":0,"min":1440,"max":1550,"unit":""}},{"k":"number","i":"In what year was William Shakespeare born?","t":"Literature","e":"\ud83c\udfad","f":"He was baptised in Stratford-upon-Avon on 26 April 1564; his exact birth date is unknown.","s":{"value":1564,"tolerance":0,"min":1520,"max":1620,"unit":""}},{"k":"number","i":"In what year did the Great Fire of London happen?","t":"London","e":"\ud83d\udd25","f":"The fire started in a bakery on Pudding Lane and destroyed about 13,200 houses.","s":{"value":1666,"tolerance":0,"min":1600,"max":1710,"unit":""}},{"k":"number","i":"In what year was the US Declaration of Independence adopted?","t":"Documents","e":"\ud83d\uddfd","f":"The Continental Congress adopted the Declaration on 4 July 1776.","s":{"value":1776,"tolerance":0,"min":1730,"max":1830,"unit":""}},{"k":"number","i":"In what year did Charles Darwin publish 'On the Origin of Species'?","t":"Science","e":"\ud83d\udc22","f":"Darwin's book came out on 24 November 1859 and its first printing sold out at once.","s":{"value":1859,"tolerance":0,"min":1800,"max":1900,"unit":""}},{"k":"number","i":"In what year did the Suez Canal open?","t":"Engineering","e":"\ud83d\udea2","f":"The canal opened in November 1869, linking the Mediterranean and the Red Sea.","s":{"value":1869,"tolerance":0,"min":1830,"max":1920,"unit":""}},{"k":"number","i":"In what year was the Eiffel Tower completed?","t":"Landmarks","e":"\ud83d\uddfc","f":"Built for the 1889 World's Fair, it was the world's tallest structure until 1930.","s":{"value":1889,"tolerance":0,"min":1850,"max":1950,"unit":""}},{"k":"number","i":"In what year did the Wright brothers make the first powered airplane flight?","t":"Aviation","e":"\u2708\ufe0f","f":"The first flight at Kitty Hawk lasted 12 seconds and covered about 37 metres.","s":{"value":1903,"tolerance":0,"min":1860,"max":1950,"unit":""}},{"k":"number","i":"In what year did Howard Carter discover Tutankhamun's tomb?","t":"Archaeology","e":"\ud83c\udffa","f":"Carter found the tomb in Egypt's Valley of the Kings in November 1922.","s":{"value":1922,"tolerance":0,"min":1870,"max":1970,"unit":""}},{"k":"number","i":"In what year was the first FIFA World Cup held?","t":"Sports","e":"\u26bd","f":"Uruguay hosted and won the first World Cup in 1930.","s":{"value":1930,"tolerance":0,"min":1890,"max":1980,"unit":""}},{"k":"number","i":"In what year did Yuri Gagarin become the first human in space?","t":"Space","e":"\ud83d\ude80","f":"Gagarin's single orbit of Earth aboard Vostok 1 took about 108 minutes.","s":{"value":1961,"tolerance":0,"min":1920,"max":2010,"unit":""}},{"k":"number","i":"In what year did euro banknotes and coins enter circulation?","t":"Money","e":"\ud83d\udcb6","f":"The euro existed as a non-cash currency from 1999; notes and coins arrived on 1 January 2002.","s":{"value":2002,"tolerance":0,"min":1950,"max":2025,"unit":""}},{"k":"number","i":"In what year did the first iPhone go on sale?","t":"Tech","e":"\ud83d\udcf1","f":"Apple announced the iPhone in January 2007 and it went on sale in the US that June.","s":{"value":2007,"tolerance":0,"min":1960,"max":2025,"unit":""}}]},{"slug":"brain-buffet-general-knowledge","title":"Brain Buffet","tagline":"A little bit of everything: warm up with this general knowledge mix.","emoji":"\ud83e\udde0","gradient":["#f59e0b","#dc2626"],"categories":["general"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":209,"items":[{"k":"choice","i":"How many sides does a hexagon have?","t":"Shapes","e":"\u2b21","f":"Honeybees build hexagonal cells because the shape fits together with no gaps and uses wax efficiently.","o":["5","6","7","8"],"s":{"index":1}},{"k":"choice","i":"Which is the largest ocean on Earth?","t":"Oceans","e":"\ud83c\udf0a","f":"The Pacific covers about a third of Earth's surface, more than all the land on the planet combined.","o":["Pacific","Atlantic","Indian","Arctic"],"s":{"index":0}},{"k":"truefalse","i":"A tomato is botanically a fruit.","t":"Food science","e":"\ud83c\udf45","f":"Botanically, fruits grow from a flower and contain seeds, so tomatoes, cucumbers and peppers all count.","a":true},{"k":"number","i":"How many keys does a standard modern piano have?","t":"Music","e":"\ud83c\udfb9","f":"A standard piano has 52 white keys and 36 black keys.","s":{"value":88,"tolerance":0,"min":50,"max":120,"unit":"keys"}},{"k":"text","i":"Which gemstone, made of pure carbon, scores 10 on the Mohs hardness scale?","t":"Minerals","e":"\ud83d\udc8e","f":"The Mohs scale of mineral hardness was devised in 1812 by German geologist Friedrich Mohs.","s":{"accepted":["Diamond","Diamonds","A diamond"]}},{"k":"choice","i":"Who painted the Mona Lisa?","t":"Art","e":"\ud83d\uddbc\ufe0f","f":"The Mona Lisa hangs in the Louvre in Paris, where it sits behind protective glass.","o":["Michelangelo","Raphael","Botticelli","Leonardo da Vinci"],"s":{"index":3}},{"k":"multi","i":"Select all the primary colors of light used by screens (RGB).","t":"Colors","e":"\ud83c\udf08","f":"Screens mix tiny red, green and blue lights at different brightnesses to create every color you see.","o":["Red","Yellow","Green","Blue","Purple"],"s":{"indices":[0,2,3]}},{"k":"order","i":"Order these units of time from shortest to longest.","t":"Time","e":"\u23f3","f":"A century is 100 years, which is roughly 3.16 billion seconds.","o":["Second","Hour","Week","Decade","Century"]},{"k":"choice","i":"What is the capital of Australia?","t":"Capitals","e":"\ud83c\udde6\ud83c\uddfa","f":"Canberra was purpose-built as the capital, partly as a compromise between rivals Sydney and Melbourne.","o":["Sydney","Melbourne","Canberra","Perth"],"s":{"index":2}},{"k":"number","i":"How many players does a football (soccer) team have on the pitch at once?","t":"Sport","e":"\u26bd","f":"A football team fields ten outfield players plus one goalkeeper.","s":{"value":11,"tolerance":0,"min":5,"max":15,"unit":"players"}},{"k":"text","i":"In which country is the ancient Inca citadel of Machu Picchu?","t":"Landmarks","e":"\ud83c\udfd4\ufe0f","f":"Machu Picchu was built by the Inca in the 15th century, high in the Andes mountains.","s":{"accepted":["Peru"]}},{"k":"choice","i":"Which language has the most native speakers in the world?","t":"Languages","e":"\ud83d\udde3\ufe0f","f":"Mandarin Chinese has well over 900 million native speakers.","o":["Mandarin Chinese","English","Spanish","Hindi"],"s":{"index":0}},{"k":"truefalse","i":"A group of crows is called a 'murder'.","t":"Animal words","e":"\ud83d\udc26","f":"Other fun collective nouns include a 'parliament' of owls and a 'flamboyance' of flamingos.","a":true}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '0288fb29dba76fad505d121d26a3b405' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 1'; end $q$;
do $q$ declare d text := $d$[{"slug":"word-detectives","title":"Word Detectives","tagline":"Every word has a backstory. Can you trace where these ones came from?","emoji":"\ud83d\udd0d","gradient":["#7c3aed","#db2777"],"categories":["language","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":210,"items":[{"k":"choice","i":"The word 'robot' comes from a play by which Czech writer?","t":"Coined words","e":"\ud83e\udd16","f":"\u010capek's play R.U.R. made 'robot' famous; it comes from Czech 'robota' (forced labour), a word his brother Josef suggested.","o":["Franz Kafka","Karel \u010capek","Milan Kundera","Jaroslav Ha\u0161ek"],"s":{"index":1}},{"k":"choice","i":"'Muscle' comes from a Latin word meaning what?","t":"Latin roots","e":"\ud83d\udcaa","f":"Romans thought a flexing muscle looked like a little mouse ('musculus') scurrying under the skin.","o":["Strong arm","Little mouse","Hidden rope","Moving stone"],"s":{"index":1}},{"k":"truefalse","i":"The 'mare' in 'nightmare' originally meant a female horse.","t":"Old English","e":"\ud83c\udf19","f":"In Old English a 'mare' was an evil spirit believed to sit on sleepers' chests, nothing to do with horses.","a":false},{"k":"number","i":"'Quarantine' comes from the Venetian words for a waiting period of how many days?","t":"Italian roots","e":"\u2693","f":"Ships arriving in Venice during plague outbreaks had to wait 'quaranta giorni', forty days, before landing.","s":{"value":40,"tolerance":0,"min":0,"max":100,"unit":"days"}},{"k":"multi","i":"Select all the words that came into English from Nahuatl, the language of the Aztecs.","t":"Borrowed words","e":"\ud83e\udd51","f":"Tomato and avocado come from Nahuatl 'tomatl' and 'ahuacatl'; banana is West African and potato comes from Ta\u00edno via Spanish.","o":["Potato","Banana","Chocolate","Avocado","Tomato"],"s":{"indices":[2,3,4]}},{"k":"choice","i":"The word 'disaster' literally blames misfortune on a bad what?","t":"Italian roots","e":"\u2728","f":"From Italian 'disastro': 'dis' (bad) + 'astro' (star), an unlucky alignment of the heavens.","o":["Harvest","Star","Storm","Journey"],"s":{"index":1}},{"k":"text","i":"Which snack is named after John Montagu, an 18th-century English earl?","t":"Eponyms","e":"\ud83e\udd6a","f":"The 4th Earl of Sandwich reputedly asked for meat between two slices of bread so he could eat without leaving his work or cards.","s":{"accepted":["Sandwich","Sandwiches","The sandwich","A sandwich"]}},{"k":"choice","i":"'Kindergarten' is borrowed from German. What does it literally mean?","t":"German loans","e":"\ud83c\udf31","f":"Educator Friedrich Fr\u00f6bel coined the name in 1840 for a school where children could grow like plants in a garden.","o":["Children's garden","Little school","Play house","First class"],"s":{"index":0}},{"k":"choice","i":"The word 'shampoo' came into English from which language?","t":"Borrowed words","e":"\ud83e\uddf4","f":"It comes from Hindi 'ch\u0101mpo', meaning press or massage. The first 'shampoos' in Britain were head massages.","o":["Japanese","Arabic","Portuguese","Hindi"],"s":{"index":3}},{"k":"choice","i":"The word 'algebra' comes from which language?","t":"Maths words","e":"\u2797","f":"It comes from 'al-jabr' in the title of a 9th-century maths book by the Baghdad scholar al-Khwarizmi.","o":["Arabic","Greek","Latin","Hebrew"],"s":{"index":0}},{"k":"truefalse","i":"'Tycoon' comes from a Japanese title meaning 'great lord'.","t":"Japanese loans","e":"\ud83c\udfef","f":"'Taikun' was a title used for the shogun in dealings with foreigners; English picked it up in the 1850s.","a":true},{"k":"choice","i":"Denim gets its name from 'serge de ___', a fabric from which French city?","t":"Fashion words","e":"\ud83d\udc56","f":"'Serge de N\u00eemes' was shortened to denim, while 'jeans' is thought to come from G\u00eanes, the French name for Genoa.","o":["Nice","Nantes","Lyon","N\u00eemes"],"s":{"index":3}},{"k":"text","i":"'Alphabet' joins the names of the first two Greek letters: alpha and which other?","t":"Greek roots","e":"\ud83d\udd24","f":"Alpha and beta themselves come from the Phoenician letters aleph (ox) and beth (house).","s":{"accepted":["Beta"]}},{"k":"truefalse","i":"The word 'salary' is linked to the Latin word for salt.","t":"Latin roots","e":"\ud83e\uddc2","f":"Latin 'salarium' is related to 'sal' (salt). The popular story that Roman soldiers were paid in salt is unproven.","a":true}]},{"slug":"silver-screen-classics","title":"Silver Screen Classics","tagline":"From Oz to Casablanca: how good is your golden-age movie memory?","emoji":"\ud83c\udf9e\ufe0f","gradient":["#b45309","#7c2d12"],"categories":["movies","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":211,"items":[{"k":"choice","i":"In 'The Wizard of Oz' (1939), what colour are Dorothy's magical slippers?","t":"Musicals","e":"\ud83d\udc60","f":"In L. Frank Baum's original book the shoes were silver; the film made them ruby red to show off Technicolor.","o":["Silver","Ruby red","Gold","Emerald green"],"s":{"index":1}},{"k":"choice","i":"Which actor played Rick Blaine in 'Casablanca' (1942)?","t":"1940s","e":"\u2708\ufe0f","f":"Casablanca won the Academy Award for Best Picture and is regularly ranked among the greatest films ever made.","o":["Cary Grant","Clark Gable","Humphrey Bogart","James Stewart"],"s":{"index":2}},{"k":"choice","i":"How many Academy Awards did 'Titanic' (1997) win?","t":"Oscars","e":"\ud83c\udfc6","f":"Titanic's 11 wins equalled Ben-Hur (1959), and The Return of the King (2003) later matched them too.","o":["9","10","12","11"],"s":{"index":3}},{"k":"choice","i":"Who dances and sings the famous title number in 'Singin' in the Rain' (1952)?","t":"Musicals","e":"\u2614","f":"Gene Kelly also co-directed the film with Stanley Donen.","o":["Gene Kelly","Fred Astaire","Donald O'Connor","Frank Sinatra"],"s":{"index":0}},{"k":"choice","i":"Which 1927 film is widely credited as the first feature-length 'talkie'?","t":"Film History","e":"\ud83c\udf99\ufe0f","f":"The Jazz Singer, starring Al Jolson, used synchronized sound for songs and some dialogue and launched the talkie era.","o":["Metropolis","The General","Nosferatu","The Jazz Singer"],"s":{"index":3}},{"k":"choice","i":"Who directed the 1962 epic 'Lawrence of Arabia'?","t":"Directors","e":"\ud83c\udfdc\ufe0f","f":"David Lean also directed 'The Bridge on the River Kwai' and 'Doctor Zhivago'.","o":["Stanley Kubrick","David Lean","Billy Wilder","John Ford"],"s":{"index":1}},{"k":"truefalse","i":"'Citizen Kane' (1941) was directed by Orson Welles, who also starred in it.","t":"Directors","e":"\ud83c\udfa5","f":"Welles was only 25 when he made Citizen Kane, which he co-wrote, directed and starred in.","a":true},{"k":"truefalse","i":"'The Sound of Music' (1965) is set in Austria.","t":"Musicals","e":"\ud83c\udfd4\ufe0f","f":"Much of the film was shot on location in and around Salzburg.","a":true},{"k":"number","i":"In what year was 'Gone with the Wind' released?","t":"1930s","e":"\ud83d\udd25","f":"1939 is often called Hollywood's greatest year: it also saw the release of The Wizard of Oz.","s":{"value":1939,"tolerance":0,"min":1925,"max":1960,"unit":""}},{"k":"order","i":"Order these films from oldest to newest.","t":"Timeline","e":"\ud83d\udcc5","f":"Casablanca came out in 1942, Singin' in the Rain in 1952, The Sound of Music in 1965, Star Wars in 1977 and Back to the Future in 1985.","o":["Casablanca","Singin' in the Rain","The Sound of Music","Star Wars","Back to the Future"]},{"k":"text","i":"Which actress played Holly Golightly in 'Breakfast at Tiffany's' (1961)?","t":"Stars","e":"\ud83d\udc8e","f":"Her little black Givenchy dress from the film is one of the most famous costumes in movie history.","s":{"accepted":["Audrey Hepburn","Hepburn"]}},{"k":"text","i":"What is the name of Charlie Chaplin's famous bowler-hatted character?","t":"Silent Era","e":"\ud83c\udfa9","f":"Chaplin first played the Tramp in 1914, complete with bowler hat, cane and baggy trousers.","s":{"accepted":["The Tramp","Tramp","The Little Tramp","Little Tramp"]}},{"k":"multi","i":"Select all the films directed by Alfred Hitchcock.","t":"Hitchcock","e":"\ud83d\udd0d","f":"Casablanca was directed by Michael Curtiz and Some Like It Hot by Billy Wilder.","o":["Vertigo","Casablanca","Rear Window","Some Like It Hot","North by Northwest"],"s":{"indices":[0,2,4]}}]},{"slug":"dinner-around-the-world","title":"Dinner Around the World","tagline":"Paella, pho or poutine? Match the world's favourite dishes to their homes.","emoji":"\ud83c\udf72","gradient":["#f97316","#be123c"],"categories":["food","culture","geo"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":212,"items":[{"k":"choice","i":"Which country is the home of paella?","t":"Rice dishes","e":"\ud83e\udd58","f":"Paella comes from Valencia, where it was traditionally cooked over an open fire in a wide, shallow pan.","o":["Italy","Mexico","Spain","Greece"],"s":{"index":2}},{"k":"choice","i":"Poutine, fries topped with cheese curds and gravy, is a classic from which country?","t":"Comfort food","e":"\ud83c\udf5f","f":"Poutine first appeared in rural Quebec in the 1950s and is now sold all over Canada.","o":["Canada","Belgium","Ireland","USA"],"s":{"index":0}},{"k":"choice","i":"Pho, a fragrant noodle soup, comes from which country?","t":"Soups","e":"\ud83c\udf5c","f":"Pho is usually made with rice noodles in a beef or chicken broth spiced with star anise and cinnamon.","o":["Thailand","Vietnam","Japan","Korea"],"s":{"index":1}},{"k":"choice","i":"Goulash (guly\u00e1s) is a hearty soup or stew from which country?","t":"Stews","e":"\ud83c\udf72","f":"The word guly\u00e1s originally meant 'herdsman': the dish began as food cooked by Hungarian cattle herders.","o":["Austria","Hungary","Poland","Romania"],"s":{"index":1}},{"k":"choice","i":"Kimchi, a spicy fermented vegetable side dish, is a staple of which cuisine?","t":"Fermented food","e":"\ud83e\udd6c","f":"Kimjang, the tradition of making and sharing kimchi before winter, is on UNESCO's intangible heritage list.","o":["Chinese","Indonesian","Mongolian","Korean"],"s":{"index":3}},{"k":"choice","i":"Ceviche, raw fish 'cooked' in citrus juice, is especially associated with which country?","t":"Seafood","e":"\ud83d\udc1f","f":"The acid in lime juice changes the proteins in the fish, making it firm and opaque without any heat.","o":["Peru","Spain","Philippines","Portugal"],"s":{"index":0}},{"k":"truefalse","i":"Wiener schnitzel is a dish from Vienna, Austria.","t":"Austria","e":"\ud83c\udf56","f":"In Austria, a true 'Wiener Schnitzel' must be made from veal; pork versions go by other names.","a":true},{"k":"truefalse","i":"Haggis is a traditional dish from Wales.","t":"Scotland","e":"\ud83c\udf7d\ufe0f","f":"Haggis is Scotland's famous dish, eaten especially on Burns Night, 25 January.","a":false},{"k":"multi","i":"Select all the dishes that come from Japan.","t":"Japan","e":"\ud83c\udf63","f":"Takoyaki, battered balls filled with pieces of octopus, were popularised in Osaka in the 1930s.","o":["Sushi","Tacos","Okonomiyaki","Pierogi","Takoyaki"],"s":{"indices":[0,2,4]}},{"k":"text","i":"Feijoada, a black bean stew with pork, is the national dish of which South American country?","t":"Brazil","e":"\ud83e\uded8","f":"Feijoada is usually served with rice, farofa (toasted cassava flour), collard greens and orange slices.","s":{"accepted":["Brazil","Brasil"]}},{"k":"text","i":"Moussaka topped with creamy b\u00e9chamel sauce is most famously associated with which country?","t":"Greece","e":"\ud83c\udf46","f":"The b\u00e9chamel-topped Greek moussaka was popularised in the 1920s by chef Nikolaos Tselementes.","s":{"accepted":["Greece","Hellas"]}},{"k":"number","i":"In what year was the art of the Neapolitan pizza maker added to UNESCO's intangible heritage list?","t":"Italy","e":"\ud83c\udf55","f":"The pizzaiuolo's craft, inscribed in 2017, includes stretching and spinning the dough entirely by hand.","s":{"value":2017,"tolerance":2,"min":1990,"max":2024,"unit":""}},{"k":"order","i":"Order these dishes by their home country, from west to east.","t":"Geography","e":"\ud83e\udded","f":"From Peru to Korea, these four dishes stretch across more than half of the globe's longitude.","o":["Ceviche","Paella","Goulash","Kimchi"]}]},{"slug":"olympic-host-hop","title":"Olympic Host Hop","tagline":"From Athens 1896 to Tokyo 2020: which cities lit the Olympic flame?","emoji":"\ud83c\udfdf\ufe0f","gradient":["#f59e0b","#dc2626"],"categories":["olympics","travel","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":213,"items":[{"k":"choice","i":"Which city hosted the first modern Olympic Games in 1896?","t":"First Games","e":"\ud83c\udfdb\ufe0f","f":"The 1896 Games were held in the Panathenaic Stadium, a rebuilt ancient stadium made almost entirely of marble.","o":["Rome","Athens","Paris","London"],"s":{"index":1}},{"k":"choice","i":"Which city hosted the 2016 Summer Olympics, the first held in South America?","t":"Summer Games","e":"\ud83c\udde7\ud83c\uddf7","f":"The Rio 2016 opening ceremony took place at the Maracan\u00e3, one of the world's most famous football stadiums.","o":["Santiago","S\u00e3o Paulo","Rio de Janeiro","Buenos Aires"],"s":{"index":2}},{"k":"truefalse","i":"London has hosted the Summer Olympics three times.","t":"Summer Games","e":"\ud83c\uddec\ud83c\udde7","f":"London hosted in 1908, 1948 and 2012, the first city to host the modern Summer Games three times.","a":true},{"k":"choice","i":"Which city hosted the 1992 Summer Olympics?","t":"Summer Games","e":"\ud83c\uddea\ud83c\uddf8","f":"Barcelona 1992 transformed the city's waterfront, and the USA's 'Dream Team' of NBA stars played there.","o":["Madrid","Valencia","Barcelona","Seville"],"s":{"index":2}},{"k":"multi","i":"Select all the cities that have hosted the Summer Olympics.","t":"Summer Games","e":"\ud83c\udf0d","f":"Montreal hosted in 1976, Seoul in 1988 and Sydney in 2000, while Toronto and Istanbul have bid without success.","o":["Sydney","Seoul","Montreal","Toronto","Istanbul"],"s":{"indices":[0,1,2]}},{"k":"order","i":"Order these Summer Olympic hosts from earliest to most recent.","t":"Timeline","e":"\ud83d\udcc5","f":"Mexico City 1968 was the first Summer Olympics held in Latin America.","o":["Mexico City","Moscow","Atlanta","Beijing"]},{"k":"number","i":"In what year did Tokyo first host the Summer Olympics?","t":"Summer Games","e":"\ud83c\uddef\ud83c\uddf5","f":"Tokyo 1964 was the first Olympics held in Asia, and the Shinkansen bullet train opened just before it.","s":{"value":1964,"tolerance":0,"min":1940,"max":2000,"unit":""}},{"k":"choice","i":"Which Canadian city hosted the 2010 Winter Olympics?","t":"Winter Games","e":"\ud83c\udde8\ud83c\udde6","f":"Canada won 14 gold medals at Vancouver 2010, a record for a single Winter Games at the time.","o":["Vancouver","Ottawa","Montreal","Calgary"],"s":{"index":0}},{"k":"text","i":"Which Australian city hosted the 1956 Summer Olympics?","t":"Summer Games","e":"\ud83e\udd98","f":"Because of quarantine rules for horses, the 1956 equestrian events were held in Stockholm, Sweden.","s":{"accepted":["Melbourne"]}},{"k":"truefalse","i":"Germany has never hosted the Summer Olympics.","t":"Summer Games","e":"\ud83c\udde9\ud83c\uddea","f":"Germany hosted the Summer Games in Berlin in 1936 and in Munich in 1972.","a":false},{"k":"choice","i":"Which Norwegian town hosted the 1994 Winter Olympics?","t":"Winter Games","e":"\ud83c\uddf3\ud83c\uddf4","f":"Lillehammer 1994 came just two years after Albertville 1992, when the Winter Games moved to their own four-year cycle.","o":["Trondheim","Oslo","Lillehammer","Bergen"],"s":{"index":2}},{"k":"multi","i":"Select all the cities that have hosted the Winter Olympics.","t":"Winter Games","e":"\u26f7\ufe0f","f":"Oslo hosted in 1952, Sapporo in 1972 and Calgary in 1988; Moscow only hosted the Summer Games, in 1980.","o":["Oslo","Sapporo","Moscow","Calgary","Madrid"],"s":{"indices":[0,1,3]}},{"k":"choice","i":"Which city hosted the Winter Olympics in both 1964 and 1976?","t":"Winter Games","e":"\ud83c\udfd4\ufe0f","f":"Innsbruck, in Austria's Tyrol, also hosted the first Winter Youth Olympic Games in 2012.","o":["St. Moritz","Lake Placid","Grenoble","Innsbruck"],"s":{"index":3}}]},{"slug":"myth-or-fact-common-myths","title":"Myth or Fact?","tagline":"Goldfish memory, lightning strikes, Napoleon's height: can you spot the myths?","emoji":"\ud83d\udd75\ufe0f","gradient":["#8b5cf6","#db2777"],"categories":["general","science"],"countries":null,"difficulty":"Medium","minutes":3,"questions":10,"prompt":"Fact or myth?","yes_label":"Fact","no_label":"Myth","sort":214,"items":[{"k":"truefalse","i":"Goldfish have a memory span of only about three seconds.","t":"Animal myths","e":"\ud83d\udc20","f":"Experiments show goldfish can remember things for months and can even be trained to respond to sounds.","a":false},{"k":"truefalse","i":"Lightning never strikes the same place twice.","t":"Weather myths","e":"\u26a1","f":"The Empire State Building in New York is struck by lightning around 20 to 25 times a year.","a":false},{"k":"truefalse","i":"Bats are blind.","t":"Animal myths","e":"\ud83e\udd87","f":"All bats can see, and many species use echolocation as well as eyesight to find food at night.","a":false},{"k":"truefalse","i":"Humans use only 10% of their brains.","t":"Body myths","e":"\ud83e\udde0","f":"Brain scans show activity across virtually every region of the brain, even during sleep.","a":false},{"k":"truefalse","i":"Ostriches bury their heads in the sand when they are frightened.","t":"Animal myths","e":"\ud83e\udeb6","f":"Ostriches lower their heads to turn their eggs or lie flat to hide, which may have started the myth.","a":false},{"k":"truefalse","i":"Hair and fingernails keep growing after death.","t":"Body myths","e":"\ud83d\udc85","f":"After death the skin dries out and pulls back, which makes hair and nails look longer than they are.","a":false},{"k":"truefalse","i":"Napoleon Bonaparte was unusually short for his time.","t":"History myths","e":"\ud83c\udfa9","f":"Napoleon was about 1.69 m (5 ft 7 in), roughly average for a Frenchman of his era.","a":false},{"k":"truefalse","i":"A day on Venus is longer than a year on Venus.","t":"Space","e":"\ud83e\ude90","f":"Venus takes about 243 Earth days to spin once, but only about 225 Earth days to orbit the Sun.","a":true},{"k":"truefalse","i":"Sound travels faster in water than in air.","t":"Physics","e":"\ud83d\udd0a","f":"Sound moves at about 1,500 m/s in water, more than four times faster than its roughly 343 m/s in air.","a":true},{"k":"truefalse","i":"Honey can stay preserved for thousands of years.","t":"Food science","e":"\ud83c\udf6f","f":"Archaeologists have found pots of honey in ancient Egyptian tombs that were still well preserved.","a":true},{"k":"truefalse","i":"Bananas are naturally slightly radioactive.","t":"Food science","e":"\ud83c\udf4c","f":"Bananas contain potassium, including a tiny amount of radioactive potassium-40, which is completely harmless.","a":true},{"k":"truefalse","i":"Wombats produce cube-shaped droppings.","t":"Animal facts","e":"\ud83d\udc3e","f":"Wombats leave their cube-shaped droppings on rocks and logs to mark their territory.","a":true},{"k":"truefalse","i":"Sharks have existed for longer than trees.","t":"Prehistory","e":"\ud83e\udd88","f":"Sharks appeared over 400 million years ago, while the first trees evolved roughly 385 million years ago.","a":true},{"k":"truefalse","i":"Octopuses have blue blood.","t":"Animal facts","e":"\ud83d\udc19","f":"Octopus blood uses a copper-based protein called hemocyanin to carry oxygen, which turns it blue.","a":true}]},{"slug":"idiom-globetrotter","title":"Idiom Globetrotter","tagline":"Tomatoes on your eyes? Noodles on your ears? Decode sayings from around the world.","emoji":"\ud83d\udde3\ufe0f","gradient":["#f97316","#dc2626"],"categories":["language","culture"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":215,"items":[{"k":"choice","i":"In German, someone who 'has tomatoes on their eyes' is\u2026","t":"German","e":"\ud83c\udf45","f":"'Tomaten auf den Augen haben' means failing to see what's right in front of you.","o":["Crying with laughter","Very sleepy","Blushing with embarrassment","Not noticing something obvious"],"s":{"index":3}},{"k":"choice","i":"Italians wish good luck by saying 'In bocca al lupo'. What does it literally mean?","t":"Italian","e":"\ud83d\udc3a","f":"The traditional reply is 'Crepi il lupo!', meaning 'may the wolf die'.","o":["Into the wolf's mouth","On the horse's back","Under the lucky moon","With the cat's tail"],"s":{"index":0}},{"k":"choice","i":"If a French friend 'pose un lapin' (puts down a rabbit), what have they done?","t":"French","e":"\ud83d\udc07","f":"'Poser un lapin' means failing to show up for a date or meeting.","o":["Told a joke","Stood you up","Paid the bill","Run away scared"],"s":{"index":1}},{"k":"choice","i":"Spanish speakers call something easy 'pan comido'. What does that mean literally?","t":"Spanish","e":"\ud83c\udf5e","f":"It's the Spanish equivalent of 'a piece of cake'.","o":["Sweet cake","Warm soup","Fresh fruit","Eaten bread"],"s":{"index":3}},{"k":"choice","i":"In German, 'Ich verstehe nur Bahnhof' (I only understand 'train station') means\u2026","t":"German","e":"\ud83d\ude89","f":"Germans say it when something makes no sense at all, like English 'It's all Greek to me'.","o":["I'm lost in a new city","I'm about to leave","I don't understand a thing","I'm very bored"],"s":{"index":2}},{"k":"multi","i":"Select all the idioms that mean 'very expensive'.","t":"Money talk","e":"\ud83d\udcb8","f":"French and Spanish both price expensive things in eyes: 'the eyes of the head' and 'an eye of the face'.","o":["Schwein haben (German)","Co\u00fbter les yeux de la t\u00eate (French)","Estar en las nubes (Spanish)","Cost an arm and a leg (English)","Costar un ojo de la cara (Spanish)"],"s":{"indices":[1,3,4]}},{"k":"truefalse","i":"In German, 'Schwein haben' (to have pig) means to be very lucky.","t":"German","e":"\ud83d\udc37","f":"Pigs are a symbol of good luck in Germany; little marzipan pigs are popular New Year's gifts.","a":true},{"k":"choice","i":"'Not my circus, not my monkeys', meaning 'not my problem', is a well-known saying from which language?","t":"Polish","e":"\ud83d\udc12","f":"'Nie m\u00f3j cyrk, nie moje ma\u0142py' has spread worldwide as a polite way to stay out of someone else's drama.","o":["Greek","Swedish","Polish","Portuguese"],"s":{"index":2}},{"k":"choice","i":"Where English says 'when pigs fly', French says 'when hens have\u2026'","t":"French","e":"\ud83d\udc14","f":"'Quand les poules auront des dents', when hens have teeth, describes something that will never happen.","o":["Wings","Teeth","Hats","Money"],"s":{"index":1}},{"k":"truefalse","i":"In Russian, to 'hang noodles on someone's ears' means to treat them to a delicious meal.","t":"Russian","e":"\ud83c\udf5c","f":"It means to fool someone or feed them nonsense.","a":false},{"k":"choice","i":"The Japanese phrase 'I'd even borrow a cat's paws' describes someone who is\u2026","t":"Japanese","e":"\ud83d\udc31","f":"'Neko no te mo karitai' means you're so busy you'd accept help from anyone, even the cat.","o":["Very lazy","Feeling lucky","Extremely busy","Really hungry"],"s":{"index":2}},{"k":"choice","i":"In Swedish, to 'slide in on a shrimp sandwich' means to\u2026","t":"Swedish","e":"\ud83e\udd90","f":"'Glida in p\u00e5 en r\u00e4kmacka' describes someone who has an easy ride and never had to work for it.","o":["Arrive late to a party","Get ahead without any effort","Make a clumsy mistake","Eat far too much"],"s":{"index":1}},{"k":"text","i":"Instead of crossing their fingers for luck, Germans 'press' which body part?","t":"German","e":"\ud83d\udc4d","f":"In Germany, Czechia, Poland and Hungary people wish luck by pressing or holding their thumbs.","s":{"accepted":["Thumbs","Thumb","Their thumbs","The thumbs","Daumen"]}},{"k":"truefalse","i":"The Portuguese idiom 'pagar o pato' (to pay the duck) means taking the blame for something you didn't do.","t":"Portuguese","e":"\ud83e\udd86","f":"It's similar to English 'carrying the can': you end up paying for someone else's mistake.","a":true}]},{"slug":"animation-station","title":"Animation Station","tagline":"Clownfish, snowmen and talking lions: how well do you know animated films?","emoji":"\ud83e\udd81","gradient":["#f97316","#db2777"],"categories":["movies","kids"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":216,"items":[{"k":"choice","i":"What was Disney's first full-length animated feature film?","t":"Disney","e":"\ud83c\udf4e","f":"Snow White and the Seven Dwarfs premiered in 1937; many in Hollywood had called it 'Disney's Folly'.","o":["Pinocchio","Fantasia","Snow White and the Seven Dwarfs","Bambi"],"s":{"index":2}},{"k":"choice","i":"What kind of fish is Nemo in 'Finding Nemo' (2003)?","t":"Pixar","e":"\ud83d\udc20","f":"His forgetful friend Dory is a blue tang.","o":["Clownfish","Blue tang","Pufferfish","Angelfish"],"s":{"index":0}},{"k":"choice","i":"Which studio made 'Spirited Away' (2001)?","t":"Anime Films","e":"\ud83d\udc09","f":"Spirited Away won the Academy Award for Best Animated Feature in 2003.","o":["Toei Animation","Studio Ghibli","Pixar","DreamWorks"],"s":{"index":1}},{"k":"choice","i":"In which city is Pixar's 'Ratatouille' (2007) set?","t":"Pixar","e":"\ud83d\udc00","f":"Remy the rat dreams of becoming a chef in a famous Paris restaurant.","o":["Paris","Lyon","Rome","Marseille"],"s":{"index":0}},{"k":"choice","i":"Which song from 'Frozen' (2013) won the Oscar for Best Original Song?","t":"Songs","e":"\u2744\ufe0f","f":"The song was written by the husband-and-wife team Kristen Anderson-Lopez and Robert Lopez.","o":["Do You Want to Build a Snowman?","For the First Time in Forever","Let It Go","Love Is an Open Door"],"s":{"index":2}},{"k":"choice","i":"What kind of animal is Baloo in Disney's 'The Jungle Book' (1967)?","t":"Disney","e":"\ud83d\udc3b","f":"Bagheera is the panther, Shere Khan the tiger and King Louie the orangutan.","o":["Panther","Tiger","Orangutan","Bear"],"s":{"index":3}},{"k":"number","i":"In what year was 'Toy Story', the first entirely computer-animated feature film, released?","t":"Pixar","e":"\ud83e\udd20","f":"Toy Story was Pixar's first feature film.","s":{"value":1995,"tolerance":0,"min":1985,"max":2005,"unit":""}},{"k":"text","i":"In 'The Lion King' (1994), what is the name of Simba's father?","t":"Disney","e":"\ud83d\udc51","f":"The Lion King was later turned into one of the most successful stage musicals ever.","s":{"accepted":["Mufasa"]}},{"k":"text","i":"What is the name of the talking snowman in 'Frozen'?","t":"Disney","e":"\u26c4","f":"Olaf loves warm hugs and dreams of summer, despite being made of snow.","s":{"accepted":["Olaf"]}},{"k":"truefalse","i":"'Shrek' (2001) won the first ever Academy Award for Best Animated Feature.","t":"Oscars","e":"\ud83d\udfe2","f":"The category was introduced for films of 2001, and Shrek beat Monsters, Inc. to the prize.","a":true},{"k":"truefalse","i":"'Beauty and the Beast' (1991) was the first animated film nominated for the Best Picture Oscar.","t":"Oscars","e":"\ud83c\udf39","f":"It was nominated at the 1992 ceremony; the award went to The Silence of the Lambs.","a":true},{"k":"multi","i":"Select all the films made by Pixar.","t":"Studios","e":"\ud83d\udca1","f":"Shrek and Madagascar are DreamWorks films, while Frozen was made by Walt Disney Animation Studios.","o":["Toy Story","Shrek","Monsters, Inc.","Frozen","The Incredibles","Madagascar"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these Disney animated films from oldest to newest.","t":"Timeline","e":"\ud83c\udff0","f":"They were released in 1937, 1950, 1967, 1989 and 2013.","o":["Snow White and the Seven Dwarfs","Cinderella","The Jungle Book","The Little Mermaid","Frozen"]}]},{"slug":"cheese-and-bread-board","title":"Cheese & Bread Board","tagline":"Feta, Gouda, naan and pretzels: a world tour for cheese and bread lovers.","emoji":"\ud83e\uddc0","gradient":["#c2410c","#92400e"],"categories":["food","culture"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":217,"items":[{"k":"choice","i":"Feta cheese comes from which country?","t":"Cheese","e":"\ud83e\uddc0","f":"Feta has EU protected status: it must be made in Greece from sheep's milk, with up to 30% goat's milk.","o":["Italy","Turkey","Greece","Cyprus"],"s":{"index":2}},{"k":"choice","i":"Which sheep's-milk blue cheese is aged in natural caves in southern France?","t":"Blue cheese","e":"\ud83d\udc11","f":"To be called Roquefort, the cheese must be aged in the natural caves of Roquefort-sur-Soulzon.","o":["Roquefort","Brie","Camembert","Comt\u00e9"],"s":{"index":0}},{"k":"choice","i":"What makes the holes in Emmental cheese?","t":"Science of cheese","e":"\ud83e\udee7","f":"Bacteria release carbon dioxide while the cheese ripens, and the gas forms the famous holes, called 'eyes'.","o":["Air pumped in by machines","Gas bubbles made by bacteria","Mice nibbling the cheese","Salt crystals dissolving"],"s":{"index":1}},{"k":"choice","i":"Halloumi, the 'squeaky' cheese you can grill without it melting, comes from which island?","t":"Cheese","e":"\ud83d\udd25","f":"Halloumi's high melting point means it browns in a pan or on a grill instead of turning runny.","o":["Sicily","Crete","Malta","Cyprus"],"s":{"index":3}},{"k":"choice","i":"Injera, a spongy sourdough flatbread, is a staple in which country?","t":"Bread","e":"\ud83e\uded3","f":"Injera is traditionally made from teff, a tiny grain native to the Horn of Africa.","o":["Ethiopia","Morocco","Nigeria","Kenya"],"s":{"index":0}},{"k":"choice","i":"Which Italian bread was only invented in 1982?","t":"Bread","e":"\ud83e\udd56","f":"Ciabatta was created by baker Arnaldo Cavallari in the Veneto region as an Italian answer to the French baguette.","o":["Focaccia","Ciabatta","Grissini","Panettone"],"s":{"index":1}},{"k":"truefalse","i":"The pretzel is closely associated with Germany, where it is called a 'Brezel'.","t":"Bread","e":"\ud83e\udd68","f":"The knotted pretzel has been used as the emblem of bakers' guilds in southern Germany for centuries.","a":true},{"k":"truefalse","i":"Cheddar cheese is named after a village in France.","t":"Cheese","e":"\ud83e\uddc0","f":"Cheddar is named after the village of Cheddar in Somerset, England, close to the caves of Cheddar Gorge.","a":false},{"k":"multi","i":"Select all the cheeses that come from Italy.","t":"Italy","e":"\ud83c\udf5d","f":"Gorgonzola is named after a town near Milan and is one of the world's oldest blue cheeses.","o":["Parmigiano Reggiano","Manchego","Mozzarella","Gruy\u00e8re","Gorgonzola"],"s":{"indices":[0,2,4]}},{"k":"text","i":"What is the long, thin French loaf whose craft joined UNESCO's heritage list in 2022?","t":"France","e":"\ud83e\udd56","f":"The 'artisanal know-how and culture of baguette bread' was added to UNESCO's intangible heritage list in 2022.","s":{"accepted":["Baguette","Baguettes","French baguette","A baguette"]}},{"k":"text","i":"Naan is traditionally baked on the inside wall of what kind of clay oven?","t":"Bread","e":"\ud83e\uded3","f":"The dough is slapped onto the hot inner wall of the tandoor, where it puffs up in just a few minutes.","s":{"accepted":["Tandoor","Tandoor oven","Tandoori oven","A tandoor"]}},{"k":"number","i":"Parmigiano Reggiano must be aged for at least how many months?","t":"Ageing","e":"\u23f3","f":"Many wheels are aged far longer: 24- and 36-month Parmigiano Reggiano are prized for their crumbly texture.","s":{"value":12,"tolerance":0,"min":1,"max":36,"unit":"months"}},{"k":"order","i":"Order these cheeses by their home country, from north to south.","t":"Geography","e":"\ud83e\udded","f":"Gouda is named after the Dutch city of Gouda, where it has long been traded at a famous cheese market.","o":["Gouda","Emmental","Parmigiano Reggiano","Feta"]},{"k":"order","i":"Order these cheesemaking steps from first to last.","t":"Cheesemaking","e":"\ud83e\udd5b","f":"Rennet contains enzymes that make milk proteins clump together into solid curds.","o":["Warm the milk and add a starter culture","Add rennet to set the curd","Cut the curd and drain the whey","Press and salt the cheese","Age the cheese"]}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '0d02403aa46d91a226a7912bc73eba8d' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 2'; end $q$;
do $q$ declare d text := $d$[{"slug":"rings-torches-medals","title":"Rings, Torches & Medals","tagline":"Olympic symbols, traditions and legends from more than a century of Games.","emoji":"\ud83e\udd47","gradient":["#2563eb","#7c3aed"],"categories":["olympics","history","sports"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":218,"items":[{"k":"number","i":"How many interlocking rings are on the Olympic flag?","t":"Symbols","e":"\u2b55","f":"Pierre de Coubertin designed the rings in 1913; they symbolise the union of the five continents.","s":{"value":5,"tolerance":0,"min":1,"max":10,"unit":""}},{"k":"choice","i":"Which of these colours is NOT one of the colours of the Olympic rings?","t":"Symbols","e":"\ud83c\udfa8","f":"Coubertin said the five ring colours plus the white background included a colour from every nation's flag of his time.","o":["Green","Blue","Red","Purple"],"s":{"index":3}},{"k":"choice","i":"Who is credited as the founder of the modern Olympic Games?","t":"Founders","e":"\ud83c\udfa9","f":"Pierre de Coubertin founded the International Olympic Committee in 1894 and later served as its president.","o":["Pierre de Coubertin","Juan Antonio Samaranch","Baron Haussmann","Avery Brundage"],"s":{"index":0}},{"k":"text","i":"The Olympic motto is 'Citius, Altius, Fortius'. In which language is it written?","t":"Symbols","e":"\ud83d\udcdc","f":"It means 'Faster, Higher, Stronger'; in 2021 the IOC added 'Communiter', meaning 'Together'.","s":{"accepted":["Latin"]}},{"k":"choice","i":"In which country is the Olympic flame traditionally lit before each Games?","t":"Traditions","e":"\ud83d\udd25","f":"The flame is lit at ancient Olympia using a curved mirror that focuses the Sun's rays.","o":["Switzerland","Italy","France","Greece"],"s":{"index":3}},{"k":"truefalse","i":"The first Olympic torch relay from Olympia was held for the 1936 Berlin Games.","t":"Traditions","e":"\ud83c\udfc3","f":"A flame first burned in the stadium at Amsterdam 1928, but the first relay from Olympia came in 1936.","a":true},{"k":"choice","i":"Which swimmer won a record eight gold medals at a single Olympics, at Beijing 2008?","t":"Legends","e":"\ud83c\udfca","f":"Phelps broke Mark Spitz's record of seven golds at one Games, set at Munich 1972.","o":["Michael Phelps","Mark Spitz","Ryan Lochte","Ian Thorpe"],"s":{"index":0}},{"k":"choice","i":"Which sprinter won the Olympic 100 m title at Beijing 2008, London 2012 and Rio 2016?","t":"Legends","e":"\u26a1","f":"Usain Bolt is the only athlete to win the Olympic 100 m title three times in a row.","o":["Usain Bolt","Carl Lewis","Justin Gatlin","Yohan Blake"],"s":{"index":0}},{"k":"choice","i":"At Montreal 1976, which gymnast scored the first perfect 10 in Olympic history?","t":"Legends","e":"\ud83e\udd38","f":"The scoreboard couldn't display 10.00, so Nadia Com\u0103neci's perfect score appeared as 1.00.","o":["Nadia Com\u0103neci","Olga Korbut","Simone Biles","Larisa Latynina"],"s":{"index":0}},{"k":"order","i":"Order these Olympic milestones from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"The first Winter Games, held in Chamonix in 1924, were originally called 'International Winter Sports Week'.","o":["First modern Olympics","First Winter Olympics","First Olympics held in Asia","First Olympics held in South America"]},{"k":"truefalse","i":"Olympic gold medals are made of solid gold.","t":"Medals","e":"\ud83c\udfc5","f":"Solid gold medals were last awarded in 1912; today they are mostly silver, plated with at least 6 grams of gold.","a":false},{"k":"choice","i":"Jesse Owens won four gold medals at which Olympics?","t":"Legends","e":"\ud83d\udc5f","f":"Owens won the 100 m, 200 m, long jump and 4\u00d7100 m relay in Berlin.","o":["Berlin 1936","Helsinki 1952","London 1948","Los Angeles 1932"],"s":{"index":0}},{"k":"number","i":"In what year did women first compete at the modern Olympic Games?","t":"History","e":"\ud83c\udfbe","f":"British tennis player Charlotte Cooper became the first female Olympic champion in an individual event, at Paris 1900.","s":{"value":1900,"tolerance":0,"min":1890,"max":1950,"unit":""}},{"k":"multi","i":"Select all the events that were part of the ancient Olympic Games in Greece.","t":"Ancient Games","e":"\ud83c\udffa","f":"Traditionally dated to 776 BC, the ancient Games at Olympia were held every four years for more than a thousand years.","o":["Wrestling","Discus throw","Chariot racing","Volleyball","Swimming"],"s":{"indices":[0,1,2]}}]},{"slug":"rivers-and-mountains-of-the-world","title":"Rivers & Mountains","tagline":"From the Volga to Kilimanjaro: how well do you know Earth's great landmarks?","emoji":"\u26f0\ufe0f","gradient":["#0284c7","#0f766e"],"categories":["geo","nature"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":219,"items":[{"k":"choice","i":"Which mountain is the highest above sea level?","t":"Mountains","e":"\ud83c\udfd4\ufe0f","f":"Everest's summit sits on the border between Nepal and China.","o":["K2","Kangchenjunga","Mount Everest","Lhotse"],"s":{"index":2}},{"k":"choice","i":"The Danube River flows into which sea?","t":"Rivers","e":"\ud83c\udf0a","f":"The Danube flows through or along the borders of 10 countries, more than any other river in the world.","o":["Black Sea","Adriatic Sea","Baltic Sea","North Sea"],"s":{"index":0}},{"k":"choice","i":"K2, the world's second-highest mountain, lies on the border of Pakistan and which other country?","t":"Mountains","e":"\ud83e\uddd7","f":"K2 is nicknamed the 'Savage Mountain' because it is so difficult and dangerous to climb.","o":["India","China","Nepal","Afghanistan"],"s":{"index":1}},{"k":"number","i":"Roughly how high is Mount Everest, in metres?","t":"Mountains","e":"\ud83d\udccf","f":"A joint China-Nepal survey in 2020 measured Everest at 8,848.86 m above sea level.","s":{"value":8849,"tolerance":100,"min":6000,"max":11000,"unit":"m"}},{"k":"text","i":"What is the longest river in Europe?","t":"Rivers","e":"\ud83d\udef6","f":"The Volga flows about 3,500 km through Russia before emptying into the Caspian Sea.","s":{"accepted":["Volga","Volga River","The Volga","River Volga"]}},{"k":"multi","i":"Select all the rivers that flow through Africa.","t":"Rivers","e":"\ud83c\udf0d","f":"The Zambezi plunges over Victoria Falls on the border between Zambia and Zimbabwe.","o":["Nile","Mekong","Zambezi","Rhine","Congo"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these mountains from highest to lowest.","t":"Mountains","e":"\u26f0\ufe0f","f":"Aconcagua in Argentina is the highest mountain anywhere outside Asia.","o":["Mount Everest","Aconcagua","Denali","Kilimanjaro","Mont Blanc"]},{"k":"choice","i":"Which river carries the most water of any river in the world?","t":"Rivers","e":"\ud83d\udca7","f":"The Amazon carries about a fifth of all the river water that flows into the world's oceans.","o":["Nile","Yangtze","Mississippi","Amazon"],"s":{"index":3}},{"k":"choice","i":"Which river carved the Grand Canyon?","t":"Rivers","e":"\ud83c\udfdc\ufe0f","f":"Over millions of years the Colorado River cut the Grand Canyon to depths of more than 1.8 km.","o":["Colorado","Mississippi","Rio Grande","Columbia"],"s":{"index":0}},{"k":"text","i":"Which mountain range in Russia is traditionally seen as part of the boundary between Europe and Asia?","t":"Mountains","e":"\ud83d\uddfb","f":"The Ural Mountains run for about 2,500 km, from the Arctic coast south towards Kazakhstan.","s":{"accepted":["Ural Mountains","Urals","Ural","The Urals","Ural Mountain Range"]}},{"k":"truefalse","i":"The Nile flows from south to north.","t":"Rivers","e":"\ud83e\udded","f":"The Nile's drainage basin spans eleven countries before the river reaches the Mediterranean Sea.","a":true},{"k":"choice","i":"Mount Kilimanjaro is located in which country?","t":"Mountains","e":"\ud83e\udd92","f":"Kilimanjaro is the world's highest free-standing mountain, rising alone from the surrounding plains.","o":["Kenya","Uganda","Tanzania","Ethiopia"],"s":{"index":2}},{"k":"order","i":"Order these rivers from longest to shortest.","t":"Rivers","e":"\ud83d\udcd0","f":"The Yangtze is the longest river in Asia and the third-longest in the world.","o":["Yangtze","Congo","Danube","Rhine","Thames"]}]},{"slug":"tongues-of-the-world","title":"Tongues of the World","tagline":"Scripts, alphabets and language families: a tour of how the world talks.","emoji":"\ud83c\udf10","gradient":["#0891b2","#4f46e5"],"categories":["language","geo"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":220,"items":[{"k":"text","i":"Besides English, which language is an official language of Canada?","t":"Official languages","e":"\ud83c\udf41","f":"Canada became officially bilingual with the Official Languages Act of 1969.","s":{"accepted":["French"]}},{"k":"choice","i":"Hungarian belongs to the same language family as which language?","t":"Language families","e":"\ud83c\udf33","f":"Hungarian, Finnish and Estonian are all Uralic languages, unrelated to most of their European neighbours.","o":["German","Finnish","Romanian","Slovak"],"s":{"index":1}},{"k":"truefalse","i":"Basque, spoken in parts of Spain and France, is not known to be related to any other living language.","t":"Language isolates","e":"\u26f0\ufe0f","f":"Basque is a 'language isolate'; it is thought to predate the arrival of Indo-European languages in Western Europe.","a":true},{"k":"choice","i":"Who created the constructed language Esperanto?","t":"Invented languages","e":"\ud83d\udc9a","f":"Zamenhof published the first Esperanto textbook in Warsaw in 1887, hoping for a neutral international language.","o":["L. L. Zamenhof","J. R. R. Tolkien","Noam Chomsky","Noah Webster"],"s":{"index":0}},{"k":"number","i":"How many national languages does Switzerland have?","t":"Official languages","e":"\ud83c\udde8\ud83c\udded","f":"German, French, Italian and Romansh, though Romansh is spoken by well under 1% of the population.","s":{"value":4,"tolerance":0,"min":1,"max":8,"unit":""}},{"k":"multi","i":"Select all the languages normally written in the Cyrillic alphabet.","t":"Scripts","e":"\u270d\ufe0f","f":"Cyrillic is named after the 9th-century scholar Cyril; Polish, Croatian and Romanian use the Latin alphabet.","o":["Russian","Romanian","Polish","Bulgarian","Ukrainian","Croatian"],"s":{"indices":[0,3,4]}},{"k":"multi","i":"Select all the languages written from right to left.","t":"Scripts","e":"\u21a9\ufe0f","f":"Arabic, Hebrew and Persian run right to left, but numbers inside the text are still read left to right.","o":["Hebrew","Arabic","Greek","Hindi","Persian"],"s":{"indices":[0,1,4]}},{"k":"choice","i":"The Korean alphabet, Hangul, was created under which ruler?","t":"Scripts","e":"\ud83c\uddf0\ud83c\uddf7","f":"King Sejong introduced Hangul in the 1440s so that ordinary people could learn to read and write easily.","o":["King Sejong the Great","Emperor Meiji","Kublai Khan","Genghis Khan"],"s":{"index":0}},{"k":"number","i":"How many different scripts are routinely mixed in everyday written Japanese?","t":"Scripts","e":"\ud83c\uddef\ud83c\uddf5","f":"Hiragana, katakana and kanji often all appear in one sentence, plus Latin letters known as r\u014dmaji.","s":{"value":3,"tolerance":0,"min":1,"max":6,"unit":""}},{"k":"truefalse","i":"Mandarin Chinese is a tonal language, where the pitch of a syllable can change its meaning.","t":"Sounds","e":"\ud83c\udfb5","f":"With different tones, 'ma' can mean mother, hemp, horse or scold.","a":true},{"k":"choice","i":"Hindi is most commonly written in which script?","t":"Scripts","e":"\ud83c\uddee\ud83c\uddf3","f":"Devanagari, also used for Sanskrit, Marathi and Nepali, hangs its letters from a horizontal line along the top.","o":["Cyrillic","Hangul","Latin","Devanagari"],"s":{"index":3}},{"k":"order","i":"Order these languages by number of native speakers, most to fewest.","t":"Speakers","e":"\ud83d\udc65","f":"Mandarin has the most native speakers of any language; Icelandic has only a few hundred thousand.","o":["Mandarin Chinese","Spanish","French","Hungarian","Icelandic"]},{"k":"order","i":"Order these alphabets by number of letters, fewest first.","t":"Alphabets","e":"\ud83d\udd20","f":"Hawaiian has 13 letters, Greek 24, English 26, Russian 33 and Hungarian 44, counting letters like 'cs' and 'gy'.","o":["Hawaiian","Greek","English","Russian","Hungarian"]}]},{"slug":"directors-chair","title":"The Director's Chair","tagline":"Spielberg, Kubrick, Kurosawa: match the visionaries to their films.","emoji":"\ud83c\udfac","gradient":["#1e3a8a","#7c3aed"],"categories":["movies"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":221,"items":[{"k":"choice","i":"Which director made 'Jaws' (1975), 'E.T.' (1982) and 'Jurassic Park' (1993)?","t":"Directors","e":"\ud83e\udd88","f":"Jaws is often called the first summer blockbuster.","o":["George Lucas","Steven Spielberg","James Cameron","Robert Zemeckis"],"s":{"index":1}},{"k":"choice","i":"Who directed '2001: A Space Odyssey' (1968)?","t":"Sci-Fi","e":"\ud83d\ude80","f":"Kubrick co-wrote the screenplay with science-fiction author Arthur C. Clarke.","o":["Stanley Kubrick","Ridley Scott","Andrei Tarkovsky","Francis Ford Coppola"],"s":{"index":0}},{"k":"choice","i":"Which director made both 'Titanic' (1997) and 'Avatar' (2009)?","t":"Blockbusters","e":"\ud83d\udea2","f":"James Cameron was born in Canada, in Kapuskasing, Ontario.","o":["Peter Jackson","Michael Bay","James Cameron","Ron Howard"],"s":{"index":2}},{"k":"choice","i":"Which Japanese director made 'Seven Samurai' (1954)?","t":"World Cinema","e":"\ud83d\uddfe","f":"Seven Samurai inspired the 1960 Hollywood western 'The Magnificent Seven'.","o":["Yasujir\u014d Ozu","Akira Kurosawa","Hayao Miyazaki","Takeshi Kitano"],"s":{"index":1}},{"k":"choice","i":"Which director made 'Beetlejuice' (1988) and 'Edward Scissorhands' (1990)?","t":"Directors","e":"\u2702\ufe0f","f":"Both films feature music by Danny Elfman, Tim Burton's long-time composer.","o":["Wes Anderson","Terry Gilliam","Guillermo del Toro","Tim Burton"],"s":{"index":3}},{"k":"choice","i":"Who directed 'The Grand Budapest Hotel' (2014)?","t":"Directors","e":"\ud83c\udfe8","f":"Despite its name, the hotel is in the fictional country of Zubrowka, not Hungary.","o":["Spike Jonze","Wes Anderson","Noah Baumbach","Richard Linklater"],"s":{"index":1}},{"k":"truefalse","i":"George Lucas directed 'The Empire Strikes Back' (1980).","t":"Star Wars","e":"\ud83c\udf0c","f":"Lucas produced and wrote the story, but the film was directed by Irvin Kershner.","a":false},{"k":"truefalse","i":"Director Sofia Coppola is the daughter of director Francis Ford Coppola.","t":"Film Families","e":"\ud83d\udc68\u200d\ud83d\udc67","f":"Sofia Coppola won the Oscar for Best Original Screenplay for 'Lost in Translation' (2003).","a":true},{"k":"number","i":"In what year did Kathryn Bigelow become the first woman to win the Oscar for Best Director?","t":"Oscars","e":"\ud83e\udd47","f":"She won for 'The Hurt Locker' at the 82nd Academy Awards.","s":{"value":2010,"tolerance":0,"min":1990,"max":2020,"unit":""}},{"k":"text","i":"Which New Zealand director made 'The Lord of the Rings' film trilogy?","t":"Fantasy","e":"\ud83d\udc8d","f":"The trilogy was filmed in New Zealand, and its landscapes have drawn film fans there ever since.","s":{"accepted":["Peter Jackson","Jackson","Sir Peter Jackson"]}},{"k":"text","i":"In which country was Alfred Hitchcock born?","t":"Hitchcock","e":"\ud83c\uddec\ud83c\udde7","f":"Born in London in 1899, Hitchcock made his early films in Britain before moving to Hollywood in 1939.","s":{"accepted":["England","United Kingdom","UK","Britain","Great Britain"]}},{"k":"multi","i":"Select all the films directed by Christopher Nolan.","t":"Nolan","e":"\ud83c\udf00","f":"Avatar is by James Cameron, Gravity by Alfonso Cuar\u00f3n and Up by Pete Docter.","o":["Inception","Avatar","Memento","Gravity","Interstellar","Up"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these Steven Spielberg films from oldest to newest.","t":"Spielberg","e":"\ud83c\udf9e\ufe0f","f":"They were released in 1975, 1982, 1993 and 2002.","o":["Jaws","E.T. the Extra-Terrestrial","Jurassic Park","Catch Me If You Can"]}]},{"slug":"spices-coffee-tea","title":"Spices, Coffee & Tea","tagline":"From saffron threads to espresso shots: how well do you know your pantry?","emoji":"\u2615","gradient":["#b45309","#b91c1c"],"categories":["food","nature","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":222,"items":[{"k":"choice","i":"Which spice is the most expensive by weight?","t":"Spices","e":"\ud83c\udf38","f":"Saffron threads are the hand-picked stigmas of a crocus flower, and each flower has only three.","o":["Vanilla","Cardamom","Saffron","Cinnamon"],"s":{"index":2}},{"k":"choice","i":"Cinnamon comes from which part of a tree?","t":"Spices","e":"\ud83c\udf33","f":"Cinnamon sticks are strips of inner bark that curl up into 'quills' as they dry.","o":["Bark","Seeds","Roots","Flowers"],"s":{"index":0}},{"k":"choice","i":"Vanilla comes from the pods of which kind of plant?","t":"Spices","e":"\ud83c\udf3a","f":"Vanilla is native to Mexico; outside its homeland, its flowers are usually pollinated by hand.","o":["A palm","An orchid","A cactus","A bean bush"],"s":{"index":1}},{"k":"choice","i":"Which country is famous for paprika, a spice made from ground dried peppers?","t":"Spices","e":"\ud83c\udf36\ufe0f","f":"Hungarian scientist Albert Szent-Gy\u00f6rgyi used paprika peppers to isolate vitamin C and won a Nobel Prize in 1937.","o":["India","Morocco","Thailand","Hungary"],"s":{"index":3}},{"k":"choice","i":"Legend says coffee was discovered when a goatherd saw his goats dancing. In which country?","t":"Coffee","e":"\ud83d\udc10","f":"The legend names the goatherd Kaldi, and coffee plants still grow wild in Ethiopia's forests.","o":["Yemen","Ethiopia","Brazil","Colombia"],"s":{"index":1}},{"k":"choice","i":"Cappuccino is named after the colour of the robes worn by which group?","t":"Coffee","e":"\u2615","f":"The milky brown colour of the drink reminded people of the hooded habits of Capuchin friars.","o":["Roman senators","Venetian gondoliers","Capuchin friars","Swiss guards"],"s":{"index":2}},{"k":"truefalse","i":"Rooibos tea is made from the same plant as green tea.","t":"Tea","e":"\ud83c\udf75","f":"Rooibos comes from a South African shrub and is naturally caffeine-free; true teas come from Camellia sinensis.","a":false},{"k":"truefalse","i":"Coffee beans are actually the seeds of a fruit.","t":"Coffee","e":"\ud83c\udf52","f":"Coffee grows inside red or yellow 'coffee cherries', and each cherry usually holds two seeds.","a":true},{"k":"multi","i":"Select all the drinks made from the tea plant (Camellia sinensis).","t":"Tea","e":"\ud83e\uded6","f":"Earl Grey is black tea flavoured with oil from bergamot, a fragrant citrus fruit.","o":["Matcha","Oolong","Chamomile","Earl Grey","Peppermint tea"],"s":{"indices":[0,1,3]}},{"k":"multi","i":"Select all the spices that are seeds.","t":"Spices","e":"\ud83c\udf30","f":"Nutmeg is the seed of a tropical tree; the lacy red covering around it is dried to make mace.","o":["Nutmeg","Cinnamon","Mustard","Cloves","Saffron"],"s":{"indices":[0,2]}},{"k":"text","i":"Which country's coffee culture gave the world the espresso and the cappuccino?","t":"Coffee","e":"\u2615","f":"Luigi Bezzera patented an early espresso machine in Milan in 1901.","s":{"accepted":["Italy","Italia"]}},{"k":"text","i":"What South American drink is sipped from a gourd through a metal straw called a bombilla?","t":"Drinks","e":"\ud83e\uddc9","f":"Mate is shared among friends in Argentina, Uruguay, Paraguay and southern Brazil.","s":{"accepted":["Mate","Mat\u00e9","Yerba mate","Yerba mat\u00e9","Chimarr\u00e3o"]}},{"k":"number","i":"In what year did the Boston Tea Party take place?","t":"History","e":"\ud83d\udce6","f":"Protesters emptied 342 chests of tea into Boston Harbor on 16 December 1773.","s":{"value":1773,"tolerance":0,"min":1700,"max":1800,"unit":""}},{"k":"order","i":"Order these chillies from mildest to hottest.","t":"Chillies","e":"\ud83c\udf36\ufe0f","f":"Chilli heat is measured in Scoville Heat Units, named after pharmacist Wilbur Scoville, who devised his test in 1912.","o":["Bell pepper","Jalape\u00f1o","Habanero","Carolina Reaper"]}]},{"slug":"world-cup-chronicles","title":"World Cup Chronicles","tagline":"Winners, hosts and legends of football's biggest stage, from 1930 to 2018.","emoji":"\ud83c\udfc6","gradient":["#16a34a","#0f766e"],"categories":["football","sports","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":223,"items":[{"k":"choice","i":"Which country won the very first FIFA World Cup?","t":"Winners","e":"\ud83c\uddfa\ud83c\uddfe","f":"Uruguay hosted and won the first World Cup, beating Argentina 4\u20132 in the final in Montevideo.","o":["Brazil","Italy","Uruguay","Argentina"],"s":{"index":2}},{"k":"number","i":"How many World Cups had Brazil won by the end of the 2018 tournament?","t":"Winners","e":"\ud83c\udde7\ud83c\uddf7","f":"Brazil won in 1958, 1962, 1970, 1994 and 2002, and is the only nation to have played at every World Cup.","s":{"value":5,"tolerance":0,"min":0,"max":10,"unit":""}},{"k":"choice","i":"Which country hosted the 2010 World Cup, the first held in Africa?","t":"Hosts","e":"\ud83c\udf0d","f":"Spain won the 2010 final against the Netherlands with an extra-time goal from Andr\u00e9s Iniesta.","o":["Nigeria","Egypt","Morocco","South Africa"],"s":{"index":3}},{"k":"truefalse","i":"The 2002 World Cup was co-hosted by Japan and South Korea.","t":"Hosts","e":"\ud83e\udd1d","f":"It was the first World Cup held in Asia and the first with two host nations.","a":true},{"k":"choice","i":"Which country won the 1966 World Cup on home soil?","t":"Winners","e":"\ud83c\udff4","f":"Geoff Hurst scored a hat-trick in the 1966 final as England beat West Germany 4\u20132 after extra time.","o":["Brazil","Portugal","England","West Germany"],"s":{"index":2}},{"k":"order","i":"Order these World Cup host countries from earliest to most recent tournament.","t":"Hosts","e":"\ud83d\udcc5","f":"Switzerland 1954 was the first World Cup to be shown on television.","o":["Switzerland","Chile","Spain","South Africa"]},{"k":"text","i":"Which country won the 2014 World Cup in Brazil?","t":"Winners","e":"\ud83c\udde9\ud83c\uddea","f":"Germany beat hosts Brazil 7\u20131 in the semi-final, then beat Argentina 1\u20130 in the final.","s":{"accepted":["Germany"]}},{"k":"choice","i":"Which player scored twice in the 1998 World Cup final as France beat Brazil 3\u20130?","t":"Legends","e":"\u26bd","f":"Zidane's two goals were both headers from corners, and Emmanuel Petit added the third.","o":["Didier Deschamps","Zinedine Zidane","Thierry Henry","Emmanuel Petit"],"s":{"index":1}},{"k":"multi","i":"Select all the countries that won the World Cup between 1930 and 2018.","t":"Winners","e":"\ud83c\udfc6","f":"Through 2018, Hungary had reached two finals and the Netherlands three, without winning either.","o":["Uruguay","Argentina","Netherlands","Spain","Portugal","Hungary"],"s":{"indices":[0,1,3]}},{"k":"choice","i":"Which player led Argentina to the 1986 World Cup and scored the famous 'Hand of God' goal?","t":"Legends","e":"\ud83c\udde6\ud83c\uddf7","f":"Minutes after the 'Hand of God', Maradona scored a solo goal against England later voted the 'Goal of the Century'.","o":["Gabriel Batistuta","Mario Kempes","Diego Maradona","Lionel Messi"],"s":{"index":2}},{"k":"truefalse","i":"Pel\u00e9 won the World Cup three times as a player.","t":"Legends","e":"\ud83d\udc51","f":"Pel\u00e9 won in 1958, 1962 and 1970, and is the only player with three World Cup winner's medals.","a":true},{"k":"multi","i":"Select all the countries that hosted the World Cup twice between 1930 and 2018.","t":"Hosts","e":"\ud83c\udfdf\ufe0f","f":"Mexico hosted in 1970 and 1986, and Italy in 1934 and 1990.","o":["England","Argentina","Italy","Mexico","Spain"],"s":{"indices":[2,3]}},{"k":"number","i":"In what year was the first FIFA World Cup played?","t":"History","e":"\ud83d\udcc6","f":"Only 13 teams took part in the first World Cup, as most European sides declined the long sea voyage to Uruguay.","s":{"value":1930,"tolerance":0,"min":1900,"max":1960,"unit":""}},{"k":"choice","i":"Which country won the 2018 World Cup in Russia?","t":"Winners","e":"\ud83c\uddeb\ud83c\uddf7","f":"France beat Croatia 4\u20132 in the final in Moscow; it was Croatia's first ever World Cup final.","o":["Croatia","Belgium","France","England"],"s":{"index":2}}]},{"slug":"world-geography-extremes","title":"Earth's Extremes","tagline":"The biggest, smallest, deepest and lowest places on the planet.","emoji":"\ud83c\udf0d","gradient":["#0d9488","#1e3a8a"],"categories":["geo","general"],"countries":null,"difficulty":"Hard","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":224,"items":[{"k":"choice","i":"What is the largest country in the world by area?","t":"Countries","e":"\ud83d\uddfa\ufe0f","f":"Russia covers more than 17 million square kilometres, over a ninth of all the land on Earth.","o":["Canada","China","United States","Russia"],"s":{"index":3}},{"k":"number","i":"How many time zones does Russia span?","t":"Countries","e":"\ud83d\udd70\ufe0f","f":"When it is morning in Kaliningrad in the west, it is already evening on Russia's Pacific coast.","s":{"value":11,"tolerance":0,"min":1,"max":20,"unit":"time zones"}},{"k":"choice","i":"What is the smallest country in the world by area?","t":"Countries","e":"\ud83d\udccd","f":"Vatican City covers less than half a square kilometre, smaller than many city parks.","o":["Monaco","Vatican City","San Marino","Liechtenstein"],"s":{"index":1}},{"k":"choice","i":"Where is the lowest point on dry land on Earth?","t":"Low points","e":"\u2b07\ufe0f","f":"The shore of the Dead Sea lies more than 400 m below sea level.","o":["The Dead Sea shore","Death Valley","Lake Assal","Caspian Depression"],"s":{"index":0}},{"k":"text","i":"What is the name of the deepest ocean trench on Earth?","t":"Oceans","e":"\ud83c\udf0a","f":"The trench's deepest point, Challenger Deep, lies nearly 11 km below the surface of the Pacific.","s":{"accepted":["Mariana Trench","Marianas Trench","The Mariana Trench","Mariana","Challenger Deep"]}},{"k":"choice","i":"Which is the largest island in the world (not counting continents)?","t":"Islands","e":"\ud83c\udfdd\ufe0f","f":"Greenland covers more than 2 million square kilometres, and most of it is buried under an ice sheet.","o":["New Guinea","Borneo","Greenland","Madagascar"],"s":{"index":2}},{"k":"choice","i":"Which body of water is the largest lake in the world by surface area?","t":"Lakes","e":"\ud83c\udfde\ufe0f","f":"Despite its name, the Caspian Sea is generally considered the world's largest lake.","o":["Lake Superior","Lake Victoria","Lake Baikal","Caspian Sea"],"s":{"index":3}},{"k":"number","i":"Lake Baikal in Russia is the world's deepest lake. Roughly how deep is it, in metres?","t":"Lakes","e":"\ud83e\udd3f","f":"Lake Baikal holds about a fifth of the world's unfrozen fresh surface water.","s":{"value":1642,"tolerance":100,"min":500,"max":3000,"unit":"m"}},{"k":"multi","i":"Select all the landlocked countries.","t":"Countries","e":"\ud83e\udded","f":"Paraguay and Bolivia are the only landlocked countries in South America.","o":["Switzerland","Nepal","Portugal","Paraguay","Vietnam"],"s":{"indices":[0,1,3]}},{"k":"order","i":"Order these continents from largest to smallest by area.","t":"Continents","e":"\ud83c\udf10","f":"Asia covers about 30% of Earth's land area.","o":["Asia","Africa","North America","South America","Antarctica"]},{"k":"choice","i":"Which country has the longest coastline in the world?","t":"Coastlines","e":"\ud83c\udfd6\ufe0f","f":"Canada's coastline is over 200,000 km long, thanks to its thousands of islands.","o":["Australia","Canada","Russia","Norway"],"s":{"index":1}},{"k":"truefalse","i":"The summit of Mount Everest is the point on Earth's surface farthest from Earth's centre.","t":"Mountains","e":"\ud83c\udfd4\ufe0f","f":"Earth bulges at the equator, so the summit of Chimborazo in Ecuador is the farthest point from Earth's centre.","a":false},{"k":"choice","i":"Which waterfall has the highest uninterrupted drop in the world?","t":"Waterfalls","e":"\ud83d\udca6","f":"Angel Falls in Venezuela drops 979 m in total, including a single uninterrupted plunge of about 807 m.","o":["Niagara Falls","Victoria Falls","Angel Falls","Iguazu Falls"],"s":{"index":2}}]},{"slug":"classic-novel-club","title":"Classic Novel Club","tagline":"Monsters, whales and ballrooms: how well do you know the great novels?","emoji":"\ud83d\udcda","gradient":["#b45309","#7c2d12"],"categories":["literature"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":225,"items":[{"k":"order","i":"Order these novels by first publication, oldest first.","t":"Timeline","e":"\ud83d\udd70\ufe0f","f":"1605, 1726, 1818, 1862 and 1949: more than three centuries of storytelling.","o":["Don Quixote (Part One)","Gulliver's Travels","Frankenstein","Les Mis\u00e9rables","Nineteen Eighty-Four"]},{"k":"choice","i":"Who wrote 'Pride and Prejudice'?","t":"Authors","e":"\ud83d\udc83","f":"Published in 1813, it was first sold simply as 'by the author of Sense and Sensibility'.","o":["Charlotte Bront\u00eb","Mary Shelley","Jane Austen","George Eliot"],"s":{"index":2}},{"k":"text","i":"'Call me Ishmael' is the opening line of which Herman Melville novel?","t":"First lines","e":"\ud83d\udc0b","f":"Published in 1851, Moby-Dick sold poorly in Melville's lifetime and is now considered a masterpiece.","s":{"accepted":["Moby-Dick","Moby Dick","Moby-Dick; or, The Whale","Moby Dick or The Whale","The Whale"]}},{"k":"truefalse","i":"In Mary Shelley's novel, 'Frankenstein' is the name of the monster.","t":"Characters","e":"\ud83e\udddf","f":"Victor Frankenstein is the young scientist; the creature he makes is never given a name.","a":false},{"k":"choice","i":"Which Russian author wrote 'War and Peace'?","t":"Authors","e":"\ud83c\uddf7\ud83c\uddfa","f":"Tolstoy's epic first appeared in instalments and was published in full as a book in 1869.","o":["Fyodor Dostoevsky","Leo Tolstoy","Anton Chekhov","Ivan Turgenev"],"s":{"index":1}},{"k":"choice","i":"In Franz Kafka's 'The Metamorphosis', Gregor Samsa wakes up transformed into what?","t":"Plots","e":"\ud83e\udeb2","f":"Kafka's 1915 novella never says exactly what creature Gregor becomes, only a monstrous kind of vermin.","o":["A wolf","A statue","A bird","A giant insect"],"s":{"index":3}},{"k":"multi","i":"Select all the novels written by Charles Dickens.","t":"Authors","e":"\ud83c\udfa9","f":"Most of Dickens's novels first appeared in weekly or monthly instalments, often ending on cliffhangers.","o":["Vanity Fair","Great Expectations","Jane Eyre","A Tale of Two Cities","Oliver Twist"],"s":{"indices":[1,3,4]}},{"k":"number","i":"In Jules Verne's famous novel, Phileas Fogg bets he can go around the world in how many days?","t":"Plots","e":"\ud83c\udf88","f":"Verne's 1872 story was inspired by new travel links such as the Suez Canal and America's transcontinental railroad.","s":{"value":80,"tolerance":0,"min":10,"max":200,"unit":"days"}},{"k":"choice","i":"Which novel features Captain Nemo and his submarine, the Nautilus?","t":"Plots","e":"\ud83c\udf0a","f":"The 'twenty thousand leagues' is the distance travelled under the sea, not the depth reached.","o":["Treasure Island","The Time Machine","Twenty Thousand Leagues Under the Sea","Robinson Crusoe"],"s":{"index":2}},{"k":"choice","i":"Who wrote 'One Hundred Years of Solitude'?","t":"Authors","e":"\ud83e\udd8b","f":"Published in 1967, it follows seven generations of the Buend\u00eda family in the fictional town of Macondo.","o":["Jorge Luis Borges","Isabel Allende","Pablo Neruda","Gabriel Garc\u00eda M\u00e1rquez"],"s":{"index":3}},{"k":"text","i":"Which Irish author created Count Dracula?","t":"Authors","e":"\ud83e\udddb","f":"Stoker's 'Dracula' (1897) is told through letters, diary entries and newspaper clippings.","s":{"accepted":["Bram Stoker","Stoker","Abraham Stoker"]}},{"k":"choice","i":"In 'Gulliver's Travels', what is the name of the land of tiny people?","t":"Places","e":"\ud83d\udd2d","f":"The word 'Lilliputian', meaning very small, entered English thanks to Jonathan Swift's satire.","o":["Lilliput","Narnia","Neverland","Oz"],"s":{"index":0}},{"k":"truefalse","i":"The Bront\u00eb sisters first published their work under male-sounding pen names.","t":"Authors","e":"\ud83d\udd8b\ufe0f","f":"They wrote as Currer, Ellis and Acton Bell; 'Jane Eyre' and 'Wuthering Heights' both came out in 1847.","a":true},{"k":"choice","i":"Which Harper Lee novel is narrated by a young girl nicknamed Scout?","t":"Narrators","e":"\ud83d\udd4a\ufe0f","f":"Published in 1960, it won the Pulitzer Prize for Fiction the following year.","o":["Little Women","To Kill a Mockingbird","The Catcher in the Rye","Of Mice and Men"],"s":{"index":1}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '0a0923bec66ce87fdba80d44c6b83edc' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 3'; end $q$;
do $q$ declare d text := $d$[{"slug":"maestro-mix","title":"Maestro Mix","tagline":"Bach to Tchaikovsky: a quick tour of classical music's greatest names.","emoji":"\ud83c\udfbc","gradient":["#6d28d9","#be185d"],"categories":["music","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":226,"items":[{"k":"choice","i":"Which composer kept writing music after becoming almost completely deaf?","t":"Composers","e":"\ud83d\udc42","f":"Beethoven composed his famous Ninth Symphony while profoundly deaf.","o":["Mozart","Bach","Beethoven","Haydn"],"s":{"index":2}},{"k":"choice","i":"In which city was Wolfgang Amadeus Mozart born?","t":"Composers","e":"\ud83c\udfd9\ufe0f","f":"Mozart was born in Salzburg in 1756 and was performing for royalty as a young child.","o":["Vienna","Salzburg","Prague","Munich"],"s":{"index":1}},{"k":"choice","i":"Who composed the set of violin concertos known as 'The Four Seasons'?","t":"Baroque","e":"\ud83c\udf42","f":"Antonio Vivaldi was a Venetian priest nicknamed 'il Prete Rosso', the Red Priest, for his red hair.","o":["Handel","Corelli","Telemann","Vivaldi"],"s":{"index":3}},{"k":"choice","i":"Fr\u00e9d\u00e9ric Chopin wrote almost all of his music for which instrument?","t":"Romantic Era","e":"\ud83c\udfb9","f":"Chopin was born in Poland in 1810, and nearly every one of his works includes the piano.","o":["Violin","Piano","Cello","Organ"],"s":{"index":1}},{"k":"choice","i":"Who composed the opera 'Carmen'?","t":"Opera","e":"\ud83d\udc83","f":"Carmen is set in Seville and premiered in Paris in 1875.","o":["Georges Bizet","Giuseppe Verdi","Claude Debussy","Maurice Ravel"],"s":{"index":0}},{"k":"choice","i":"Who composed 'The Blue Danube' waltz?","t":"Waltz","e":"\ud83c\udf0a","f":"Strauss was nicknamed 'the Waltz King'; The Blue Danube premiered in Vienna in 1867.","o":["Franz Schubert","Franz Liszt","Anton\u00edn Dvo\u0159\u00e1k","Johann Strauss II"],"s":{"index":3}},{"k":"number","i":"How many symphonies did Ludwig van Beethoven complete?","t":"Beethoven","e":"\ud83c\udfbb","f":"His Ninth ends with the 'Ode to Joy', whose melody became the anthem of the European Union.","s":{"value":9,"tolerance":0,"min":1,"max":20,"unit":""}},{"k":"text","i":"Which Russian composer wrote the ballets 'Swan Lake' and 'The Nutcracker'?","t":"Ballet","e":"\ud83e\ude70","f":"The Nutcracker premiered in St Petersburg in 1892 and is now a Christmas tradition worldwide.","s":{"accepted":["Tchaikovsky","Pyotr Ilyich Tchaikovsky","Tchaikovski","Tschaikowsky","Chaikovsky","Peter Tchaikovsky"]}},{"k":"text","i":"Which piano virtuoso and composer was born in the Kingdom of Hungary in 1811?","t":"Composers","e":"\ud83c\udded\ud83c\uddfa","f":"Liszt wrote 19 Hungarian Rhapsodies, and Budapest's main airport is named after him.","s":{"accepted":["Franz Liszt","Liszt","Liszt Ferenc","Ferenc Liszt"]}},{"k":"truefalse","i":"Johann Sebastian Bach and George Frideric Handel were both born in 1685.","t":"Baroque","e":"\ud83c\udf82","f":"Both were born in Germany in 1685, only weeks apart, though as far as we know they never met.","a":true},{"k":"truefalse","i":"Wolfgang Amadeus Mozart lived to be over 60 years old.","t":"Mozart","e":"\u23f3","f":"Mozart died in 1791 at just 35, yet left more than 600 works.","a":false},{"k":"multi","i":"Select all the Italian composers.","t":"Opera","e":"\ud83c\uddee\ud83c\uddf9","f":"Wagner was German and Bizet was French.","o":["Giuseppe Verdi","Richard Wagner","Giacomo Puccini","Georges Bizet","Gioachino Rossini"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these composers by year of birth, earliest first.","t":"Timeline","e":"\ud83d\udcdc","f":"Bach was born in 1685, Mozart in 1756, Beethoven in 1770, Chopin in 1810 and Tchaikovsky in 1840.","o":["Johann Sebastian Bach","Wolfgang Amadeus Mozart","Ludwig van Beethoven","Fr\u00e9d\u00e9ric Chopin","Pyotr Ilyich Tchaikovsky"]}]},{"slug":"wonders-and-landmarks","title":"Wonders & Landmarks","tagline":"Pyramids, towers and temples: tour the planet's most famous sights.","emoji":"\ud83d\uddfd","gradient":["#0891b2","#4f46e5"],"categories":["travel","history","geo"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":227,"items":[{"k":"choice","i":"Which is the only one of the Seven Wonders of the Ancient World still standing?","t":"Ancient wonders","e":"\ud83d\udd3a","f":"The Great Pyramid was the tallest human-made structure on Earth for more than 3,800 years.","o":["Colossus of Rhodes","Great Pyramid of Giza","Lighthouse of Alexandria","Hanging Gardens of Babylon"],"s":{"index":1}},{"k":"choice","i":"The Statue of Liberty was a gift to the USA from which country?","t":"USA","e":"\ud83d\uddfd","f":"The statue was dedicated in 1886, and its iron framework was designed by Gustave Eiffel.","o":["United Kingdom","Spain","France","Italy"],"s":{"index":2}},{"k":"choice","i":"Machu Picchu, the Inca citadel high in the Andes, is in which country?","t":"South America","e":"\u26f0\ufe0f","f":"Machu Picchu was built in the 15th century and was brought to world attention by Hiram Bingham in 1911.","o":["Bolivia","Chile","Ecuador","Peru"],"s":{"index":3}},{"k":"choice","i":"The ancient city of Petra, carved into rose-red rock, is in which country?","t":"Middle East","e":"\ud83c\udfdc\ufe0f","f":"Petra was built by the Nabataeans, who carved its tombs and temples straight into sandstone cliffs.","o":["Jordan","Egypt","Turkey","Morocco"],"s":{"index":0}},{"k":"choice","i":"Who designed the Sydney Opera House?","t":"Architecture","e":"\ud83c\udfad","f":"Danish architect J\u00f8rn Utzon won the design competition in 1957, and the Opera House opened in 1973.","o":["Frank Gehry","J\u00f8rn Utzon","Le Corbusier","Zaha Hadid"],"s":{"index":1}},{"k":"choice","i":"Emperor Shah Jahan built the Taj Mahal in memory of whom?","t":"India","e":"\ud83d\udd4c","f":"The white marble mausoleum in Agra honours Mumtaz Mahal and took around 20 years to complete.","o":["His mother","His daughter","His wife","His teacher"],"s":{"index":2}},{"k":"choice","i":"The giant Christ the Redeemer statue overlooks which city?","t":"Brazil","e":"\u26ea","f":"The Art Deco statue was completed in 1931 on top of Corcovado mountain.","o":["S\u00e3o Paulo","Rio de Janeiro","Buenos Aires","Lisbon"],"s":{"index":1}},{"k":"truefalse","i":"'Big Ben' is officially the name of the clock tower in London.","t":"London","e":"\ud83d\udd14","f":"Big Ben is the nickname of the Great Bell inside; the tower was renamed Elizabeth Tower in 2012.","a":false},{"k":"multi","i":"Select all the landmarks found in Italy.","t":"Italy","e":"\ud83c\udfdb\ufe0f","f":"The Leaning Tower of Pisa is a bell tower that began to tilt while it was still being built in the 12th century.","o":["Leaning Tower of Pisa","Sagrada Fam\u00edlia","Colosseum","Acropolis","Trevi Fountain"],"s":{"indices":[0,2,4]}},{"k":"text","i":"On which Chilean island would you find the giant moai statues?","t":"Statues","e":"\ud83d\uddff","f":"Nearly 1,000 moai were carved on Rapa Nui, most of them from volcanic rock at the Rano Raraku quarry.","s":{"accepted":["Easter Island","Rapa Nui","Isla de Pascua"]}},{"k":"number","i":"How many presidents' faces are carved into Mount Rushmore?","t":"USA","e":"\ud83c\udfd4\ufe0f","f":"Washington, Jefferson, Theodore Roosevelt and Lincoln each have faces about 18 metres tall.","s":{"value":4,"tolerance":0,"min":1,"max":10,"unit":""}},{"k":"number","i":"The Eiffel Tower opened for the 1889 World's Fair. About how tall was it then, in metres?","t":"Paris","e":"\ud83d\uddfc","f":"It was about 300 m tall in 1889; antennas added over the years have raised it to around 330 m.","s":{"value":300,"tolerance":15,"min":100,"max":600,"unit":"m"}},{"k":"order","i":"Order these landmarks from oldest to newest.","t":"Timeline","e":"\u23f3","f":"More than 4,500 years separate the Great Pyramid from the Sydney Opera House.","o":["Great Pyramid of Giza","Colosseum","Taj Mahal","Eiffel Tower","Sydney Opera House"]}]},{"slug":"clubs-and-stadiums","title":"Clubs & Stadiums","tagline":"From Anfield to the Bernab\u00e9u: do you know football's giants and their homes?","emoji":"\u26bd","gradient":["#dc2626","#7c2d12"],"categories":["football","sports","travel"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":228,"items":[{"k":"choice","i":"Which club plays its home games at Anfield?","t":"Stadiums","e":"\ud83c\udff4","f":"Anfield was originally Everton's home ground, before Liverpool FC was formed there in 1892.","o":["Manchester United","Arsenal","Liverpool","Everton"],"s":{"index":2}},{"k":"choice","i":"The Santiago Bernab\u00e9u Stadium is home to which club?","t":"Stadiums","e":"\ud83c\uddea\ud83c\uddf8","f":"The stadium is named after Santiago Bernab\u00e9u, a former player who was Real Madrid's president for 35 years.","o":["Real Madrid","Sevilla","FC Barcelona","Atl\u00e9tico Madrid"],"s":{"index":0}},{"k":"text","i":"Which city is home to both AC Milan and Inter, who share the San Siro stadium?","t":"Cities","e":"\ud83c\uddee\ud83c\uddf9","f":"San Siro's official name is Stadio Giuseppe Meazza, after a striker who played for both clubs.","s":{"accepted":["Milan","Milano"]}},{"k":"choice","i":"Camp Nou is the home stadium of which club?","t":"Stadiums","e":"\ud83c\udfdf\ufe0f","f":"Camp Nou means 'new field' in Catalan, and the stadium first opened in 1957.","o":["FC Barcelona","Valencia","Espanyol","Real Betis"],"s":{"index":0}},{"k":"choice","i":"Which German club plays at the Allianz Arena, whose outside can glow red?","t":"Stadiums","e":"\ud83c\udde9\ud83c\uddea","f":"The Allianz Arena's outer shell is made of inflated plastic panels that can be lit in different colours.","o":["Bayern Munich","Hamburger SV","Borussia Dortmund","Schalke 04"],"s":{"index":0}},{"k":"truefalse","i":"Old Trafford is the home ground of Manchester City.","t":"Stadiums","e":"\ud83d\udd34","f":"Old Trafford belongs to Manchester United and is nicknamed 'The Theatre of Dreams'.","a":false},{"k":"choice","i":"Which Italian club is nicknamed 'The Old Lady' (La Vecchia Signora)?","t":"Nicknames","e":"\ud83d\udc75","f":"Juventus is based in Turin, and its black-and-white stripes were inspired by the kit of England's Notts County.","o":["AS Roma","Juventus","Napoli","Lazio"],"s":{"index":1}},{"k":"multi","i":"Select all the clubs based in London.","t":"Cities","e":"\ud83c\uddec\ud83c\udde7","f":"Aston Villa play in Birmingham and Everton in Liverpool.","o":["Tottenham Hotspur","Chelsea","Everton","Arsenal","Aston Villa"],"s":{"indices":[0,1,3]}},{"k":"choice","i":"Which Dutch club plays at the Johan Cruyff Arena?","t":"Stadiums","e":"\ud83c\uddf3\ud83c\uddf1","f":"The Amsterdam stadium was renamed in 2018 to honour Johan Cruyff, Ajax's most famous player.","o":["AZ Alkmaar","Feyenoord","Ajax","PSV Eindhoven"],"s":{"index":2}},{"k":"order","i":"Order these clubs from oldest to youngest by founding year.","t":"History","e":"\ud83d\udcdc","f":"Sheffield FC, founded in 1857, is recognised by FIFA as the world's oldest football club.","o":["Sheffield FC","Juventus","FC Barcelona","Real Madrid","Inter Milan"]},{"k":"choice","i":"Which Argentine club plays at La Bombonera?","t":"Stadiums","e":"\ud83c\udde6\ud83c\uddf7","f":"La Bombonera means 'the chocolate box', a nickname inspired by the stadium's steep, boxy shape.","o":["Boca Juniors","River Plate","Racing Club","Independiente"],"s":{"index":0}},{"k":"text","i":"Which Portuguese club is nicknamed 'The Eagles' and plays at the Est\u00e1dio da Luz?","t":"Nicknames","e":"\ud83e\udd85","f":"A live eagle named Vit\u00f3ria traditionally flies around the Est\u00e1dio da Luz before Benfica's home matches.","s":{"accepted":["Benfica","SL Benfica","S.L. Benfica"]}},{"k":"number","i":"In what year did the original Wembley Stadium open, in time for the FA Cup final?","t":"Stadiums","e":"\ud83d\udc0e","f":"The 1923 FA Cup final is called the 'White Horse Final' after a police horse helped clear the overcrowded pitch.","s":{"value":1923,"tolerance":0,"min":1880,"max":1960,"unit":""}},{"k":"truefalse","i":"Borussia Dortmund's stadium is famous for a huge standing terrace called the 'Yellow Wall'.","t":"Fans","e":"\ud83d\udc9b","f":"The S\u00fcdtrib\u00fcne, or 'Yellow Wall', is one of the largest standing terraces in European football, holding around 25,000 fans.","a":true}]},{"slug":"deserts-and-volcanoes","title":"Deserts & Volcanoes","tagline":"Scorching sands and fiery peaks: how hot is your knowledge?","emoji":"\ud83c\udf0b","gradient":["#f97316","#b91c1c"],"categories":["geo","nature","science"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":229,"items":[{"k":"truefalse","i":"The Sahara is the largest desert in the world.","t":"Deserts","e":"\ud83c\udfdc\ufe0f","f":"Antarctica is the largest desert, because deserts are defined by low rainfall; the Sahara is the largest hot desert.","a":false},{"k":"choice","i":"Which is the driest non-polar desert on Earth?","t":"Deserts","e":"\u2600\ufe0f","f":"Parts of Chile's Atacama Desert receive less than 1 mm of rain a year.","o":["Gobi","Atacama","Kalahari","Mojave"],"s":{"index":1}},{"k":"choice","i":"The Gobi Desert lies mainly in Mongolia and which other country?","t":"Deserts","e":"\ud83d\udc2b","f":"The Gobi is a cold desert, where winter temperatures can fall below -40 \u00b0C.","o":["Kazakhstan","Russia","India","China"],"s":{"index":3}},{"k":"choice","i":"Mount Vesuvius famously buried which Roman city in AD 79?","t":"Volcanoes","e":"\ud83c\udfdb\ufe0f","f":"Volcanic ash preserved Pompeii so well that archaeologists have even found loaves of bread turned to carbon.","o":["Pompeii","Rome","Carthage","Ostia"],"s":{"index":0}},{"k":"text","i":"What is molten rock called once it erupts onto Earth's surface?","t":"Volcanoes","e":"\ud83d\udd25","f":"Underground, molten rock is called magma; once it reaches the surface, it is called lava.","s":{"accepted":["Lava"]}},{"k":"choice","i":"The 'Ring of Fire', a belt of volcanoes and earthquakes, surrounds which ocean?","t":"Volcanoes","e":"\ud83d\udc8d","f":"About 75% of Earth's volcanoes lie along the Pacific Ring of Fire.","o":["Atlantic","Indian","Pacific","Arctic"],"s":{"index":2}},{"k":"choice","i":"Which Hawaiian volcano is the largest active volcano on Earth?","t":"Volcanoes","e":"\ud83c\udf3a","f":"Mauna Loa makes up about half of the Island of Hawaii, the 'Big Island'.","o":["Mauna Loa","Kilauea","Mauna Kea","Haleakala"],"s":{"index":0}},{"k":"multi","i":"Select all the deserts found in Africa.","t":"Deserts","e":"\ud83c\udf0d","f":"The Namib is thought to be one of the oldest deserts on Earth, at least 55 million years old.","o":["Sahara","Kalahari","Gobi","Namib","Atacama"],"s":{"indices":[0,1,3]}},{"k":"number","i":"In what year did Mount St. Helens erupt in Washington State, USA?","t":"Volcanoes","e":"\ud83c\udf0b","f":"The eruption on 18 May 1980 blew about 400 m off the top of the mountain.","s":{"value":1980,"tolerance":0,"min":1950,"max":2010,"unit":""}},{"k":"multi","i":"Select all the countries that the Sahara Desert extends into.","t":"Deserts","e":"\ud83d\uddfa\ufe0f","f":"The Sahara stretches across North Africa from the Atlantic coast to the Red Sea.","o":["Egypt","Kenya","Algeria","South Africa","Libya"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these deserts from largest to smallest by area.","t":"Deserts","e":"\ud83d\udccf","f":"The Sahara covers roughly 9 million square kilometres, about the size of China or the United States.","o":["Sahara","Arabian","Gobi","Kalahari"]},{"k":"choice","i":"What is the name for a huge bowl-shaped hollow formed when a volcano collapses into its emptied magma chamber?","t":"Volcanoes","e":"\ud83e\udd63","f":"Crater Lake in Oregon fills a caldera formed when a volcano collapsed about 7,700 years ago.","o":["Fumarole","Geyser","Dyke","Caldera"],"s":{"index":3}},{"k":"text","i":"Which desert animal, nicknamed the 'ship of the desert', stores fat in its hump?","t":"Desert animals","e":"\ud83d\udc2a","f":"A camel's hump stores fat, not water, which the camel can use for energy when food is scarce.","s":{"accepted":["Camel","Camels","Dromedary","Bactrian camel","A camel"]}}]},{"slug":"to-quiz-or-not-to-quiz","title":"To Quiz or Not to Quiz","tagline":"Ghosts, witches and star-crossed lovers: test your Shakespeare smarts.","emoji":"\ud83c\udfad","gradient":["#831843","#6d28d9"],"categories":["literature","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":230,"items":[{"k":"choice","i":"In which town was William Shakespeare born?","t":"His life","e":"\ud83c\udfe1","f":"He was baptised there on 26 April 1564; his birthday is traditionally celebrated on 23 April.","o":["Stratford-upon-Avon","Oxford","Canterbury","Bath"],"s":{"index":0}},{"k":"multi","i":"Select all the plays that are tragedies.","t":"Genres","e":"\ud83d\udc80","f":"Hamlet, Macbeth, King Lear and Othello are often called Shakespeare's four great tragedies.","o":["A Midsummer Night's Dream","Twelfth Night","Hamlet","Macbeth","King Lear"],"s":{"indices":[2,3,4]}},{"k":"choice","i":"'To be, or not to be, that is the question' is spoken by which character?","t":"Famous lines","e":"\ud83e\udd14","f":"Hamlet is Shakespeare's longest play, and its title role is the biggest part he ever wrote.","o":["Macbeth","Hamlet","Romeo","Othello"],"s":{"index":1}},{"k":"choice","i":"In which Italian city is 'Romeo and Juliet' set?","t":"Settings","e":"\ud83c\udf39","f":"Visitors to Verona flock to a house with a balcony known as 'Juliet's House', though the story is fiction.","o":["Verona","Venice","Florence","Rome"],"s":{"index":0}},{"k":"number","i":"How many lines does a Shakespearean sonnet have?","t":"Poetry","e":"\ud83d\udcdc","f":"His sonnets end with a rhyming couplet, and those last two lines often deliver a twist.","s":{"value":14,"tolerance":0,"min":4,"max":30,"unit":"lines"}},{"k":"text","i":"What was the name of Shakespeare's famous open-air theatre in London, built in 1599?","t":"Theatre","e":"\ud83c\udf0d","f":"A modern reconstruction, Shakespeare's Globe, opened in 1997 close to the original site by the Thames.","s":{"accepted":["The Globe","Globe","Globe Theatre","The Globe Theatre","Globe Theater","The Globe Theater"]}},{"k":"choice","i":"Which play features the line 'Et tu, Brute?'","t":"Famous lines","e":"\ud83c\udfdb\ufe0f","f":"The Latin phrase means 'You too, Brutus?', words of shock at a friend's betrayal.","o":["Antony and Cleopatra","Julius Caesar","Coriolanus","Titus Andronicus"],"s":{"index":1}},{"k":"truefalse","i":"Actors traditionally avoid saying 'Macbeth' inside a theatre, calling it 'the Scottish play' instead.","t":"Superstitions","e":"\ud83e\uddd9","f":"Superstition says naming it brings bad luck; offenders may be asked to step outside, spin around three times and knock.","a":true},{"k":"choice","i":"In 'A Midsummer Night's Dream', mischievous Puck gives Bottom the head of which animal?","t":"Characters","e":"\ud83e\udecf","f":"Under a magic spell, the fairy queen Titania falls in love with Bottom anyway.","o":["A donkey","A pig","A goat","A lion"],"s":{"index":0}},{"k":"number","i":"How many daughters does King Lear have?","t":"Characters","e":"\ud83d\udc51","f":"Goneril and Regan flatter their father, while honest Cordelia refuses to, with tragic results.","s":{"value":3,"tolerance":0,"min":1,"max":10,"unit":""}},{"k":"choice","i":"What was the name of Shakespeare's wife?","t":"His life","e":"\ud83d\udc8d","f":"They married in 1582 when Shakespeare was 18 and Anne was 26. Mary Arden was his mother.","o":["Anne Hathaway","Mary Arden","Elizabeth Tudor","Jane Seymour"],"s":{"index":0}},{"k":"choice","i":"Which magician rules an island in 'The Tempest'?","t":"Characters","e":"\ud83c\udf29\ufe0f","f":"Prospero, the exiled Duke of Milan, commands the airy spirit Ariel.","o":["Prospero","Oberon","Merlin","Malvolio"],"s":{"index":0}},{"k":"text","i":"Complete Richard III's famous cry: 'A horse! A horse! My ___ for a horse!'","t":"Famous lines","e":"\ud83d\udc0e","f":"Richard III was a real English king; Shakespeare made him one of the theatre's most famous villains.","s":{"accepted":["Kingdom"]}},{"k":"truefalse","i":"In 'Twelfth Night', Viola disguises herself as a young man named Cesario.","t":"Plots","e":"\ud83c\udfa9","f":"Disguise plots were extra fun because in Shakespeare's day all female roles were played by male actors.","a":true}]},{"slug":"retro-radio-80s-90s","title":"Retro Radio: 80s & 90s","tagline":"Grunge, girl power and pencil-sketch videos. Rewind the charts!","emoji":"\ud83d\udcfb","gradient":["#ec4899","#8b5cf6"],"categories":["music","popculture"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":231,"items":[{"k":"choice","i":"In what year was Michael Jackson's album 'Thriller' released?","t":"1980s","e":"\ud83e\udddf","f":"Thriller is widely cited as the best-selling album of all time.","o":["1979","1982","1985","1987"],"s":{"index":1}},{"k":"choice","i":"Which band released the album 'Nevermind' in 1991?","t":"Grunge","e":"\ud83c\udfb8","f":"Nevermind's success brought Seattle grunge into the mainstream.","o":["Nirvana","Pearl Jam","Soundgarden","Alice in Chains"],"s":{"index":0}},{"k":"choice","i":"Which singer, often called the 'Queen of Pop', released the hit 'Vogue' in 1990?","t":"Pop","e":"\ud83d\udc83","f":"The song was inspired by a dance style from New York's ballroom scene.","o":["Whitney Houston","Cyndi Lauper","Janet Jackson","Madonna"],"s":{"index":3}},{"k":"choice","i":"Which band had a 1985 hit with 'Take On Me', famous for its pencil-sketch animated video?","t":"1980s","e":"\u270f\ufe0f","f":"a-ha come from Norway.","o":["a-ha","Duran Duran","Tears for Fears","Depeche Mode"],"s":{"index":0}},{"k":"choice","i":"Which singer released the 1995 album 'Jagged Little Pill'?","t":"1990s","e":"\ud83d\udc8a","f":"Alanis Morissette is Canadian, and the album won the Grammy for Album of the Year.","o":["C\u00e9line Dion","Shania Twain","Alanis Morissette","Avril Lavigne"],"s":{"index":2}},{"k":"choice","i":"Which C\u00e9line Dion song was the theme for the film 'Titanic' (1997)?","t":"Film Songs","e":"\ud83d\udea2","f":"My Heart Will Go On won the Academy Award for Best Original Song.","o":["The Power of Love","Because You Loved Me","It's All Coming Back to Me Now","My Heart Will Go On"],"s":{"index":3}},{"k":"number","i":"In what year did MTV launch in the United States?","t":"Music TV","e":"\ud83d\udcfa","f":"The first music video MTV played was 'Video Killed the Radio Star' by The Buggles.","s":{"value":1981,"tolerance":0,"min":1970,"max":1995,"unit":""}},{"k":"text","i":"Which British girl group released 'Wannabe' as its debut single in 1996?","t":"1990s","e":"\u270c\ufe0f","f":"Each member got a nickname: Scary, Sporty, Baby, Ginger and Posh.","s":{"accepted":["Spice Girls","The Spice Girls"]}},{"k":"text","i":"What was the name of the huge 1985 charity concert held in London and Philadelphia on the same day?","t":"1980s","e":"\ud83c\udf0d","f":"Live Aid took place on 13 July 1985 and was organised by Bob Geldof and Midge Ure.","s":{"accepted":["Live Aid","LiveAid"]}},{"k":"truefalse","i":"Whitney Houston's 'I Will Always Love You' was originally written and recorded by Dolly Parton.","t":"Ballads","e":"\ud83c\udfa4","f":"Dolly Parton wrote it in 1973; Houston's version was recorded for the 1992 film 'The Bodyguard'.","a":true},{"k":"truefalse","i":"Prince's real first name was Prince.","t":"1980s","e":"\ud83d\udc9c","f":"He was born Prince Rogers Nelson in Minneapolis in 1958.","a":true},{"k":"multi","i":"Select all the bands that were formed in the United Kingdom.","t":"Bands","e":"\ud83c\uddec\ud83c\udde7","f":"U2 formed in Dublin, Ireland, while Bon Jovi and R.E.M. are American.","o":["Oasis","U2","Blur","Bon Jovi","Duran Duran","R.E.M."],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these albums from oldest to newest.","t":"Albums","e":"\ud83d\udcbf","f":"They came out in 1982, 1984, 1991, 1995 and 1999.","o":["Thriller (Michael Jackson)","Purple Rain (Prince)","Nevermind (Nirvana)","(What's the Story) Morning Glory? (Oasis)","...Baby One More Time (Britney Spears)"]}]},{"slug":"city-nicknames","title":"City Nicknames","tagline":"The Big Apple, the Windy City, the Eternal City... can you name them all?","emoji":"\ud83c\udfd9\ufe0f","gradient":["#7c3aed","#db2777"],"categories":["travel","geo"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":232,"items":[{"k":"choice","i":"Which city is known as 'the Big Apple'?","t":"USA","e":"\ud83c\udf4e","f":"The nickname was popularised by a sports writer in the 1920s and revived by a tourism campaign in the 1970s.","o":["Los Angeles","Chicago","New York City","Boston"],"s":{"index":2}},{"k":"choice","i":"Which city is called 'the City of Light' (La Ville Lumi\u00e8re)?","t":"Europe","e":"\ud83d\udca1","f":"Paris earned the name as a centre of ideas during the Enlightenment and as an early adopter of street lighting.","o":["Paris","Vienna","Rome","Madrid"],"s":{"index":0}},{"k":"choice","i":"Which city is nicknamed 'the Eternal City'?","t":"Europe","e":"\ud83c\udfdb\ufe0f","f":"The Roman poet Tibullus already called Rome 'Urbs Aeterna', the eternal city, over 2,000 years ago.","o":["Athens","Rome","Istanbul","Cairo"],"s":{"index":1}},{"k":"choice","i":"Which US city is nicknamed 'the Big Easy'?","t":"USA","e":"\ud83c\udfb7","f":"New Orleans is also famous as the birthplace of jazz and for its colourful Mardi Gras celebrations.","o":["Nashville","Miami","Memphis","New Orleans"],"s":{"index":3}},{"k":"choice","i":"Prague is often called 'the City of a Hundred...' what?","t":"Europe","e":"\u26ea","f":"Prague's skyline is packed with church towers and spires; in reality there are far more than a hundred.","o":["Bridges","Spires","Castles","Fountains"],"s":{"index":1}},{"k":"choice","i":"Which US city is known as 'the Motor City'?","t":"USA","e":"\ud83d\ude97","f":"The Detroit area became the heart of the US car industry, home to Ford, General Motors and Chrysler.","o":["Cleveland","Pittsburgh","Detroit","Houston"],"s":{"index":2}},{"k":"choice","i":"Jaipur in India is famous as 'the ___ City'. Which colour completes its nickname?","t":"Asia","e":"\ud83e\ude77","f":"Jaipur's old city was painted pink to welcome the Prince of Wales, later King Edward VII, in 1876.","o":["Pink","Blue","Golden","White"],"s":{"index":0}},{"k":"truefalse","i":"'Auld Reekie' ('Old Smoky') is a nickname for Dublin.","t":"Europe","e":"\ud83d\udca8","f":"Auld Reekie is Edinburgh, named for the smoke from coal and wood fires that once hung over the Scottish capital.","a":false},{"k":"multi","i":"Select all the nicknames used for New York City.","t":"New York","e":"\ud83d\uddfd","f":"Writer Washington Irving first linked the name 'Gotham' to New York in 1807.","o":["The Big Apple","The City That Never Sleeps","The Big Easy","Gotham","Motor City"],"s":{"indices":[0,1,3]}},{"k":"text","i":"Which US city is nicknamed 'the Windy City'?","t":"USA","e":"\ud83c\udf2c\ufe0f","f":"Some say Chicago's nickname refers to its boastful politicians rather than to the weather.","s":{"accepted":["Chicago"]}},{"k":"number","i":"Rome is traditionally said to have been built on how many hills?","t":"Rome","e":"\u26f0\ufe0f","f":"The Seven Hills of Rome include the Palatine, where legend says the city was founded.","s":{"value":7,"tolerance":0,"min":1,"max":12,"unit":""}},{"k":"number","i":"Denver is 'the Mile High City'. Roughly how many metres above sea level is it?","t":"USA","e":"\u26f0\ufe0f","f":"One step of the Colorado State Capitol is marked as exactly one mile (about 1,609 m) above sea level.","s":{"value":1609,"tolerance":30,"min":500,"max":3000,"unit":"m"}},{"k":"order","i":"Order these cities from west to east.","t":"Geography","e":"\ud83e\udded","f":"Los Angeles takes its name from the Spanish words for 'the angels'.","o":["Los Angeles (City of Angels)","Chicago (Windy City)","Paris (City of Light)","Jaipur (Pink City)"]}]},{"slug":"sports-by-the-numbers","title":"Sports by the Numbers","tagline":"Players, points and pitch sizes: the numbers behind your favourite games.","emoji":"\ud83d\udd22","gradient":["#0891b2","#1d4ed8"],"categories":["sports","math"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":233,"items":[{"k":"number","i":"How many players per side are on the field at the start of a football (soccer) match?","t":"Team sizes","e":"\u26bd","f":"A football match cannot start or continue if either team has fewer than seven players.","s":{"value":11,"tolerance":0,"min":1,"max":20,"unit":""}},{"k":"number","i":"How many players per team are on the court in indoor volleyball?","t":"Team sizes","e":"\ud83c\udfd0","f":"Volleyball was invented in 1895 by William G. Morgan in Massachusetts and was first called 'mintonette'.","s":{"value":6,"tolerance":0,"min":1,"max":12,"unit":""}},{"k":"choice","i":"How many players does a rugby union team have on the field?","t":"Team sizes","e":"\ud83c\udfc9","f":"Rugby league, a separate code of the game, uses 13 players per side instead of 15.","o":["11","13","15","18"],"s":{"index":2}},{"k":"choice","i":"What is the maximum break in snooker under standard play (without free balls)?","t":"Scoring","e":"\ud83c\udfb1","f":"A 147 needs all 15 reds, each followed by the black, then all six colours in order.","o":["100","147","155","180"],"s":{"index":1}},{"k":"choice","i":"What is the highest score possible with three darts?","t":"Scoring","e":"\ud83c\udfaf","f":"180 means hitting the treble 20 with all three darts; 170 is the highest possible checkout.","o":["150","170","180","200"],"s":{"index":2}},{"k":"truefalse","i":"A marathon is exactly 42.195 kilometres long.","t":"Distances","e":"\ud83c\udfc3","f":"The distance was fixed at 42.195 km in 1921, based on the course used at the 1908 London Olympics.","a":true},{"k":"text","i":"In golf, what is the term for a score of one under par on a hole?","t":"Scoring","e":"\u26f3","f":"One under par is a birdie, two under is an eagle and three under is an albatross, or double eagle.","s":{"accepted":["Birdie","A birdie"]}},{"k":"order","i":"Order these team sports by the number of players per side on the field, from fewest to most.","t":"Team sizes","e":"\ud83d\udc65","f":"Ice hockey teams play six at a time, including the goaltender, and swap lines on the fly.","o":["Basketball","Ice hockey","Baseball","Football (soccer)"]},{"k":"number","i":"How long is an Olympic swimming pool?","t":"Distances","e":"\ud83c\udfca","f":"Olympic events use 50 m 'long-course' pools, while 'short-course' pools are 25 m long.","s":{"value":50,"tolerance":0,"min":10,"max":100,"unit":"m"}},{"k":"order","i":"Order these balls from smallest to largest.","t":"Equipment","e":"\ud83c\udfd3","f":"A table tennis ball is 40 mm across, just a little smaller than a golf ball at about 42.7 mm.","o":["Table tennis ball","Golf ball","Tennis ball","Basketball"]},{"k":"multi","i":"Select all the sports played with a net dividing the two sides.","t":"Rules","e":"\ud83c\udfbe","f":"Squash players share the same court and hit the ball against the front wall instead of over a net.","o":["Badminton","Basketball","Tennis","Volleyball","Squash"],"s":{"indices":[0,2,3]}},{"k":"choice","i":"In American football, how many points is a touchdown worth?","t":"Scoring","e":"\ud83c\udfc8","f":"After a touchdown, a team can try for one extra point with a kick or two points with a play.","o":["3","4","5","6"],"s":{"index":3}},{"k":"number","i":"How long is one lap of a standard outdoor running track?","t":"Distances","e":"\ud83c\udfdf\ufe0f","f":"A 400 m lap is measured along the inside lane, so the outer lanes use staggered starts.","s":{"value":400,"tolerance":0,"min":100,"max":1000,"unit":"m"}},{"k":"truefalse","i":"In cricket, a 'century' means a batter has scored 100 runs.","t":"Rules","e":"\ud83c\udfcf","f":"In cricket, hitting the ball over the boundary without a bounce scores six runs, and one that bounces first scores four.","a":true}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '3ba8fddd4aae827455e2a46e02da21ce' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 4'; end $q$;
do $q$ declare d text := $d$[{"slug":"ancient-civilizations","title":"Ancient Civilizations","tagline":"Pyramids, pharaohs and philosophers: travel back thousands of years.","emoji":"\ud83c\udfdb\ufe0f","gradient":["#d97706","#7c2d12"],"categories":["history","culture"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":234,"items":[{"k":"choice","i":"The Great Pyramid of Giza was built as a tomb for which pharaoh?","t":"Egypt","e":"\ud83d\udd3a","f":"The Great Pyramid was the tallest human-made structure in the world for over 3,800 years.","o":["Tutankhamun","Ramses II","Khufu","Cleopatra"],"s":{"index":2}},{"k":"choice","i":"Which civilization invented cuneiform, one of the earliest writing systems?","t":"Mesopotamia","e":"\u270d\ufe0f","f":"Cuneiform was written by pressing a reed stylus into tablets of wet clay.","o":["Egyptians","Sumerians","Greeks","Romans"],"s":{"index":1}},{"k":"text","i":"What is the name of the ancient Egyptian writing system that used pictures and symbols?","t":"Egypt","e":"\ud83d\udd23","f":"The Rosetta Stone, carved in 196 BC, helped scholars finally decode hieroglyphs in the 1820s.","s":{"accepted":["Hieroglyphs","Hieroglyphics","Hieroglyphic","Egyptian hieroglyphs","Hieroglyph"]}},{"k":"choice","i":"In which modern-day country did the ancient city of Babylon stand?","t":"Mesopotamia","e":"\ud83c\udffa","f":"Babylon stood on the Euphrates River, about 85 km south of modern Baghdad.","o":["Iran","Syria","Egypt","Iraq"],"s":{"index":3}},{"k":"number","i":"The first recorded ancient Olympic Games took place at Olympia in which year BC?","t":"Ancient Greece","e":"\ud83c\udfc5","f":"Winners at the ancient Olympic Games were crowned with a wreath of olive leaves.","s":{"value":776,"tolerance":0,"min":100,"max":1500,"unit":"BC"}},{"k":"order","i":"Order these events from oldest to most recent.","t":"Timeline","e":"\ud83d\udcdc","f":"The Western Roman Empire is traditionally said to have ended in AD 476.","o":["Great Pyramid of Giza built","Traditional founding of Rome","Parthenon built in Athens","Death of Julius Caesar","Fall of the Western Roman Empire"]},{"k":"choice","i":"Which Greek philosopher was a teacher of Alexander the Great?","t":"Ancient Greece","e":"\ud83e\udd89","f":"Aristotle had himself studied for about 20 years at Plato's Academy in Athens.","o":["Aristotle","Socrates","Plato","Pythagoras"],"s":{"index":0}},{"k":"multi","i":"Select all the Seven Wonders of the Ancient World.","t":"Wonders","e":"\ud83d\uddff","f":"The Great Pyramid is the only one of the original Seven Wonders that still stands today.","o":["Great Pyramid of Giza","Colosseum","Hanging Gardens of Babylon","Great Wall of China","Lighthouse of Alexandria"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"What language did the ancient Romans speak?","t":"Rome","e":"\ud83c\udfdf\ufe0f","f":"Latin developed into the Romance languages, including Italian, Spanish, French, Portuguese and Romanian.","o":["Greek","Latin","Etruscan","Aramaic"],"s":{"index":1}},{"k":"choice","i":"Which empire was ruled from the city of Cusco in the Andes?","t":"Americas","e":"\ud83e\udd99","f":"The Inca built a road network tens of thousands of kilometres long across the Andes.","o":["Aztec","Maya","Inca","Olmec"],"s":{"index":2}},{"k":"truefalse","i":"Cleopatra lived closer in time to the first Moon landing than to the building of the Great Pyramid.","t":"Timeline","e":"\ud83c\udf19","f":"About 2,500 years separate Cleopatra from the Great Pyramid, but only about 2,000 separate her from the Moon landing.","a":true},{"k":"text","i":"Which river was the lifeline of ancient Egypt?","t":"Egypt","e":"\ud83c\udf3e","f":"Yearly Nile floods left rich black soil, so Egyptians called their land 'Kemet', the Black Land.","s":{"accepted":["Nile","The Nile","Nile River","River Nile"]}},{"k":"multi","i":"Select all the gods from Greek mythology.","t":"Mythology","e":"\u26a1","f":"In Greek myths, the twelve major gods lived on Mount Olympus, Greece's highest mountain.","o":["Zeus","Thor","Athena","Ra","Poseidon"],"s":{"indices":[0,2,4]}}]},{"slug":"storybook-shelf","title":"Storybook Shelf","tagline":"Hungry caterpillars, golden tickets and a bear from Peru. Remember your favourites?","emoji":"\ud83e\uddf8","gradient":["#16a34a","#0d9488"],"categories":["literature","kids"],"countries":null,"difficulty":"Easy","minutes":3,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":235,"items":[{"k":"number","i":"In 'The Very Hungry Caterpillar', how many plums does the caterpillar eat on Wednesday?","t":"Picture books","e":"\ud83d\udc1b","f":"Eric Carle's 1969 book has little holes in its pages; the caterpillar ends up as a beautiful butterfly.","s":{"value":3,"tolerance":0,"min":1,"max":10,"unit":""}},{"k":"choice","i":"What is the name of the boy who sails away to where the Wild Things are?","t":"Picture books","e":"\ud83d\udc79","f":"In Maurice Sendak's 1963 book, Max is sent to bed after causing mischief in his wolf suit.","o":["Sam","Leo","Tom","Max"],"s":{"index":3}},{"k":"choice","i":"Which Swedish author created Pippi Longstocking?","t":"Authors","e":"\ud83d\udc67","f":"Pippi lives in Villa Villekulla with a monkey, Mr. Nilsson, and a horse she can lift with her bare hands.","o":["Selma Lagerl\u00f6f","Tove Jansson","Astrid Lindgren","Hans Christian Andersen"],"s":{"index":2}},{"k":"text","i":"What is the name of Winnie-the-Pooh's gloomy donkey friend?","t":"Characters","e":"\ud83e\udecf","f":"A. A. Milne based the characters on his son's real stuffed toys, which are now on display in New York.","s":{"accepted":["Eeyore","Eyore","Eeyor"]}},{"k":"truefalse","i":"Lewis Carroll, author of 'Alice's Adventures in Wonderland', was a pen name.","t":"Authors","e":"\ud83d\udc07","f":"His real name was Charles Lutwidge Dodgson, and he taught mathematics at Oxford.","a":true},{"k":"number","i":"How many golden tickets does Willy Wonka hide in his chocolate bars?","t":"Roald Dahl","e":"\ud83c\udf6b","f":"Roald Dahl got the idea partly from chocolate companies sending new bars to his school for pupils to taste-test.","s":{"value":5,"tolerance":0,"min":1,"max":20,"unit":""}},{"k":"choice","i":"Paddington Bear travelled to London from which country?","t":"Characters","e":"\ud83d\udc3b","f":"He was found at Paddington station wearing a label: 'Please look after this bear. Thank you.'","o":["Brazil","Canada","Mexico","Peru"],"s":{"index":3}},{"k":"multi","i":"Select all the characters from Rudyard Kipling's 'The Jungle Book'.","t":"Characters","e":"\ud83d\udc05","f":"Kipling was born in Bombay (now Mumbai), and the Mowgli stories are set in the forests of India.","o":["Bagheera","Tigger","Baloo","Mowgli","Aslan"],"s":{"indices":[0,2,3]}},{"k":"choice","i":"In 'The Little Prince', where does the prince come from?","t":"Classics","e":"\ud83c\udf39","f":"Antoine de Saint-Exup\u00e9ry's 1943 book names the prince's home asteroid B-612.","o":["A tiny asteroid","The bottom of the sea","A cloud kingdom","A desert oasis"],"s":{"index":0}},{"k":"truefalse","i":"Dr. Seuss wrote 'Green Eggs and Ham' using only 50 different words.","t":"Picture books","e":"\ud83c\udf73","f":"He wrote it after his publisher bet him he couldn't write a whole book with just 50 words.","a":true},{"k":"choice","i":"Whose nose grows longer every time he tells a lie?","t":"Classics","e":"\ud83e\udd25","f":"Carlo Collodi's 'The Adventures of Pinocchio' was first published as a book in Italy in 1883.","o":["Peter Pan","Pinocchio","Tom Thumb","Puss in Boots"],"s":{"index":1}},{"k":"multi","i":"Select all the words Charlotte the spider weaves into her web to save Wilbur the pig.","t":"Classics","e":"\ud83d\udd78\ufe0f","f":"Her fourth and final word was 'Humble'. E. B. White's 'Charlotte's Web' was published in 1952.","o":["Radiant","Terrific","Clever","Some Pig","Famous"],"s":{"indices":[0,1,3]}},{"k":"order","i":"Order these children's books by publication date, oldest first.","t":"Timeline","e":"\ud83d\udcd6","f":"1865, 1902, 1926, 1957 and 1999: over a century of bedtime stories.","o":["Alice's Adventures in Wonderland","The Tale of Peter Rabbit","Winnie-the-Pooh","The Cat in the Hat","The Gruffalo"]},{"k":"text","i":"Which author wrote 'Matilda', 'The BFG' and 'The Twits'?","t":"Roald Dahl","e":"\u270f\ufe0f","f":"Roald Dahl was born in Wales in 1916 to Norwegian parents.","s":{"accepted":["Roald Dahl","Dahl"]}}]},{"slug":"instrument-inspector","title":"Instrument Inspector","tagline":"Strings, reeds and kettledrums: how well do you know your instruments?","emoji":"\ud83c\udfbb","gradient":["#0f766e","#1d4ed8"],"categories":["music","kids"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":236,"items":[{"k":"choice","i":"How many strings does a standard violin have?","t":"Strings","e":"\ud83c\udfbb","f":"A violin's strings are usually tuned to G, D, A and E.","o":["4","5","6","8"],"s":{"index":0}},{"k":"choice","i":"To which instrument family does the saxophone belong?","t":"Woodwinds","e":"\ud83c\udfb7","f":"Although it is made of brass, the saxophone is a woodwind because its sound comes from a reed.","o":["Brass","Woodwind","Percussion","Strings"],"s":{"index":1}},{"k":"choice","i":"The sitar is most closely associated with the classical music of which country?","t":"World Music","e":"\ud83e\ude95","f":"Ravi Shankar helped make the sitar famous around the world in the 1960s.","o":["Japan","Turkey","India","Iran"],"s":{"index":2}},{"k":"choice","i":"The Great Highland bagpipe is most closely associated with which country?","t":"World Music","e":"\ud83c\udff4","f":"Ireland has its own bagpipe, the uilleann pipes, which are pumped with the elbow instead of blown.","o":["Scotland","Ireland","Wales","Norway"],"s":{"index":0}},{"k":"choice","i":"The piano's original Italian name, 'pianoforte', means what?","t":"Piano","e":"\ud83c\udfb9","f":"Bartolomeo Cristofori built the first pianos in Italy around 1700; unlike the harpsichord, they could play soft or loud.","o":["Little harp","Hammer keys","Soft-loud","Grand sound"],"s":{"index":2}},{"k":"choice","i":"Which instruments does a timpanist play?","t":"Percussion","e":"\ud83e\udd41","f":"Timpani can be tuned to specific notes, often by pressing a foot pedal.","o":["Harps","Kettledrums","Triangles","Xylophones"],"s":{"index":1}},{"k":"number","i":"How many keys does a standard modern piano have?","t":"Piano","e":"\ud83c\udfb9","f":"A standard piano has 52 white keys and 36 black keys.","s":{"value":88,"tolerance":0,"min":50,"max":120,"unit":""}},{"k":"number","i":"How many valves does a standard modern trumpet have?","t":"Brass","e":"\ud83c\udfba","f":"By combining its three valves, a trumpeter can play every note of the chromatic scale.","s":{"value":3,"tolerance":0,"min":1,"max":6,"unit":""}},{"k":"truefalse","i":"The tuba is the lowest-pitched brass instrument in a standard symphony orchestra.","t":"Brass","e":"\ud83d\udcef","f":"The tuba is also one of the youngest orchestral instruments, invented in the 1830s.","a":true},{"k":"truefalse","i":"The didgeridoo comes from Australia.","t":"World Music","e":"\ud83e\udd98","f":"It is traditionally played by Aboriginal peoples of northern Australia, often made from termite-hollowed eucalyptus.","a":true},{"k":"text","i":"Which large keyboard instrument, found in many churches and concert halls, makes its sound with pipes?","t":"Keyboards","e":"\u26ea","f":"Large pipe organs can have thousands of pipes, from the size of a pencil to over 10 metres tall.","s":{"accepted":["Organ","Pipe organ","The organ"]}},{"k":"multi","i":"Select all the string instruments.","t":"Strings","e":"\ud83c\udfb5","f":"The clarinet is a woodwind, the trombone is brass and the xylophone is percussion.","o":["Cello","Harp","Clarinet","Banjo","Trombone","Xylophone"],"s":{"indices":[0,1,3]}},{"k":"order","i":"Order these string instruments from highest to lowest pitch.","t":"Orchestra","e":"\ud83c\udfb6","f":"The bigger the instrument, the lower its voice: the double bass sounds lowest of all.","o":["Violin","Viola","Cello","Double bass"]}]},{"slug":"festival-passport","title":"Festival Passport","tagline":"Colour fights, tomato battles and water parties: join the world's celebrations.","emoji":"\ud83c\udf89","gradient":["#e11d48","#9333ea"],"categories":["holidays","culture","travel"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":237,"items":[{"k":"choice","i":"Holi, the 'festival of colours' where people throw coloured powder, is celebrated mainly in which country?","t":"India","e":"\ud83c\udfa8","f":"Holi welcomes the arrival of spring and is celebrated at the full moon of the Hindu month of Phalguna.","o":["India","Thailand","Brazil","Indonesia"],"s":{"index":0}},{"k":"choice","i":"La Tomatina, a giant tomato fight, takes place in which country?","t":"Spain","e":"\ud83c\udf45","f":"It is held in the town of Bu\u00f1ol near Valencia, usually on the last Wednesday of August.","o":["Italy","Spain","Portugal","Mexico"],"s":{"index":1}},{"k":"choice","i":"Munich's Oktoberfest began in 1810 to celebrate what?","t":"Germany","e":"\ud83e\udd68","f":"It marked the wedding of Crown Prince Ludwig and Princess Therese; the festival grounds are named Theresienwiese.","o":["The end of a war","A good harvest","A royal wedding","A new king's birthday"],"s":{"index":2}},{"k":"choice","i":"Songkran, famous for its huge water fights, is the traditional New Year of which country?","t":"Thailand","e":"\ud83d\udca6","f":"Songkran falls in mid-April, the hottest time of year in Thailand, so a splash of water is very welcome.","o":["Vietnam","Japan","Philippines","Thailand"],"s":{"index":3}},{"k":"choice","i":"In Japan, what is the custom of picnicking under blooming cherry trees called?","t":"Japan","e":"\ud83c\udf38","f":"Japanese forecasters track the 'cherry blossom front' as the blooms spread north through the country each spring.","o":["Hanami","Origami","Ikebana","Karaoke"],"s":{"index":0}},{"k":"choice","i":"Which flower is the symbol of Mexico's Day of the Dead and decorates family altars?","t":"Mexico","e":"\ud83c\udf3c","f":"Bright orange cempas\u00fachil marigolds are believed to guide the spirits of loved ones home with their colour and scent.","o":["Rose","Marigold","Tulip","Sunflower"],"s":{"index":1}},{"k":"truefalse","i":"Diwali is known as the 'festival of lights'.","t":"India","e":"\ud83e\ude94","f":"Families light rows of small clay oil lamps called diyas to celebrate Diwali.","a":true},{"k":"truefalse","i":"St Patrick's Day is celebrated on 17 July.","t":"Ireland","e":"\u2618\ufe0f","f":"St Patrick's Day is on 17 March, and Chicago even dyes its river green for the occasion.","a":false},{"k":"multi","i":"Select all the animals that are part of the Chinese zodiac.","t":"Lunar New Year","e":"\ud83d\udc09","f":"The Chinese zodiac has 12 animals, each linked to a year in a repeating 12-year cycle.","o":["Rabbit","Lion","Dragon","Cat","Monkey"],"s":{"indices":[0,2,4]}},{"k":"text","i":"Which Brazilian city hosts a world-famous carnival samba parade in its Sambadrome?","t":"Brazil","e":"\ud83e\udd41","f":"Rio's Sambadrome was designed by architect Oscar Niemeyer and opened in 1984.","s":{"accepted":["Rio de Janeiro","Rio"]}},{"k":"text","i":"What is the Scottish name for the New Year's Eve celebrations?","t":"Scotland","e":"\ud83c\udf86","f":"Hogmanay traditions include 'first-footing': being the first visitor to a home after midnight.","s":{"accepted":["Hogmanay"]}},{"k":"number","i":"US Thanksgiving falls on which Thursday of November? (1st, 2nd, 3rd...)","t":"North America","e":"\ud83e\udd83","f":"Canada celebrates its Thanksgiving much earlier, on the second Monday of October.","s":{"value":4,"tolerance":0,"min":1,"max":5,"unit":""}},{"k":"order","i":"Order these festivals as they fall in the calendar year, starting from January.","t":"Calendar","e":"\ud83d\udcc5","f":"Burns Night on 25 January honours Scottish poet Robert Burns with haggis, poetry and bagpipes.","o":["Burns Night","St Patrick's Day","La Tomatina","Day of the Dead"]}]},{"slug":"courtside-classics","title":"Courtside Classics","tagline":"Grand Slams and slam dunks: test your tennis and basketball basics.","emoji":"\ud83c\udfbe","gradient":["#65a30d","#ea580c"],"categories":["sports"],"countries":null,"difficulty":"Easy","minutes":3,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":238,"items":[{"k":"choice","i":"Which Grand Slam tennis tournament is played on grass?","t":"Grand Slams","e":"\ud83c\udf31","f":"Wimbledon, first held in 1877, is the oldest tennis tournament in the world.","o":["Wimbledon","US Open","French Open","Australian Open"],"s":{"index":0}},{"k":"choice","i":"On what surface is the French Open (Roland-Garros) played?","t":"Grand Slams","e":"\ud83e\uddf1","f":"Roland-Garros's red clay is actually white limestone covered with a thin layer of crushed brick.","o":["Carpet","Clay","Hard court","Grass"],"s":{"index":1}},{"k":"order","i":"Order the four Grand Slam tournaments as they happen in the calendar year, starting in January.","t":"Grand Slams","e":"\ud83d\udcc5","f":"The Australian Open in Melbourne opens the Grand Slam season every January.","o":["Australian Open","French Open","Wimbledon","US Open"]},{"k":"text","i":"In tennis, what word is used for a score of zero?","t":"Tennis scoring","e":"0\ufe0f\u20e3","f":"One popular theory links 'love' to playing just for the love of the game, but its true origin is uncertain.","s":{"accepted":["Love"]}},{"k":"order","i":"Order the scores a player calls out while winning a game, from the first point won to the last.","t":"Tennis scoring","e":"\ud83c\udfbe","f":"Players must win a game by two clear points, so a 40\u201340 'deuce' can go on for a long time.","o":["15","30","40","Game"]},{"k":"truefalse","i":"Wimbledon has a tradition of strict, almost all-white clothing for players.","t":"Traditions","e":"\u26aa","f":"Wimbledon's rules require players to dress almost entirely in white, a tradition dating back to Victorian times.","a":true},{"k":"number","i":"How many players from each team are on a basketball court at one time?","t":"Basketball","e":"\ud83c\udfc0","f":"Basketball was invented in 1891 by James Naismith, who used peach baskets as the first hoops.","s":{"value":5,"tolerance":0,"min":1,"max":12,"unit":""}},{"k":"number","i":"How high above the floor is a regulation basketball rim, in feet?","t":"Basketball","e":"\ud83d\udccf","f":"The 10-foot rim height has stayed the same since Naismith hung his first peach baskets in 1891.","s":{"value":10,"tolerance":0,"min":5,"max":15,"unit":"ft"}},{"k":"choice","i":"In which country was James Naismith, the inventor of basketball, born?","t":"Basketball","e":"\ud83c\udf41","f":"Naismith was born in Ontario, Canada, but invented the game in Springfield, Massachusetts.","o":["Scotland","England","Canada","United States"],"s":{"index":2}},{"k":"choice","i":"How many points is a basket worth when scored from beyond the arc?","t":"Basketball","e":"\ud83c\udfaf","f":"The NBA adopted the three-point line in the 1979\u201380 season.","o":["1","2","3","4"],"s":{"index":2}},{"k":"multi","i":"Select all the terms used in basketball.","t":"Basketball","e":"\ud83d\udde3\ufe0f","f":"An 'ace' is a serve the opponent can't touch in tennis, and a 'birdie' belongs to golf.","o":["Birdie","Free throw","Rebound","Ace","Dribble"],"s":{"indices":[1,2,4]}},{"k":"truefalse","i":"In tennis, a tiebreak is usually played when a set reaches 6\u20136.","t":"Tennis scoring","e":"\u2696\ufe0f","f":"The tiebreak was first used at a Grand Slam at the 1970 US Open, to stop sets dragging on for hours.","a":true},{"k":"choice","i":"Which NBA legend wore number 23 and won six titles with the Chicago Bulls?","t":"Basketball","e":"\ud83d\udc02","f":"Jordan won his six NBA titles in two 'three-peats': 1991\u201393 and 1996\u201398.","o":["Kareem Abdul-Jabbar","Larry Bird","Magic Johnson","Michael Jordan"],"s":{"index":3}},{"k":"choice","i":"In which city is the US Open tennis tournament held?","t":"Grand Slams","e":"\ud83d\uddfd","f":"The US Open is played at the USTA Billie Jean King National Tennis Center in Flushing Meadows, Queens.","o":["Los Angeles","New York","Miami","Chicago"],"s":{"index":1}}]},{"slug":"twentieth-century-milestones","title":"20th Century Milestones","tagline":"From the first flight to the World Wide Web: a century of big moments.","emoji":"\ud83d\udcfb","gradient":["#4f46e5","#be185d"],"categories":["history","society"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":239,"items":[{"k":"number","i":"In what year did the Wright brothers make the first powered airplane flight?","t":"Aviation","e":"\u2708\ufe0f","f":"The first flight at Kitty Hawk lasted just 12 seconds and covered about 37 m.","s":{"value":1903,"tolerance":0,"min":1880,"max":1930,"unit":""}},{"k":"choice","i":"Which ship sank on its maiden voyage in April 1912?","t":"1910s","e":"\ud83d\udea2","f":"The wreck of the Titanic was found in 1985, about 3,800 m deep in the North Atlantic.","o":["Lusitania","Titanic","Britannic","Queen Mary"],"s":{"index":1}},{"k":"choice","i":"Who were the first people confirmed to reach the summit of Mount Everest, in 1953?","t":"Exploration","e":"\ud83c\udfd4\ufe0f","f":"Edmund Hillary was a beekeeper from New Zealand, and Tenzing Norgay was a Sherpa mountaineer.","o":["Edmund Hillary and Tenzing Norgay","George Mallory and Andrew Irvine","Reinhold Messner and Peter Habeler","Roald Amundsen and Robert Scott"],"s":{"index":0}},{"k":"order","i":"Order these events from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"All five events happened within a span of less than 80 years, from 1912 to 1989.","o":["Titanic sinks","Penicillin is discovered","First ascent of Mount Everest","First crewed Moon landing","Fall of the Berlin Wall"]},{"k":"truefalse","i":"The first Disneyland park opened in California in the 1950s.","t":"1950s","e":"\ud83c\udfa2","f":"Disneyland opened in Anaheim, California, on 17 July 1955.","a":true},{"k":"choice","i":"Which band released the album 'Abbey Road' in 1969?","t":"1960s","e":"\ud83c\udfb8","f":"The album's famous cover shows the band walking across a zebra crossing outside the studio in London.","o":["The Rolling Stones","The Who","Pink Floyd","The Beatles"],"s":{"index":3}},{"k":"text","i":"Which Danish toy company patented its famous stud-and-tube plastic building brick in 1958?","t":"Toys","e":"\ud83e\uddf1","f":"The name LEGO comes from the Danish words 'leg godt', meaning 'play well'.","s":{"accepted":["LEGO","Lego","The LEGO Group","Lego Group"]}},{"k":"number","i":"In what year did the Channel Tunnel between England and France open?","t":"Engineering","e":"\ud83d\ude84","f":"The tunnel is about 50 km long, with roughly 38 km of it running under the sea.","s":{"value":1994,"tolerance":0,"min":1950,"max":2010,"unit":""}},{"k":"choice","i":"Which British computer scientist invented the World Wide Web in 1989?","t":"Technology","e":"\ud83c\udf10","f":"Tim Berners-Lee wrote his proposal for the Web while working at CERN, near Geneva.","o":["Bill Gates","Steve Jobs","Tim Berners-Lee","Alan Turing"],"s":{"index":2}},{"k":"multi","i":"Select all the events that happened in the 1960s.","t":"1960s","e":"\ud83d\udd7a","f":"Yuri Gagarin became the first human in space on 12 April 1961.","o":["First crewed Moon landing","Titanic sinks","The Beatles release their first album","Yuri Gagarin flies into space","Disneyland opens","Channel Tunnel opens"],"s":{"indices":[0,2,3]}},{"k":"choice","i":"The first Winter Olympic Games were held in 1924 in which country?","t":"Sport","e":"\u26f7\ufe0f","f":"Just 16 nations competed at the first Winter Olympics in Chamonix, France.","o":["France","Norway","Switzerland","United States"],"s":{"index":0}},{"k":"truefalse","i":"The first email was sent in the 1990s.","t":"Technology","e":"\ud83d\udce7","f":"Ray Tomlinson sent the first network email in 1971 and chose the @ symbol for addresses.","a":false},{"k":"choice","i":"In 1997, which world chess champion lost a match to IBM's Deep Blue computer?","t":"1990s","e":"\u265f\ufe0f","f":"It was the first time a computer beat a reigning world champion in a match under standard tournament conditions.","o":["Bobby Fischer","Garry Kasparov","Anatoly Karpov","Magnus Carlsen"],"s":{"index":1}}]},{"slug":"olympus-roll-call","title":"Olympus Roll Call","tagline":"Thunderbolts, tridents and trouble: meet the gods and heroes of ancient Greece.","emoji":"\u26a1","gradient":["#1d4ed8","#0ea5e9"],"categories":["myth","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":240,"items":[{"k":"choice","i":"Who is the king of the Greek gods?","t":"Gods","e":"\u26a1","f":"Zeus ruled from Mount Olympus and hurled thunderbolts forged for him by the Cyclopes.","o":["Zeus","Apollo","Poseidon","Hades"],"s":{"index":0}},{"k":"choice","i":"What is the Roman name for Poseidon, god of the sea?","t":"Roman names","e":"\ud83d\udd31","f":"The planet Neptune's symbol is a trident, the three-pronged spear carried by the sea god.","o":["Mars","Mercury","Neptune","Vulcan"],"s":{"index":2}},{"k":"choice","i":"How was Athena, goddess of wisdom, born?","t":"Gods","e":"\ud83e\udd89","f":"Athena emerged from Zeus's head wearing armour. The city of Athens is named after her.","o":["She sprang fully grown from Zeus's head","She rose from the sea foam","She hatched from a golden egg","She was carved from marble"],"s":{"index":0}},{"k":"text","i":"What is the name of the three-headed dog that guards the underworld?","t":"Creatures","e":"\ud83d\udc15","f":"Cerberus belonged to Hades, god of the underworld, and made sure no one left the realm of the dead.","s":{"accepted":["Cerberus","Kerberos","Cerberos"]}},{"k":"number","i":"How many labours did the hero Heracles have to complete?","t":"Heroes","e":"\ud83d\udcaa","f":"His tasks included wrestling the Nemean lion and cleaning the vast Augean stables in a single day.","s":{"value":12,"tolerance":0,"min":1,"max":30,"unit":""}},{"k":"multi","i":"Select all the Olympians who are children of Zeus.","t":"Family tree","e":"\ud83c\udf33","f":"Poseidon and Hera were Zeus's siblings, all children of the Titans Cronus and Rhea.","o":["Athena","Poseidon","Hermes","Hera","Apollo"],"s":{"indices":[0,2,4]}},{"k":"truefalse","i":"In the earliest Greek versions of the myth, 'Pandora's box' was actually a large jar.","t":"Myths","e":"\ud83c\udffa","f":"The poet Hesiod describes a 'pithos', a storage jar; it became a 'box' after a 16th-century mistranslation.","a":true},{"k":"choice","i":"Which hero defeated the Gorgon Medusa?","t":"Heroes","e":"\ud83d\udc0d","f":"Perseus avoided Medusa's stone-turning gaze by watching her reflection in a polished shield.","o":["Perseus","Theseus","Jason","Achilles"],"s":{"index":0}},{"k":"choice","i":"Icarus flew too close to the sun on wings made of feathers and what?","t":"Myths","e":"\ud83e\udeb6","f":"His father Daedalus built the wings to escape Crete; he had also designed the Minotaur's labyrinth.","o":["Silk","Gold","Clay","Wax"],"s":{"index":3}},{"k":"choice","i":"Which Titan stole fire from the gods and gave it to humans?","t":"Titans","e":"\ud83d\udd25","f":"Prometheus means 'forethought'; his less clever brother Epimetheus means 'afterthought'.","o":["Atlas","Cronus","Prometheus","Hyperion"],"s":{"index":2}},{"k":"text","i":"The Roman goddess Venus was known to the Greeks by what name?","t":"Roman names","e":"\ud83d\udc98","f":"Aphrodite, goddess of love, was said to have been born from the sea foam near Cyprus.","s":{"accepted":["Aphrodite","Afrodite","Aphrodit\u00e9"]}},{"k":"choice","i":"Which god is the messenger of the gods, known for his winged sandals?","t":"Gods","e":"\ud83d\udc5f","f":"Hermes was also the god of travellers, merchants and thieves; the Romans called him Mercury.","o":["Hermes","Ares","Apollo","Hephaestus"],"s":{"index":0}},{"k":"truefalse","i":"Apollo and Artemis are twins.","t":"Family tree","e":"\ud83c\udff9","f":"Their mother was the Titaness Leto. Artemis became goddess of the hunt and Apollo god of music and light.","a":true},{"k":"order","i":"Order these figures from the oldest generation to the youngest.","t":"Family tree","e":"\ud83d\udc6a","f":"Earth goddess Gaia was Cronus's mother; Cronus fathered Zeus, and Zeus was Athena's father.","o":["Gaia","Cronus","Zeus","Athena"]}]},{"slug":"where-stars-were-born","title":"Where Stars Were Born","tagline":"Zanzibar, Beirut, Honolulu: guess where famous faces started out.","emoji":"\ud83c\udf1f","gradient":["#d97706","#dc2626"],"categories":["celebs","geo"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":241,"items":[{"k":"choice","i":"In which country was Arnold Schwarzenegger born?","t":"Actors","e":"\ud83d\udcaa","f":"He was born in 1947 in Thal, a village near Graz, and became a bodybuilding champion before Hollywood.","o":["Germany","Switzerland","Austria","Netherlands"],"s":{"index":2}},{"k":"choice","i":"On which Caribbean island was Rihanna born?","t":"Singers","e":"\ud83c\udfdd\ufe0f","f":"Rihanna was born in Saint Michael, Barbados, in 1988.","o":["Barbados","Jamaica","Trinidad","Bahamas"],"s":{"index":0}},{"k":"choice","i":"In which city was actor Keanu Reeves born?","t":"Actors","e":"\ud83d\udd76\ufe0f","f":"Keanu Reeves was born in Beirut, Lebanon, and grew up mainly in Toronto, Canada.","o":["Toronto","Beirut","Sydney","Honolulu"],"s":{"index":1}},{"k":"choice","i":"On which island was Queen singer Freddie Mercury born?","t":"Rock Legends","e":"\ud83d\udc51","f":"He was born Farrokh Bulsara in 1946 in Stone Town, Zanzibar, now part of Tanzania.","o":["Mauritius","Madagascar","Zanzibar","Sri Lanka"],"s":{"index":2}},{"k":"choice","i":"In which city was 'Harry Potter' star Emma Watson born?","t":"Actors","e":"\ud83e\ude84","f":"Emma Watson was born in Paris in 1990 and moved to England at the age of five.","o":["London","Oxford","Dublin","Paris"],"s":{"index":3}},{"k":"choice","i":"Where was action star Jackie Chan born?","t":"Actors","e":"\ud83e\udd4b","f":"Born in 1954, Jackie Chan trained at a Peking opera school as a child, learning acrobatics and martial arts.","o":["Taipei","Hong Kong","Shanghai","Singapore"],"s":{"index":1}},{"k":"truefalse","i":"Australian actress Nicole Kidman was born in Hawaii.","t":"Actors","e":"\ud83c\udf3a","f":"She was born in Honolulu in 1967 to Australian parents and grew up in Sydney.","a":true},{"k":"truefalse","i":"Bruce Lee was born in Hong Kong.","t":"Martial Arts","e":"\ud83c\udf09","f":"Bruce Lee was born in San Francisco in 1940 and raised in Hong Kong.","a":false},{"k":"text","i":"In which South American country was Shakira born?","t":"Singers","e":"\ud83d\udc83","f":"Shakira was born in Barranquilla, on Colombia's Caribbean coast, in 1977.","s":{"accepted":["Colombia","Columbia"]}},{"k":"text","i":"In which US state was Elvis Presley born?","t":"Rock Legends","e":"\ud83c\udfb8","f":"Elvis was born in Tupelo in 1935 and later lived at Graceland in Memphis, Tennessee.","s":{"accepted":["Mississippi"]}},{"k":"number","i":"In what year was Charlie Chaplin born in London?","t":"Silent Era","e":"\ud83c\udfa9","f":"Chaplin grew up in poverty in London before finding fame in Hollywood.","s":{"value":1889,"tolerance":0,"min":1850,"max":1920,"unit":""}},{"k":"multi","i":"Select all the stars who were born in Canada.","t":"Canada","e":"\ud83c\udf41","f":"Hugh Jackman and Chris Hemsworth were born in Australia, and Tom Hanks in California.","o":["C\u00e9line Dion","Hugh Jackman","Ryan Reynolds","Tom Hanks","Justin Bieber","Chris Hemsworth"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these stars by year of birth, oldest first.","t":"Birth Years","e":"\ud83c\udf82","f":"Marilyn Monroe was born in 1926, Elvis in 1935, Madonna in 1958 and Beyonc\u00e9 in 1981.","o":["Marilyn Monroe","Elvis Presley","Madonna","Beyonc\u00e9"]}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '93c06362681b19e82ddd4d97d63f0b2b' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 5'; end $q$;
do $q$ declare d text := $d$[{"slug":"christmas-around-the-globe","title":"Christmas Around the Globe","tagline":"Fried chicken in Japan, Yule Lads in Iceland: how does the world celebrate?","emoji":"\ud83c\udf84","gradient":["#dc2626","#15803d"],"categories":["holidays","culture"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":242,"items":[{"k":"choice","i":"In which country is it a popular tradition to eat KFC fried chicken at Christmas?","t":"Japan","e":"\ud83c\udf57","f":"The custom took off after KFC's 'Kentucky for Christmas' campaign in Japan in 1974.","o":["South Korea","Japan","Australia","Brazil"],"s":{"index":1}},{"k":"choice","i":"In Italian tradition, who brings gifts to children on the night before 6 January?","t":"Italy","e":"\ud83e\uddf9","f":"La Befana is a kindly old witch who flies on a broomstick and fills children's stockings with sweets.","o":["Krampus","Sinterklaas","La Befana","Ded Moroz"],"s":{"index":2}},{"k":"choice","i":"Which famous carol was first performed in Austria in 1818?","t":"Carols","e":"\ud83c\udfb6","f":"'Stille Nacht' was first sung in Oberndorf near Salzburg, with music by Franz Xaver Gruber.","o":["Jingle Bells","Silent Night","Deck the Halls","O Holy Night"],"s":{"index":1}},{"k":"choice","i":"Which country sends a giant Christmas tree to London's Trafalgar Square every year?","t":"Norway","e":"\ud83c\udf32","f":"Oslo has sent the tree every year since 1947 as a thank-you gift to the people of London.","o":["Sweden","Denmark","Norway","Finland"],"s":{"index":2}},{"k":"choice","i":"Which Mexican plant with bright red leaves became a Christmas symbol worldwide?","t":"Mexico","e":"\ud83c\udf3a","f":"It is named after Joel Poinsett, the first US minister to Mexico, who brought it to the USA in the 1820s.","o":["Holly","Poinsettia","Mistletoe","Amaryllis"],"s":{"index":1}},{"k":"choice","i":"In Sweden, millions of families watch what on TV at 3 pm on Christmas Eve?","t":"Sweden","e":"\ud83e\udd86","f":"The Disney show, known as 'Kalle Anka' in Swedish, has been a Christmas Eve tradition there for over 60 years.","o":["A Donald Duck Christmas special","The King's speech","A ski jumping contest","The Nutcracker ballet"],"s":{"index":0}},{"k":"truefalse","i":"Christmas crackers were invented by a London sweet-maker in the 1840s.","t":"UK","e":"\ud83c\udf89","f":"Tom Smith first wrapped sweets in twists of paper, later adding the 'snap', paper hats and jokes.","a":true},{"k":"truefalse","i":"In 1965, astronauts played 'Jingle Bells' on a harmonica from space.","t":"Space","e":"\ud83d\ude80","f":"Gemini 6 astronauts Wally Schirra and Tom Stafford played it after jokingly reporting a 'UFO' in a red suit.","a":true},{"k":"multi","i":"Select all the names of Santa's reindeer from the 1823 poem 'A Visit from St. Nicholas'.","t":"Santa","e":"\ud83e\udd8c","f":"Rudolph joined the team later: he was created in 1939 by Robert L. May for a department store booklet.","o":["Dasher","Rudolph","Comet","Cupid","Sparkle"],"s":{"indices":[0,2,3]}},{"k":"multi","i":"Select all the countries where Christmas falls in summer.","t":"Summer Christmas","e":"\ud83c\udfd6\ufe0f","f":"In the Southern Hemisphere, Christmas comes in summer, so beach trips and barbecues are popular.","o":["Australia","Canada","Argentina","Norway","South Africa"],"s":{"indices":[0,2,4]}},{"k":"text","i":"The Finnish city of Rovaniemi, on the Arctic Circle, is promoted as the official hometown of whom?","t":"Finland","e":"\ud83c\udf85","f":"At Santa Claus Village in Rovaniemi, visitors can step across the line of the Arctic Circle.","s":{"accepted":["Santa Claus","Santa","Father Christmas","Joulupukki","Saint Nicholas"]}},{"k":"number","i":"In Icelandic folklore, how many mischievous Yule Lads visit children before Christmas?","t":"Iceland","e":"\u2744\ufe0f","f":"Each Yule Lad has a funny name, like Spoon-Licker, Door-Slammer and Sausage-Swiper.","s":{"value":13,"tolerance":0,"min":1,"max":20,"unit":""}},{"k":"order","i":"Order these December traditions by date, from earliest to latest.","t":"Calendar","e":"\ud83d\udd6f\ufe0f","f":"On St Lucia Day, 13 December, Swedish girls wear white gowns and crowns of candles.","o":["St Nicholas Day","St Lucia Day","Christmas Eve","Boxing Day"]}]},{"slug":"euro-flag-spotter","title":"Euro Flag Spotter","tagline":"Tricolours, crosses and maps: can you name Europe's flags at a glance?","emoji":"\ud83c\uddea\ud83c\uddfa","gradient":["#1d4ed8","#9333ea"],"categories":["flags","geo"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":243,"items":[{"k":"choice","i":"Which country does this flag belong to?","t":"Tricolours","e":"\ud83c\uddee\ud83c\uddea","f":"Ireland's flag has green for the Gaelic tradition, orange for supporters of William of Orange, and white for peace between them.","o":["India","C\u00f4te d'Ivoire","Italy","Ireland"],"s":{"index":3}},{"k":"choice","i":"Whose flag is this?","t":"Tricolours","e":"\ud83c\uddee\ud83c\uddf9","f":"Italy's flag, 'il Tricolore', was inspired by the French tricolour that arrived with Napoleon's army.","o":["Italy","Mexico","Hungary","Ireland"],"s":{"index":0}},{"k":"text","i":"Name the country this black, red and gold flag belongs to.","t":"Tricolours","e":"\ud83c\udde9\ud83c\uddea","f":"Germany's black-red-gold colours trace back to the uniforms of volunteer soldiers in the early 1800s.","s":{"accepted":["Germany","Deutschland"]}},{"k":"choice","i":"Which country flies this red, white and blue horizontal tricolour?","t":"Tricolours","e":"\ud83c\uddf3\ud83c\uddf1","f":"The Dutch flag's top stripe was originally orange, after William of Orange, before it became red.","o":["Croatia","Netherlands","Russia","France"],"s":{"index":1}},{"k":"choice","i":"Which country's flag has nine blue and white stripes?","t":"Stripes","e":"\ud83c\uddec\ud83c\uddf7","f":"The nine stripes are often said to match the nine syllables of the Greek motto 'Freedom or Death'.","o":["Israel","Greece","Uruguay","Finland"],"s":{"index":1}},{"k":"choice","i":"Which country does this green and red flag with an armillary sphere belong to?","t":"Symbols","e":"\ud83c\uddf5\ud83c\uddf9","f":"The armillary sphere on Portugal's flag honours the navigators of the country's Age of Discovery.","o":["Brazil","Spain","Mozambique","Portugal"],"s":{"index":3}},{"k":"choice","i":"This flag is one of only two square national flags. Which country is it?","t":"Shapes","e":"\ud83c\udde8\ud83c\udded","f":"The only other square national flag belongs to Vatican City.","o":["Austria","Switzerland","Denmark","Georgia"],"s":{"index":1}},{"k":"truefalse","i":"Denmark's flag, the Dannebrog, is often cited as the oldest national flag still in continuous use.","t":"Crosses","e":"\ud83c\udde9\ud83c\uddf0","f":"Legend says the Dannebrog fell from the sky during a battle in Estonia in 1219.","a":true},{"k":"multi","i":"Select all the countries whose flags feature a Nordic cross.","t":"Crosses","e":"\ud83c\uddf3\ud83c\uddf4","f":"The Nordic cross is shifted towards the flagpole side, a design that started with Denmark's flag.","o":["Belgium","Finland","Poland","Austria","Sweden","Norway"],"s":{"indices":[1,4,5]}},{"k":"multi","i":"Select all the countries whose flags use only red and white.","t":"Colours","e":"\ud83c\uddf5\ud83c\uddf1","f":"Monaco and Indonesia also use red and white, with red on top, the reverse of Poland's flag.","o":["Italy","Belgium","Austria","Denmark","Poland"],"s":{"indices":[2,3,4]}},{"k":"choice","i":"Which country's flag is this red, white and green tricolour?","t":"Tricolours","e":"\ud83c\udded\ud83c\uddfa","f":"In Hungary's flag, red is said to stand for strength, white for faithfulness and green for hope.","o":["Iran","Hungary","Italy","Bulgaria"],"s":{"index":1}},{"k":"choice","i":"Whose flag has vertical black, yellow and red stripes?","t":"Tricolours","e":"\ud83c\udde7\ud83c\uddea","f":"Belgium's colours come from the coat of arms of the Duchy of Brabant.","o":["Germany","Romania","Belgium","Andorra"],"s":{"index":2}},{"k":"truefalse","i":"France's tricolour has its blue stripe on the side nearest the flagpole.","t":"Tricolours","e":"\ud83c\uddeb\ud83c\uddf7","f":"France's flag reads blue, white, red from the pole; blue and red are the traditional colours of Paris.","a":true},{"k":"text","i":"Which island nation's flag shows a copper-coloured map of the island?","t":"Maps","e":"\ud83c\udde8\ud83c\uddfe","f":"Cyprus's flag shows the island's outline in copper above two olive branches, a symbol of peace.","s":{"accepted":["Cyprus"]}}]},{"slug":"medieval-times","title":"Medieval Matters","tagline":"Castles, knights and Vikings: how well do you know the Middle Ages?","emoji":"\ud83c\udff0","gradient":["#7c3aed","#1e3a8a"],"categories":["history","culture"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":244,"items":[{"k":"choice","i":"Which English king sealed the Magna Carta at Runnymede?","t":"England","e":"\ud83d\udcdc","f":"Magna Carta, meaning 'Great Charter', limited the king's power and influenced later ideas about the rule of law.","o":["Richard I","Henry II","John","Edward I"],"s":{"index":2}},{"k":"number","i":"In what year was the Magna Carta sealed?","t":"England","e":"\ud83d\udd8b\ufe0f","f":"Four original copies of the 1215 Magna Carta still survive today.","s":{"value":1215,"tolerance":0,"min":1000,"max":1500,"unit":""}},{"k":"text","i":"What is the name for the deep, often water-filled ditch dug around a castle?","t":"Castles","e":"\ud83c\udff0","f":"Moats made it much harder for attackers to reach castle walls or tunnel underneath them.","s":{"accepted":["Moat","A moat","The moat"]}},{"k":"choice","i":"Which famous Paris cathedral was begun in 1163?","t":"Architecture","e":"\u26ea","f":"Notre-Dame de Paris took nearly 200 years to complete.","o":["Notre-Dame","Sacr\u00e9-C\u0153ur","Sainte-Chapelle","Panth\u00e9on"],"s":{"index":0}},{"k":"truefalse","i":"Medieval knights in full plate armour could not get up again if they fell over.","t":"Knights","e":"\ud83d\udee1\ufe0f","f":"A full suit of plate armour weighed about 15 to 25 kg, spread across the body, so knights could move and mount horses.","a":false},{"k":"choice","i":"What was the medieval system in which lords granted land in exchange for loyalty and service?","t":"Society","e":"\ud83d\udc51","f":"At the bottom of the feudal system were serfs, peasants who worked the land and were bound to it.","o":["Mercantilism","Feudalism","Industrialism","Colonialism"],"s":{"index":1}},{"k":"choice","i":"Which Mongol leader founded the Mongol Empire in 1206?","t":"Asia","e":"\ud83d\udc0e","f":"At its height in the 13th century, the Mongol Empire stretched from the Pacific coast of Asia into Eastern Europe.","o":["Kublai Khan","Attila the Hun","Tamerlane","Genghis Khan"],"s":{"index":3}},{"k":"multi","i":"Select all the inventions that were developed in Europe during the Middle Ages.","t":"Inventions","e":"\ud83d\udc53","f":"The first eyeglasses appeared in Italy around 1286.","o":["Eyeglasses","Telescope","Mechanical clock","Steam engine","Gutenberg's printing press"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these events from earliest to latest.","t":"Timeline","e":"\u23f3","f":"Charlemagne was crowned emperor in Rome on Christmas Day in the year 800.","o":["Charlemagne crowned emperor","Norman Conquest of England","Magna Carta sealed","Marco Polo sets out for Asia","Gutenberg's printing press"]},{"k":"choice","i":"In a medieval monastery, what was a 'scriptorium'?","t":"Books","e":"\ud83d\udcd6","f":"Before printing, copying a single book by hand could take a scribe months or even years.","o":["A royal treasury","A jousting arena","A room where monks copied books","A castle tower"],"s":{"index":2}},{"k":"text","i":"Which Venetian merchant became famous for describing his travels to Kublai Khan's China?","t":"Explorers","e":"\ud83e\udded","f":"The book of Marco Polo's travels introduced many Europeans to Asia for the first time.","s":{"accepted":["Marco Polo","Polo"]}},{"k":"truefalse","i":"The Middle Ages are usually dated from about the 5th century to the late 15th century.","t":"Timeline","e":"\ud83d\uddd3\ufe0f","f":"The fall of the Western Roman Empire in 476 is often used as the starting point of the Middle Ages.","a":true},{"k":"choice","i":"Which Norse explorer is believed to have reached North America around the year 1000?","t":"Vikings","e":"\u26f5","f":"A Norse site at L'Anse aux Meadows in Newfoundland, Canada, confirms that Vikings reached North America.","o":["Leif Erikson","Erik the Red","Ragnar Lothbrok","Harald Hardrada"],"s":{"index":0}}]},{"slug":"valhalla-calling","title":"Valhalla Calling","tagline":"Hammers, ravens and a world tree: how deep does your Norse lore go?","emoji":"\ud83d\udd28","gradient":["#334155","#0f766e"],"categories":["myth","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":245,"items":[{"k":"choice","i":"What is the name of Thor's hammer?","t":"Gods","e":"\ud83d\udd28","f":"Forged by dwarves, Mj\u00f6lnir always returned to Thor's hand after he threw it.","o":["Gungnir","Mj\u00f6lnir","Gram","Excalibur"],"s":{"index":1}},{"k":"number","i":"How many legs does Odin's horse Sleipnir have?","t":"Creatures","e":"\ud83d\udc0e","f":"Sleipnir is the fastest of all horses, and, strangely, the trickster Loki is his mother.","s":{"value":8,"tolerance":0,"min":2,"max":12,"unit":"legs"}},{"k":"text","i":"Which day of the week is named after Thor?","t":"Weekdays","e":"\ud83d\udcc5","f":"In German it's 'Donnerstag', thunder's day, after Donar, the German form of Thor's name.","s":{"accepted":["Thursday"]}},{"k":"multi","i":"Select all the English weekdays named after Norse or Germanic gods.","t":"Weekdays","e":"\ud83d\uddd3\ufe0f","f":"Tuesday is Tyr's day, Wednesday Woden's (Odin's) and Friday Frigg's; Saturday comes from the Roman god Saturn.","o":["Wednesday","Tuesday","Saturday","Monday","Friday"],"s":{"indices":[0,1,4]}},{"k":"choice","i":"What is the name of the giant tree that connects the nine worlds?","t":"Cosmos","e":"\ud83c\udf33","f":"Yggdrasil is usually described as a huge ash tree, with a squirrel called Ratatoskr running up and down it.","o":["Bifr\u00f6st","Midgard","Asgard","Yggdrasil"],"s":{"index":3}},{"k":"choice","i":"What did Odin give up in exchange for a drink from the well of wisdom?","t":"Gods","e":"\ud83d\udc41\ufe0f","f":"The well belonged to the wise being M\u00edmir; afterwards Odin is usually shown with just one eye.","o":["One of his eyes","His spear","His voice","His horse"],"s":{"index":0}},{"k":"text","i":"Odin has two ravens that fly around the world bringing him news. Name either one.","t":"Creatures","e":"\ud83d\udc26\u200d\u2b1b","f":"Their names mean 'thought' and 'memory'.","s":{"accepted":["Huginn","Muninn","Hugin","Munin"]}},{"k":"choice","i":"Which god guards Bifr\u00f6st, the rainbow bridge to Asgard?","t":"Gods","e":"\ud83c\udf08","f":"Heimdall can hear grass growing, and will blow the horn Gjallarhorn when Ragnar\u00f6k begins.","o":["Loki","Freyr","Heimdall","Baldr"],"s":{"index":2}},{"k":"truefalse","i":"The goddess Freyja rides in a chariot pulled by two cats.","t":"Gods","e":"\ud83d\udc08","f":"Thor's chariot, meanwhile, is pulled by two goats, Tanngrisnir and Tanngnj\u00f3str.","a":true},{"k":"choice","i":"What is Ragnar\u00f6k in Norse mythology?","t":"Cosmos","e":"\ud83c\udf0b","f":"After Ragnar\u00f6k a new green world rises from the sea and a few surviving gods return.","o":["The end of the world, followed by its rebirth","The home of the gods","A magic golden ring","The first frost giant"],"s":{"index":0}},{"k":"choice","i":"Which shapeshifting trickster is the father of the giant wolf Fenrir?","t":"Gods","e":"\ud83d\udc3a","f":"Fenrir's siblings are the world-circling Midgard Serpent and Hel, ruler of the realm of the dead.","o":["Loki","Tyr","Odin","Freyr"],"s":{"index":0}},{"k":"choice","i":"Where were most of the Norse myths we know today written down?","t":"Sources","e":"\ud83d\udcdc","f":"The Poetic Edda and Snorri Sturluson's Prose Edda were both put together in 13th-century Iceland.","o":["Denmark","England","Germany","Iceland"],"s":{"index":3}},{"k":"truefalse","i":"In Norse myth, Midgard is the world of humans.","t":"Cosmos","e":"\ud83c\udf0d","f":"Midgard means 'middle enclosure'; it is linked to Asgard, home of the gods, by the rainbow bridge.","a":true},{"k":"truefalse","i":"In Norse myth, Thor is the father of Odin.","t":"Family tree","e":"\ud83d\udc68\u200d\ud83d\udc66","f":"It's the other way round: Odin is Thor's father, and Thor's mother is J\u00f6r\u00f0, a giantess who personifies the Earth.","a":false}]},{"slug":"stage-names-unmasked","title":"Stage Names Unmasked","tagline":"Reginald, Stefani, Marshall: match the stars to their real names.","emoji":"\ud83c\udfad","gradient":["#9333ea","#e11d48"],"categories":["celebs","music"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":246,"items":[{"k":"choice","i":"What is Lady Gaga's real first name?","t":"Real Names","e":"\ud83e\udd84","f":"She was born Stefani Joanne Angelina Germanotta in New York City in 1986.","o":["Stefani","Katheryn","Ella","Amber"],"s":{"index":0}},{"k":"choice","i":"Which star was born Reginald Kenneth Dwight?","t":"Real Names","e":"\ud83d\udd76\ufe0f","f":"He took his stage name from saxophonist Elton Dean and singer Long John Baldry.","o":["Freddie Mercury","Elton John","David Bowie","Rod Stewart"],"s":{"index":1}},{"k":"choice","i":"What was Marilyn Monroe's name at birth?","t":"Hollywood","e":"\ud83d\udc8b","f":"The other names belong to Judy Garland, Joan Crawford and Doris Day.","o":["Frances Gumm","Lucille LeSueur","Norma Jeane Mortenson","Doris Kappelhoff"],"s":{"index":2}},{"k":"choice","i":"Which rapper's real name is Marshall Mathers?","t":"Rap","e":"\ud83c\udfa4","f":"The name Eminem comes from his initials, M and M.","o":["Jay-Z","Snoop Dogg","50 Cent","Eminem"],"s":{"index":3}},{"k":"choice","i":"What is the real first name of the singer P!nk?","t":"Real Names","e":"\ud83c\udf38","f":"P!nk was born Alecia Beth Moore in Pennsylvania in 1979.","o":["Christina","Gwen","Alecia","Shania"],"s":{"index":2}},{"k":"choice","i":"Which actor was born Nicolas Kim Coppola?","t":"Hollywood","e":"\ud83c\udfac","f":"He changed his surname so he would not be seen as relying on his uncle, director Francis Ford Coppola.","o":["Ethan Hawke","Nicolas Cage","John Travolta","Michael Keaton"],"s":{"index":1}},{"k":"text","i":"Which musician was born David Robert Jones?","t":"Real Names","e":"\u26a1","f":"He changed his name in the 1960s to avoid confusion with Davy Jones of The Monkees.","s":{"accepted":["David Bowie","Bowie"]}},{"k":"text","i":"Which singer was born Stevland Hardaway Judkins?","t":"Motown","e":"\ud83c\udfb9","f":"He signed with Motown's Tamla label at the age of 11.","s":{"accepted":["Stevie Wonder","Wonder"]}},{"k":"truefalse","i":"Bruno Mars's real name is Peter Gene Hernandez.","t":"Real Names","e":"\ud83c\udf0b","f":"His father nicknamed him 'Bruno' when he was a toddler.","a":true},{"k":"truefalse","i":"The singer Sting's real name is Gordon Sumner.","t":"Real Names","e":"\ud83d\udc1d","f":"He got his nickname from a black-and-yellow striped jumper he liked to wear.","a":true},{"k":"truefalse","i":"Katy Perry's real surname is Perry.","t":"Real Names","e":"\ud83c\udf6d","f":"She was born Katheryn Hudson; Perry was her mother's maiden name.","a":false},{"k":"number","i":"In what year did Prince change his name to an unpronounceable symbol?","t":"Name Changes","e":"\ud83d\udc9c","f":"He was often called 'The Artist Formerly Known as Prince' until he returned to his name in 2000.","s":{"value":1993,"tolerance":0,"min":1980,"max":2005,"unit":""}},{"k":"multi","i":"Select all the stars who perform under a stage name rather than their birth name.","t":"Stage Names","e":"\ud83c\udf9f\ufe0f","f":"Bob Dylan was born Robert Zimmerman and Whoopi Goldberg was born Caryn Johnson.","o":["Elton John","Taylor Swift","Bob Dylan","Leonardo DiCaprio","Whoopi Goldberg"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these stars by year of birth, oldest first.","t":"Birth Years","e":"\ud83c\udf82","f":"Bob Dylan was born in 1941, Elton John in 1947, Eminem in 1972 and Lady Gaga in 1986.","o":["Bob Dylan","Elton John","Eminem","Lady Gaga"]}]},{"slug":"dances-of-the-world","title":"Dances of the World","tagline":"Tango, flamenco, haka, polka: match the moves to their homelands.","emoji":"\ud83d\udc83","gradient":["#c026d3","#e11d48"],"categories":["culture","music","travel"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":247,"items":[{"k":"choice","i":"Flamenco developed in which region of Spain?","t":"Spain","e":"\ud83d\udc83","f":"Flamenco combines song (cante), guitar (toque), dance (baile) and rhythmic hand-clapping (palmas).","o":["Catalonia","Galicia","Andalusia","Basque Country"],"s":{"index":2}},{"k":"choice","i":"The haka is a traditional dance of which people?","t":"New Zealand","e":"\ud83c\udfc9","f":"New Zealand's All Blacks rugby team famously performs the haka 'Ka Mate' before matches.","o":["M\u0101ori of New Zealand","Aboriginal Australians","Native Hawaiians","Inuit of Canada"],"s":{"index":0}},{"k":"choice","i":"Tango was born in the late 1800s around the R\u00edo de la Plata, in Argentina and which other country?","t":"South America","e":"\ud83c\udf39","f":"In 2009, UNESCO added tango to its intangible heritage list at the joint request of Argentina and Uruguay.","o":["Chile","Paraguay","Brazil","Uruguay"],"s":{"index":3}},{"k":"choice","i":"The polka originated in the 1830s in Bohemia, which is part of which modern country?","t":"Czech Republic","e":"\ud83e\ude97","f":"Despite its name, the polka is Czech; one theory links it to 'p\u016flka', Czech for 'half', after its quick half-steps.","o":["Poland","Czech Republic","Austria","Slovakia"],"s":{"index":1}},{"k":"choice","i":"The cs\u00e1rd\u00e1s, a folk dance that starts slowly and ends at a whirlwind pace, comes from which country?","t":"Hungary","e":"\ud83c\udfbb","f":"Its name comes from 'cs\u00e1rda', the Hungarian word for a roadside tavern where people gathered to dance.","o":["Greece","Hungary","Romania","Croatia"],"s":{"index":1}},{"k":"choice","i":"Which Greek dance was actually created for the 1964 film 'Zorba the Greek'?","t":"Greece","e":"\ud83c\udfac","f":"Sirtaki mixes slow and fast steps from the traditional hasapiko dance and was choreographed for the film.","o":["Kalamatianos","Hasapiko","Sirtaki","Tsamiko"],"s":{"index":2}},{"k":"choice","i":"Capoeira, which blends martial arts, acrobatics and music, comes from which country?","t":"Brazil","e":"\ud83e\udd38","f":"Capoeira is played inside a circle called a 'roda', to the sound of a one-stringed instrument called the berimbau.","o":["Cuba","Brazil","Jamaica","Colombia"],"s":{"index":1}},{"k":"truefalse","i":"The waltz is traditionally associated with Vienna, Austria.","t":"Austria","e":"\ud83c\udfbc","f":"Johann Strauss II, the 'Waltz King', premiered 'The Blue Danube' in Vienna in 1867.","a":true},{"k":"truefalse","i":"Hula is a traditional dance from Japan.","t":"Hawaii","e":"\ud83c\udf3a","f":"Hula comes from Hawaii, where its graceful hand movements tell stories about nature, legends and history.","a":false},{"k":"multi","i":"Select all the dances that come from Poland.","t":"Poland","e":"\ud83c\udfb9","f":"Composer Fr\u00e9d\u00e9ric Chopin wrote dozens of mazurkas and polonaises inspired by Polish folk dances.","o":["Mazurka","Flamenco","Polonaise","Samba","Krakowiak"],"s":{"indices":[0,2,4]}},{"k":"text","i":"Which Irish dance show became a worldwide hit after a seven-minute performance at Eurovision 1994?","t":"Ireland","e":"\u2618\ufe0f","f":"Riverdance was first performed as the interval act of the 1994 Eurovision Song Contest in Dublin.","s":{"accepted":["Riverdance","River Dance"]}},{"k":"number","i":"How many beats are there in each bar of a classic waltz?","t":"Rhythm","e":"\ud83c\udfb5","f":"The waltz's '1-2-3' rhythm is written in 3/4 time, with the strongest beat on 'one'.","s":{"value":3,"tolerance":0,"min":1,"max":8,"unit":""}},{"k":"order","i":"Order these dances by their homeland, from west to east.","t":"Geography","e":"\ud83e\udded","f":"Bharatanatyam is a classical dance from Tamil Nadu in southern India, known for expressive hand gestures called mudras.","o":["Tango","Flamenco","Cs\u00e1rd\u00e1s","Bharatanatyam"]}]},{"slug":"flag-safari-asia-africa","title":"Flag Safari: Asia & Africa","tagline":"Rising suns, cedar trees and thunder dragons: spot flags from two continents.","emoji":"\ud83c\udf0d","gradient":["#ea580c","#be123c"],"categories":["flags","geo"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":248,"items":[{"k":"choice","i":"Which country's flag is a red disc on a white background?","t":"Asia","e":"\ud83c\uddef\ud83c\uddf5","f":"Japan's flag is called Nissh\u014dki or Hinomaru, meaning 'circle of the sun'.","o":["Bangladesh","South Korea","Japan","China"],"s":{"index":2}},{"k":"choice","i":"Which country has a green cedar tree on its flag?","t":"Asia","e":"\ud83c\uddf1\ud83c\udde7","f":"The cedar has been a symbol of the region since ancient times and even appears in the Epic of Gilgamesh.","o":["Lebanon","Cyprus","Jordan","Morocco"],"s":{"index":0}},{"k":"choice","i":"Whose flag features a Maasai shield and two crossed spears?","t":"Africa","e":"\ud83c\uddf0\ud83c\uddea","f":"Kenya's flag uses black for the people, red for the struggle for independence and green for the land.","o":["Tanzania","Ethiopia","Kenya","Uganda"],"s":{"index":2}},{"k":"choice","i":"Which country's flag has a 24-spoke wheel in its centre?","t":"Asia","e":"\ud83c\uddee\ud83c\uddf3","f":"The navy-blue wheel is the Ashoka Chakra, taken from an ancient lion sculpture at Sarnath.","o":["Pakistan","Sri Lanka","India","Nepal"],"s":{"index":2}},{"k":"text","i":"Which country has the world's only non-rectangular national flag, made of two stacked triangles?","t":"Asia","e":"\ud83c\uddf3\ud83c\uddf5","f":"Nepal's two triangular pennants carry a white moon and a white sun.","s":{"accepted":["Nepal"]}},{"k":"choice","i":"Which country's flag shows a red and blue circle surrounded by four black trigrams?","t":"Asia","e":"\ud83c\uddf0\ud83c\uddf7","f":"South Korea's flag is called Taegukgi, after the red and blue taegeuk circle in the middle.","o":["Vietnam","South Korea","Mongolia","Japan"],"s":{"index":1}},{"k":"choice","i":"Which country's flag has a sideways green 'Y' shape and six colours?","t":"Africa","e":"\ud83c\uddff\ud83c\udde6","f":"South Africa's six-colour flag was first raised in 1994 and was originally meant to be temporary.","o":["Namibia","Zimbabwe","South Africa","Ghana"],"s":{"index":2}},{"k":"truefalse","i":"Bhutan's flag features a white dragon.","t":"Asia","e":"\ud83c\udde7\ud83c\uddf9","f":"The dragon is the Druk, or Thunder Dragon, and Bhutan calls itself Druk Yul, 'Land of the Thunder Dragon'.","a":true},{"k":"multi","i":"Select all the countries whose flags feature a crescent moon.","t":"Symbols","e":"\ud83c\udf19","f":"A crescent and star appear on several flags across North Africa and Asia, from Algeria to Malaysia.","o":["Malaysia","Kenya","Ghana","Pakistan","Turkey","Japan"],"s":{"indices":[0,3,4]}},{"k":"choice","i":"Which country's flag has a black star on red, gold and green stripes?","t":"Africa","e":"\ud83c\uddec\ud83c\udded","f":"Ghana's black star inspired the nickname of its national football team, the Black Stars.","o":["Mali","Ghana","Senegal","Cameroon"],"s":{"index":1}},{"k":"multi","i":"Select all the countries whose flags use green, yellow and red.","t":"Africa","e":"\ud83c\uddea\ud83c\uddf9","f":"Green, gold and red are known as Pan-African colours, inspired by the flag of Ethiopia.","o":["Ethiopia","Senegal","Mali","Tunisia","Egypt"],"s":{"indices":[0,1,2]}},{"k":"choice","i":"Whose flag has red, white and blue stripes, with a wide blue band in the middle?","t":"Asia","e":"\ud83c\uddf9\ud83c\udded","f":"Thailand's flag is called Thong Trairong, meaning 'tricolour flag'.","o":["Laos","Cambodia","Thailand","Costa Rica"],"s":{"index":2}},{"k":"order","i":"Order these countries' flags by their number of stars, from fewest to most.","t":"Stars","e":"\u2b50","f":"Cape Verde's flag has ten stars, representing the country's ten main islands.","o":["Vietnam","Philippines","China","Cape Verde"]},{"k":"truefalse","i":"Sri Lanka's flag features a golden lion holding a sword.","t":"Asia","e":"\ud83c\uddf1\ud83c\uddf0","f":"The golden lion has given Sri Lanka's national flag its popular nickname, the 'Lion Flag'.","a":true}]},{"slug":"periodic-table-challenge","title":"Periodic Table Challenge","tagline":"Symbols, gases and metals: are you in your element?","emoji":"\u2697\ufe0f","gradient":["#059669","#0e7490"],"categories":["science"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":249,"items":[{"k":"text","i":"Which element has the chemical symbol 'Au'?","t":"Symbols","e":"\ud83e\udd47","f":"'Au' comes from 'aurum', the Latin word for gold.","s":{"accepted":["Gold"]}},{"k":"choice","i":"What is the most abundant gas in Earth's atmosphere?","t":"Gases","e":"\ud83d\udca8","f":"Nitrogen makes up about 78% of the air we breathe; oxygen makes up about 21%.","o":["Oxygen","Nitrogen","Carbon dioxide","Argon"],"s":{"index":1}},{"k":"choice","i":"Which element has atomic number 1?","t":"Elements","e":"\ud83c\udf88","f":"Hydrogen is the most abundant element in the universe.","o":["Helium","Lithium","Hydrogen","Oxygen"],"s":{"index":2}},{"k":"number","i":"What is the atomic number of carbon?","t":"Elements","e":"\u270f\ufe0f","f":"Carbon atoms can link into long chains and rings, forming the backbone of all known life.","s":{"value":6,"tolerance":0,"min":1,"max":20,"unit":""}},{"k":"multi","i":"Select all the noble gases.","t":"Gases","e":"\ud83d\udca1","f":"Noble gases rarely react with other elements because their outer electron shells are full.","o":["Neon","Nitrogen","Argon","Chlorine","Krypton"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"Which metal is a liquid at room temperature?","t":"Metals","e":"\ud83c\udf21\ufe0f","f":"Mercury's symbol, Hg, comes from 'hydrargyrum', meaning 'liquid silver'.","o":["Lead","Tin","Aluminium","Mercury"],"s":{"index":3}},{"k":"truefalse","i":"The chemical symbol for sodium is 'So'.","t":"Symbols","e":"\ud83e\uddc2","f":"Sodium's symbol is Na, from its Latin name 'natrium'.","a":false},{"k":"choice","i":"Which element is named after the creator of the periodic table?","t":"History","e":"\ud83d\udccb","f":"Dmitri Mendeleev published his periodic table in 1869, leaving gaps for elements not yet discovered.","o":["Mendelevium","Einsteinium","Curium","Nobelium"],"s":{"index":0}},{"k":"order","i":"Order these elements by atomic number, from lowest to highest.","t":"Elements","e":"\ud83d\udd22","f":"An element's atomic number is the number of protons in the nucleus of each of its atoms.","o":["Hydrogen","Helium","Carbon","Oxygen","Iron"]},{"k":"multi","i":"Select all the elements that are metals.","t":"Metals","e":"\ud83d\udd29","f":"Copper was one of the first metals people learned to use, around 10,000 years ago.","o":["Iron","Sulfur","Copper","Neon","Zinc"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"What is the lightest (least dense) metal?","t":"Metals","e":"\ud83d\udd0b","f":"Lithium is so light that it floats on water, although it reacts with it.","o":["Sodium","Lithium","Aluminium","Magnesium"],"s":{"index":1}},{"k":"truefalse","i":"Diamond and graphite (pencil 'lead') are both made of pure carbon.","t":"Elements","e":"\ud83d\udc8e","f":"The difference between them comes entirely from how their carbon atoms are arranged.","a":true},{"k":"choice","i":"What is the chemical symbol for silver?","t":"Symbols","e":"\ud83e\udd48","f":"'Ag' comes from 'argentum', the Latin word for silver; Argentina's name comes from the same root.","o":["Si","Sv","Ag","Sl"],"s":{"index":2}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'd17c7f0971c5f012493ef8696667e8c2' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 6'; end $q$;
do $q$ declare d text := $d$[{"slug":"mythical-beasts","title":"Mythical Beasts","tagline":"Phoenixes, kappas and huts on chicken legs: legends from every corner of the globe.","emoji":"\ud83d\udc09","gradient":["#9333ea","#16a34a"],"categories":["myth","culture"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":250,"items":[{"k":"choice","i":"Which mythical creature is the national animal of Scotland?","t":"National symbols","e":"\ud83e\udd84","f":"Unicorns appear on Scotland's royal coat of arms, usually shown wearing a golden chain.","o":["Dragon","Unicorn","Griffin","Phoenix"],"s":{"index":1}},{"k":"choice","i":"In Slavic folklore, the witch Baba Yaga lives in a hut standing on what?","t":"Slavic","e":"\ud83d\udc14","f":"Her hut can turn to face visitors, and she flies through the air in a large mortar.","o":["A giant turtle","Tall stilts","A floating cloud","Chicken legs"],"s":{"index":3}},{"k":"multi","i":"Select all the creatures that are part human, part animal.","t":"Hybrids","e":"\ud83e\udddc","f":"Centaurs are half horse, the Minotaur half bull and mermaids half fish; the griffin mixes lion and eagle.","o":["Minotaur","Mermaid","Pegasus","Griffin","Centaur"],"s":{"indices":[0,1,4]}},{"k":"text","i":"Which fiery bird is said to be reborn from its own ashes?","t":"Birds","e":"\ud83d\udd25","f":"The Greek historian Herodotus wrote that the phoenix came to Egypt only once every 500 years.","s":{"accepted":["Phoenix","The phoenix","A phoenix","Fenix","Phenix"]}},{"k":"choice","i":"In Japanese folklore, where does the mischievous kappa live?","t":"Japanese","e":"\ud83d\udc22","f":"A kappa carries water in a dish on top of its head; if it spills, the kappa loses its strength.","o":["On mountain tops","In rivers and ponds","Inside volcanoes","In bamboo forests"],"s":{"index":1}},{"k":"choice","i":"Anansi, the clever trickster of West African and Caribbean tales, usually takes the form of which animal?","t":"West African","e":"\ud83d\udd77\ufe0f","f":"Anansi stories come from the Akan people of Ghana and travelled to the Caribbean, where they are still told.","o":["A tortoise","A monkey","A crow","A spider"],"s":{"index":3}},{"k":"choice","i":"Where is the Yeti, or 'Abominable Snowman', said to live?","t":"Cryptids","e":"\ud83c\udfd4\ufe0f","f":"North America has its own big hairy legend: Bigfoot, also known as Sasquatch.","o":["The Alps","The Andes","The Rocky Mountains","The Himalayas"],"s":{"index":3}},{"k":"truefalse","i":"A red dragon appears on the national flag of Wales.","t":"National symbols","e":"\ud83d\udc32","f":"Y Ddraig Goch, the Red Dragon, stands on a background of green and white.","a":true},{"k":"choice","i":"The Turul, a great falcon-like bird, is a legendary national symbol of which country?","t":"National symbols","e":"\ud83e\udd85","f":"A large bronze Turul statue spreads its wings over the Danube at Buda Castle in Budapest.","o":["Greece","Hungary","Ireland","Norway"],"s":{"index":1}},{"k":"number","i":"In Greek myth, how many new heads did the Hydra grow for each one that was cut off?","t":"Greek","e":"\ud83d\udc0d","f":"Heracles defeated the Hydra as one of his labours, with help from his nephew Iolaus.","s":{"value":2,"tolerance":0,"min":1,"max":10,"unit":""}},{"k":"truefalse","i":"The Kraken is a giant sea monster from Japanese legend.","t":"Sea monsters","e":"\ud83e\udd91","f":"The Kraken comes from Scandinavian folklore and is usually imagined as an enormous squid or octopus.","a":false},{"k":"choice","i":"In Greek myth, which creature asked travellers what walks on four legs in the morning, two at noon and three in the evening?","t":"Greek","e":"\ud83e\udd81","f":"Oedipus solved it: a human crawls as a baby, walks as an adult and uses a stick in old age.","o":["The Cyclops","The Minotaur","The Sphinx","Medusa"],"s":{"index":2}},{"k":"choice","i":"According to Irish folklore, what does a leprechaun keep hidden?","t":"Irish","e":"\ud83c\udf40","f":"Leprechauns are traditionally pictured as shoemakers who guard their gold very carefully.","o":["A magic harp","A pot of gold","A silver key","A four-leaf clover"],"s":{"index":1}},{"k":"choice","i":"In Japanese folklore, the kitsune is a magical shapeshifting\u2026","t":"Japanese","e":"\ud83e\udd8a","f":"The more tails a kitsune has, the older and wiser it is, up to a maximum of nine.","o":["Fox","Cat","Crane","Badger"],"s":{"index":0}}]},{"slug":"oscar-night-legends","title":"Oscar Night Legends","tagline":"Golden statuettes, famous firsts and big winners from Academy Awards history.","emoji":"\ud83c\udfc6","gradient":["#ca8a04","#7c2d12"],"categories":["celebs","movies"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":251,"items":[{"k":"choice","i":"Which actor won Best Actor Oscars in back-to-back years for 'Philadelphia' and 'Forrest Gump'?","t":"Best Actor","e":"\ud83c\udfc3","f":"Spencer Tracy, in the 1930s, was the only actor before Hanks to win Best Actor two years in a row.","o":["Tom Hanks","Denzel Washington","Al Pacino","Daniel Day-Lewis"],"s":{"index":0}},{"k":"choice","i":"For which film did Leonardo DiCaprio win the Oscar for Best Actor?","t":"Best Actor","e":"\ud83d\udc3b","f":"He won at the 2016 ceremony after four previous acting nominations.","o":["Titanic","The Aviator","The Revenant","Inception"],"s":{"index":2}},{"k":"choice","i":"Which actress won Best Actress for the musical 'La La Land' (2016)?","t":"Best Actress","e":"\ud83c\udfb9","f":"La La Land won six Oscars, including Best Director for Damien Chazelle.","o":["Emma Watson","Emma Stone","Natalie Portman","Jennifer Lawrence"],"s":{"index":1}},{"k":"choice","i":"What is the official name of the Oscar statuette?","t":"The Statuette","e":"\u2728","f":"The gold-plated statuette stands about 34 cm (13.5 in) tall.","o":["Golden Knight Trophy","Hollywood Honor","Silver Screen Medal","Academy Award of Merit"],"s":{"index":3}},{"k":"choice","i":"Which actress won Best Actress for playing the title role in 'Mary Poppins' (1964)?","t":"Best Actress","e":"\u2602\ufe0f","f":"Mary Poppins was Julie Andrews' very first film role.","o":["Audrey Hepburn","Judy Garland","Debbie Reynolds","Julie Andrews"],"s":{"index":3}},{"k":"number","i":"How many Best Actress Oscars did Katharine Hepburn win?","t":"Records","e":"\u2b50","f":"Her four wins came between 1934 and 1982, for films from 'Morning Glory' to 'On Golden Pond'.","s":{"value":4,"tolerance":0,"min":1,"max":8,"unit":""}},{"k":"number","i":"In what year was the very first Academy Awards ceremony held?","t":"Oscar History","e":"\ud83d\udcc5","f":"The first ceremony, at the Hollywood Roosevelt Hotel, lasted only about 15 minutes.","s":{"value":1929,"tolerance":0,"min":1900,"max":1960,"unit":""}},{"k":"truefalse","i":"Heath Ledger won an Oscar for playing the Joker in 'The Dark Knight' (2008).","t":"Supporting Roles","e":"\ud83c\udccf","f":"He won Best Supporting Actor; the award was given posthumously and accepted by his family.","a":true},{"k":"truefalse","i":"Meryl Streep made her film debut in the 1990s.","t":"Stars","e":"\ud83c\udfad","f":"Her film debut was 'Julia' (1977), and she won her first Oscar for 'Kramer vs. Kramer' (1979).","a":false},{"k":"truefalse","i":"Walt Disney holds the record for the most Academy Awards won by an individual.","t":"Records","e":"\ud83d\udc2d","f":"Walt Disney won 22 competitive Oscars plus four honorary awards.","a":true},{"k":"text","i":"In 2002, who became the first Black woman to win the Academy Award for Best Actress?","t":"Famous Firsts","e":"\ud83c\udf1f","f":"Halle Berry won at the 74th Academy Awards in March 2002.","s":{"accepted":["Halle Berry","Berry"]}},{"k":"multi","i":"Select all the actors who have won the Oscar for Best Actor.","t":"Best Actor","e":"\ud83c\udf96\ufe0f","f":"Daniel Day-Lewis has won Best Actor three times, a record for the category.","o":["Daniel Day-Lewis","Richard Burton","Anthony Hopkins","Harrison Ford","Denzel Washington"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these Best Picture winners from earliest to latest.","t":"Best Picture","e":"\ud83c\udfac","f":"They are films from 1965, 1976, 1994, 1997 and 2011.","o":["The Sound of Music","Rocky","Forrest Gump","Titanic","The Artist"]}]},{"slug":"fact-or-fiction-world-tour","title":"Fact or Fiction: World Tour","tagline":"Quirky customs and surprising facts from around the globe. Fact or fiction?","emoji":"\ud83e\udd14","gradient":["#0d9488","#2563eb"],"categories":["culture","travel","general"],"countries":null,"difficulty":"Easy","minutes":3,"questions":10,"prompt":"Fact or fiction?","yes_label":"Fact","no_label":"Fiction","sort":252,"items":[{"k":"truefalse","i":"Fortune cookies were invented in China.","t":"Food","e":"\ud83e\udd60","f":"Fortune cookies became popular in California in the early 1900s and are rarely seen in China.","a":false},{"k":"truefalse","i":"In Japan, it is customary to take off your shoes before entering someone's home.","t":"Japan","e":"\ud83d\udc5f","f":"Many Japanese homes have a 'genkan', an entryway where shoes are removed and slippers are put on.","a":true},{"k":"truefalse","i":"The croissant has roots in Austria.","t":"Food","e":"\ud83e\udd50","f":"The croissant is thought to descend from the Austrian 'kipferl', brought to Paris by Viennese bakers in the 1830s.","a":true},{"k":"truefalse","i":"Spain's famous afternoon nap is called the 'fiesta'.","t":"Spain","e":"\ud83d\ude34","f":"The nap is the 'siesta'; a 'fiesta' is a party or festival.","a":false},{"k":"truefalse","i":"The kilt is a traditional garment from Scotland.","t":"Scotland","e":"\ud83e\uddf5","f":"Kilts are often made of tartan, a criss-cross pattern of coloured stripes.","a":true},{"k":"truefalse","i":"Venice is built on more than 100 small islands.","t":"Italy","e":"\ud83d\udef6","f":"Venice spreads across about 118 small islands linked by more than 400 bridges.","a":true},{"k":"truefalse","i":"In Thailand, the traditional greeting is a firm handshake.","t":"Thailand","e":"\ud83d\ude4f","f":"The traditional Thai greeting is the 'wai': a slight bow with the palms pressed together.","a":false},{"k":"truefalse","i":"Canada has two official languages: English and French.","t":"Canada","e":"\ud83c\udf41","f":"Canada's official bilingualism was set out in the Official Languages Act of 1969.","a":true},{"k":"truefalse","i":"Bagpipes are played only in Scotland.","t":"Music","e":"\ud83c\udfb6","f":"Bagpipes are played across Europe and beyond, from Ireland and Spain's Galicia to Bulgaria.","a":false},{"k":"truefalse","i":"Russian matryoshka dolls are designed to nest inside one another.","t":"Russia","e":"\ud83e\ude86","f":"The first matryoshka set, made in the 1890s, had eight dolls.","a":true},{"k":"truefalse","i":"Origami is the Japanese art of flower arranging.","t":"Japan","e":"\ud83e\udda2","f":"Origami is the art of paper folding; Japanese flower arranging is called ikebana.","a":false},{"k":"truefalse","i":"Tulips originally come from the Netherlands.","t":"Netherlands","e":"\ud83c\udf37","f":"Tulips grow wild in Central Asia and reached the Netherlands via the Ottoman Empire in the 1500s.","a":false},{"k":"truefalse","i":"Fish and chips is a classic takeaway meal in the United Kingdom.","t":"UK","e":"\ud83d\udc1f","f":"Fish and chip shops began appearing in Britain in the 1860s.","a":true}]},{"slug":"euro-capital-quest","title":"Euro Capital Quest","tagline":"From Lisbon to Helsinki: hop across Europe one capital city at a time.","emoji":"\ud83c\udff0","gradient":["#7c3aed","#db2777"],"categories":["capitals","geo","travel"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":253,"items":[{"k":"choice","i":"What is the capital of Switzerland?","t":"Western Europe","e":"\ud83c\udde8\ud83c\udded","f":"Switzerland's constitution names no official capital, so Bern is officially called the 'federal city'.","o":["Bern","Basel","Geneva","Zurich"],"s":{"index":0}},{"k":"choice","i":"What is the capital of Slovenia?","t":"Central Europe","e":"\ud83c\uddf8\ud83c\uddee","f":"Ljubljana's symbol is a dragon, which you can see on the city's famous Dragon Bridge.","o":["Ljubljana","Bratislava","Skopje","Zagreb"],"s":{"index":0}},{"k":"text","i":"What is the capital of Norway?","t":"Northern Europe","e":"\ud83c\uddf3\ud83c\uddf4","f":"Oslo was called Christiania for about 300 years before taking back its old name in 1925.","s":{"accepted":["Oslo"]}},{"k":"choice","i":"What is the capital of Croatia?","t":"Southern Europe","e":"\ud83c\udded\ud83c\uddf7","f":"Zagreb's funicular railway is one of the shortest in the world, at only about 66 m long.","o":["Sarajevo","Split","Zagreb","Dubrovnik"],"s":{"index":2}},{"k":"multi","i":"Select all the capitals that stand on the River Danube.","t":"Rivers","e":"\ud83c\udf0a","f":"Belgrade is a fourth Danube capital, making the Danube the river that flows through the most capital cities.","o":["Prague","Warsaw","Vienna","Budapest","Bratislava"],"s":{"indices":[2,3,4]}},{"k":"order","i":"Order these capitals from west to east.","t":"Geography","e":"\ud83e\udded","f":"Lisbon is the westernmost capital city of mainland Europe.","o":["Lisbon","Madrid","Rome","Athens"]},{"k":"truefalse","i":"Edinburgh is the capital of Scotland.","t":"Northern Europe","e":"\ud83c\udff4","f":"Edinburgh Castle sits on Castle Rock, the plug of an extinct volcano.","a":true},{"k":"choice","i":"What is the capital of Romania?","t":"Eastern Europe","e":"\ud83c\uddf7\ud83c\uddf4","f":"Bucharest's Palace of the Parliament is often listed as the heaviest building in the world.","o":["Budapest","Sofia","Chi\u0219in\u0103u","Bucharest"],"s":{"index":3}},{"k":"multi","i":"Select all the capital cities that lie on the Baltic Sea.","t":"Coasts","e":"\u2693","f":"Helsinki and Tallinn face each other across the Gulf of Finland, only about 80 km apart.","o":["Oslo","Warsaw","Stockholm","Helsinki","Tallinn"],"s":{"indices":[2,3,4]}},{"k":"truefalse","i":"Krak\u00f3w is the capital of Poland.","t":"Central Europe","e":"\ud83c\uddf5\ud83c\uddf1","f":"Warsaw is Poland's capital; Krak\u00f3w was the royal capital until the late 1500s.","a":false},{"k":"choice","i":"What is the capital of Lithuania?","t":"Northern Europe","e":"\ud83c\uddf1\ud83c\uddf9","f":"Vilnius has one of the largest surviving medieval old towns in Northern Europe.","o":["Kaunas","Tallinn","Vilnius","Riga"],"s":{"index":2}},{"k":"number","i":"According to legend, Rome was founded in which year BC?","t":"Legends","e":"\ud83d\udc3a","f":"Legend says Rome was founded by Romulus, who named the city after himself.","s":{"value":753,"tolerance":0,"min":500,"max":1000,"unit":"BC"}},{"k":"choice","i":"What is the capital of Belgium, home to many European Union institutions?","t":"Western Europe","e":"\ud83c\udde7\ud83c\uddea","f":"Brussels' Grand-Place, lined with ornate guild houses, is a UNESCO World Heritage Site.","o":["Brussels","Antwerp","Bruges","Ghent"],"s":{"index":0}},{"k":"text","i":"What is the capital of Iceland?","t":"Northern Europe","e":"\ud83c\uddee\ud83c\uddf8","f":"Reykjav\u00edk is the northernmost capital of a sovereign state in the world.","s":{"accepted":["Reykjavik","Reykjav\u00edk"]}}]},{"slug":"famous-scientists-and-discoveries","title":"Great Scientists","tagline":"Eureka! From Newton's apple to Einstein's E = mc\u00b2.","emoji":"\ud83d\udd2c","gradient":["#2563eb","#7c3aed"],"categories":["science","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":254,"items":[{"k":"choice","i":"Which pair of scientists published the double-helix model of DNA in 1953?","t":"Biology","e":"\ud83e\uddec","f":"Their model drew on X-ray images of DNA made by Rosalind Franklin.","o":["Charles Darwin and Alfred Wallace","James Watson and Francis Crick","Pierre and Marie Curie","Robert Hooke and Robert Boyle"],"s":{"index":1}},{"k":"choice","i":"Which scientist formulated the laws of motion and the law of universal gravitation?","t":"Physics","e":"\ud83c\udf4e","f":"Newton himself later told the story of how a falling apple got him thinking about gravity.","o":["Johannes Kepler","Galileo Galilei","Nicolaus Copernicus","Isaac Newton"],"s":{"index":3}},{"k":"text","i":"Who proposed the theory of evolution by natural selection in 'On the Origin of Species' (1859)?","t":"Biology","e":"\ud83d\udc22","f":"Darwin's visit to the Gal\u00e1pagos Islands aboard HMS Beagle helped shape his ideas.","s":{"accepted":["Charles Darwin","Darwin"]}},{"k":"choice","i":"Marie Curie won Nobel Prizes in which two sciences?","t":"Chemistry","e":"\u2622\ufe0f","f":"In 1903, Marie Curie became the first woman ever to win a Nobel Prize.","o":["Chemistry and Medicine","Physics and Medicine","Physics and Chemistry","Chemistry and Biology"],"s":{"index":2}},{"k":"number","i":"In what year did Galileo Galilei first observe Jupiter's four largest moons?","t":"Astronomy","e":"\ud83d\udd2d","f":"Io, Europa, Ganymede and Callisto are still called the Galilean moons in his honour.","s":{"value":1610,"tolerance":0,"min":1500,"max":1800,"unit":""}},{"k":"choice","i":"Who discovered the electron in 1897?","t":"Physics","e":"\u269b\ufe0f","f":"Thomson discovered the electron while experimenting with cathode rays.","o":["J.J. Thomson","Ernest Rutherford","Michael Faraday","James Chadwick"],"s":{"index":0}},{"k":"order","i":"Order these scientists by year of birth, from earliest to latest.","t":"Timeline","e":"\ud83d\udcc6","f":"Albert Einstein was born in 1879, the same year that physicist James Clerk Maxwell died.","o":["Galileo Galilei","Isaac Newton","Charles Darwin","Marie Curie","Albert Einstein"]},{"k":"multi","i":"Select all the scientists who won a Nobel Prize.","t":"Nobel Prize","e":"\ud83c\udfc6","f":"The first Nobel Prizes were awarded in 1901, long after Newton and Darwin had died.","o":["Albert Einstein","Isaac Newton","Marie Curie","Charles Darwin","Niels Bohr"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"Which astronomer published a detailed Sun-centred model of the solar system in 1543?","t":"Astronomy","e":"\u2600\ufe0f","f":"Copernicus's great book was published in 1543, the year he died.","o":["Ptolemy","Nicolaus Copernicus","Johannes Kepler","Tycho Brahe"],"s":{"index":1}},{"k":"text","i":"Which scientist's famous equation E = mc\u00b2 links mass and energy?","t":"Physics","e":"\ud83d\udca1","f":"The 'c' is the speed of light; squared, it is a huge number, so a little mass holds a lot of energy.","s":{"accepted":["Albert Einstein","Einstein"]}},{"k":"number","i":"In what year did Isaac Newton publish his 'Principia', setting out his laws of motion?","t":"Physics","e":"\ud83d\udcd8","f":"The Principia is widely regarded as one of the most important books in the history of science.","s":{"value":1687,"tolerance":0,"min":1500,"max":1900,"unit":""}},{"k":"choice","i":"Which scientist is known as the father of genetics for his experiments with pea plants?","t":"Biology","e":"\ud83c\udf31","f":"Mendel grew thousands of pea plants in his monastery garden to study how traits are inherited.","o":["Louis Pasteur","Carl Linnaeus","Gregor Mendel","Robert Hooke"],"s":{"index":2}},{"k":"truefalse","i":"Albert Einstein won his Nobel Prize for the theory of relativity.","t":"Nobel Prize","e":"\ud83c\udf93","f":"Einstein's 1921 Nobel Prize in Physics was awarded for explaining the photoelectric effect.","a":false}]},{"slug":"alphabet-soup-orgs","title":"Alphabet Soup","tagline":"UN, WHO, UNESCO, ICJ: how well do you know the world's big organisations?","emoji":"\ud83c\udf0d","gradient":["#2563eb","#0891b2"],"categories":["society","general"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":255,"items":[{"k":"number","i":"In what year was the United Nations founded?","t":"United Nations","e":"\ud83c\uddfa\ud83c\uddf3","f":"The UN Charter was signed in San Francisco in June 1945 by representatives of 50 countries.","s":{"value":1945,"tolerance":0,"min":1900,"max":2000,"unit":""}},{"k":"choice","i":"In which city is the headquarters of the United Nations?","t":"United Nations","e":"\ud83c\udfd9\ufe0f","f":"The UN issues its own postage stamps, which can only be posted from its offices in New York, Geneva and Vienna.","o":["Geneva","Brussels","Vienna","New York"],"s":{"index":3}},{"k":"multi","i":"Select all the official languages of the United Nations.","t":"United Nations","e":"\ud83d\udde3\ufe0f","f":"There are six in total: Arabic, Chinese, English, French, Russian and Spanish.","o":["Chinese","Arabic","Portuguese","German","Spanish","Japanese"],"s":{"indices":[0,1,4]}},{"k":"choice","i":"The World Health Organization (WHO) is headquartered in which city?","t":"Health","e":"\ud83c\udfe5","f":"The WHO was founded on 7 April 1948, a date now marked every year as World Health Day.","o":["Paris","Geneva","London","Rome"],"s":{"index":1}},{"k":"text","i":"Which UN agency, based in Paris, keeps the famous World Heritage List?","t":"Culture","e":"\ud83c\udfdb\ufe0f","f":"UNESCO stands for the United Nations Educational, Scientific and Cultural Organization.","s":{"accepted":["UNESCO","Unesco"]}},{"k":"choice","i":"Who founded the Red Cross movement in 1863?","t":"Humanitarian","e":"\u26d1\ufe0f","f":"Swiss businessman Henry Dunant shared the very first Nobel Peace Prize, awarded in 1901.","o":["Florence Nightingale","Alfred Nobel","Henry Dunant","Louis Pasteur"],"s":{"index":2}},{"k":"number","i":"How many stars are on the flag of the European Union?","t":"Europe","e":"\ud83c\uddea\ud83c\uddfa","f":"The number never changes: twelve stands for unity and completeness, not the number of member states.","s":{"value":12,"tolerance":0,"min":1,"max":30,"unit":"stars"}},{"k":"multi","i":"Select all the founding members of the European Economic Community in 1957.","t":"Europe","e":"\ud83e\udd1d","f":"The six founders were Belgium, France, Italy, Luxembourg, the Netherlands and West Germany.","o":["United Kingdom","Italy","Spain","Denmark","France","Belgium"],"s":{"indices":[1,4,5]}},{"k":"choice","i":"In which city is the International Olympic Committee based?","t":"Sport","e":"\ud83c\udfc5","f":"Lausanne, Switzerland, calls itself the 'Olympic Capital' and is home to the Olympic Museum.","o":["Athens","Paris","Zurich","Lausanne"],"s":{"index":3}},{"k":"truefalse","i":"The Schengen Agreement, which removed border checks across much of Europe, is named after a small village in Luxembourg.","t":"Europe","e":"\ud83d\udec2","f":"It was signed in 1985 aboard a boat on the Moselle river, close to where Luxembourg, France and Germany meet.","a":true},{"k":"choice","i":"What did the 'C' in UNICEF originally stand for?","t":"Acronyms","e":"\ud83e\uddd2","f":"Founded in 1946 as the International Children's Emergency Fund, it's now the UN Children's Fund but kept the acronym.","o":["Cultural","Children's","Council","Cooperation"],"s":{"index":1}},{"k":"choice","i":"In which city does the International Court of Justice sit?","t":"Justice","e":"\u2696\ufe0f","f":"The court meets in the Peace Palace, a building largely funded by industrialist Andrew Carnegie.","o":["Brussels","Geneva","Strasbourg","The Hague"],"s":{"index":3}},{"k":"truefalse","i":"Interpol, the international police organisation, has its headquarters in London.","t":"Justice","e":"\ud83d\ude93","f":"Interpol's General Secretariat is in Lyon, France; the organisation was founded in 1923.","a":false},{"k":"order","i":"Order these organisations by founding year, oldest first.","t":"Timeline","e":"\ud83d\udcc6","f":"1863, 1894, 1945 and 1971. Doctors Without Borders (MSF) was founded in France by doctors and journalists.","o":["Red Cross (ICRC)","International Olympic Committee","United Nations","Doctors Without Borders"]}]},{"slug":"console-chronicles","title":"Console Chronicles","tagline":"Cartridges to discs: trace the history of home and handheld consoles.","emoji":"\ud83c\udfae","gradient":["#16a34a","#1e40af"],"categories":["gaming","tech"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":256,"items":[{"k":"choice","i":"Which company made the original PlayStation?","t":"Consoles","e":"\ud83d\udd79\ufe0f","f":"The first PlayStation launched in Japan in December 1994.","o":["Sega","Nintendo","Microsoft","Sony"],"s":{"index":3}},{"k":"choice","i":"Which handheld console did Nintendo release in 1989?","t":"Handhelds","e":"\ud83d\udd0b","f":"The original Game Boy ran on four AA batteries and had a green-tinted screen.","o":["Game Boy","Virtual Boy","Nintendo DS","Game & Watch"],"s":{"index":0}},{"k":"choice","i":"What does 'SNES' stand for?","t":"Acronyms","e":"\ud83d\udd24","f":"The SNES was released in Japan in 1990, where it was called the Super Famicom.","o":["Sega Nintendo Electronic Set","Standard Nintendo Electronic System","Super Nintendo Entertainment System","Super Network Entertainment Station"],"s":{"index":2}},{"k":"choice","i":"What was the name of the handheld console Sony released in 2004?","t":"Handhelds","e":"\ud83d\udcf1","f":"PSP stands for PlayStation Portable; it played games on small optical discs called UMDs.","o":["PS Vita","PocketStation","PSP","WonderSwan"],"s":{"index":2}},{"k":"choice","i":"Where did the Nintendo 64 get its name?","t":"Consoles","e":"6\ufe0f\u20e3","f":"The Nintendo 64 launched in Japan in 1996, alongside Super Mario 64.","o":["Its 64 launch games","Its 64-bit processor","A price of $64","It was Nintendo's 64th product"],"s":{"index":1}},{"k":"choice","i":"Which was Nintendo's first home console to use optical discs instead of cartridges?","t":"Consoles","e":"\ud83d\udcbf","f":"The GameCube, released in 2001, used small 8 cm discs.","o":["Nintendo 64","Wii","GameCube","Virtual Boy"],"s":{"index":2}},{"k":"number","i":"In what year did the Nintendo Entertainment System (NES) launch in North America?","t":"Consoles","e":"\ud83c\udf44","f":"It first launched in Japan as the Famicom in 1983.","s":{"value":1985,"tolerance":0,"min":1975,"max":1995,"unit":""}},{"k":"number","i":"In what year did Microsoft's first console, the Xbox, launch?","t":"Consoles","e":"\u274e","f":"The original Xbox launched in North America in November 2001.","s":{"value":2001,"tolerance":0,"min":1990,"max":2010,"unit":""}},{"k":"truefalse","i":"The Nintendo Wii used motion-sensing controllers.","t":"Consoles","e":"\ud83c\udfb3","f":"The Wii launched in 2006, and its Wii Remote let players swing, point and bowl.","a":true},{"k":"truefalse","i":"In North America, the original Game Boy came bundled with Tetris.","t":"Handhelds","e":"\ud83e\uddf1","f":"The pairing helped make both Tetris and the Game Boy worldwide hits.","a":true},{"k":"text","i":"Which Nintendo console, released in 2017, can be used both as a handheld and docked to a TV?","t":"Consoles","e":"\ud83d\udd00","f":"The Switch's detachable controllers are called Joy-Con.","s":{"accepted":["Nintendo Switch","Switch","The Switch"]}},{"k":"multi","i":"Select all the consoles made by Sega.","t":"Sega","e":"\ud83e\udd94","f":"The Dreamcast, released in 1998, was Sega's last home console.","o":["Mega Drive (Genesis)","GameCube","Saturn","Atari Jaguar","Dreamcast"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these consoles by original release, oldest first.","t":"Timeline","e":"\ud83d\udcc5","f":"They arrived in 1977, 1983, 1994, 2001 and 2006.","o":["Atari 2600","NES (Famicom)","PlayStation","Xbox","Wii"]}]},{"slug":"fashion-house-origins","title":"Fashion House Origins","tagline":"Chanel, Gucci, Levi's, Zara: where did fashion's biggest names begin?","emoji":"\ud83d\udc5c","gradient":["#be185d","#4c1d95"],"categories":["fashion","brands","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":257,"items":[{"k":"choice","i":"In which Italian city was Gucci founded in 1921?","t":"Italy","e":"\ud83d\udc5c","f":"Guccio Gucci was inspired by the luggage of elegant guests he saw while working at London's Savoy Hotel.","o":["Milan","Florence","Rome","Venice"],"s":{"index":1}},{"k":"choice","i":"Louis Vuitton began in 1854 as a maker of what?","t":"France","e":"\ud83e\uddf3","f":"Vuitton's flat-topped trunks could be stacked easily, unlike the rounded-top trunks common at the time.","o":["Perfume","Hats","Travel trunks","Shoes"],"s":{"index":2}},{"k":"choice","i":"Herm\u00e8s was founded in Paris in 1837 as a workshop making what?","t":"France","e":"\ud83d\udc0e","f":"The horse-and-carriage logo of Herm\u00e8s is a nod to its beginnings as a harness maker.","o":["Silk scarves","Harnesses for horses","Watches","Gloves"],"s":{"index":1}},{"k":"choice","i":"Zara, one of the world's best-known fashion chains, comes from which country?","t":"Spain","e":"\ud83d\udecd\ufe0f","f":"Zara opened its first store in A Coru\u00f1a, Galicia, in 1975.","o":["Italy","France","Spain","Portugal"],"s":{"index":2}},{"k":"choice","i":"Which tennis champion founded a clothing brand with a crocodile logo?","t":"Sportswear","e":"\ud83d\udc0a","f":"Ren\u00e9 Lacoste was nicknamed 'the Crocodile' by the press, and his shirt company launched in 1933.","o":["Fred Perry","Ren\u00e9 Lacoste","Bj\u00f6rn Borg","Arthur Ashe"],"s":{"index":1}},{"k":"choice","i":"H&M was founded in 1947 in which country?","t":"Sweden","e":"\ud83d\udc5a","f":"The first store, in V\u00e4ster\u00e5s, sold only women's clothing and was called 'Hennes', Swedish for 'hers'.","o":["Denmark","Norway","Netherlands","Sweden"],"s":{"index":3}},{"k":"truefalse","i":"Coco Chanel helped make the 'little black dress' a fashion staple in the 1920s.","t":"Icons","e":"\ud83d\udc57","f":"In 1926, American Vogue compared Chanel's simple black dress to the Ford Model T: chic and for everyone.","a":true},{"k":"truefalse","i":"Burberry was founded in Italy.","t":"Britain","e":"\ud83e\udde5","f":"Thomas Burberry founded the brand in England in 1856 and later invented gabardine, a weatherproof fabric.","a":false},{"k":"multi","i":"Select all the fashion houses founded in Italy.","t":"Italy","e":"\ud83d\udc60","f":"Prada was founded in Milan in 1913 by Mario Prada and his brother Martino.","o":["Prada","Dior","Versace","Armani","Givenchy"],"s":{"indices":[0,2,3]}},{"k":"text","i":"Which designer launched the famous 'New Look' in Paris in 1947?","t":"Designers","e":"\u2702\ufe0f","f":"The New Look featured cinched waists and full skirts, a dramatic change after years of wartime fabric rationing.","s":{"accepted":["Christian Dior","Dior"]}},{"k":"text","i":"Adidas is named after its founder, Adolf 'Adi' ___. What is his surname?","t":"Sportswear","e":"\ud83d\udc5f","f":"His brother Rudolf Dassler founded Puma in the same small German town, Herzogenaurach.","s":{"accepted":["Dassler"]}},{"k":"number","i":"In what year did Levi Strauss and Jacob Davis patent their riveted denim work trousers?","t":"Denim","e":"\ud83d\udc56","f":"Copper rivets at the stress points made the trousers tough enough for miners and other workers.","s":{"value":1873,"tolerance":0,"min":1800,"max":1950,"unit":""}},{"k":"order","i":"Order these fashion houses by founding date, from oldest to newest.","t":"Timeline","e":"\ud83d\udcdc","f":"Coco Chanel opened her first shop, selling hats, in Paris in 1910.","o":["Herm\u00e8s","Louis Vuitton","Chanel","Christian Dior"]}]},{"slug":"far-flung-capitals","title":"Far-Flung Capitals","tagline":"Beyond Europe: capitals of the Americas, Asia, Africa and Oceania.","emoji":"\ud83c\udf0f","gradient":["#059669","#0284c7"],"categories":["capitals","geo"],"countries":null,"difficulty":"Hard","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":258,"items":[{"k":"choice","i":"What is the capital of Australia?","t":"Oceania","e":"\ud83c\udde6\ud83c\uddfa","f":"Canberra was purpose-built as a compromise after Sydney and Melbourne both wanted to be the capital.","o":["Perth","Melbourne","Sydney","Canberra"],"s":{"index":3}},{"k":"choice","i":"What is the capital of Brazil?","t":"South America","e":"\ud83c\udde7\ud83c\uddf7","f":"Seen from above, L\u00facio Costa's plan for Bras\u00edlia is often said to look like an airplane or a bird.","o":["Salvador","Bras\u00edlia","Rio de Janeiro","S\u00e3o Paulo"],"s":{"index":1}},{"k":"text","i":"What is the capital of Kenya?","t":"Africa","e":"\ud83c\uddf0\ud83c\uddea","f":"Nairobi National Park lies right next to the city, so giraffes can be seen with skyscrapers behind them.","s":{"accepted":["Nairobi"]}},{"k":"choice","i":"What is the capital of Vietnam?","t":"Asia","e":"\ud83c\uddfb\ud83c\uddf3","f":"Hanoi's name means 'inside the river', referring to its position in the Red River delta.","o":["Hu\u1ebf","Ho Chi Minh City","Da Nang","Hanoi"],"s":{"index":3}},{"k":"choice","i":"What is the capital of Morocco?","t":"Africa","e":"\ud83c\uddf2\ud83c\udde6","f":"Rabat is Morocco's capital, although Casablanca is its largest city.","o":["Rabat","Marrakesh","Fez","Casablanca"],"s":{"index":0}},{"k":"multi","i":"Select all the capital cities located in South America.","t":"South America","e":"\ud83c\udf0e","f":"Quito, high in the Andes at about 2,850 m, is one of the highest capital cities in the world.","o":["Bogot\u00e1","Lima","Havana","Panama City","Quito"],"s":{"indices":[0,1,4]}},{"k":"order","i":"Order these capitals from north to south.","t":"Geography","e":"\ud83e\udded","f":"Santiago, Chile's capital, sits in a valley with the snow-capped Andes visible from the city.","o":["Washington, D.C.","Mexico City","Bogot\u00e1","Santiago"]},{"k":"truefalse","i":"La Paz, Bolivia's seat of government, lies more than 3,500 metres above sea level.","t":"South America","e":"\ud83c\udde7\ud83c\uddf4","f":"Bolivia's constitutional capital is Sucre, while the government sits in La Paz, the highest seat of government in the world.","a":true},{"k":"choice","i":"What is the capital of South Korea?","t":"Asia","e":"\ud83c\uddf0\ud83c\uddf7","f":"Seoul has been Korea's capital for over 600 years, since the Joseon dynasty chose it in 1394.","o":["Daegu","Incheon","Busan","Seoul"],"s":{"index":3}},{"k":"truefalse","i":"New York City is the capital of the United States.","t":"North America","e":"\ud83c\uddfa\ud83c\uddf8","f":"Washington, D.C. has been the US capital since 1800; New York briefly served as capital in 1789\u20131790.","a":false},{"k":"choice","i":"What is the capital of Nigeria?","t":"Africa","e":"\ud83c\uddf3\ud83c\uddec","f":"Abuja officially replaced Lagos as Nigeria's capital in 1991.","o":["Abuja","Lagos","Kano","Ibadan"],"s":{"index":0}},{"k":"multi","i":"Select all the African capital cities.","t":"Africa","e":"\ud83c\udf0d","f":"Addis Ababa, the capital of Ethiopia, is home to the headquarters of the African Union.","o":["Manila","Addis Ababa","Dakar","Accra","Jakarta"],"s":{"indices":[1,2,3]}},{"k":"text","i":"What is the capital of Argentina?","t":"South America","e":"\ud83c\udde6\ud83c\uddf7","f":"Avenida 9 de Julio in Buenos Aires is one of the widest avenues in the world.","s":{"accepted":["Buenos Aires"]}},{"k":"number","i":"In what year did Bras\u00edlia officially become Brazil's capital?","t":"South America","e":"\ud83c\udfd7\ufe0f","f":"Bras\u00edlia was built in under four years on an empty plateau in the country's interior.","s":{"value":1960,"tolerance":0,"min":1900,"max":2000,"unit":""}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'c189478dfc3e195104e013c7015961d5' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 7'; end $q$;
do $q$ declare d text := $d$[{"slug":"inventions-through-time","title":"Inventions Through Time","tagline":"Wheels, light bulbs and Velcro: when did the world change?","emoji":"\ud83d\udca1","gradient":["#ca8a04","#c2410c"],"categories":["science","history","tech"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":259,"items":[{"k":"order","i":"Order these transport milestones from oldest to newest.","t":"Transport","e":"\ud83d\udede","f":"The earliest known wheels, from Mesopotamia around 3500 BC, were potter's wheels rather than wheels for carts.","o":["The wheel","First crewed hot-air balloon flight","Steam locomotive","Powered airplane","Jet-powered airplane"]},{"k":"choice","i":"Who is credited with patenting the telephone in 1876?","t":"Communication","e":"\u260e\ufe0f","f":"Bell's first words over the phone were reportedly 'Mr. Watson, come here, I want to see you.'","o":["Thomas Edison","Alexander Graham Bell","Nikola Tesla","Guglielmo Marconi"],"s":{"index":1}},{"k":"number","i":"In what year did Karl Benz patent his Motorwagen, often called the first true automobile?","t":"Transport","e":"\ud83d\ude97","f":"The Benz Patent-Motorwagen had three wheels and a top speed of about 16 km/h.","s":{"value":1886,"tolerance":0,"min":1800,"max":1950,"unit":""}},{"k":"choice","i":"Whose team developed a long-lasting, practical incandescent light bulb in 1879?","t":"Electricity","e":"\ud83d\udca1","f":"Edison's team tested thousands of materials before finding a carbon filament that glowed for many hours.","o":["Benjamin Franklin","Nikola Tesla","James Watt","Thomas Edison"],"s":{"index":3}},{"k":"truefalse","i":"Paper was invented in ancient China.","t":"Ancient inventions","e":"\ud83d\udcdc","f":"Cai Lun, a Chinese court official, is traditionally credited with improving papermaking around AD 105.","a":true},{"k":"choice","i":"What did Guglielmo Marconi pioneer in the 1890s?","t":"Communication","e":"\ud83d\udcfb","f":"In 1901, Marconi's team received a radio signal sent all the way across the Atlantic Ocean.","o":["Radio communication","Photography","The telephone","The phonograph"],"s":{"index":0}},{"k":"order","i":"Order these communication inventions from oldest to newest.","t":"Communication","e":"\ud83d\udce1","f":"Johannes Gutenberg developed his movable-type printing press in Germany around 1440.","o":["Printing press","Electric telegraph","Telephone","Radio","Television"]},{"k":"multi","i":"Select all the inventions from the 20th century.","t":"20th century","e":"\ud83d\udcfa","f":"The microwave oven was invented after engineer Percy Spencer noticed a radar device had melted a chocolate bar in his pocket.","o":["Powered airplane","Telephone","Microwave oven","Steam engine","Television"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"James Watt is famous for greatly improving which machine?","t":"Industry","e":"\ud83c\udfed","f":"The watt, the unit of power, is named after him.","o":["Printing press","Spinning wheel","Steam engine","Telescope"],"s":{"index":2}},{"k":"truefalse","i":"The first computer mouse was made of wood.","t":"Computers","e":"\ud83d\uddb1\ufe0f","f":"Douglas Engelbart's 1964 mouse prototype was a wooden block with two metal wheels underneath.","a":true},{"k":"choice","i":"Which Scottish inventor gave the first public demonstration of a working television system in 1926?","t":"Television","e":"\ud83d\udcfa","f":"Baird's early television was mechanical, using a spinning disc to scan images.","o":["John Logie Baird","Philo Farnsworth","Alexander Fleming","James Watt"],"s":{"index":0}},{"k":"text","i":"Which fastener did George de Mestral invent after noticing burrs sticking to his dog's fur?","t":"Everyday inventions","e":"\ud83d\udc15","f":"De Mestral got the idea after a walk in the Swiss Alps in 1941.","s":{"accepted":["Velcro","Hook-and-loop","Hook and loop","Hook-and-loop fastener","Hook and loop fastener"]}},{"k":"choice","i":"Which ancient civilization is credited with inventing the magnetic compass?","t":"Navigation","e":"\ud83e\udded","f":"Early Chinese compasses used lodestone, a naturally magnetic mineral.","o":["Ancient Greece","Ancient China","Ancient Egypt","Ancient Rome"],"s":{"index":1}}]},{"slug":"global-rulebook","title":"Global Rulebook","tagline":"Which side to drive on, what number to dial: everyday rules around the world.","emoji":"\ud83d\udea6","gradient":["#ea580c","#ca8a04"],"categories":["society","travel"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":260,"items":[{"k":"multi","i":"Select all the countries where people drive on the left.","t":"Roads","e":"\ud83d\ude97","f":"Around a third of the world's people live in countries that drive on the left, including the UK and Ireland.","o":["France","Japan","India","Brazil","Australia"],"s":{"indices":[1,2,4]}},{"k":"truefalse","i":"Sweden switched from driving on the left to driving on the right in 1967.","t":"Roads","e":"\ud83d\udd04","f":"The overnight switch on 3 September 1967 was called Dagen H, 'H Day', after 'H\u00f6gertrafik' (right-hand traffic).","a":true},{"k":"choice","i":"Which emergency phone number works across the whole European Union?","t":"Emergencies","e":"\ud83d\ude91","f":"112 works in every EU country; 911 is used in the US and Canada, and 999 in the UK.","o":["911","112","999","000"],"s":{"index":1}},{"k":"choice","i":"Which country's international dialling code is +1?","t":"Phones","e":"\ud83d\udcde","f":"Canada and many Caribbean nations share +1 with the US as part of the North American Numbering Plan.","o":["United States","United Kingdom","China","Russia"],"s":{"index":0}},{"k":"number","i":"What is Hungary's international dialling code? (+?)","t":"Phones","e":"\u260e\ufe0f","f":"For comparison, Germany uses +49, the UK +44 and France +33.","s":{"value":36,"tolerance":0,"min":1,"max":99,"unit":""}},{"k":"choice","i":"In Japan, the school year traditionally begins in which month?","t":"School","e":"\ud83c\udf38","f":"Both the school and business year start in April, around cherry-blossom season.","o":["September","January","June","April"],"s":{"index":3}},{"k":"truefalse","i":"In Bulgaria, a nod of the head has traditionally meant 'no' rather than 'yes'.","t":"Gestures","e":"\ud83d\ude42","f":"Bulgarians traditionally shake the head for 'yes' and nod for 'no', which can confuse visitors.","a":true},{"k":"choice","i":"Which of these countries mainly uses Fahrenheit in everyday weather forecasts?","t":"Measurements","e":"\ud83c\udf21\ufe0f","f":"Daniel Gabriel Fahrenheit proposed his scale in 1724; most of the world has since switched to Celsius.","o":["Canada","Australia","United Kingdom","United States"],"s":{"index":3}},{"k":"choice","i":"In the United States, the date 4/7 usually means\u2026","t":"Dates","e":"\ud83d\udcc5","f":"Americans usually write month first; most of Europe puts the day first, so 4/7 there means 4 July.","o":["July 4","April 7","April 4","July 7"],"s":{"index":1}},{"k":"text","i":"Which unit is used for distances on road signs in the United Kingdom?","t":"Measurements","e":"\ud83d\udee3\ufe0f","f":"The UK uses metric for most things, but road signs show miles and speed limits in miles per hour.","s":{"accepted":["Miles","Mile","mi"]}},{"k":"order","i":"Order these cities by when they celebrate the arrival of New Year, first to last.","t":"Time zones","e":"\ud83c\udf86","f":"Some islands of Kiribati, at UTC+14, are among the very first places on Earth to see in each New Year.","o":["Tokyo","Moscow","London","New York","Los Angeles"]},{"k":"truefalse","i":"In Japan, leaving a tip in restaurants is generally expected, just like in the US.","t":"Etiquette","e":"\ud83d\udcb4","f":"Tipping is not customary in Japan; leaving extra money on the table may even confuse the staff.","a":false},{"k":"choice","i":"What does a red octagonal road sign mean in most of the world?","t":"Roads","e":"\ud83d\uded1","f":"Its unusual eight-sided shape means drivers can recognise a STOP sign even from behind.","o":["Give way","Stop","No entry","Speed limit"],"s":{"index":1}},{"k":"number","i":"How many time zones does China officially use?","t":"Time zones","e":"\ud83d\udd50","f":"Although China spans roughly 5,000 km from east to west, the whole country officially runs on Beijing time.","s":{"value":1,"tolerance":0,"min":1,"max":10,"unit":""}}]},{"slug":"arcade-legends","title":"Arcade Legends","tagline":"Insert coin! Ghosts, barrels and space invaders from the golden age.","emoji":"\ud83d\udd79\ufe0f","gradient":["#7c3aed","#db2777"],"categories":["gaming","popculture"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":261,"items":[{"k":"choice","i":"Which company created Pac-Man (1980)?","t":"Pac-Man","e":"\ud83d\udfe1","f":"Pac-Man was designed by Toru Iwatani, who wanted a game that would appeal to everyone.","o":["Atari","Namco","Taito","Sega"],"s":{"index":1}},{"k":"choice","i":"Which company made the 1978 arcade hit 'Space Invaders'?","t":"Shooters","e":"\ud83d\udc7e","f":"Space Invaders was designed by Tomohiro Nishikado.","o":["Namco","Atari","Taito","Konami"],"s":{"index":2}},{"k":"choice","i":"In the original 'Donkey Kong' (1981), what does Donkey Kong throw at the player?","t":"Donkey Kong","e":"\ud83d\udee2\ufe0f","f":"Donkey Kong was designed by Shigeru Miyamoto, who later created Super Mario Bros. and Zelda.","o":["Barrels","Bananas","Coconuts","Rocks"],"s":{"index":0}},{"k":"choice","i":"Which 1984 puzzle game was created by Soviet engineer Alexey Pajitnov?","t":"Puzzle","e":"\ud83e\uddf1","f":"Its name blends 'tetra' (four, the number of squares in each piece) with tennis, Pajitnov's favourite sport.","o":["Columns","Dr. Mario","Tetris","Puyo Puyo"],"s":{"index":2}},{"k":"choice","i":"Which sport does Atari's 'Pong' imitate?","t":"Pong","e":"\ud83c\udfd3","f":"A test Pong machine in a California bar reportedly stopped working because it was stuffed with too many coins.","o":["Tennis","Table tennis","Ice hockey","Squash"],"s":{"index":1}},{"k":"choice","i":"In which 1983 arcade game did Mario's brother Luigi first appear?","t":"Mario","e":"\ud83d\udfe2","f":"In Mario Bros., the brothers clear pests out of the sewers, which is where their plumber image began.","o":["Donkey Kong Jr.","Super Mario Bros.","Donkey Kong 3","Mario Bros."],"s":{"index":3}},{"k":"number","i":"In what year did Atari release the arcade game 'Pong'?","t":"Pong","e":"\ud83c\udfd3","f":"Pong is often called the first commercially successful video game.","s":{"value":1972,"tolerance":0,"min":1960,"max":1985,"unit":""}},{"k":"number","i":"How many ghosts chase Pac-Man in the original arcade game?","t":"Pac-Man","e":"\ud83d\udc7b","f":"Each ghost has its own personality and way of chasing Pac-Man.","s":{"value":4,"tolerance":0,"min":1,"max":10,"unit":""}},{"k":"truefalse","i":"In the original 'Donkey Kong', the hero was called Jumpman before being named Mario.","t":"Donkey Kong","e":"\ud83e\udd8d","f":"He was renamed Mario, reportedly after the landlord of Nintendo of America's warehouse.","a":true},{"k":"truefalse","i":"Pac-Man was originally released in Japan under the name 'Puck Man'.","t":"Pac-Man","e":"\ud83c\udf52","f":"The name comes from the Japanese 'paku paku', the sound of a mouth opening and closing.","a":true},{"k":"text","i":"Which 1979 Atari arcade game has players blasting space rocks from a small triangular ship?","t":"Shooters","e":"\u2604\ufe0f","f":"Asteroids was Atari's best-selling arcade game.","s":{"accepted":["Asteroids"]}},{"k":"multi","i":"Select all the names of ghosts from the original Pac-Man.","t":"Pac-Man","e":"\ud83d\udc7b","f":"The fourth ghost is Pinky.","o":["Blinky","Sparky","Inky","Dusty","Clyde"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these arcade games from oldest to newest.","t":"Timeline","e":"\ud83d\udcc5","f":"They came out in 1972, 1978, 1980, 1981 and 1998.","o":["Pong","Space Invaders","Pac-Man","Donkey Kong","Dance Dance Revolution"]}]},{"slug":"wardrobe-word-origins","title":"Wardrobe Word Origins","tagline":"Cardigans, bikinis, jeans and tuxedos: the stories behind what you wear.","emoji":"\ud83d\udc55","gradient":["#2563eb","#9333ea"],"categories":["fashion","history","language"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":262,"items":[{"k":"choice","i":"The cardigan is named after what kind of person?","t":"Knitwear","e":"\ud83e\uddf6","f":"The 7th Earl of Cardigan, a British army officer, made the buttoned knitted waistcoat fashionable in the 1850s.","o":["A British earl","A French chef","A Scottish king","An Italian painter"],"s":{"index":0}},{"k":"choice","i":"Denim is thought to take its name from 'serge de N\u00eemes'. In which country is N\u00eemes?","t":"Denim","e":"\ud83d\udc56","f":"The word 'jeans' is linked to Genoa in Italy, whose sailors wore sturdy cotton trousers.","o":["Italy","France","Spain","Belgium"],"s":{"index":1}},{"k":"choice","i":"The Wellington boot is named after whom?","t":"Footwear","e":"\ud83e\udd7e","f":"The 1st Duke of Wellington asked his shoemaker to adapt the Hessian boot into a sleek, calf-length style.","o":["A New Zealand city","A British duke","An American general","A Dutch shoemaker"],"s":{"index":1}},{"k":"choice","i":"Which hat is named after an 1882 French play?","t":"Hats","e":"\ud83c\udfa9","f":"Victorien Sardou's play 'F\u00e9dora' starred Sarah Bernhardt, who wore a soft hat with a crease down the crown.","o":["Fedora","Beret","Bowler","Panama"],"s":{"index":0}},{"k":"choice","i":"Panama hats are traditionally made in which country?","t":"Hats","e":"\ud83d\udc52","f":"The hats got their name because they were shipped via Panama and worn by workers building the Panama Canal.","o":["Panama","Ecuador","Mexico","Cuba"],"s":{"index":1}},{"k":"choice","i":"Swiss engineer George de Mestral invented Velcro after noticing what stuck to his dog?","t":"Inventions","e":"\ud83c\udf3f","f":"Under a microscope he saw tiny hooks on the burrs that caught on loops in fur and fabric.","o":["Chewing gum","Pine sap","Burrs from a plant","Spider silk"],"s":{"index":2}},{"k":"truefalse","i":"The tuxedo is named after Tuxedo Park, a community in New York State.","t":"Formalwear","e":"\ud83e\udd35","f":"Short dinner jackets were worn at Tuxedo Park's autumn ball in 1886, and the name stuck in America.","a":true},{"k":"truefalse","i":"The kimono is the traditional garment of Korea.","t":"Traditional dress","e":"\ud83d\udc58","f":"The kimono is Japanese; Korea's traditional dress is called the hanbok.","a":false},{"k":"multi","i":"Select all the garments named after people.","t":"Eponyms","e":"\ud83c\udff7\ufe0f","f":"The leotard is named after Jules L\u00e9otard, the French trapeze artist who popularised the one-piece outfit.","o":["Cardigan","Leotard","Kilt","Mackintosh","Poncho"],"s":{"indices":[0,1,3]}},{"k":"text","i":"What is the long, draped garment traditionally worn by women in India called?","t":"Traditional dress","e":"\ud83e\udd7b","f":"A sari can be draped in many regional styles; the most common today is the Nivi drape.","s":{"accepted":["Sari","Saree"]}},{"k":"number","i":"In what year did Louis R\u00e9ard unveil the bikini in Paris?","t":"Swimwear","e":"\ud83d\udc59","f":"R\u00e9ard named his tiny swimsuit after Bikini Atoll in the Pacific, expecting it to cause a sensation.","s":{"value":1946,"tolerance":1,"min":1900,"max":2000,"unit":""}},{"k":"number","i":"In what year did DuPont's nylon stockings first go on sale across the USA?","t":"Fabrics","e":"\ud83e\udde6","f":"Millions of pairs sold within days when nylons went on sale nationwide on 15 May 1940.","s":{"value":1940,"tolerance":1,"min":1900,"max":2000,"unit":""}},{"k":"order","i":"Order these garments by when they got their names, from oldest to newest.","t":"Timeline","e":"\u23f3","f":"From the Duke of Wellington's boots to post-war swimwear, these four names span about 130 years.","o":["Wellington boot","Cardigan","Tuxedo","Bikini"]}]},{"slug":"discover-hungary","title":"Discover Hungary","tagline":"Lake Balaton, Rubik's Cubes and thermal baths: how well do you know Hungary?","emoji":"\ud83c\udded\ud83c\uddfa","gradient":["#16a34a","#dc2626"],"categories":["geo","culture","travel"],"countries":["HU"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":263,"items":[{"k":"choice","i":"What is the largest lake in Central Europe, found in Hungary?","t":"Lakes","e":"\ud83c\udfd6\ufe0f","f":"Lake Balaton is about 77 km long and is nicknamed 'the Hungarian Sea'.","o":["Lake Bled","Lake Neusiedl","Lake Balaton","Lake Constance"],"s":{"index":2}},{"k":"choice","i":"Which river divides Budapest into Buda and Pest?","t":"Rivers","e":"\ud83c\udf09","f":"Buda, Pest and \u00d3buda were united into a single city, Budapest, in 1873.","o":["Tisza","Danube","Drava","R\u00e1ba"],"s":{"index":1}},{"k":"truefalse","i":"The Rubik's Cube was invented by a Hungarian.","t":"Inventors","e":"\ud83e\udde9","f":"Ern\u0151 Rubik, a Hungarian architect and design teacher, created the cube in Budapest in 1974.","a":true},{"k":"choice","i":"What is the name of Hungary's currency?","t":"Money","e":"\ud83d\udcb0","f":"The forint was introduced in 1946, replacing the peng\u0151 after record-breaking inflation.","o":["Koruna","Forint","Z\u0142oty","Euro"],"s":{"index":1}},{"k":"text","i":"Budapest's huge neo-Gothic building on the Danube houses which national institution?","t":"Landmarks","e":"\ud83c\udfdb\ufe0f","f":"The Hungarian Parliament Building, completed in 1904, is the largest building in Hungary.","s":{"accepted":["Parliament","The Parliament","Hungarian Parliament","National Assembly"]}},{"k":"number","i":"How many countries border Hungary?","t":"Borders","e":"\ud83d\uddfa\ufe0f","f":"Landlocked Hungary borders Austria, Slovakia, Ukraine, Romania, Serbia, Croatia and Slovenia.","s":{"value":7,"tolerance":0,"min":1,"max":12,"unit":""}},{"k":"choice","i":"Which thermal bath complex in Budapest's City Park is one of the largest in Europe?","t":"Baths","e":"\u2668\ufe0f","f":"Sz\u00e9chenyi Baths opened in 1913, and people famously play chess in its warm outdoor pools.","o":["Rudas","Kir\u00e1ly","Gell\u00e9rt","Sz\u00e9chenyi"],"s":{"index":3}},{"k":"multi","i":"Select all the inventions credited to Hungarians.","t":"Inventors","e":"\ud83d\udca1","f":"L\u00e1szl\u00f3 B\u00edr\u00f3 patented the ballpoint pen, and Dennis Gabor won a Nobel Prize for inventing holography.","o":["Holography","Light bulb","Telephone","Ballpoint pen","Dynamite"],"s":{"indices":[0,3]}},{"k":"choice","i":"Which Hungarian composer and piano virtuoso wrote the 'Hungarian Rhapsodies'?","t":"Music","e":"\ud83c\udfb9","f":"Franz Liszt helped found Budapest's Academy of Music, which now bears his name.","o":["Ferenc Erkel","Franz Liszt","B\u00e9la Bart\u00f3k","Zolt\u00e1n Kod\u00e1ly"],"s":{"index":1}},{"k":"order","i":"Order these Hungarian cities from north to south.","t":"Cities","e":"\ud83e\udded","f":"P\u00e9cs, near Hungary's southern border, was a European Capital of Culture in 2010.","o":["Miskolc","Budapest","Kecskem\u00e9t","P\u00e9cs"]},{"k":"truefalse","i":"Hungary's highest point, K\u00e9kes, is over 2,000 metres tall.","t":"Mountains","e":"\u26f0\ufe0f","f":"K\u00e9kes, in the M\u00e1tra Mountains, is Hungary's highest peak at about 1,014 m.","a":false},{"k":"choice","i":"Which grassy plain in eastern Hungary is famous for its horsemen and grey cattle?","t":"Nature","e":"\ud83d\udc04","f":"Hortob\u00e1gy National Park, founded in 1973, was Hungary's first national park.","o":["\u0150rs\u00e9g","Hortob\u00e1gy","Transdanubia","B\u00fckk"],"s":{"index":1}},{"k":"text","i":"What is the Hungarian name for Hungary? (It starts with M.)","t":"Language","e":"\ud83d\udde3\ufe0f","f":"Hungarians call themselves 'magyar', and 'orsz\u00e1g' means 'country'.","s":{"accepted":["Magyarorsz\u00e1g","Magyarorszag"]}},{"k":"choice","i":"Which island in the Danube, in the heart of Budapest, is named after a medieval princess?","t":"Landmarks","e":"\ud83c\udf33","f":"Margaret Island is named after the daughter of King B\u00e9la IV and is now a park with a musical fountain.","o":["Szentendre Island","Csepel Island","Margaret Island","\u00d3buda Island"],"s":{"index":2}}]},{"slug":"solar-system-tour","title":"Solar System Tour","tagline":"Blast off past rings, red planets and giant storms.","emoji":"\ud83e\ude90","gradient":["#1d4ed8","#9333ea"],"categories":["space","science"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":264,"items":[{"k":"choice","i":"Which is the largest planet in our solar system?","t":"Planets","e":"\ud83d\udfe0","f":"More than 1,300 Earths could fit inside Jupiter.","o":["Saturn","Jupiter","Neptune","Earth"],"s":{"index":1}},{"k":"order","i":"Order these planets from closest to farthest from the Sun.","t":"Planets","e":"\u2600\ufe0f","f":"Neptune is about 30 times farther from the Sun than Earth is.","o":["Mars","Jupiter","Saturn","Uranus","Neptune"]},{"k":"choice","i":"Which planet is known as the Red Planet?","t":"Planets","e":"\ud83d\udd34","f":"Mars looks red because its surface is rich in iron oxide, better known as rust.","o":["Venus","Mercury","Jupiter","Mars"],"s":{"index":3}},{"k":"number","i":"How many planets are in our solar system?","t":"Planets","e":"\ud83d\udd2d","f":"Pluto was reclassified as a dwarf planet in 2006.","s":{"value":8,"tolerance":0,"min":1,"max":12,"unit":"planets"}},{"k":"text","i":"Which planet is famous for its spectacular, bright ring system?","t":"Planets","e":"\ud83d\udc8d","f":"Saturn's rings are made mostly of chunks of ice, mixed with some rock and dust.","s":{"accepted":["Saturn"]}},{"k":"choice","i":"Roughly how long does it take light from the Sun to reach Earth?","t":"The Sun","e":"\u23f1\ufe0f","f":"Sunlight travels about 150 million km to reach us, at nearly 300,000 km per second.","o":["About 8 seconds","About 8 minutes","About 8 hours","About 8 days"],"s":{"index":1}},{"k":"multi","i":"Select all the rocky (terrestrial) planets.","t":"Planets","e":"\ud83e\udea8","f":"Venus is a rocky planet too, and its thick carbon dioxide atmosphere makes it even hotter than Mercury.","o":["Mercury","Jupiter","Earth","Saturn","Mars"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"Which planet spins on its side, with its axis tilted about 98 degrees?","t":"Planets","e":"\ud83d\udd04","f":"Because of its tilt, each pole of Uranus gets about 42 years of sunlight followed by 42 years of darkness.","o":["Uranus","Neptune","Saturn","Mars"],"s":{"index":0}},{"k":"truefalse","i":"Pluto is smaller than Earth's Moon.","t":"Dwarf planets","e":"\ud83c\udf11","f":"Pluto is about 2,377 km across, while the Moon is about 3,475 km across.","a":true},{"k":"choice","i":"What is the name of the giant storm on Jupiter?","t":"Planets","e":"\ud83c\udf00","f":"Jupiter's Great Red Spot is a giant storm that has been observed for more than 150 years.","o":["The Great Dark Spot","The Hexagon","The Great Red Spot","The Great White Spot"],"s":{"index":2}},{"k":"text","i":"What is the name of the giant Martian volcano, the largest known volcano in the solar system?","t":"Mars","e":"\ud83c\udf0b","f":"Olympus Mons rises about 22 km, roughly two and a half times the height of Mount Everest.","s":{"accepted":["Olympus Mons","Olympus"]}},{"k":"number","i":"Roughly how many Earth days does it take Mars to orbit the Sun once?","t":"Mars","e":"\ud83d\udcc5","f":"A year on Mars lasts about 687 Earth days, almost twice as long as a year on Earth.","s":{"value":687,"tolerance":20,"min":300,"max":1000,"unit":"days"}},{"k":"order","i":"Order these planets by size, from largest to smallest.","t":"Planets","e":"\ud83d\udccf","f":"Mercury is the smallest planet, not much bigger than Earth's Moon.","o":["Jupiter","Saturn","Earth","Mars","Mercury"]}]},{"slug":"garage-to-global","title":"Garage to Global","tagline":"Paper mills, playing cards and looms: the surprising origins of famous companies.","emoji":"\ud83d\ude80","gradient":["#4338ca","#0f766e"],"categories":["business","brands"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":265,"items":[{"k":"choice","i":"Long before mobile phones, Nokia started out in 1865 as what kind of business?","t":"Origins","e":"\ud83d\udcc4","f":"Engineer Fredrik Idestam founded it in Finland; it took its name from the town of Nokia, beside the Nokianvirta river.","o":["A paper mill","A shipyard","A bakery","A bank"],"s":{"index":0}},{"k":"truefalse","i":"Nintendo has been making video games ever since it was founded in the 1880s.","t":"Origins","e":"\ud83c\udfb4","f":"Nintendo was founded in Kyoto in 1889 to make hanafuda playing cards; video games came almost a century later.","a":false},{"k":"choice","i":"LEGO comes from the Danish words 'leg godt'. What do they mean?","t":"Names","e":"\ud83e\uddf1","f":"LEGO was founded by Danish carpenter Ole Kirk Christiansen in the town of Billund.","o":["Build big","Little bricks","Good toys","Play well"],"s":{"index":3}},{"k":"truefalse","i":"IKEA's name comes from its founder's initials plus the farm and village where he grew up.","t":"Names","e":"\ud83d\udecb\ufe0f","f":"I.K. for Ingvar Kamprad, E for Elmtaryd farm and A for the village of Agunnaryd in Sweden.","a":true},{"k":"choice","i":"What did Amazon sell when it first opened for business in 1995?","t":"Origins","e":"\ud83d\udce6","f":"Founder Jeff Bezos briefly considered the name 'Cadabra' before choosing Amazon, after the world's largest river.","o":["Music CDs","Electronics","Shoes","Books"],"s":{"index":3}},{"k":"text","i":"Before it was called Google, Larry Page and Sergey Brin's search engine had what name?","t":"Names","e":"\ud83d\udd0e","f":"The name Google is a play on 'googol', the number 1 followed by 100 zeros.","s":{"accepted":["BackRub","Back Rub","Backrub"]}},{"k":"multi","i":"Select all of Apple's co-founders.","t":"Founders","e":"\ud83c\udf4e","f":"Ronald Wayne sold his 10% stake back after just 12 days, for $800.","o":["Steve Jobs","Steve Wozniak","Paul Allen","Ronald Wayne","Bill Gates"],"s":{"indices":[0,1,3]}},{"k":"number","i":"In what year was Coca-Cola first sold?","t":"Origins","e":"\ud83e\udd64","f":"Pharmacist John Pemberton's drink was first sold at a soda fountain in Atlanta for five cents a glass.","s":{"value":1886,"tolerance":0,"min":1800,"max":1950,"unit":""}},{"k":"choice","i":"Toyota grew out of a company that made what?","t":"Origins","e":"\ud83e\uddf5","f":"The car division of Toyoda Automatic Loom Works was spun off in 1937 as the Toyota Motor Company.","o":["Bicycles","Sewing needles","Weaving looms","Radios"],"s":{"index":2}},{"k":"truefalse","i":"The name Samsung means 'three stars' in Korean.","t":"Names","e":"\u2b50","f":"Samsung began in 1938 as a small trading company selling groceries such as dried fish and noodles.","a":true},{"k":"choice","i":"Starbucks is named after a character in which novel?","t":"Names","e":"\u2615","f":"Starbuck is the first mate on the whaling ship Pequod; the first Starbucks opened in Seattle in 1971.","o":["Treasure Island","Robinson Crusoe","Moby-Dick","The Old Man and the Sea"],"s":{"index":2}},{"k":"order","i":"Order these companies by founding year, oldest first.","t":"Timeline","e":"\ud83c\udfed","f":"1903, 1932, 1943, 1976 and 1998: each one started small.","o":["Harley-Davidson","LEGO","IKEA","Apple","Google"]},{"k":"choice","i":"In which US city was Harley-Davidson founded?","t":"Origins","e":"\ud83c\udfcd\ufe0f","f":"William Harley and Arthur Davidson built their first motorcycle in a small wooden shed.","o":["Detroit","Milwaukee","Chicago","Cleveland"],"s":{"index":1}},{"k":"choice","i":"Which car brand's name is Latin for 'I roll'?","t":"Names","e":"\ud83d\ude99","f":"Audi is Latin too: it means 'listen', a translation of founder August Horch's surname.","o":["Audi","Fiat","Volvo","Skoda"],"s":{"index":2}}]},{"slug":"game-character-lineup","title":"Game Character Lineup","tagline":"Plumbers, hedgehogs and electric mice: do you know your video game heroes?","emoji":"\ud83c\udf44","gradient":["#dc2626","#2563eb"],"categories":["gaming","kids"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":266,"items":[{"k":"choice","i":"What is the name of Sonic the Hedgehog's two-tailed fox friend?","t":"Sonic","e":"\ud83e\udd8a","f":"Tails's full name is Miles Prower, a pun on 'miles per hour'.","o":["Knuckles","Tails","Shadow","Amy"],"s":{"index":1}},{"k":"choice","i":"What is the name of the hero you play as in 'The Legend of Zelda' series?","t":"Zelda","e":"\ud83d\udde1\ufe0f","f":"Many people think the hero is called Zelda, but Zelda is the princess.","o":["Link","Zelda","Ganondorf","Navi"],"s":{"index":0}},{"k":"choice","i":"Lara Croft is the hero of which game series?","t":"Adventure","e":"\ud83c\udffa","f":"Lara Croft first appeared in Tomb Raider in 1996.","o":["Uncharted","Prince of Persia","Tomb Raider","Resident Evil"],"s":{"index":2}},{"k":"choice","i":"What is the name of the spiky, turtle-like king who is Mario's arch-enemy?","t":"Mario","e":"\ud83d\udc22","f":"Bowser is also known as King Koopa.","o":["Wario","Ganon","Dr. Eggman","Bowser"],"s":{"index":3}},{"k":"choice","i":"What was the name of Minecraft's original default player character?","t":"Minecraft","e":"\u26cf\ufe0f","f":"Alex was added as a second default character in 2014.","o":["Alex","Steve","Notch","Herobrine"],"s":{"index":1}},{"k":"choice","i":"In the Super Mario games, which item makes Mario grow bigger?","t":"Mario","e":"\ud83c\udf44","f":"The Fire Flower lets Mario throw fireballs, and the Starman makes him briefly invincible.","o":["Fire Flower","Starman","Super Mushroom","Super Leaf"],"s":{"index":2}},{"k":"number","i":"How many Pok\u00e9mon were in the original Pok\u00e9mon Red and Green games (1996)?","t":"Pok\u00e9mon","e":"\ud83d\udcd5","f":"Mew, number 151, was a secret addition that most players could only get at special events.","s":{"value":151,"tolerance":0,"min":50,"max":300,"unit":""}},{"k":"truefalse","i":"Pikachu is an Electric-type Pok\u00e9mon.","t":"Pok\u00e9mon","e":"\u26a1","f":"In the anime, Ash's Pikachu famously refuses to ride inside a Pok\u00e9 Ball.","a":true},{"k":"truefalse","i":"Sonic the Hedgehog was created by Nintendo.","t":"Sonic","e":"\ud83e\udd94","f":"Sonic was created by Sega and first appeared in 1991 as its answer to Mario.","a":false},{"k":"text","i":"What is the name of the green dinosaur that Mario rides?","t":"Mario","e":"\ud83e\udd96","f":"Yoshi made his debut in Super Mario World for the Super Nintendo in 1990.","s":{"accepted":["Yoshi"]}},{"k":"text","i":"Which round pink Nintendo hero inhales enemies to copy their powers?","t":"Nintendo","e":"\ud83c\udf38","f":"Kirby first appeared in Kirby's Dream Land for the Game Boy in 1992.","s":{"accepted":["Kirby"]}},{"k":"multi","i":"Select all the characters from the Super Mario series.","t":"Mario","e":"\u2b50","f":"Crash Bandicoot first starred on PlayStation, Samus Aran is from Metroid and Knuckles is from Sonic.","o":["Luigi","Crash Bandicoot","Princess Peach","Samus Aran","Toad","Knuckles"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these characters by their first game appearance, earliest first.","t":"Debuts","e":"\ud83d\udcc5","f":"They debuted in 1980, 1981, 1986, 1991 and 1996.","o":["Pac-Man","Mario","Link","Sonic","Lara Croft"]}]},{"slug":"logos-and-slogans","title":"Logos & Slogans","tagline":"Swooshes, stars and catchy taglines: how brand-savvy are you?","emoji":"\ud83c\udff7\ufe0f","gradient":["#e11d48","#c2410c"],"categories":["brands","business","popculture"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":267,"items":[{"k":"choice","i":"Which company uses the slogan 'Just Do It'?","t":"Slogans","e":"\u2714\ufe0f","f":"The 'Just Do It' slogan was introduced in 1988 by the advertising agency Wieden+Kennedy.","o":["Adidas","Nike","Reebok","Puma"],"s":{"index":1}},{"k":"choice","i":"The three-pointed star of Mercedes-Benz stands for engines on land, at sea and where else?","t":"Logos","e":"\u2b50","f":"The star reflected the Daimler company's ambition to motorise travel on land, on water and in the air.","o":["On rails","In the air","In space","On snow"],"s":{"index":1}},{"k":"choice","i":"Which brand's slogan is 'Because You're Worth It'?","t":"Slogans","e":"\ud83d\udc84","f":"The famous line was written in 1971 by copywriter Ilon Specht.","o":["Nivea","Maybelline","L'Or\u00e9al","Dove"],"s":{"index":2}},{"k":"choice","i":"Which mythical creature appears on the Starbucks logo?","t":"Logos","e":"\ud83e\udddc","f":"The siren comes from an old woodcut and nods to the seafaring history of Seattle, where Starbucks began.","o":["A dragon","A two-tailed siren","A phoenix","A unicorn"],"s":{"index":1}},{"k":"choice","i":"What is the name of the Michelin tyre company's mascot, made of stacked white tyres?","t":"Mascots","e":"\ud83d\udede","f":"Bibendum first appeared in 1898, making him one of the oldest trademarks still in use.","o":["Rollo","Gommi","Tyrone","Bibendum"],"s":{"index":3}},{"k":"choice","i":"Which fast-food chain's slogan is 'I'm Lovin' It'?","t":"Slogans","e":"\ud83c\udf54","f":"The campaign launched in 2003 and debuted first in Germany as 'Ich liebe es'.","o":["Burger King","KFC","McDonald's","Subway"],"s":{"index":2}},{"k":"truefalse","i":"Apple's very first logo showed Isaac Newton sitting under a tree.","t":"Logos","e":"\ud83c\udf4f","f":"Co-founder Ronald Wayne drew it in 1976, but it was soon replaced by the rainbow-striped apple.","a":true},{"k":"truefalse","i":"Audi's four rings stand for the four wheels of a car.","t":"Logos","e":"\u2b55","f":"The rings stand for four companies that merged in 1932 to form Auto Union: Audi, DKW, Horch and Wanderer.","a":false},{"k":"multi","i":"Select all the brands whose logo features an animal.","t":"Logos","e":"\ud83d\udc0e","f":"Ferrari's prancing horse sits on a yellow background, the colour of Modena, Enzo Ferrari's home town.","o":["Ferrari","Lacoste","Shell","Puma","Nike"],"s":{"indices":[0,1,3]}},{"k":"text","i":"Which energy drink brand says it 'gives you wings'?","t":"Slogans","e":"\ud83e\udebd","f":"Red Bull was launched in Austria in 1987, inspired by a Thai energy drink called Krating Daeng.","s":{"accepted":["Red Bull","RedBull"]}},{"k":"text","i":"Finish the chocolate slogan: 'Have a break, have a ___'.","t":"Slogans","e":"\ud83c\udf6b","f":"The 'Have a break' slogan has been used in the UK since 1957.","s":{"accepted":["KitKat","Kit Kat","Kit-Kat"]}},{"k":"number","i":"How many US dollars was design student Carolyn Davidson first paid for creating the Nike swoosh in 1971?","t":"Logos","e":"\u270f\ufe0f","f":"Davidson was later given Nike shares as a thank-you for her famous design.","s":{"value":35,"tolerance":0,"min":0,"max":500,"unit":"dollars"}},{"k":"order","i":"Order these slogans by the year they were introduced, oldest first.","t":"Timeline","e":"\ud83d\udcc5","f":"Apple's 1997 'Think Different' campaign celebrated famous thinkers such as Albert Einstein.","o":["Because You're Worth It (L'Or\u00e9al)","Just Do It (Nike)","Think Different (Apple)","I'm Lovin' It (McDonald's)"]}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'b15c2719af17ebb3ec9c6a0eb53c2619' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 8'; end $q$;
do $q$ declare d text := $d$[{"slug":"taste-of-hungary","title":"A Taste of Hungary","tagline":"Goulash, chimney cake and folk traditions: how Hungarian is your palate?","emoji":"\ud83c\udf36\ufe0f","gradient":["#b91c1c","#ea580c"],"categories":["food","culture"],"countries":["HU"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":268,"items":[{"k":"choice","i":"Which spice gives Hungarian goulash its signature flavour and colour?","t":"Spices","e":"\ud83c\udf36\ufe0f","f":"Szeged and Kalocsa are Hungary's two most famous paprika-growing regions.","o":["Saffron","Turmeric","Cumin","Paprika"],"s":{"index":3}},{"k":"truefalse","i":"Traditional Hungarian goulash (guly\u00e1s) is a soup rather than a thick stew.","t":"Dishes","e":"\ud83c\udf72","f":"Guly\u00e1s comes from the word for a cattle herdsman, as herders cooked it in kettles over open fires.","a":true},{"k":"choice","i":"What is k\u00fcrt\u0151skal\u00e1cs, a popular Hungarian street treat?","t":"Sweets","e":"\ud83c\udf00","f":"Chimney cake dough is wound around a spit, roasted over heat and rolled in sugar.","o":["A cabbage roll","A chimney cake","A fried fish","A cheese soup"],"s":{"index":1}},{"k":"text","i":"What is the name of the famous Hungarian layered sponge cake topped with hard caramel? (It starts with D.)","t":"Sweets","e":"\ud83c\udf70","f":"Confectioner J\u00f3zsef C. Dobos created the cake in 1884, and its caramel top helped it stay fresh longer.","s":{"accepted":["Dobos","Dobos torte","Dobos torta","Dobostorta","Dobos cake"]}},{"k":"choice","i":"L\u00e1ngos, a favourite snack at Hungarian beaches, is usually topped with what?","t":"Street food","e":"\ud83e\uded3","f":"L\u00e1ngos is deep-fried dough, often rubbed with garlic before the toppings go on.","o":["Sour cream and cheese","Tomato and basil","Honey and walnuts","Chocolate spread"],"s":{"index":0}},{"k":"multi","i":"Select all the traditional Hungarian dishes.","t":"Dishes","e":"\ud83c\udf7d\ufe0f","f":"Hal\u00e1szl\u00e9 is a fiery paprika fish soup, traditionally made with carp from the Danube or the Tisza.","o":["Paprik\u00e1s csirke","Pierogi","T\u00f6lt\u00f6tt k\u00e1poszta","Hal\u00e1szl\u00e9","Paella"],"s":{"indices":[0,2,3]}},{"k":"choice","i":"What is T\u00far\u00f3 Rudi, a much-loved Hungarian snack?","t":"Snacks","e":"\ud83c\udf6b","f":"T\u00far\u00f3 Rudi has been made since 1968, and its red polka-dot wrapper is instantly recognisable in Hungary.","o":["A fruit jelly","A salted pretzel","A chocolate-coated curd cheese bar","A sausage roll"],"s":{"index":2}},{"k":"choice","i":"Which festival in Moh\u00e1cs features people in scary wooden masks chasing winter away?","t":"Festivals","e":"\ud83d\udc79","f":"Bus\u00f3j\u00e1r\u00e1s in Moh\u00e1cs is on UNESCO's list of Intangible Cultural Heritage.","o":["Bus\u00f3j\u00e1r\u00e1s","Budapest Spring Festival","Sziget","Kalocsa Paprika Days"],"s":{"index":0}},{"k":"truefalse","i":"In Hungary, Mikul\u00e1s (St. Nicholas) traditionally brings small gifts on 6 December.","t":"Traditions","e":"\ud83c\udf85","f":"Hungarian children leave polished boots on the windowsill the night before Mikul\u00e1s comes.","a":true},{"k":"choice","i":"T\u00e9li szal\u00e1mi, or 'winter salami', is a famous Hungarian type of what?","t":"Dishes","e":"\ud83e\udd53","f":"Winter salami gets its name because it was traditionally made in the colder months, then smoked and air-dried.","o":["Cheese","Bread","Salami","Pastry"],"s":{"index":2}},{"k":"order","i":"Order these Hungarian celebrations through the calendar year, starting in January.","t":"Holidays","e":"\ud83d\udcc5","f":"On 20 August, St. Stephen's Day, Budapest celebrates with a huge fireworks display over the Danube.","o":["National Day (15 March)","St. Stephen's Day (20 August)","1956 Revolution Day (23 October)","Mikul\u00e1s (6 December)"]},{"k":"number","i":"In what year did Albert Szent-Gy\u00f6rgyi, who studied vitamin C using Hungarian paprika, win the Nobel Prize?","t":"Science","e":"\ud83d\udd2c","f":"Szent-Gy\u00f6rgyi found that Szeged paprika was rich in vitamin C, letting him produce it in large amounts.","s":{"value":1937,"tolerance":0,"min":1900,"max":1980,"unit":""}},{"k":"choice","i":"What is lecs\u00f3?","t":"Dishes","e":"\ud83e\uded1","f":"Lecs\u00f3 is often cooked with sausage or eggs and is a summer favourite when peppers are in season.","o":["A poppy seed roll","A stew of peppers, tomatoes and onions","A plum dumpling","A cold cherry soup"],"s":{"index":1}},{"k":"text","i":"Which poppy seed or walnut roll is a Hungarian Christmas classic? (It starts with B.)","t":"Sweets","e":"\ud83c\udf84","f":"Bejgli is traditionally baked in two versions, poppy seed and walnut, and served at Christmas.","s":{"accepted":["Bejgli","Beigli"]}}]},{"slug":"space-exploration-milestones","title":"Mission Control","tagline":"Sputnik to Pluto: relive the greatest moments of space exploration.","emoji":"\ud83d\ude80","gradient":["#1e40af","#db2777"],"categories":["space","history","tech"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":269,"items":[{"k":"number","i":"In what year did Apollo 11 land the first astronauts on the Moon?","t":"Moon","e":"\ud83c\udf15","f":"Neil Armstrong and Buzz Aldrin walked on the Moon while Michael Collins orbited above in the command module.","s":{"value":1969,"tolerance":0,"min":1950,"max":2000,"unit":""}},{"k":"choice","i":"Who was the first human to travel into space?","t":"Astronauts","e":"\ud83d\udc68\u200d\ud83d\ude80","f":"Gagarin's 1961 flight aboard Vostok 1 lasted 108 minutes and made one orbit of Earth.","o":["Neil Armstrong","Yuri Gagarin","John Glenn","Alan Shepard"],"s":{"index":1}},{"k":"choice","i":"What was the name of the first artificial satellite, launched in 1957?","t":"Satellites","e":"\ud83d\udef0\ufe0f","f":"Sputnik 1 was a metal ball about 58 cm across that beeped radio signals as it orbited.","o":["Explorer 1","Vanguard 1","Telstar 1","Sputnik 1"],"s":{"index":3}},{"k":"choice","i":"Who was the first woman to travel into space, in 1963?","t":"Astronauts","e":"\ud83d\udc69\u200d\ud83d\ude80","f":"Valentina Tereshkova orbited Earth 48 times aboard Vostok 6.","o":["Sally Ride","Mae Jemison","Valentina Tereshkova","Svetlana Savitskaya"],"s":{"index":2}},{"k":"truefalse","i":"The Hubble Space Telescope was launched in 1990.","t":"Telescopes","e":"\ud83d\udd2d","f":"Hubble orbits above Earth's atmosphere, so its view of the universe isn't blurred by air.","a":true},{"k":"order","i":"Order these space milestones from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"The first long-term crew arrived at the International Space Station in November 2000.","o":["Sputnik 1 launched","First human in space","First crewed Moon landing","Hubble Space Telescope launched","First crew arrives at the International Space Station"]},{"k":"text","i":"What was the name of the NASA program that landed astronauts on the Moon?","t":"Moon","e":"\ud83c\udf19","f":"Twelve astronauts walked on the Moon during six Apollo landings between 1969 and 1972.","s":{"accepted":["Apollo","Apollo program","Project Apollo","The Apollo program","Apollo programme"]}},{"k":"multi","i":"Select all the astronauts who walked on the Moon.","t":"Moon","e":"\ud83d\udc63","f":"Alan Shepard, the first American in space, later hit golf balls on the Moon during Apollo 14.","o":["Neil Armstrong","Yuri Gagarin","Buzz Aldrin","Michael Collins","Alan Shepard"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"Which car-sized NASA rover landed on Mars in 2012?","t":"Mars","e":"\ud83e\udd16","f":"Curiosity was lowered to the Martian surface on cables by a rocket-powered 'sky crane'.","o":["Curiosity","Sojourner","Spirit","Opportunity"],"s":{"index":0}},{"k":"truefalse","i":"The Voyager 1 probe has left the heliosphere and entered interstellar space.","t":"Probes","e":"\ud83d\udef8","f":"Voyager 1, launched in 1977, crossed into interstellar space in 2012.","a":true},{"k":"choice","i":"What was the name of NASA's reusable spacecraft that flew from 1981 to 2011?","t":"Spacecraft","e":"\ud83d\ude80","f":"Five Space Shuttle orbiters flew in space, completing 135 missions in total.","o":["Space Shuttle","Soyuz","Gemini","Orion"],"s":{"index":0}},{"k":"multi","i":"Select all the missions that explored Mars.","t":"Mars","e":"\ud83d\udd34","f":"Viking 1 became the first US spacecraft to land successfully on Mars, in 1976.","o":["Viking 1","Voyager 1","Perseverance","Hubble Space Telescope","Opportunity"],"s":{"indices":[0,2,4]}},{"k":"text","i":"What is the name of the orbiting laboratory, built by several nations, whose first module launched in 1998?","t":"Space stations","e":"\ud83d\udef0\ufe0f","f":"The ISS travels at about 28,000 km/h, circling Earth roughly every 90 minutes.","s":{"accepted":["International Space Station","ISS","The International Space Station","The ISS"]}},{"k":"choice","i":"Which space probe made the first flyby of Pluto, in 2015?","t":"Probes","e":"\ud83c\udf11","f":"New Horizons revealed a huge heart-shaped plain on Pluto's surface.","o":["Cassini","Juno","Voyager 2","New Horizons"],"s":{"index":3}}]},{"slug":"cash-around-the-world","title":"Cash Around the World","tagline":"Yen, zloty, rand and real: can you name the money in other people's wallets?","emoji":"\ud83d\udcb1","gradient":["#15803d","#0e7490"],"categories":["business","geo"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":270,"items":[{"k":"choice","i":"What is the currency of Japan?","t":"Asia","e":"\ud83d\udcb4","f":"Yen, yuan and won all come from the same Chinese character, meaning 'round', after round coins.","o":["Won","Yuan","Yen","Ringgit"],"s":{"index":2}},{"k":"multi","i":"Select all the countries that use the euro.","t":"Europe","e":"\ud83d\udcb6","f":"Euro coins share a common side, but each country designs its own national side.","o":["Germany","United Kingdom","Switzerland","Portugal","Spain","Norway"],"s":{"indices":[0,3,4]}},{"k":"text","i":"The British pound is officially known as the pound\u2026","t":"Europe","e":"\ud83d\udcb7","f":"Sterling is one of the world's oldest currencies still in use, dating back over 1,200 years.","s":{"accepted":["Sterling","Pound sterling"]}},{"k":"choice","i":"Which country uses the forint?","t":"Europe","e":"\ud83c\udded\ud83c\uddfa","f":"Its name comes from the gold florin coins first minted in medieval Florence.","o":["Poland","Romania","Hungary","Croatia"],"s":{"index":2}},{"k":"choice","i":"The z\u0142oty is the currency of which country?","t":"Europe","e":"\ud83c\uddf5\ud83c\uddf1","f":"'Z\u0142oty' simply means 'golden' in Polish.","o":["Czech Republic","Slovakia","Poland","Bulgaria"],"s":{"index":2}},{"k":"choice","i":"What is Brazil's currency?","t":"Americas","e":"\ud83c\udde7\ud83c\uddf7","f":"The real was introduced in 1994 to bring an end to years of extremely high inflation.","o":["Peso","Real","Bol\u00edvar","Sol"],"s":{"index":1}},{"k":"number","i":"In what year did euro banknotes and coins go into circulation?","t":"Europe","e":"\ud83e\ude99","f":"The euro existed electronically from 1999; the cash arrived on 1 January 2002 in 12 countries.","s":{"value":2002,"tolerance":0,"min":1990,"max":2010,"unit":""}},{"k":"choice","i":"What is Mexico's currency?","t":"Americas","e":"\ud83c\uddf2\ud83c\uddfd","f":"The '$' sign was used for the Spanish-American peso before the US dollar adopted it.","o":["Peso","Real","Dollar","Col\u00f3n"],"s":{"index":0}},{"k":"truefalse","i":"Spain's currency before the euro was the peseta.","t":"Europe","e":"\ud83c\uddea\ud83c\uddf8","f":"The peseta served as Spain's currency for more than 130 years before the euro replaced it.","a":true},{"k":"truefalse","i":"The rand is the currency of Australia.","t":"Africa","e":"\ud83c\uddff\ud83c\udde6","f":"The rand belongs to South Africa and is named after the Witwatersrand, a gold-rich ridge. Australia uses the dollar.","a":false},{"k":"order","i":"Order these currencies by when they were introduced, oldest first.","t":"Timeline","e":"\u23f3","f":"Sterling dates from Anglo-Saxon times, the Swiss franc from 1850, the Deutsche Mark from 1948 and the euro from 1999.","o":["Pound sterling","Swiss franc","Deutsche Mark","Euro"]},{"k":"choice","i":"Which country's currency is the rupee?","t":"Asia","e":"\ud83c\uddee\ud83c\uddf3","f":"Rupee comes from the Sanskrit 'r\u016bpya', meaning wrought silver; Indonesia's rupiah shares the same root.","o":["Indonesia","Thailand","India","Vietnam"],"s":{"index":2}},{"k":"text","i":"Which currency name is shared by the United States, Canada and Australia?","t":"Americas","e":"\ud83d\udcb5","f":"'Dollar' comes from the 'thaler', a silver coin first minted in Joachimsthal, now J\u00e1chymov in the Czech Republic.","s":{"accepted":["Dollar","Dollars","The dollar"]}}]},{"slug":"anime-classics","title":"Anime Classics","tagline":"Dragon Balls, magical girls and giant robots from anime's golden eras.","emoji":"\ud83d\udc09","gradient":["#ea580c","#be123c"],"categories":["anime"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":271,"items":[{"k":"choice","i":"What is the name of the main hero of 'Dragon Ball'?","t":"Dragon Ball","e":"\ud83d\udc12","f":"Son Goku is loosely based on Sun Wukong, the Monkey King from the Chinese classic 'Journey to the West'.","o":["Vegeta","Goku","Gohan","Piccolo"],"s":{"index":1}},{"k":"choice","i":"In 'Naruto', what is the title of the leader of the Hidden Leaf Village?","t":"Naruto","e":"\ud83c\udf65","f":"Naruto Uzumaki's dream is to become Hokage and be recognised by everyone in his village.","o":["Hokage","Kazekage","Shogun","Sensei"],"s":{"index":0}},{"k":"choice","i":"What is Sailor Moon's everyday name?","t":"Sailor Moon","e":"\ud83c\udf19","f":"In some English dubs, Usagi was renamed Serena.","o":["Ami Mizuno","Rei Hino","Usagi Tsukino","Makoto Kino"],"s":{"index":2}},{"k":"choice","i":"Which manga artist created 'Astro Boy'?","t":"Creators","e":"\ud83e\udd16","f":"Osamu Tezuka is often called the 'God of Manga'.","o":["Akira Toriyama","Rumiko Takahashi","Go Nagai","Osamu Tezuka"],"s":{"index":3}},{"k":"choice","i":"What is the name of Team Rocket's talking cat Pok\u00e9mon in the anime?","t":"Pok\u00e9mon","e":"\ud83d\ude3c","f":"Meowth taught himself to walk and talk like a human, which is why he speaks.","o":["Meowth","Persian","Jigglypuff","Psyduck"],"s":{"index":0}},{"k":"choice","i":"'Mobile Suit Gundam' is a landmark series of which genre?","t":"Genres","e":"\ud83e\uddbe","f":"Gundam helped create the 'real robot' style, treating giant robots as military machines rather than superheroes.","o":["Magical girl","Sports","Slice of life","Mecha (giant robots)"],"s":{"index":3}},{"k":"choice","i":"Which manga magazine first serialized 'Dragon Ball', 'Naruto' and 'One Piece'?","t":"Manga","e":"\ud83d\udcd6","f":"Weekly Sh\u014dnen Jump is one of Japan's best-selling manga magazines.","o":["Nakayoshi","Weekly Sh\u014dnen Magazine","Weekly Sh\u014dnen Jump","CoroCoro Comic"],"s":{"index":2}},{"k":"number","i":"How many Dragon Balls must be gathered to summon the wish-granting dragon Shenron?","t":"Dragon Ball","e":"\ud83d\udd2e","f":"Each Dragon Ball has between one and seven stars inside it.","s":{"value":7,"tolerance":0,"min":1,"max":12,"unit":""}},{"k":"truefalse","i":"In 'One Piece', Monkey D. Luffy dreams of becoming King of the Pirates.","t":"One Piece","e":"\ud83c\udff4\u200d\u2620\ufe0f","f":"Luffy's body became stretchy like rubber after he ate a Devil Fruit.","a":true},{"k":"truefalse","i":"In 'Sailor Moon', Luna is a talking black cat.","t":"Sailor Moon","e":"\ud83d\udc08\u200d\u2b1b","f":"Luna has a crescent moon mark on her forehead.","a":true},{"k":"text","i":"What is the name of the blue robot cat from the future in Fujiko F. Fujio's classic manga?","t":"Classics","e":"\ud83d\udd14","f":"Doraemon pulls amazing gadgets out of a four-dimensional pocket on his tummy.","s":{"accepted":["Doraemon"]}},{"k":"multi","i":"Select all the series created by Akira Toriyama.","t":"Creators","e":"\u270f\ufe0f","f":"Sailor Moon is by Naoko Takeuchi, Naruto by Masashi Kishimoto and One Piece by Eiichiro Oda.","o":["Dragon Ball","Sailor Moon","Dr. Slump","Naruto","One Piece"],"s":{"indices":[0,2]}},{"k":"order","i":"Order these anime series by their first TV broadcast, oldest first.","t":"Timeline","e":"\ud83d\udcfa","f":"They premiered in 1963, 1979, 1986, 1992 and 2002.","o":["Astro Boy","Mobile Suit Gundam","Dragon Ball","Sailor Moon","Naruto"]}]},{"slug":"brand-name-origins","title":"What's in a Brand Name?","tagline":"LEGO, IKEA, Volvo and Haribo: decode the stories behind famous names.","emoji":"\ud83d\udd24","gradient":["#4f46e5","#0e7490"],"categories":["brands","language","business"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":272,"items":[{"k":"choice","i":"The name LEGO comes from the Danish words 'leg godt'. What do they mean?","t":"Toys","e":"\ud83e\uddf1","f":"LEGO was founded in Billund, Denmark, by carpenter Ole Kirk Christiansen in 1932.","o":["Build big","Play well","Little bricks","Good toys"],"s":{"index":1}},{"k":"choice","i":"IKEA's name combines its founder's initials with the names of his farm and village. Where is IKEA from?","t":"Furniture","e":"\ud83d\udecb\ufe0f","f":"IKEA stands for Ingvar Kamprad, Elmtaryd and Agunnaryd; Kamprad founded it aged 17 in 1943.","o":["Norway","Denmark","Sweden","Finland"],"s":{"index":2}},{"k":"choice","i":"Volvo's name comes from Latin. What does 'volvo' mean?","t":"Latin","e":"\ud83d\ude99","f":"Volvo was originally a brand name for ball bearings made by the Swedish company SKF.","o":["I drive","I fly","I win","I roll"],"s":{"index":3}},{"k":"choice","i":"What does the name 'Samsung' mean in Korean?","t":"Korea","e":"\u2b50","f":"Samsung began in 1938 as a small trading company selling dried fish, vegetables and noodles.","o":["Big ocean","Three stars","Golden dragon","Bright future"],"s":{"index":1}},{"k":"choice","i":"Starbucks is named after a character from which classic novel?","t":"Literature","e":"\ud83d\udcd6","f":"Starbuck is the first mate of the whaling ship Pequod in Herman Melville's 1851 novel.","o":["Treasure Island","Robinson Crusoe","Moby-Dick","Gulliver's Travels"],"s":{"index":2}},{"k":"truefalse","i":"Google's name comes from 'googol', the number 1 followed by 100 zeros.","t":"Tech","e":"\ud83d\udd22","f":"The name was meant to reflect the huge amount of information the search engine set out to organise.","a":true},{"k":"truefalse","i":"Coca-Cola was first sold in New York City.","t":"Drinks","e":"\ud83e\udd64","f":"Pharmacist John Pemberton created Coca-Cola in Atlanta, Georgia, in 1886.","a":false},{"k":"multi","i":"Select all the brands that come from Japan.","t":"Japan","e":"\ud83c\udfb4","f":"Nintendo was founded in Kyoto in 1889 as a maker of hanafuda playing cards.","o":["Sony","Nokia","Canon","Samsung","Nintendo"],"s":{"indices":[0,2,4]}},{"k":"multi","i":"Select all the brand names that come from Latin words.","t":"Latin","e":"\ud83c\udfdb\ufe0f","f":"Audi is Latin for 'listen!', a translation of founder August Horch's surname, which means 'hark' in German.","o":["Audi","Nivea","Kodak","H\u00e4agen-Dazs","LEGO"],"s":{"indices":[0,1]}},{"k":"text","i":"Haribo's name comes from HAns RIegel and his home city, BO... Which German city?","t":"Sweets","e":"\ud83d\udc3b","f":"Hans Riegel founded the company in Bonn in 1920 and later created its famous gummy bears.","s":{"accepted":["Bonn"]}},{"k":"text","i":"Which Swiss chocolate's name blends its creator's surname with 'torrone', Italian nougat?","t":"Chocolate","e":"\ud83c\udf6b","f":"Theodor Tobler created the triangular bar in Bern in 1908.","s":{"accepted":["Toblerone"]}},{"k":"number","i":"In what year was LEGO's interlocking plastic brick patented?","t":"Toys","e":"\ud83e\uddf1","f":"LEGO bricks made today still fit together with bricks made back in 1958.","s":{"value":1958,"tolerance":0,"min":1900,"max":2000,"unit":""}},{"k":"order","i":"Order these brands by founding year, oldest first.","t":"Timeline","e":"\u23f3","f":"Coca-Cola is the oldest of the four, created in 1886, three years before Nintendo began making playing cards.","o":["Coca-Cola","Nintendo","LEGO","IKEA"]}]},{"slug":"deutschland-deep-dive","title":"Deutschland Deep Dive","tagline":"Castles, composers and currywurst: explore Germany's past and present.","emoji":"\ud83c\udde9\ud83c\uddea","gradient":["#b91c1c","#ca8a04"],"categories":["history","culture","geo"],"countries":["DE"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":273,"items":[{"k":"choice","i":"Which Bavarian castle inspired Disney's Sleeping Beauty Castle?","t":"Castles","e":"\ud83c\udff0","f":"Neuschwanstein was commissioned by King Ludwig II of Bavaria, who died before it was finished.","o":["Hohenzollern","Neuschwanstein","Heidelberg","Sanssouci"],"s":{"index":1}},{"k":"number","i":"In what year was Germany reunified?","t":"History","e":"\ud83e\udd1d","f":"German Unity Day is celebrated every year on 3 October.","s":{"value":1990,"tolerance":0,"min":1950,"max":2010,"unit":""}},{"k":"choice","i":"Which composer, born in Bonn, set the 'Ode to Joy' in his Ninth Symphony?","t":"Music","e":"\ud83c\udfbc","f":"Beethoven was almost completely deaf when he composed his Ninth Symphony.","o":["Johann Sebastian Bach","Ludwig van Beethoven","Johannes Brahms","Richard Wagner"],"s":{"index":1}},{"k":"multi","i":"Select all the rivers that flow through Germany.","t":"Rivers","e":"\ud83c\udf0a","f":"The Danube rises in Germany's Black Forest and flows all the way to the Black Sea.","o":["Danube","Vistula","Elbe","Seine","Rhine"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these German composers by birth year, from earliest to latest.","t":"Music","e":"\ud83c\udfbb","f":"Richard Wagner had his own opera house built in Bayreuth, which still hosts a festival of his works every summer.","o":["Johann Sebastian Bach","Ludwig van Beethoven","Richard Wagner","Johannes Brahms"]},{"k":"text","i":"Which German city is home to the Brandenburg Gate?","t":"Landmarks","e":"\ud83c\udfdb\ufe0f","f":"The Brandenburg Gate was completed in 1791 and is topped by the Quadriga, a chariot pulled by four horses.","s":{"accepted":["Berlin"]}},{"k":"choice","i":"Which brothers collected fairy tales such as 'Hansel and Gretel' and 'Snow White'?","t":"Literature","e":"\ud83d\udcda","f":"Jacob and Wilhelm Grimm also began a huge German dictionary, finished more than a century after their deaths.","o":["The Schlegel brothers","The Humboldt brothers","The Mann brothers","The Brothers Grimm"],"s":{"index":3}},{"k":"choice","i":"What is the highest mountain in Germany?","t":"Mountains","e":"\ud83c\udfd4\ufe0f","f":"The Zugspitze, at 2,962 m, sits right on the border with Austria.","o":["Brocken","Feldberg","Zugspitze","Watzmann"],"s":{"index":2}},{"k":"order","i":"Order these German cities from north to south.","t":"Cities","e":"\ud83e\udded","f":"Hamburg's port on the Elbe is one of Europe's busiest, even though it lies about 100 km from the sea.","o":["Hamburg","Berlin","Frankfurt","Munich"]},{"k":"choice","i":"Which German dish is a sliced sausage served with curry-spiced ketchup?","t":"Food","e":"\ud83c\udf2d","f":"Currywurst is credited to Herta Heuwer, who first sold it in Berlin in 1949.","o":["Currywurst","Schnitzel","Sp\u00e4tzle","Sauerbraten"],"s":{"index":0}},{"k":"choice","i":"Which writer created the famous play 'Faust'?","t":"Literature","e":"\u2712\ufe0f","f":"Goethe worked on Faust on and off for most of his adult life, finishing Part Two shortly before his death in 1832.","o":["Franz Kafka","Johann Wolfgang von Goethe","Friedrich Schiller","Hermann Hesse"],"s":{"index":1}},{"k":"number","i":"How many countries border Germany?","t":"Borders","e":"\ud83d\uddfa\ufe0f","f":"Germany's neighbours are Denmark, Poland, Czechia, Austria, Switzerland, France, Luxembourg, Belgium and the Netherlands.","s":{"value":9,"tolerance":0,"min":1,"max":15,"unit":""}},{"k":"truefalse","i":"The Black Forest is located in north-eastern Germany.","t":"Nature","e":"\ud83c\udf32","f":"The Black Forest is in the south-west, in Baden-W\u00fcrttemberg, and is famous for its cuckoo clocks.","a":false},{"k":"truefalse","i":"Cologne Cathedral took more than 600 years to complete.","t":"Landmarks","e":"\u26ea","f":"Construction of Cologne Cathedral began in 1248, and the building was finally completed in 1880.","a":true}]},{"slug":"stars-and-galaxies","title":"Stars & Galaxies","tagline":"Light-years, black holes and supergiants: explore the deep sky.","emoji":"\ud83c\udf0c","gradient":["#3730a3","#7e22ce"],"categories":["space","science"],"countries":null,"difficulty":"Hard","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":274,"items":[{"k":"choice","i":"What is the name of the galaxy we live in?","t":"Galaxies","e":"\ud83c\udf0c","f":"The Milky Way is a barred spiral galaxy roughly 100,000 light-years across.","o":["Andromeda","Milky Way","Triangulum","Whirlpool"],"s":{"index":1}},{"k":"choice","i":"What is the nearest large spiral galaxy to the Milky Way?","t":"Galaxies","e":"\ud83c\udf00","f":"Andromeda is about 2.5 million light-years away, yet visible to the naked eye on a dark night.","o":["Andromeda","Sombrero","Whirlpool","Pinwheel"],"s":{"index":0}},{"k":"choice","i":"What does a light-year measure?","t":"Units","e":"\ud83d\udccf","f":"A light-year is about 9.46 trillion km, the distance light travels in one year.","o":["Time","Brightness","Distance","Speed"],"s":{"index":2}},{"k":"text","i":"What is the name of the star system closest to our Sun?","t":"Stars","e":"\u2b50","f":"Proxima Centauri, part of the Alpha Centauri system, is about 4.2 light-years away.","s":{"accepted":["Alpha Centauri","Proxima Centauri","Alpha Centauri system","Proxima"]}},{"k":"multi","i":"Select all the objects that are stars.","t":"Stars","e":"\u2728","f":"Venus is often mistaken for a star, but it shines by reflecting sunlight.","o":["Polaris","Venus","Vega","Halley's Comet","Rigel"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"What forms when a very massive star collapses into an object whose gravity is so strong that not even light can escape?","t":"Black holes","e":"\ud83d\udd73\ufe0f","f":"The first image of a black hole, in the galaxy M87, was released in 2019.","o":["Neutron star","White dwarf","Pulsar","Black hole"],"s":{"index":3}},{"k":"multi","i":"Select all the constellations of the zodiac.","t":"Constellations","e":"\u264c","f":"The zodiac constellations lie along the ecliptic, the Sun's apparent yearly path across the sky.","o":["Orion","Leo","Scorpius","Ursa Major","Gemini"],"s":{"indices":[1,2,4]}},{"k":"choice","i":"Which is the brightest star in the night sky?","t":"Stars","e":"\ud83d\udc15","f":"Sirius, the 'Dog Star', is about 8.6 light-years from Earth.","o":["Polaris","Betelgeuse","Sirius","Vega"],"s":{"index":2}},{"k":"order","i":"Order these from smallest to largest.","t":"Scale","e":"\ud83d\udd2d","f":"The Sun's diameter is about 109 times that of Earth.","o":["The Moon","Earth","Jupiter","The Sun","The Milky Way"]},{"k":"truefalse","i":"Stars appear to twinkle because their light is bent by Earth's moving atmosphere.","t":"Observing","e":"\ud83c\udf20","f":"Seen from space, above the atmosphere, stars shine steadily without twinkling.","a":true},{"k":"number","i":"To the nearest billion, how old is the universe, in billions of years?","t":"Cosmology","e":"\ud83d\udca5","f":"Measurements of the cosmic microwave background put the universe's age at about 13.8 billion years.","s":{"value":14,"tolerance":0,"min":1,"max":30,"unit":"billion years"}},{"k":"choice","i":"Which element is the main fuel of the Sun?","t":"The Sun","e":"\u2600\ufe0f","f":"Every second, the Sun converts about 4 million tonnes of matter into energy.","o":["Helium","Hydrogen","Oxygen","Carbon"],"s":{"index":1}},{"k":"text","i":"What is the name of the red supergiant star that marks one of Orion's shoulders?","t":"Stars","e":"\ud83d\udd34","f":"Betelgeuse is so large that, placed where the Sun is, it would extend beyond the orbit of Mars.","s":{"accepted":["Betelgeuse","Betelgeuze"]}}]},{"slug":"business-buzzwords","title":"Business Buzzwords","tagline":"IPOs, unicorns and bull markets: do you speak fluent boardroom?","emoji":"\ud83d\udcc8","gradient":["#1e40af","#7c3aed"],"categories":["business","general"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":275,"items":[{"k":"choice","i":"What does 'IPO' stand for?","t":"Acronyms","e":"\ud83d\udd14","f":"An IPO is when a private company first sells its shares to the public on a stock exchange.","o":["International Price Order","Internal Profit Outlook","Initial Public Offering","Investor Payment Option"],"s":{"index":2}},{"k":"choice","i":"In investing, a 'bull market' is one in which prices are\u2026","t":"Markets","e":"\ud83d\udc02","f":"A popular explanation: a bull thrusts its horns up, while a bear swipes its paws down.","o":["Rising","Falling","Frozen","Fixed by law"],"s":{"index":0}},{"k":"choice","i":"A privately held startup valued at over $1 billion is nicknamed a\u2026","t":"Startups","e":"\ud83e\udd84","f":"Investor Aileen Lee coined the term in 2013, when such companies were rare.","o":["Dragon","Phoenix","Pegasus","Unicorn"],"s":{"index":3}},{"k":"text","i":"What does the 'E' in CEO stand for?","t":"Acronyms","e":"\ud83d\udc54","f":"CEO means Chief Executive Officer; the CFO is the Chief Financial Officer.","s":{"accepted":["Executive"]}},{"k":"choice","i":"What does 'B2B' mean?","t":"Acronyms","e":"\ud83e\udd1d","f":"B2C, business to consumer, describes companies that sell directly to the public.","o":["Bank to bank","Brand to buyer","Bulk to buyer","Business to business"],"s":{"index":3}},{"k":"truefalse","i":"GDP stands for Gross Domestic Product.","t":"Economics","e":"\ud83c\udf10","f":"GDP measures the total value of goods and services a country produces over a set period, such as a year.","a":true},{"k":"choice","i":"Wall Street, home of the famous stock exchange, is in which city?","t":"Markets","e":"\ud83d\uddfd","f":"The street is named after a wall built by Dutch settlers when the city was still called New Amsterdam.","o":["Chicago","New York","London","Boston"],"s":{"index":1}},{"k":"multi","i":"Select all the stock market indexes.","t":"Markets","e":"\ud83d\udcca","f":"The FTSE 100 tracks big companies in London and the Nikkei 225 in Tokyo; the Fortune 500 is a ranking, not an index.","o":["FTSE 100","Dow Jones Industrial Average","Nikkei 225","Forbes 400","Fortune 500"],"s":{"indices":[0,1,2]}},{"k":"number","i":"In what year was the Dow Jones Industrial Average first published?","t":"Markets","e":"\ud83d\udcf0","f":"It started with just 12 companies; today it tracks 30.","s":{"value":1896,"tolerance":0,"min":1800,"max":2000,"unit":""}},{"k":"choice","i":"What is 'inflation'?","t":"Economics","e":"\ud83c\udf88","f":"Many central banks aim to keep inflation at around 2% a year.","o":["A rise in one company's share price","A general rise in prices over time","An increase in population","A fall in interest rates"],"s":{"index":1}},{"k":"truefalse","i":"A company's 'revenue' and its 'profit' mean the same thing.","t":"Accounting","e":"\ud83d\udcb0","f":"Revenue is all the money coming in; profit is what's left after the costs have been paid.","a":false},{"k":"text","i":"Which three-letter abbreviation stands for 'return on investment'?","t":"Acronyms","e":"\u21a9\ufe0f","f":"ROI compares the gain from an investment with what it cost, usually shown as a percentage.","s":{"accepted":["ROI","R.O.I."]}},{"k":"order","i":"Order these numbers from smallest to largest.","t":"Big numbers","e":"\ud83d\udd22","f":"A googol is 1 followed by 100 zeros, far more than the estimated number of atoms in the observable universe.","o":["A thousand","A million","A billion","A trillion","A googol"]},{"k":"choice","i":"What is a 'dividend'?","t":"Investing","e":"\ud83e\uddfe","f":"Not every company pays dividends; many fast-growing firms reinvest their profits instead.","o":["A fee for opening a bank account","A share of profits paid to shareholders","A penalty for paying late","A tax on imported goods"],"s":{"index":1}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'bf43c5d34d5b448ce9461e10d6e508bc' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 9'; end $q$;
do $q$ declare d text := $d$[{"slug":"studio-ghibli-magic","title":"Studio Ghibli Magic","tagline":"Catbuses, fire demons and flying castles: step into Ghibli's worlds.","emoji":"\ud83c\udf43","gradient":["#15803d","#0369a1"],"categories":["anime","movies"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":276,"items":[{"k":"choice","i":"Which famous director co-founded Studio Ghibli with Isao Takahata and Toshio Suzuki?","t":"Founders","e":"\ud83c\udfa8","f":"The name 'Ghibli' comes from an Italian word for a hot wind that blows across the Sahara.","o":["Hayao Miyazaki","Mamoru Hosoda","Makoto Shinkai","Satoshi Kon"],"s":{"index":0}},{"k":"choice","i":"In 'My Neighbor Totoro' (1988), what magical vehicle do the sisters ride?","t":"Totoro","e":"\ud83d\ude8c","f":"Totoro later became the studio's logo.","o":["A dragon train","A Catbus","A flying broom","A paper boat"],"s":{"index":1}},{"k":"choice","i":"In 'Kiki's Delivery Service' (1989), what is the name of Kiki's black cat?","t":"Kiki","e":"\ud83d\udc08\u200d\u2b1b","f":"Kiki is a young witch who starts a flying delivery service on her broom.","o":["Jiji","Luna","Haku","Teto"],"s":{"index":0}},{"k":"choice","i":"In 'Spirited Away', what happens to Chihiro's parents?","t":"Spirited Away","e":"\ud83d\udc37","f":"They are transformed after greedily eating food meant for the spirits.","o":["They fall asleep","They turn to stone","They turn into pigs","They shrink"],"s":{"index":2}},{"k":"choice","i":"In 'Ponyo' (2008), what does the little fish Ponyo want to become?","t":"Ponyo","e":"\ud83d\udc1f","f":"Ponyo was inspired in part by Hans Christian Andersen's 'The Little Mermaid'.","o":["A bird","A human girl","A mermaid queen","A dragon"],"s":{"index":1}},{"k":"choice","i":"In which city is the Ghibli Museum located?","t":"Places","e":"\ud83c\udfdb\ufe0f","f":"The museum, designed by Hayao Miyazaki, opened in 2001.","o":["Kyoto","Osaka","Nagoya","Mitaka (Tokyo)"],"s":{"index":3}},{"k":"number","i":"In what year was Studio Ghibli founded?","t":"History","e":"\ud83d\udcc5","f":"Ghibli's first official film was 'Castle in the Sky' in 1986.","s":{"value":1985,"tolerance":0,"min":1970,"max":2000,"unit":""}},{"k":"truefalse","i":"'Spirited Away' won the Golden Bear, the top prize at the Berlin International Film Festival.","t":"Awards","e":"\ud83d\udc3b","f":"It shared the 2002 Golden Bear, a rare honour for an animated film.","a":true},{"k":"truefalse","i":"'Nausica\u00e4 of the Valley of the Wind' (1984) was released before Studio Ghibli was founded.","t":"History","e":"\ud83c\udf2c\ufe0f","f":"Its success led directly to the founding of Studio Ghibli.","a":true},{"k":"text","i":"In 'Howl's Moving Castle', what is the name of the fire demon who powers the castle?","t":"Howl","e":"\ud83d\udd25","f":"Calcifer was voiced by Billy Crystal in the English dub.","s":{"accepted":["Calcifer"]}},{"k":"text","i":"In 'Castle in the Sky' (1986), what is the name of the floating castle?","t":"Castle in the Sky","e":"\ud83c\udff0","f":"The name is borrowed from the flying island in Jonathan Swift's 'Gulliver's Travels'.","s":{"accepted":["Laputa"]}},{"k":"multi","i":"Select all the films directed by Hayao Miyazaki.","t":"Miyazaki","e":"\ud83c\udfac","f":"Your Name is by Makoto Shinkai, Princess Kaguya by Isao Takahata and Akira by Katsuhiro Otomo.","o":["Spirited Away","Your Name","Princess Mononoke","The Tale of the Princess Kaguya","Ponyo","Akira"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these Studio Ghibli films from oldest to newest.","t":"Timeline","e":"\ud83c\udf9e\ufe0f","f":"They were released in 1988, 1989, 1997, 2001 and 2008.","o":["My Neighbor Totoro","Kiki's Delivery Service","Princess Mononoke","Spirited Away","Ponyo"]}]},{"slug":"car-brand-passport","title":"Where's That Car From?","tagline":"\u0160koda, Kia, Volvo, Fiat: match the badges to their home countries.","emoji":"\ud83d\ude97","gradient":["#0f766e","#1d4ed8"],"categories":["cars","geo","brands"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":277,"items":[{"k":"choice","i":"\u0160koda cars come from which country?","t":"Europe","e":"\ud83d\ude97","f":"\u0160koda's story began in 1895 in Mlad\u00e1 Boleslav, when Laurin & Klement started out making bicycles.","o":["Poland","Czech Republic","Hungary","Slovakia"],"s":{"index":1}},{"k":"choice","i":"Kia and Hyundai are car makers from which country?","t":"Asia","e":"\ud83d\ude99","f":"The name Hyundai means 'modern' in Korean.","o":["Japan","China","South Korea","Taiwan"],"s":{"index":2}},{"k":"choice","i":"Which car brand's name stands for 'Fabbrica Italiana Automobili Torino'?","t":"Italy","e":"\ud83d\ude98","f":"Fiat was founded in Turin in 1899.","o":["Ferrari","Alfa Romeo","Lancia","Fiat"],"s":{"index":3}},{"k":"choice","i":"Dacia, maker of affordable cars like the Duster, comes from which country?","t":"Europe","e":"\ud83d\ude90","f":"Dacia is named after the ancient region that covered much of present-day Romania; Renault has owned it since 1999.","o":["Romania","Bulgaria","Serbia","Croatia"],"s":{"index":0}},{"k":"choice","i":"The six stars on Subaru's badge represent which star cluster?","t":"Japan","e":"\u2728","f":"'Subaru' is the Japanese name for the Pleiades star cluster.","o":["Orion's Belt","The Big Dipper","The Pleiades","The Southern Cross"],"s":{"index":2}},{"k":"choice","i":"Koenigsegg, a maker of hypercars, is based in which country?","t":"Supercars","e":"\ud83c\udfc1","f":"Koenigsegg builds its cars in former fighter-jet hangars near \u00c4ngelholm in southern Sweden.","o":["Sweden","Italy","Croatia","Netherlands"],"s":{"index":0}},{"k":"choice","i":"SEAT and Cupra cars come from which country?","t":"Spain","e":"\u2600\ufe0f","f":"SEAT was founded in 1950 and is based in Martorell, near Barcelona.","o":["Portugal","Spain","Mexico","Italy"],"s":{"index":1}},{"k":"truefalse","i":"Ferrari is based in Maranello, Italy.","t":"Italy","e":"\ud83d\udc0e","f":"The first car to carry the Ferrari name, the 125 S, was built in Maranello in 1947.","a":true},{"k":"truefalse","i":"Peugeot is a British car brand.","t":"France","e":"\ud83e\udd81","f":"Peugeot is French; the family business started out making tools, coffee grinders and pepper mills.","a":false},{"k":"multi","i":"Select all the car brands that come from the United Kingdom.","t":"Britain","e":"\ud83c\udfce\ufe0f","f":"McLaren's headquarters is in Woking, England.","o":["Aston Martin","Renault","McLaren","Mini","Citro\u00ebn"],"s":{"indices":[0,2,3]}},{"k":"text","i":"Toyota, Honda, Mazda and Nissan all come from which country?","t":"Japan","e":"\ud83d\uddfe","f":"Toyota started out as part of a company that made automatic looms for weaving cloth.","s":{"accepted":["Japan","Nippon"]}},{"k":"number","i":"In what year did the first Volvo car roll out of the factory?","t":"Sweden","e":"\ud83d\udcc5","f":"The first Volvo, the \u00d6V4, nicknamed 'Jakob', left the factory in Gothenburg on 14 April 1927.","s":{"value":1927,"tolerance":0,"min":1880,"max":2000,"unit":""}},{"k":"order","i":"Order these brands' home cities from north to south.","t":"Geography","e":"\ud83e\udded","f":"Gothenburg, Volvo's home, is Sweden's second-largest city.","o":["Volvo (Gothenburg)","\u0160koda (Mlad\u00e1 Boleslav)","Fiat (Turin)","SEAT (Martorell)"]}]},{"slug":"stars-and-stripes-story","title":"Stars & Stripes Story","tagline":"Founders, moon landings and gold rushes: America's history in one quiz.","emoji":"\ud83c\uddfa\ud83c\uddf8","gradient":["#1d4ed8","#b91c1c"],"categories":["history","culture"],"countries":["US"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":278,"items":[{"k":"number","i":"In what year was the US Declaration of Independence adopted?","t":"Founding","e":"\ud83d\udcdc","f":"It was adopted on 4 July 1776, which is why Americans celebrate Independence Day on the Fourth of July.","s":{"value":1776,"tolerance":0,"min":1700,"max":1850,"unit":""}},{"k":"choice","i":"Who was the first President of the United States?","t":"Presidents","e":"\ud83c\udf96\ufe0f","f":"George Washington is the only US president to have been elected unanimously by the Electoral College.","o":["Benjamin Franklin","George Washington","John Adams","Thomas Jefferson"],"s":{"index":1}},{"k":"choice","i":"Which president is carved on Mount Rushmore alongside Washington, Jefferson and Theodore Roosevelt?","t":"Landmarks","e":"\ud83d\uddff","f":"Each face on Mount Rushmore is about 18 m tall, and the carving took 14 years, from 1927 to 1941.","o":["Abraham Lincoln","Franklin D. Roosevelt","Ulysses S. Grant","John F. Kennedy"],"s":{"index":0}},{"k":"truefalse","i":"The Statue of Liberty was a gift from France.","t":"Landmarks","e":"\ud83d\uddfd","f":"Designed by Fr\u00e9d\u00e9ric Auguste Bartholdi, with an iron frame by Gustave Eiffel, it was dedicated in 1886.","a":true},{"k":"choice","i":"Which mission first landed humans on the Moon in 1969?","t":"Space","e":"\ud83d\ude80","f":"Neil Armstrong and Buzz Aldrin walked on the Moon while Michael Collins orbited above in the command module.","o":["Apollo 11","Apollo 8","Gemini 4","Apollo 13"],"s":{"index":0}},{"k":"order","i":"Order these events in US history from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"The first transcontinental railroad was completed in 1869 with a ceremonial golden spike in Utah.","o":["Declaration of Independence","California Gold Rush","First transcontinental railroad completed","Wright brothers' first powered flight"]},{"k":"text","i":"Which US state did the United States buy from Russia in 1867?","t":"Geography","e":"\ud83d\udc3b","f":"The US paid $7.2 million for Alaska, roughly two cents per acre.","s":{"accepted":["Alaska"]}},{"k":"choice","i":"Which city was the first capital of the United States under the Constitution?","t":"Founding","e":"\ud83c\udfd9\ufe0f","f":"George Washington took his oath of office at Federal Hall in New York City in 1789.","o":["New York City","Washington, D.C.","Philadelphia","Boston"],"s":{"index":0}},{"k":"multi","i":"Select all the people who served as US president.","t":"Presidents","e":"\ud83c\udfdb\ufe0f","f":"Benjamin Franklin and Alexander Hamilton appear on US banknotes even though neither was ever president.","o":["Theodore Roosevelt","Abraham Lincoln","Alexander Hamilton","Thomas Edison","Benjamin Franklin"],"s":{"indices":[0,1]}},{"k":"choice","i":"How many stars are on the US flag today?","t":"Symbols","e":"\u2b50","f":"The 50-star flag has flown since 1960, the year after Hawaii became the 50th state.","o":["13","48","49","50"],"s":{"index":3}},{"k":"choice","i":"Which famous gold rush began after gold was found at Sutter's Mill in 1848?","t":"Gold Rush","e":"\u26cf\ufe0f","f":"So many people arrived in 1849 that the gold seekers became known as 'forty-niners'.","o":["California Gold Rush","Black Hills Gold Rush","Klondike Gold Rush","Colorado Gold Rush"],"s":{"index":0}},{"k":"truefalse","i":"The Wright brothers made their first powered flight in Ohio.","t":"Inventors","e":"\u2708\ufe0f","f":"Their first flight took place near Kitty Hawk, North Carolina, in 1903; the brothers lived in Dayton, Ohio.","a":false},{"k":"choice","i":"Who invented the phonograph and ran a famous laboratory at Menlo Park, New Jersey?","t":"Inventors","e":"\ud83d\udca1","f":"Edison was nicknamed 'The Wizard of Menlo Park' and held more than 1,000 US patents.","o":["Henry Ford","Nikola Tesla","Thomas Edison","Alexander Graham Bell"],"s":{"index":2}},{"k":"number","i":"How many original colonies joined together to form the United States?","t":"Founding","e":"\ud83c\uddfa\ud83c\uddf8","f":"The 13 stripes on the US flag represent the original colonies.","s":{"value":13,"tolerance":0,"min":1,"max":30,"unit":""}}]},{"slug":"animal-record-breakers","title":"Animal Record Breakers","tagline":"The fastest, biggest and longest-lived creatures on Earth.","emoji":"\ud83d\udc06","gradient":["#16a34a","#b45309"],"categories":["nature","kids"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":279,"items":[{"k":"choice","i":"What is the fastest land animal?","t":"Speed","e":"\ud83d\udc06","f":"Cheetahs can sprint at around 100 km/h, but only in short bursts.","o":["Lion","Cheetah","Pronghorn","Greyhound"],"s":{"index":1}},{"k":"choice","i":"What is the largest animal living today?","t":"Size","e":"\ud83d\udc0b","f":"Blue whales can grow to about 30 m long.","o":["African elephant","Whale shark","Blue whale","Giraffe"],"s":{"index":2}},{"k":"text","i":"What is the tallest living animal?","t":"Size","e":"\ud83e\udd92","f":"A giraffe's neck has seven vertebrae, the same number as a human's.","s":{"accepted":["Giraffe","Giraffes","The giraffe"]}},{"k":"choice","i":"Which bird is the fastest animal on Earth when diving?","t":"Speed","e":"\ud83e\udd85","f":"Peregrine falcons have been measured diving at more than 300 km/h.","o":["Golden eagle","Albatross","Swift","Peregrine falcon"],"s":{"index":3}},{"k":"multi","i":"Select all the animals that can live for more than 100 years.","t":"Lifespan","e":"\ud83d\udc22","f":"Greenland sharks may live for around 400 years, making them the longest-lived vertebrates known.","o":["Greenland shark","Giant tortoise","House cat","Bowhead whale","Horse"],"s":{"indices":[0,1,3]}},{"k":"number","i":"How many hearts does an octopus have?","t":"Anatomy","e":"\ud83d\udc19","f":"Two of an octopus's hearts pump blood through the gills, while the third pumps it around the body.","s":{"value":3,"tolerance":0,"min":1,"max":8,"unit":"hearts"}},{"k":"order","i":"Order these animals from fastest to slowest top running speed.","t":"Speed","e":"\ud83c\udfc3","f":"Elite human sprinters reach top speeds of about 44 km/h.","o":["Racehorse","Grizzly bear","Human sprinter","Chicken","Garden snail"]},{"k":"choice","i":"Which animal has the largest eyes of any known animal?","t":"Senses","e":"\ud83d\udc41\ufe0f","f":"The colossal squid's eyes can be about 27 cm across, roughly the size of a dinner plate.","o":["Colossal squid","Blue whale","Ostrich","Tarsier"],"s":{"index":0}},{"k":"truefalse","i":"The world's smallest bird is a species of hummingbird.","t":"Size","e":"\ud83d\udc26","f":"The bee hummingbird of Cuba is only about 5 to 6 cm long.","a":true},{"k":"choice","i":"Which animal makes the longest yearly migration?","t":"Migration","e":"\ud83d\udd4a\ufe0f","f":"An Arctic tern can fly more than 70,000 km a year, travelling between the Arctic and the Antarctic.","o":["Monarch butterfly","Arctic tern","Humpback whale","Wildebeest"],"s":{"index":1}},{"k":"text","i":"What is the largest species of big cat?","t":"Size","e":"\ud83d\udc05","f":"Siberian (Amur) tigers can weigh up to about 300 kg.","s":{"accepted":["Tiger","Tigers","The tiger","Siberian tiger","Amur tiger","Bengal tiger"]}},{"k":"choice","i":"What is the largest living reptile?","t":"Size","e":"\ud83d\udc0a","f":"Male saltwater crocodiles can grow to more than 6 m long.","o":["Komodo dragon","Green anaconda","Saltwater crocodile","Leatherback turtle"],"s":{"index":2}},{"k":"order","i":"Order these animals from heaviest to lightest.","t":"Size","e":"\u2696\ufe0f","f":"A male African bush elephant can weigh around 6 tonnes, making it the heaviest land animal.","o":["Blue whale","African elephant","Hippopotamus","Polar bear","Human"]}]},{"slug":"mental-math-sprint","title":"Mental Math Sprint","tagline":"No calculators allowed. Percentages, powers and quick sums against the clock.","emoji":"\ud83e\uddee","gradient":["#e11d48","#f97316"],"categories":["math"],"countries":null,"difficulty":"Medium","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":280,"items":[{"k":"number","i":"What is 15% of 240?","t":"Percentages","e":"\ud83d\udcaf","f":"10% of 240 is 24 and 5% is 12, so 15% is 24 + 12 = 36.","s":{"value":36,"tolerance":0,"min":0,"max":240,"unit":""}},{"k":"number","i":"What is 12 \u00d7 12?","t":"Multiplication","e":"\u2716\ufe0f","f":"144 is also called a 'gross', an old counting unit equal to a dozen dozens.","s":{"value":144,"tolerance":0,"min":0,"max":300,"unit":""}},{"k":"number","i":"What is the square root of 169?","t":"Roots","e":"\ud83c\udf31","f":"13 \u00d7 13 = 169. Squares are worth memorising: 11\u00b2 = 121, 12\u00b2 = 144, 14\u00b2 = 196.","s":{"value":13,"tolerance":0,"min":0,"max":50,"unit":""}},{"k":"number","i":"What is 1,000 \u2212 387?","t":"Subtraction","e":"\u2796","f":"Shortcut: 999 \u2212 387 = 612, then add 1 to get 613.","s":{"value":613,"tolerance":0,"min":0,"max":1000,"unit":""}},{"k":"number","i":"What is 25 \u00d7 16?","t":"Multiplication","e":"\u26a1","f":"Since 25 \u00d7 4 = 100, 25 \u00d7 16 is just 4 lots of 100.","s":{"value":400,"tolerance":0,"min":0,"max":1000,"unit":""}},{"k":"choice","i":"Which of these is the largest?","t":"Fractions","e":"\u2696\ufe0f","f":"3/5 = 0.6 and 5/8 = 0.625, so 0.65 wins by a nose.","o":["3/5","0.65","5/8","0.62"],"s":{"index":1}},{"k":"number","i":"What is 2 to the power of 10?","t":"Powers","e":"\ud83d\udcbe","f":"That's why a kilobyte was traditionally counted as 1,024 bytes.","s":{"value":1024,"tolerance":0,"min":0,"max":2000,"unit":""}},{"k":"truefalse","i":"50% of 80 is the same as 80% of 50.","t":"Percentages","e":"\ud83d\udd01","f":"x% of y always equals y% of x, a handy trick: 4% of 75 equals 75% of 4, which is 3.","a":true},{"k":"order","i":"Order these values from smallest to largest.","t":"Comparing","e":"\ud83d\udccf","f":"0.09, then 1/10 = 0.1, then 12% = 0.12, then 0.2.","o":["0.09","1/10","12%","0.2"]},{"k":"multi","i":"Select all the prime numbers.","t":"Primes","e":"\ud83d\udd10","f":"51 looks prime but is 3 \u00d7 17, 21 is 3 \u00d7 7, and 1 is not counted as a prime number.","o":["51","2","29","21","1","17"],"s":{"indices":[1,2,5]}},{"k":"number","i":"A \u20ac40 shirt is reduced by 25%. What is its new price?","t":"Percentages","e":"\ud83c\udff7\ufe0f","f":"25% of 40 is 10, so the shirt now costs 30.","s":{"value":30,"tolerance":0,"min":0,"max":40,"unit":"\u20ac"}},{"k":"choice","i":"What is 9 + 9 \u00d7 9?","t":"Order of operations","e":"\ud83e\udde0","f":"Multiplication comes first: 9 \u00d7 9 = 81, then add 9 to get 90.","o":["90","162","99","81"],"s":{"index":0}},{"k":"number","i":"How many seconds are there in one hour?","t":"Time","e":"\u23f1\ufe0f","f":"60 seconds \u00d7 60 minutes = 3,600, and a full day has 86,400 seconds.","s":{"value":3600,"tolerance":0,"min":0,"max":10000,"unit":"s"}},{"k":"order","i":"Order these products from smallest to largest.","t":"Multiplication","e":"\ud83d\udcf6","f":"40, 42, 44 and 45: close together, but only one right order.","o":["8 \u00d7 5","6 \u00d7 7","4 \u00d7 11","5 \u00d7 9"]}]},{"slug":"manga-lingo-legends","title":"Manga Lingo & Legends","tagline":"Mangaka, chibi, otaku: speak fluent anime fan and name the legends.","emoji":"\u270d\ufe0f","gradient":["#e11d48","#4f46e5"],"categories":["anime","language"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":281,"items":[{"k":"choice","i":"What is a 'mangaka'?","t":"Terms","e":"\ud83d\udd8b\ufe0f","f":"Many mangaka work with a team of assistants to meet weekly deadlines.","o":["A manga artist","A manga shop","A voice actor","A comic convention"],"s":{"index":0}},{"k":"choice","i":"'Sh\u014dnen' manga is traditionally aimed at which readers?","t":"Genres","e":"\ud83d\udc66","f":"Sh\u014dnen series often focus on action, friendship and never giving up.","o":["Young girls","Teenage boys","Adult women","Toddlers"],"s":{"index":1}},{"k":"choice","i":"In which direction are traditional Japanese manga read?","t":"Reading","e":"\ud83d\udcd6","f":"That means a manga book starts from what Western readers think of as the back.","o":["Left to right","Bottom to top","Right to left","Center outward"],"s":{"index":2}},{"k":"choice","i":"What does the Japanese word 'kawaii' mean?","t":"Terms","e":"\ud83e\udd70","f":"Kawaii culture is behind famous characters like Hello Kitty.","o":["Scary","Funny","Strong","Cute"],"s":{"index":3}},{"k":"choice","i":"The word 'cosplay' is a blend of which two English words?","t":"Terms","e":"\ud83d\udc58","f":"In Japanese the word is 'kosupure', and cosplayers dress up as their favourite characters.","o":["Costume and play","Cosmic and display","Comic and roleplay","Cosmetics and playground"],"s":{"index":0}},{"k":"choice","i":"Which manga artist created 'Ranma \u00bd' and 'Inuyasha'?","t":"Creators","e":"\ud83d\udc3e","f":"Rumiko Takahashi is one of the best-selling female comic artists in history.","o":["Naoko Takeuchi","CLAMP","Osamu Tezuka","Rumiko Takahashi"],"s":{"index":3}},{"k":"number","i":"How many episodes did the original 'Neon Genesis Evangelion' TV series (1995\u201396) have?","t":"Evangelion","e":"\ud83e\udd16","f":"The series was created by Hideaki Anno at the studio Gainax.","s":{"value":26,"tolerance":0,"min":10,"max":60,"unit":""}},{"k":"truefalse","i":"'Sh\u014djo' manga is traditionally aimed at teenage girls.","t":"Genres","e":"\ud83d\udc67","f":"'Sh\u014djo' simply means 'young girl' in Japanese.","a":true},{"k":"truefalse","i":"Akira Toriyama, creator of 'Dragon Ball', also designed the characters for the 'Dragon Quest' games.","t":"Creators","e":"\ud83d\udc09","f":"His cheerful art style has been part of Dragon Quest since the first game in 1986.","a":true},{"k":"text","i":"What word describes the cute art style where characters are drawn small with big heads?","t":"Terms","e":"\ud83e\uddf8","f":"'Chibi' is Japanese slang for a short person or small child.","s":{"accepted":["Chibi"]}},{"k":"text","i":"What Japanese word is used for a devoted fan, especially of anime and manga?","t":"Terms","e":"\ud83c\udf8c","f":"Tokyo's Akihabara district is famous as a paradise for otaku.","s":{"accepted":["Otaku"]}},{"k":"multi","i":"Select all the series that are sh\u014dnen manga.","t":"Genres","e":"\ud83d\udca5","f":"Sailor Moon and Cardcaptor Sakura are classic sh\u014djo series, both first published in Nakayoshi magazine.","o":["Dragon Ball","Sailor Moon","Naruto","Cardcaptor Sakura","One Piece"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these manga creators by year of birth, earliest first.","t":"Creators","e":"\ud83c\udf82","f":"Tezuka was born in 1928, Toriyama in 1955, Takahashi in 1957 and Oda in 1975.","o":["Osamu Tezuka","Akira Toriyama","Rumiko Takahashi","Eiichiro Oda"]}]},{"slug":"legendary-car-models","title":"Legendary Car Models","tagline":"Model T, Beetle, Mini and Mustang: rev up your car history knowledge.","emoji":"\ud83c\udfce\ufe0f","gradient":["#b91c1c","#1e3a8a"],"categories":["cars","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":282,"items":[{"k":"choice","i":"Which car, built from 1908 to 1927, 'put America on wheels'?","t":"USA","e":"\ud83d\ude97","f":"Ford's moving assembly line, introduced in 1913, cut Model T build time from over 12 hours to about 1.5 hours.","o":["Ford Model T","Chevrolet Bel Air","Cadillac Eldorado","Dodge Charger"],"s":{"index":0}},{"k":"choice","i":"Who is credited with building the first practical petrol-powered car in 1886?","t":"Pioneers","e":"\ud83d\udee0\ufe0f","f":"In 1888, Bertha Benz drove the Patent-Motorwagen about 106 km to show the world that it worked.","o":["Henry Ford","Karl Benz","Gottlieb Daimler","Ferdinand Porsche"],"s":{"index":1}},{"k":"choice","i":"The original Mini, launched in 1959, was designed by whom?","t":"Britain","e":"\ud83d\ude99","f":"Its sideways-mounted engine left 80% of the car's floor space for passengers and luggage.",