ink contains melanin, the same pigment found in human skin and hair.","o":["Jellyfish","Sea turtle","Squid","Crab"],"s":{"index":2}},{"k":"choice","i":"What is the name of the warm ocean current that flows from the Gulf of Mexico across the Atlantic?","t":"Currents","e":"\ud83c\udf21\ufe0f","f":"The Gulf Stream helps keep Western Europe milder than other places at similar latitudes.","o":["Gulf Stream","Humboldt Current","Kuroshio Current","Canary Current"],"s":{"index":0}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'c3fcb2bbc4ca284eae8eafdddcceabe9' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse