do $q$ declare d text := $d$[{"slug":"sequence-sleuth","title":"Sequence Sleuth","tagline":"Spot the pattern, crack the code: what comes next?","emoji":"\ud83d\udd22","gradient":["#0d9488","#2563eb"],"categories":["math","puzzles"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":285,"items":[{"k":"number","i":"What comes next? 2, 4, 8, 16, \u2026","t":"Doubling","e":"\u270c\ufe0f","f":"Each number doubles: these are the powers of two.","s":{"value":32,"tolerance":0,"min":0,"max":100,"unit":""}},{"k":"number","i":"What comes next? 1, 1, 2, 3, 5, 8, 13, \u2026","t":"Fibonacci","e":"\ud83d\udc1a","f":"The Fibonacci sequence: each number is the sum of the two before it.","s":{"value":21,"tolerance":0,"min":0,"max":50,"unit":""}},{"k":"multi","i":"Select all the square numbers.","t":"Squares","e":"\u2b1b","f":"49 = 7\u00b2, 64 = 8\u00b2 and 81 = 9\u00b2; 50 and 90 fall between square numbers.","o":["64","49","50","90","81"],"s":{"indices":[0,1,4]}},{"k":"number","i":"What comes next? 2, 3, 5, 7, 11, \u2026","t":"Primes","e":"\ud83d\udd10","f":"These are the prime numbers, divisible only by 1 and themselves.","s":{"value":13,"tolerance":0,"min":0,"max":50,"unit":""}},{"k":"number","i":"What comes next? 1, 3, 6, 10, 15, 21, \u2026","t":"Triangular numbers","e":"\ud83d\udd3a","f":"Add 2, then 3, then 4 and so on. These triangular numbers are how bowling pins are arranged.","s":{"value":28,"tolerance":0,"min":0,"max":60,"unit":""}},{"k":"number","i":"What comes next? 1, 8, 27, 64, \u2026","t":"Cubes","e":"\ud83e\uddca","f":"These are cube numbers: 1\u00b3, 2\u00b3, 3\u00b3, 4\u00b3, so next is 5\u00b3 = 125.","s":{"value":125,"tolerance":0,"min":0,"max":200,"unit":""}},{"k":"number","i":"What comes next? 100, 90, 81, 73, \u2026","t":"Shrinking steps","e":"\ud83d\udcc9","f":"Subtract 10, then 9, then 8, then 7.","s":{"value":66,"tolerance":0,"min":0,"max":100,"unit":""}},{"k":"choice","i":"What comes next? 3, 6, 12, 24, \u2026","t":"Doubling","e":"\ud83d\udd01","f":"Each term is double the one before it.","o":["36","48","30","42"],"s":{"index":1}},{"k":"choice","i":"Which letter comes next? A, C, E, G, \u2026","t":"Letters","e":"\ud83d\udd24","f":"Skip one letter each time: A (b) C (d) E (f) G (h) I.","o":["H","I","J","K"],"s":{"index":1}},{"k":"text","i":"Which letter comes next? O, T, T, F, F, S, S, E, \u2026","t":"Letters","e":"\ud83d\udd75\ufe0f","f":"They're the first letters of One, Two, Three, Four, Five, Six, Seven, Eight, so Nine comes next.","s":{"accepted":["N"]}},{"k":"text","i":"Which letter comes next? J, F, M, A, M, J, J, \u2026","t":"Letters","e":"\ud83d\udcc5","f":"They're the first letters of the months, January to July, so August comes next.","s":{"accepted":["A"]}},{"k":"order","i":"Order these from smallest to largest.","t":"Powers","e":"\ud83d\udcf6","f":"2\u00b3 = 8, 3\u00b2 = 9, 2\u2074 = 16, 5\u00b2 = 25 and 3\u00b3 = 27.","o":["2\u00b3","3\u00b2","2\u2074","5\u00b2","3\u00b3"]},{"k":"truefalse","i":"In the sequence 1, 2, 4, 7, 11, 16, the gap grows by one each step.","t":"Growing steps","e":"\ud83e\ude9c","f":"The gaps are 1, 2, 3, 4, 5, so the next number would be 16 + 6 = 22.","a":true},{"k":"multi","i":"Select all the numbers that appear in the Fibonacci sequence.","t":"Fibonacci","e":"\ud83c\udf3b","f":"\u202621, 34, 55, 89, 144\u2026 The ratio between neighbours gets closer and closer to the golden ratio, about 1.618.","o":["50","89","55","34","70"],"s":{"indices":[1,2,3]}}]},{"slug":"internet-origins","title":"Internet Origins","tagline":"From CERN's first web page to the first YouTube video: how did it all begin?","emoji":"\ud83c\udf10","gradient":["#0284c7","#4338ca"],"categories":["popculture","tech","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":286,"items":[{"k":"choice","i":"Who invented the World Wide Web?","t":"Web Pioneers","e":"\ud83e\uddd1\u200d\ud83d\udcbb","f":"Tim Berners-Lee proposed the web in 1989 while working at CERN.","o":["Vint Cerf","Bill Gates","Steve Jobs","Tim Berners-Lee"],"s":{"index":3}},{"k":"choice","i":"At which research centre was the world's first website created?","t":"First Website","e":"\ud83d\udd2c","f":"The first website, at info.cern.ch, explained what the World Wide Web was and how to use it.","o":["MIT","CERN","Stanford University","NASA"],"s":{"index":1}},{"k":"choice","i":"What was the title of the very first video uploaded to YouTube in 2005?","t":"YouTube","e":"\ud83d\udc18","f":"The 19-second clip shows co-founder Jawed Karim in front of the elephants at San Diego Zoo.","o":["Hello World","My First Vlog","Me at the zoo","Charlie Bit My Finger"],"s":{"index":2}},{"k":"choice","i":"At which university was Facebook launched by students?","t":"Social Media","e":"\ud83c\udf93","f":"It began as 'TheFacebook' and was at first open only to Harvard students.","o":["Stanford","Yale","MIT","Harvard"],"s":{"index":3}},{"k":"choice","i":"What does 'URL' stand for?","t":"Acronyms","e":"\ud83d\udd17","f":"A URL is the address you type to visit a page on the web.","o":["Universal Resource Link","Uniform Resource Locator","Unified Reference Line","User Request Locator"],"s":{"index":1}},{"k":"choice","i":"Which 1993 web browser is credited with making the World Wide Web popular?","t":"Browsers","e":"\ud83e\udded","f":"Mosaic showed images alongside text on the same page, which made the web far more appealing.","o":["Mosaic","Netscape Navigator","Internet Explorer","Opera"],"s":{"index":0}},{"k":"choice","i":"What was the original name of the search project that became Google?","t":"Google","e":"\ud83d\udd0e","f":"Larry Page and Sergey Brin started the project as PhD students at Stanford University.","o":["Googol","BackRub","AltaSearch","PageFind"],"s":{"index":1}},{"k":"number","i":"In what year was Google founded?","t":"Google","e":"\ud83c\udfe0","f":"Google was incorporated in September 1998 and set up shop in a friend's garage in Menlo Park, California.","s":{"value":1998,"tolerance":0,"min":1990,"max":2010,"unit":""}},{"k":"truefalse","i":"Wikipedia was launched in 2001.","t":"Wikipedia","e":"\ud83d\udcda","f":"Its name combines 'wiki', from a Hawaiian word for 'quick', with 'encyclopedia'.","a":true},{"k":"truefalse","i":"The first email was sent in the 1990s.","t":"Email","e":"\ud83d\udce7","f":"Ray Tomlinson sent the first networked email in 1971 and chose the @ sign to separate user and computer.","a":false},{"k":"text","i":"What does 'WWW' stand for?","t":"Acronyms","e":"\ud83d\udd78\ufe0f","f":"The web runs on top of the internet, which existed for years before the web was invented.","s":{"accepted":["World Wide Web","The World Wide Web"]}},{"k":"multi","i":"Select all the companies that were founded in the 1990s.","t":"Founding Years","e":"\ud83c\udfe2","f":"Amazon was founded in 1994, eBay in 1995 and Netflix in 1997, which started by mailing DVDs.","o":["Amazon","Facebook","eBay","YouTube","Netflix","Twitter"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these platforms by launch year, oldest first.","t":"Timeline","e":"\ud83d\udcc5","f":"They launched in 2001, 2004, 2005, 2006 and 2010.","o":["Wikipedia","Facebook","YouTube","Twitter","Instagram"]}]},{"slug":"inventors-and-inventions","title":"Inventors & Inventions","tagline":"From printing presses to QR codes: who dreamed up the tech we use?","emoji":"\ud83d\udca1","gradient":["#ea580c","#7e22ce"],"categories":["tech","history","science"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":287,"items":[{"k":"choice","i":"Who was granted the first US patent for the telephone in 1876?","t":"Communication","e":"\u260e\ufe0f","f":"Bell's first words on the phone to his assistant were reportedly: 'Mr. Watson, come here, I want to see you.'","o":["Thomas Edison","Alexander Graham Bell","Nikola Tesla","Samuel Morse"],"s":{"index":1}},{"k":"choice","i":"In which German city did Johannes Gutenberg print his famous Bible in the 1450s?","t":"Printing","e":"\ud83d\udcdc","f":"The Gutenberg Bible, finished around 1455, was one of the first major books in Europe printed with movable metal type.","o":["Mainz","Munich","Hamburg","Cologne"],"s":{"index":0}},{"k":"choice","i":"Which Hungarian inventor created the ballpoint pen, patented in 1938?","t":"Everyday objects","e":"\ud83d\udd8a\ufe0f","f":"In many countries people still call a ballpoint pen a 'biro' after him.","o":["Ern\u0151 Rubik","L\u00e1szl\u00f3 B\u00edr\u00f3","John von Neumann","Le\u00f3 Szil\u00e1rd"],"s":{"index":1}},{"k":"choice","i":"Engineer Percy Spencer invented the microwave oven after noticing what had melted in his pocket?","t":"Kitchen","e":"\ud83c\udf6b","f":"Spencer was working on radar equipment; the first commercial microwave oven stood nearly 1.8 m tall.","o":["A chocolate bar","An ice cube","A candle","A crayon"],"s":{"index":0}},{"k":"choice","i":"The QR code was invented in 1994 in which country, originally to track car parts?","t":"Codes","e":"\ud83d\udcf1","f":"Masahiro Hara of Denso Wave was inspired by the black and white stones of the board game Go.","o":["South Korea","USA","Japan","Germany"],"s":{"index":2}},{"k":"choice","i":"Who invented the phonograph in 1877, a machine that could record sound and play it back?","t":"Sound","e":"\ud83c\udf99\ufe0f","f":"The first words Edison recorded were from the nursery rhyme 'Mary Had a Little Lamb'.","o":["Emile Berliner","Guglielmo Marconi","Louis Daguerre","Thomas Edison"],"s":{"index":3}},{"k":"choice","i":"Who made the first controlled, powered aeroplane flight in 1903?","t":"Flight","e":"\u2708\ufe0f","f":"Their first flight at Kitty Hawk, North Carolina, on 17 December 1903 lasted just 12 seconds.","o":["Otto Lilienthal","The Montgolfier brothers","The Wright brothers","Louis Bl\u00e9riot"],"s":{"index":2}},{"k":"truefalse","i":"The Rubik's Cube was invented by a Hungarian architecture professor.","t":"Puzzles","e":"\ud83e\uddca","f":"Ern\u0151 Rubik first called it the 'Magic Cube'; it was renamed Rubik's Cube in 1980.","a":true},{"k":"truefalse","i":"The first photograph ever taken was in colour.","t":"Photography","e":"\ud83d\udcf7","f":"The oldest surviving camera photograph, by Nic\u00e9phore Ni\u00e9pce around 1826, needed an exposure of many hours.","a":false},{"k":"multi","i":"Select all the inventions created in the 20th century.","t":"Timeline","e":"\ud83d\udd70\ufe0f","f":"The 20th century also gave us the transistor, invented at Bell Labs in 1947.","o":["Ballpoint pen","Telephone","QR code","Printing press","Microwave oven"],"s":{"indices":[0,2,4]}},{"k":"text","i":"Which Swedish chemist invented dynamite and left his fortune to fund a set of famous prizes?","t":"Inventors","e":"\ud83c\udfc5","f":"Alfred Nobel patented dynamite in 1867, and the first Nobel Prizes were awarded in 1901.","s":{"accepted":["Alfred Nobel","Nobel"]}},{"k":"number","i":"In what year did Ern\u0151 Rubik create his famous cube?","t":"Puzzles","e":"\ud83e\udde9","f":"The cube went on sale worldwide in 1980 and became one of the best-selling toys of all time.","s":{"value":1974,"tolerance":1,"min":1900,"max":2020,"unit":""}},{"k":"order","i":"Order these inventions from oldest to newest.","t":"Timeline","e":"\u23f3","f":"More than 500 years separate Gutenberg's press from the invention of the QR code.","o":["Gutenberg's printing press","Edison's phonograph","B\u00edr\u00f3's ballpoint pen","The QR code"]}]},{"slug":"oh-canada","title":"Oh, Canada!","tagline":"Maple syrup, moose and mighty mountains: explore the True North.","emoji":"\ud83c\udde8\ud83c\udde6","gradient":["#dc2626","#9f1239"],"categories":["geo","culture"],"countries":["CA"],"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":288,"items":[{"k":"choice","i":"What is the capital of Canada?","t":"Capitals","e":"\ud83c\udfdb\ufe0f","f":"Queen Victoria chose Ottawa as the capital in 1857, partly as a compromise between English and French Canada.","o":["Vancouver","Montreal","Toronto","Ottawa"],"s":{"index":3}},{"k":"choice","i":"Which leaf appears on Canada's flag?","t":"Symbols","e":"\ud83c\udf41","f":"The red leaf on Canada's flag is a stylised maple leaf with 11 points.","o":["Maple","Birch","Pine","Oak"],"s":{"index":0}},{"k":"number","i":"How many provinces does Canada have?","t":"Government","e":"\ud83d\uddfa\ufe0f","f":"Canada has 10 provinces and 3 territories: Yukon, the Northwest Territories and Nunavut.","s":{"value":10,"tolerance":0,"min":1,"max":20,"unit":""}},{"k":"truefalse","i":"Canada has two official languages: English and French.","t":"Language","e":"\ud83d\udde3\ufe0f","f":"Quebec is the only province where French is the sole official language.","a":true},{"k":"multi","i":"Select all the Great Lakes that border Canada.","t":"Lakes","e":"\ud83c\udf0a","f":"Lake Michigan is the only Great Lake that lies entirely within the United States.","o":["Lake Erie","Lake Tahoe","Lake Michigan","Lake Ontario","Lake Superior"],"s":{"indices":[0,3,4]}},{"k":"choice","i":"Which Canadian province produces most of the world's maple syrup?","t":"Food","e":"\ud83e\udd5e","f":"Quebec makes most of the world's maple syrup and even keeps a strategic reserve of it.","o":["Ontario","Quebec","British Columbia","Nova Scotia"],"s":{"index":1}},{"k":"choice","i":"Which animal is Canada's official national animal?","t":"Symbols","e":"\ud83e\uddab","f":"The beaver became an official national symbol in 1975 and appears on Canada's five-cent coin.","o":["Beaver","Canada goose","Polar bear","Moose"],"s":{"index":0}},{"k":"text","i":"Which Canadian city hosted the 1988 Winter Olympics?","t":"Cities","e":"\u26f8\ufe0f","f":"Calgary is also famous for the Calgary Stampede, a huge rodeo held every July.","s":{"accepted":["Calgary"]}},{"k":"choice","i":"What is the name of the dish of fries topped with cheese curds and gravy?","t":"Food","e":"\ud83c\udf5f","f":"Poutine was first served in rural Quebec in the 1950s.","o":["Bannock","Tourti\u00e8re","Poutine","Nanaimo bar"],"s":{"index":2}},{"k":"order","i":"Order these Canadian cities from west to east.","t":"Cities","e":"\ud83e\udded","f":"Halifax, on the Atlantic coast, has one of the largest natural harbours in the world.","o":["Vancouver","Calgary","Winnipeg","Toronto","Halifax"]},{"k":"choice","i":"Which famous waterfall lies on the border between Ontario and New York State?","t":"Nature","e":"\ud83d\udca6","f":"Niagara Falls is made up of three waterfalls: Horseshoe Falls, American Falls and Bridal Veil Falls.","o":["Angel Falls","Montmorency Falls","Niagara Falls","Victoria Falls"],"s":{"index":2}},{"k":"truefalse","i":"Canada has the longest coastline of any country in the world.","t":"Geography","e":"\ud83c\udfdd\ufe0f","f":"Including its many islands, Canada's coastline stretches for more than 200,000 km.","a":true},{"k":"choice","i":"Which Canadian territory has a name meaning 'our land' in Inuktitut?","t":"Territories","e":"\u2744\ufe0f","f":"Nunavut was split from the Northwest Territories in 1999 and is Canada's largest province or territory by area.","o":["Yukon","Nunavut","Northwest Territories","Labrador"],"s":{"index":1}},{"k":"order","i":"Order these events in Canadian history from earliest to latest.","t":"History","e":"\ud83d\udcc5","f":"The last spike of the Canadian Pacific Railway was driven at Craigellachie, British Columbia, in 1885.","o":["Confederation of Canada","Canadian Pacific Railway completed","Maple Leaf flag adopted","Nunavut created"]}]},{"slug":"dinosaur-discovery","title":"Dino Discovery","tagline":"Roar through the Jurassic and beyond with these prehistoric puzzlers.","emoji":"\ud83e\udd96","gradient":["#65a30d","#166534"],"categories":["nature","science","kids"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":289,"items":[{"k":"choice","i":"Roughly when did the (non-bird) dinosaurs die out?","t":"Extinction","e":"\u2604\ufe0f","f":"An asteroid impact near Mexico's Yucat\u00e1n Peninsula is the leading explanation for their extinction.","o":["About 6.6 million years ago","About 66 million years ago","About 660 million years ago","About 6,600 years ago"],"s":{"index":1}},{"k":"text","i":"Which dinosaur's name means 'tyrant lizard king'?","t":"Dinosaurs","e":"\ud83e\udd96","f":"Tyrannosaurus rex had teeth up to about 30 cm long, including the root.","s":{"accepted":["Tyrannosaurus rex","Tyrannosaurus","T. rex","T rex","T-rex","Trex"]}},{"k":"truefalse","i":"Birds are living descendants of dinosaurs.","t":"Evolution","e":"\ud83d\udc26","f":"Scientists consider birds to be living dinosaurs, descended from small feathered theropods.","a":true},{"k":"choice","i":"Which dinosaur had three horns on its face and a large bony frill?","t":"Dinosaurs","e":"\ud83e\udd8f","f":"Triceratops lived at the very end of the Cretaceous period, at the same time as T. rex.","o":["Stegosaurus","Ankylosaurus","Triceratops","Brachiosaurus"],"s":{"index":2}},{"k":"order","i":"Order these geological periods from oldest to most recent.","t":"Timeline","e":"\ud83e\udea8","f":"The first dinosaurs appeared during the Triassic period, roughly 230 million years ago.","o":["Permian","Triassic","Jurassic","Cretaceous","Paleogene"]},{"k":"choice","i":"Which dinosaur had large bony plates along its back and spikes on its tail?","t":"Dinosaurs","e":"\ud83e\udd95","f":"The plates on Stegosaurus's back may have been used for display or to help control body temperature.","o":["Stegosaurus","Spinosaurus","Iguanodon","Parasaurolophus"],"s":{"index":0}},{"k":"truefalse","i":"Tyrannosaurus rex lived closer in time to humans than to Stegosaurus.","t":"Timeline","e":"\u23f3","f":"Stegosaurus lived around 150 million years ago, roughly 80 million years before T. rex appeared.","a":true},{"k":"multi","i":"Select all the prehistoric reptiles that were NOT dinosaurs.","t":"Prehistoric reptiles","e":"\ud83e\udd8e","f":"Flying pterosaurs and swimming plesiosaurs lived alongside dinosaurs but belonged to separate groups of reptiles.","o":["Pteranodon","Plesiosaurus","Velociraptor","Mosasaurus","Diplodocus"],"s":{"indices":[0,1,3]}},{"k":"choice","i":"What is a scientist who studies fossils of ancient life called?","t":"Science","e":"\ud83d\udd0d","f":"Archaeologists study the human past, while paleontologists study ancient life such as dinosaurs.","o":["Archaeologist","Geologist","Anthropologist","Paleontologist"],"s":{"index":3}},{"k":"number","i":"How many fingers did Tyrannosaurus rex have on each hand?","t":"Dinosaurs","e":"\u270b","f":"T. rex's arms were only about 1 m long, but they were very muscular.","s":{"value":2,"tolerance":0,"min":1,"max":5,"unit":"fingers"}},{"k":"choice","i":"Which group of long-necked, plant-eating dinosaurs included Brachiosaurus and Diplodocus?","t":"Dinosaurs","e":"\ud83e\udd95","f":"Some sauropods were among the largest land animals ever, possibly over 30 m long.","o":["Theropods","Sauropods","Ceratopsians","Hadrosaurs"],"s":{"index":1}},{"k":"text","i":"Which feathered dinosaur, shown as human-sized in the movie 'Jurassic Park', was really about the size of a turkey?","t":"Dinosaurs","e":"\ud83c\udfac","f":"Velociraptor's name means 'swift seizer', and most of its fossils have been found in Mongolia.","s":{"accepted":["Velociraptor","Velociraptors","Raptor"]}},{"k":"choice","i":"Megalosaurus, named in 1824, was the first dinosaur to be scientifically described. Where were its fossils found?","t":"History","e":"\ud83e\uddb4","f":"The word 'dinosaur', meaning 'terrible lizard', was coined by scientist Richard Owen in 1842.","o":["United States","China","England","Argentina"],"s":{"index":2}}]},{"slug":"shape-up-geometry","title":"Shape Up","tagline":"Angles, edges and polygons: a friendly workout for your geometry brain.","emoji":"\ud83d\udcd0","gradient":["#c026d3","#4f46e5"],"categories":["math","kids"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":290,"items":[{"k":"number","i":"What do the interior angles of a triangle add up to?","t":"Angles","e":"\ud83d\udd3a","f":"Every triangle's angles add up to 180\u00b0, whatever its shape or size.","s":{"value":180,"tolerance":0,"min":0,"max":720,"unit":"\u00b0"}},{"k":"multi","i":"Select all the three-dimensional (solid) shapes.","t":"3D shapes","e":"\ud83e\uddca","f":"A circle and a square are flat, 2D shapes; their 3D cousins are the sphere and the cube.","o":["Circle","Cube","Sphere","Square","Pyramid"],"s":{"indices":[1,2,4]}},{"k":"number","i":"How many edges does a cube have?","t":"3D shapes","e":"\ud83c\udfb2","f":"A cube has 6 faces, 12 edges and 8 corners, also called vertices.","s":{"value":12,"tolerance":0,"min":0,"max":30,"unit":"edges"}},{"k":"choice","i":"What do you call a triangle with all three sides the same length?","t":"Triangles","e":"\ud83d\udcd0","f":"An isosceles triangle has two equal sides; a scalene triangle has none.","o":["Isosceles","Scalene","Right-angled","Equilateral"],"s":{"index":3}},{"k":"number","i":"What is the area of a rectangle measuring 5 cm by 8 cm?","t":"Area","e":"\ud83d\udfe6","f":"Area of a rectangle = length \u00d7 width, so 5 \u00d7 8 = 40 square centimetres.","s":{"value":40,"tolerance":0,"min":0,"max":100,"unit":"cm\u00b2"}},{"k":"text","i":"What is the name of the longest side of a right-angled triangle?","t":"Triangles","e":"\ud83d\udccf","f":"By Pythagoras' theorem, its square equals the sum of the squares of the other two sides.","s":{"accepted":["Hypotenuse","The hypotenuse","Hypotenuse side"]}},{"k":"number","i":"A right-angled triangle has shorter sides of 3 cm and 4 cm. How long is its longest side?","t":"Pythagoras","e":"\ud83e\uddee","f":"3-4-5 is the most famous Pythagorean triple: 9 + 16 = 25, and \u221a25 = 5.","s":{"value":5,"tolerance":0,"min":0,"max":20,"unit":"cm"}},{"k":"choice","i":"What is a polygon with eight sides called?","t":"Polygons","e":"\ud83d\uded1","f":"'Okto' is Greek for eight, the same root as the eight-armed octopus.","o":["Hexagon","Octagon","Heptagon","Decagon"],"s":{"index":1}},{"k":"multi","i":"Select all the shapes that always have exactly four sides.","t":"Quadrilaterals","e":"\ud83d\udd37","f":"Four-sided shapes are called quadrilaterals, and their interior angles always add up to 360\u00b0.","o":["Trapezoid","Triangle","Pentagon","Parallelogram","Rhombus"],"s":{"indices":[0,3,4]}},{"k":"truefalse","i":"A square is a special kind of rectangle.","t":"Quadrilaterals","e":"\u23f9\ufe0f","f":"A rectangle needs four right angles; a square has those, plus four equal sides.","a":true},{"k":"truefalse","i":"A full circle measures 180 degrees.","t":"Angles","e":"\u2b55","f":"A full turn is 360\u00b0; 180\u00b0 is only a half turn, a straight line.","a":false},{"k":"order","i":"Order these shapes by number of sides, fewest first.","t":"Polygons","e":"\ud83d\udd22","f":"3, 5, 7, 9 and 12 sides: 'dodeca' is Greek for twelve.","o":["Triangle","Pentagon","Heptagon","Nonagon","Dodecagon"]},{"k":"choice","i":"Roughly what is the value of pi (\u03c0)?","t":"Circles","e":"\ud83e\udd67","f":"2.72 is Euler's number and 1.62 the golden ratio. Pi's digits go on forever without repeating.","o":["2.72","3.14","1.62","3.41"],"s":{"index":1}},{"k":"number","i":"What is the perimeter of a square with sides of 7 cm?","t":"Perimeter","e":"\ud83d\udfe5","f":"A square has four equal sides, so 4 \u00d7 7 = 28 cm.","s":{"value":28,"tolerance":0,"min":0,"max":100,"unit":"cm"}}]},{"slug":"superhero-origins","title":"Superhero Origins","tagline":"Krypton, Gotham and radioactive spiders: where did your heroes begin?","emoji":"\ud83e\uddb8","gradient":["#b91c1c","#312e81"],"categories":["popculture","movies"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":291,"items":[{"k":"choice","i":"What is the name of Superman's home planet?","t":"DC","e":"\ud83e\ude90","f":"Superman was created by writer Jerry Siegel and artist Joe Shuster.","o":["Mars","Oa","Thanagar","Krypton"],"s":{"index":3}},{"k":"choice","i":"How did Peter Parker get his Spider-Man powers?","t":"Marvel","e":"\ud83d\udd77\ufe0f","f":"Spider-Man first appeared in Amazing Fantasy #15 in 1962.","o":["Bitten by a radioactive spider","Exposed to gamma rays","Found a magic amulet","Born on another planet"],"s":{"index":0}},{"k":"choice","i":"Which artist co-created Spider-Man with Stan Lee?","t":"Creators","e":"\u270d\ufe0f","f":"Jack Kirby worked with Stan Lee on the Fantastic Four and the X-Men.","o":["Jack Kirby","Steve Ditko","Bob Kane","Jerry Siegel"],"s":{"index":1}},{"k":"choice","i":"Which nearly indestructible metal is bonded to Wolverine's skeleton?","t":"Marvel","e":"\ud83e\uddbe","f":"Adamantium is a fictional metal alloy from Marvel comics.","o":["Vibranium","Uru","Kryptonite","Adamantium"],"s":{"index":3}},{"k":"choice","i":"Which superhero is nicknamed 'the Scarlet Speedster'?","t":"DC","e":"\u26a1","f":"The Flash gets his super speed from a mysterious energy field called the Speed Force.","o":["The Flash","Quicksilver","Superman","Captain Marvel"],"s":{"index":0}},{"k":"choice","i":"What is the real name of the original Captain America?","t":"Marvel","e":"\ud83d\udee1\ufe0f","f":"Captain America was created by Joe Simon and Jack Kirby and first appeared in 1941.","o":["Clint Barton","Scott Lang","Steve Rogers","Matt Murdock"],"s":{"index":2}},{"k":"number","i":"In what year did Superman first appear, in Action Comics #1?","t":"Golden Age","e":"\ud83d\udcf0","f":"Action Comics #1 is one of the most valuable comic books in the world.","s":{"value":1938,"tolerance":0,"min":1920,"max":1970,"unit":""}},{"k":"truefalse","i":"Wonder Woman comes from the island of Themyscira.","t":"DC","e":"\ud83c\udfdd\ufe0f","f":"Wonder Woman first appeared in 1941, created by psychologist William Moulton Marston.","a":true},{"k":"truefalse","i":"Iron Man's secret identity is Bruce Banner.","t":"Marvel","e":"\ud83e\udd16","f":"Iron Man is Tony Stark; Bruce Banner turns into the Hulk.","a":false},{"k":"text","i":"What is the name of the city that Batman protects?","t":"DC","e":"\ud83e\udd87","f":"Batman was created by Bob Kane and Bill Finger and first appeared in 1939.","s":{"accepted":["Gotham","Gotham City"]}},{"k":"text","i":"What is the name of Thor's magical hammer?","t":"Marvel","e":"\ud83d\udd28","f":"Like Thor himself, the hammer comes from Norse mythology.","s":{"accepted":["Mjolnir","Mj\u00f6lnir","Mjollnir","Mj\u00f6lner","Mj\u00f6lnir hammer"]}},{"k":"multi","i":"Select all the Marvel characters.","t":"Publishers","e":"\ud83d\udcda","f":"Batman, Aquaman and The Flash are DC characters.","o":["Spider-Man","Batman","Wolverine","Aquaman","Captain America","The Flash"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these heroes by their first comic book appearance, earliest first.","t":"Debuts","e":"\ud83d\udcc5","f":"They debuted in 1938, 1939, 1962, 1966 and 1974.","o":["Superman","Batman","Spider-Man","Black Panther","Wolverine"]}]},{"slug":"bytes-of-internet-history","title":"Bytes of Internet History","tagline":"From ARPANET to Wikipedia: log in to the story of computers and the web.","emoji":"\ud83d\udcbb","gradient":["#2563eb","#0f766e"],"categories":["tech","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":292,"items":[{"k":"choice","i":"Who invented the World Wide Web in 1989 while working at CERN?","t":"The Web","e":"\ud83c\udf10","f":"The first website, info.cern.ch, explained what the World Wide Web was and how to use it.","o":["Bill Gates","Tim Berners-Lee","Steve Jobs","Vint Cerf"],"s":{"index":1}},{"k":"choice","i":"Which symbol did Ray Tomlinson choose for email addresses in 1971?","t":"Email","e":"\ud83d\udce7","f":"He picked @ because it was rarely used and clearly meant a user 'at' a particular computer.","o":["#","&","@","*"],"s":{"index":2}},{"k":"choice","i":"Which company did Bill Gates and Paul Allen found in 1975?","t":"Companies","e":"\ud83e\ude9f","f":"The name Microsoft is a blend of 'microcomputer' and 'software'.","o":["Apple","IBM","Intel","Microsoft"],"s":{"index":3}},{"k":"choice","i":"Google began as a research project at which university?","t":"Companies","e":"\ud83d\udd0d","f":"Larry Page and Sergey Brin founded Google in 1998, renting their first office in a garage in Menlo Park.","o":["Stanford","Harvard","MIT","Berkeley"],"s":{"index":0}},{"k":"choice","i":"Whose team found a real moth in a computer in 1947, popularising the word 'bug'?","t":"Computing","e":"\ud83d\udc1b","f":"The moth was taped into the Harvard Mark II logbook with the note 'First actual case of bug being found.'","o":["Ada Lovelace","Grace Hopper","Alan Turing","Margaret Hamilton"],"s":{"index":1}},{"k":"choice","i":"What was the network, launched in 1969, that became the forerunner of the internet?","t":"Networks","e":"\ud83d\udd0c","f":"The first ARPANET message was meant to be 'LOGIN', but the system crashed after 'LO'.","o":["ARPANET","ETHERNET","USENET","SKYNET"],"s":{"index":0}},{"k":"choice","i":"What did Douglas Engelbart show off in his famous 1968 demonstration?","t":"Hardware","e":"\ud83d\uddb1\ufe0f","f":"Engelbart's first mouse prototype was a wooden block with two metal wheels underneath.","o":["The laptop","The computer mouse","The touchscreen","The laser printer"],"s":{"index":1}},{"k":"truefalse","i":"Wikipedia was launched in 2001.","t":"The Web","e":"\ud83d\udcda","f":"Wikipedia went online on 15 January 2001; 'wiki' comes from the Hawaiian word for 'quick'.","a":true},{"k":"multi","i":"Select all the people who co-founded Apple in 1976.","t":"Companies","e":"\ud83c\udf4e","f":"Ronald Wayne sold his 10% stake in Apple for $800 just 12 days after the company was founded.","o":["Steve Jobs","Steve Wozniak","Bill Gates","Ronald Wayne","Larry Page"],"s":{"indices":[0,1,3]}},{"k":"text","i":"Which open-source operating system did Linus Torvalds release in 1991?","t":"Software","e":"\ud83d\udc27","f":"Linus Torvalds was a 21-year-old student at the University of Helsinki when he started Linux.","s":{"accepted":["Linux"]}},{"k":"number","i":"In what year was the first YouTube video, 'Me at the zoo', uploaded?","t":"The Web","e":"\u25b6\ufe0f","f":"The 19-second clip shows co-founder Jawed Karim in front of the elephants at San Diego Zoo.","s":{"value":2005,"tolerance":0,"min":1990,"max":2020,"unit":""}},{"k":"number","i":"How many bits make up one byte?","t":"Computing","e":"\ud83d\udd22","f":"With 8 bits, a single byte can store 256 different values.","s":{"value":8,"tolerance":0,"min":1,"max":32,"unit":"bits"}},{"k":"order","i":"Order these milestones from oldest to newest.","t":"Timeline","e":"\u23f3","f":"In just over 30 years, the internet grew from a few linked university computers to a global encyclopedia.","o":["First ARPANET message","First email using @","World Wide Web proposed","Google founded","Wikipedia launched"]}]},{"slug":"prague-and-beyond","title":"Prague & Beyond","tagline":"Castles, composers and a famous astronomical clock: discover Czechia.","emoji":"\ud83c\udde8\ud83c\uddff","gradient":["#1e40af","#dc2626"],"categories":["travel","history","culture"],"countries":["CZ"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":293,"items":[{"k":"choice","i":"Which river flows through Prague?","t":"Rivers","e":"\ud83c\udf0a","f":"The Vltava is the longest river within Czechia and inspired a famous symphonic poem by Bed\u0159ich Smetana.","o":["Morava","Elbe","Danube","Vltava"],"s":{"index":3}},{"k":"choice","i":"What is the name of the medieval astronomical clock on Prague's Old Town Hall?","t":"Landmarks","e":"\ud83d\udd70\ufe0f","f":"The Prague Orloj was first installed in 1410 and is the oldest astronomical clock still working.","o":["Big Ben","The Orloj","The Rathaus Clock","The Zytglogge"],"s":{"index":1}},{"k":"text","i":"Which famous stone bridge in Prague, lined with 30 statues, is named after a Holy Roman Emperor?","t":"Landmarks","e":"\ud83c\udf09","f":"Construction of Charles Bridge began in 1357 under Emperor Charles IV.","s":{"accepted":["Charles Bridge","Karl\u016fv most","Karluv most","Charles"]}},{"k":"truefalse","i":"Prague Castle is one of the largest ancient castle complexes in the world.","t":"Landmarks","e":"\ud83c\udff0","f":"Guinness World Records lists Prague Castle as the largest ancient castle complex, covering about 70,000 m\u00b2.","a":true},{"k":"choice","i":"Which writer, born in Prague, wrote 'The Metamorphosis'?","t":"Literature","e":"\ud83e\udeb2","f":"Kafka wrote in German, and most of his work was published only after his death.","o":["Milan Kundera","Franz Kafka","Jaroslav Ha\u0161ek","V\u00e1clav Havel"],"s":{"index":1}},{"k":"order","i":"Order these Czech composers by birth year, from earliest to latest.","t":"Music","e":"\ud83c\udfbc","f":"Bed\u0159ich Smetana is often called the father of Czech music.","o":["Bed\u0159ich Smetana","Anton\u00edn Dvo\u0159\u00e1k","Leo\u0161 Jan\u00e1\u010dek","Bohuslav Martin\u016f"]},{"k":"multi","i":"Select all the countries that border the Czech Republic.","t":"Borders","e":"\ud83d\uddfa\ufe0f","f":"Czechia borders four countries: Germany, Poland, Slovakia and Austria.","o":["Poland","Austria","Germany","Slovenia","Hungary"],"s":{"indices":[0,1,2]}},{"k":"number","i":"In what year did Czechoslovakia peacefully split into the Czech Republic and Slovakia?","t":"History","e":"\u2702\ufe0f","f":"The peaceful split, which took effect on 1 January 1993, is known as the 'Velvet Divorce'.","s":{"value":1993,"tolerance":0,"min":1950,"max":2010,"unit":""}},{"k":"choice","i":"Which Czech spa town is famous for its hot springs and an international film festival?","t":"Towns","e":"\ud83c\udfac","f":"Karlovy Vary, also known as Carlsbad, has hosted its international film festival since 1946.","o":["Brno","Karlovy Vary","Plze\u0148","Olomouc"],"s":{"index":1}},{"k":"choice","i":"Which Czech composer wrote the 'New World' Symphony?","t":"Music","e":"\ud83c\udfbb","f":"Dvo\u0159\u00e1k composed the 'New World' Symphony in 1893 while living in the United States.","o":["Leo\u0161 Jan\u00e1\u010dek","Anton\u00edn Dvo\u0159\u00e1k","Bed\u0159ich Smetana","Bohuslav Martin\u016f"],"s":{"index":1}},{"k":"order","i":"Order these Czech cities from west to east.","t":"Cities","e":"\ud83e\udded","f":"Ostrava, in the far east of the country, grew up as a major coal-mining and steel city.","o":["Plze\u0148","Prague","Brno","Ostrava"]},{"k":"truefalse","i":"The sugar cube was invented in the Czech lands.","t":"Inventions","e":"\ud83e\uddca","f":"Jakub Kry\u0161tof Rad patented the sugar cube in Da\u010dice in 1843, reportedly after his wife cut her finger on a sugar loaf.","a":true},{"k":"choice","i":"Which Czech dish is beef sirloin in a creamy vegetable sauce, served with dumplings?","t":"Food","e":"\ud83c\udf56","f":"Sv\u00ed\u010dkov\u00e1 is usually served with a spoonful of cranberries and a swirl of whipped cream.","o":["Bigos","Moussaka","Sv\u00ed\u010dkov\u00e1","Pierogi"],"s":{"index":2}},{"k":"choice","i":"What kind of animal is Krtek, the beloved Czech cartoon character?","t":"Cartoons","e":"\ud83d\udc3e","f":"Krtek was created by Zden\u011bk Miler in 1956, and a toy Krtek flew to the International Space Station in 2011.","o":["A mole","A rabbit","A beaver","A hedgehog"],"s":{"index":0}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'fa8e580e0c260515e131df7816aa2ce5' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 11'; end $q$;
do $q$ declare d text := $d$[{"slug":"inside-the-human-body","title":"Inside the Human Body","tagline":"Bones, blood and organs: how well do you know yourself?","emoji":"\ud83e\udec0","gradient":["#e11d48","#9f1239"],"categories":["health","science"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":294,"items":[{"k":"number","i":"How many bones are in the adult human body?","t":"Skeleton","e":"\ud83e\uddb4","f":"Babies are born with around 270 to 300 bones, and many of them fuse together as they grow.","s":{"value":206,"tolerance":0,"min":100,"max":300,"unit":"bones"}},{"k":"choice","i":"What is the largest organ of the human body?","t":"Organs","e":"\ud83d\udd90\ufe0f","f":"An adult's skin covers roughly 1.5 to 2 square metres.","o":["Liver","Brain","Skin","Lungs"],"s":{"index":2}},{"k":"choice","i":"What is the smallest bone in the human body?","t":"Skeleton","e":"\ud83d\udc42","f":"The stapes, deep inside the middle ear, is only about 3 mm long.","o":["Femur","Stapes","Hyoid","Coccyx"],"s":{"index":1}},{"k":"text","i":"What is the longest bone in the human body?","t":"Skeleton","e":"\ud83e\uddb5","f":"The femur, or thigh bone, is also the strongest bone in the body.","s":{"accepted":["Femur","The femur","Thigh bone","Thighbone"]}},{"k":"truefalse","i":"The human heart has four chambers.","t":"Heart","e":"\u2764\ufe0f","f":"The two upper atria receive blood, and the two lower ventricles pump it out to the lungs and body.","a":true},{"k":"multi","i":"Select all the organs that are part of the digestive system.","t":"Digestion","e":"\ud83c\udf7d\ufe0f","f":"The small intestine is about 6 m long, making it the longest part of the digestive tract.","o":["Stomach","Lungs","Small intestine","Kidneys","Liver"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"Which blood cells help the body fight infection?","t":"Blood","e":"\ud83e\ude78","f":"Red blood cells carry oxygen, while platelets help blood to clot.","o":["Red blood cells","Platelets","Nerve cells","White blood cells"],"s":{"index":3}},{"k":"order","i":"Order these levels of organization in the body from smallest to largest.","t":"Biology","e":"\ud83d\udd2c","f":"The human body is made up of tens of trillions of cells.","o":["Cell","Tissue","Organ","Organ system","Organism"]},{"k":"choice","i":"Which organs filter the blood to make urine?","t":"Organs","e":"\ud83e\uded8","f":"Your kidneys filter around 180 litres of fluid from the blood each day, but most of it is reabsorbed.","o":["Liver","Kidneys","Spleen","Pancreas"],"s":{"index":1}},{"k":"truefalse","i":"The blood in your veins is blue.","t":"Blood","e":"\ud83d\udc99","f":"Blood is always red; veins only look bluish because of the way light passes through skin.","a":false},{"k":"number","i":"How many teeth does an adult usually have, including wisdom teeth?","t":"Teeth","e":"\ud83e\uddb7","f":"Children have 20 baby teeth, which are replaced by permanent teeth as they grow.","s":{"value":32,"tolerance":0,"min":10,"max":50,"unit":"teeth"}},{"k":"choice","i":"What is a normal resting heart rate for an adult, in beats per minute?","t":"Heart","e":"\ud83d\udc93","f":"Over a lifetime, the human heart beats more than 2.5 billion times.","o":["20 to 40","120 to 160","60 to 100","180 to 220"],"s":{"index":2}},{"k":"choice","i":"Which protein in red blood cells carries oxygen around the body?","t":"Blood","e":"\ud83e\udec1","f":"Hemoglobin contains iron, which helps give blood its red color.","o":["Hemoglobin","Insulin","Keratin","Melanin"],"s":{"index":0}}]},{"slug":"riddle-me-this","title":"Riddle Me This","tagline":"Classic brain-teasers with sneaky wordplay. Think sideways!","emoji":"\ud83e\udd14","gradient":["#7e22ce","#1e3a8a"],"categories":["puzzles","kids"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":295,"items":[{"k":"text","i":"Riddle: What has to be broken before you can use it?","t":"Riddles","e":"\ud83e\udd5a","f":"The trick is the word 'broken': an egg must be cracked open before you can cook with it.","s":{"accepted":["Egg","An egg","Eggs","A egg"]}},{"k":"text","i":"Riddle: What gets wetter the more it dries?","t":"Riddles","e":"\ud83d\udec1","f":"A towel soaks up water as it dries you.","s":{"accepted":["Towel","A towel","Towels","Bath towel"]}},{"k":"text","i":"Riddle: What can travel around the world while staying in a corner?","t":"Riddles","e":"\u2709\ufe0f","f":"A stamp sits in the corner of an envelope while the letter travels across the world.","s":{"accepted":["Stamp","A stamp","Postage stamp","A postage stamp","Stamps"]}},{"k":"choice","i":"Riddle: What goes up but never comes down?","t":"Riddles","e":"\ud83c\udf82","f":"Every birthday adds a year, and there's no going back.","o":["A balloon","Your age","Rain","A lift"],"s":{"index":1}},{"k":"text","i":"Riddle: I'm tall when I'm young and short when I'm old, and I glow while I live. What am I?","t":"Riddles","e":"\ud83d\udd6f\ufe0f","f":"A candle gets shorter as it burns.","s":{"accepted":["Candle","A candle","Candles"]}},{"k":"text","i":"Riddle: If you have me, you want to share me. If you share me, you haven't got me. What am I?","t":"Riddles","e":"\ud83e\udd2b","f":"Once a secret is shared, it isn't a secret any more.","s":{"accepted":["Secret","A secret","Secrets"]}},{"k":"text","i":"Riddle: What belongs to you, but other people use it more than you do?","t":"Riddles","e":"\ud83d\udcdb","f":"Others say your name far more often than you do.","s":{"accepted":["Name","Your name","My name"]}},{"k":"text","i":"Riddle: Which word becomes shorter when you add two letters to it?","t":"Word play","e":"\u2702\ufe0f","f":"Add 'er' to 'short' and you get 'shorter'!","s":{"accepted":["Short"]}},{"k":"number","i":"Riddle: How many months of the year have 28 days?","t":"Trick questions","e":"\ud83d\udcc5","f":"Every month has at least 28 days; February is simply the only one with no more.","s":{"value":12,"tolerance":0,"min":1,"max":12,"unit":""}},{"k":"choice","i":"Riddle: What has hands and a face, but can't clap or smile?","t":"Riddles","e":"\ud83d\udd70\ufe0f","f":"Many early mechanical clocks had only an hour hand; minute hands became common later.","o":["A doll","A statue","A glove","A clock"],"s":{"index":3}},{"k":"choice","i":"Riddle: What has lots of teeth but can't bite?","t":"Riddles","e":"\ud83e\udeae","f":"Combs are among the oldest tools people have made, with examples thousands of years old.","o":["A shark","A dog","A comb","A crocodile"],"s":{"index":2}},{"k":"choice","i":"Riddle: What has a neck but no head?","t":"Riddles","e":"\ud83c\udf7e","f":"A guitar is out: its neck ends in a 'head' where the tuning pegs sit.","o":["A giraffe","A swan","A bottle","A guitar"],"s":{"index":2}},{"k":"truefalse","i":"Riddle: 'The more you take, the more you leave behind.' The answer is footsteps.","t":"Riddles","e":"\ud83d\udc63","f":"Every step you take leaves another footprint behind you.","a":true},{"k":"text","i":"Riddle: Forward I am heavy, but backward I am not. What am I?","t":"Word play","e":"\ud83c\udfcb\ufe0f","f":"Spell 'ton' backwards and you get 'not'!","s":{"accepted":["Ton","A ton"]}}]},{"slug":"toy-box-throwback","title":"Toy Box Throwback","tagline":"Teddy bears to Tamagotchis: the toys and games that defined generations.","emoji":"\ud83e\uddf8","gradient":["#f59e0b","#db2777"],"categories":["popculture","kids"],"countries":null,"difficulty":"Easy","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":296,"items":[{"k":"choice","i":"In which country was LEGO founded?","t":"LEGO","e":"\ud83e\uddf1","f":"The name comes from the Danish 'leg godt', meaning 'play well'.","o":["Sweden","Denmark","Germany","Netherlands"],"s":{"index":1}},{"k":"choice","i":"Which Japanese company created the Tamagotchi in 1996?","t":"Digital Pets","e":"\ud83e\udd5a","f":"The name blends the Japanese word 'tamago' (egg) with the English word 'watch'.","o":["Sega","Nintendo","Hasbro","Bandai"],"s":{"index":3}},{"k":"choice","i":"How many different colours are on a standard Rubik's Cube?","t":"Puzzles","e":"\ud83d\udfe5","f":"Each of the six faces starts as one solid colour.","o":["4","5","6","8"],"s":{"index":2}},{"k":"choice","i":"The teddy bear is named after which US president?","t":"Classic Toys","e":"\ud83d\udc3b","f":"A 1902 newspaper cartoon showed Roosevelt sparing a bear cub on a hunting trip, inspiring toymakers.","o":["Theodore Roosevelt","Abraham Lincoln","Franklin D. Roosevelt","George Washington"],"s":{"index":0}},{"k":"choice","i":"What does an Etch A Sketch use to draw lines on its screen?","t":"Classic Toys","e":"\u270f\ufe0f","f":"Turning the knobs moves a stylus that scrapes powder off the inside of the glass.","o":["Iron filings","Magnetic ink","Aluminium powder","Fine sand"],"s":{"index":2}},{"k":"choice","i":"How many letter tiles does each player hold in Scrabble?","t":"Board Games","e":"\ud83d\udd20","f":"Using all seven tiles in one turn earns a 50-point bonus.","o":["5","6","7","8"],"s":{"index":2}},{"k":"number","i":"In what year was the Barbie doll launched?","t":"Dolls","e":"\ud83d\udc71\u200d\u2640\ufe0f","f":"Barbie was created by Ruth Handler and named after her daughter, Barbara.","s":{"value":1959,"tolerance":0,"min":1940,"max":1980,"unit":""}},{"k":"number","i":"How many studs are on top of a classic 2x4 LEGO brick?","t":"LEGO","e":"\ud83d\udd22","f":"Six classic 2x4 bricks can be combined in more than 900 million different ways.","s":{"value":8,"tolerance":0,"min":1,"max":16,"unit":""}},{"k":"truefalse","i":"The Slinky was invented by accident.","t":"Classic Toys","e":"\ud83c\udf00","f":"Engineer Richard James saw a spring tumble off a shelf in 1943; the Slinky went on sale in 1945.","a":true},{"k":"truefalse","i":"The yo-yo was invented in the 20th century.","t":"Classic Toys","e":"\ud83e\ude80","f":"Yo-yos are known from ancient Greece around 500 BC.","a":false},{"k":"text","i":"Which Hungarian architecture professor invented the famous 3x3 puzzle cube in 1974?","t":"Puzzles","e":"\ud83c\udded\ud83c\uddfa","f":"Rubik originally called his invention the 'Magic Cube' (B\u0171v\u00f6s kocka in Hungarian).","s":{"accepted":["Ern\u0151 Rubik","Erno Rubik","Rubik","Rubik Ern\u0151","Rubik Erno"]}},{"k":"multi","i":"Select all the toys and games that were first released in the 1990s.","t":"1990s","e":"\ud83d\udcfc","f":"Tamagotchi and the Pok\u00e9mon card game arrived in 1996, and Furby in 1998.","o":["Tamagotchi","Rubik's Cube","Furby","Barbie","Pok\u00e9mon Trading Card Game","Cabbage Patch Kids"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these toys and games by when they first appeared, oldest first.","t":"Timeline","e":"\ud83d\udcc5","f":"Teddy bears appeared in 1902, Parker Brothers' Monopoly in 1935, Barbie in 1959, the Rubik's Cube in 1974 and Furby in 1998.","o":["Teddy bear","Monopoly","Barbie","Rubik's Cube","Furby"]}]},{"slug":"mobile-phone-throwback","title":"Mobile Phone Throwback","tagline":"Brick phones, Snake and the first text message: dial back in time.","emoji":"\ud83d\udcf1","gradient":["#7c3aed","#0284c7"],"categories":["tech","history","popculture"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":297,"items":[{"k":"choice","i":"Martin Cooper made the first handheld mobile phone call in 1973. Which company did he work for?","t":"Firsts","e":"\u260e\ufe0f","f":"Cooper called a rival engineer at Bell Labs from a New York street to announce his success.","o":["Nokia","Motorola","Ericsson","IBM"],"s":{"index":1}},{"k":"choice","i":"What did the first-ever text message, sent in 1992, say?","t":"SMS","e":"\ud83d\udcac","f":"Engineer Neil Papworth sent it from a computer to a Vodafone phone on 3 December 1992.","o":["Hello World","Merry Christmas","Happy New Year","Can you hear me?"],"s":{"index":1}},{"k":"choice","i":"Which classic game came preinstalled on many Nokia phones from 1997?","t":"Games","e":"\ud83d\udc0d","f":"Snake first appeared on the Nokia 6110 and later became a famous feature of the Nokia 3310.","o":["Tetris","Pac-Man","Snake","Pong"],"s":{"index":2}},{"k":"choice","i":"Nokia comes from which country?","t":"Companies","e":"\ud83c\udf32","f":"Nokia began in 1865 as a paper mill, and later made rubber boots and cables before mobile phones.","o":["Sweden","Denmark","Norway","Finland"],"s":{"index":3}},{"k":"choice","i":"BlackBerry phones, famous for their physical keyboards, were made by a company from which country?","t":"Companies","e":"\u2328\ufe0f","f":"Research In Motion, the company behind BlackBerry, was based in Waterloo, Ontario.","o":["Canada","USA","UK","Japan"],"s":{"index":0}},{"k":"choice","i":"The first emoji set was created in 1999 for mobile phones in which country?","t":"Emoji","e":"\ud83d\ude00","f":"Shigetaka Kurita drew the first 176 emoji for NTT Docomo; they are now in New York's Museum of Modern Art.","o":["South Korea","China","Japan","USA"],"s":{"index":2}},{"k":"choice","i":"What does 'SMS' stand for?","t":"Jargon","e":"\ud83d\udce8","f":"SMS was designed as part of the GSM mobile phone standard in the 1980s.","o":["Short Message Service","Simple Mobile System","Standard Message Signal","Smart Mobile Speech"],"s":{"index":0}},{"k":"truefalse","i":"The first iPhone was released in 2007.","t":"Smartphones","e":"\ud83c\udf4f","f":"Steve Jobs introduced it on 9 January 2007 as 'an iPod, a phone, and an internet communicator'.","a":true},{"k":"multi","i":"Select all the phones made by Nokia.","t":"Classic phones","e":"\ud83d\udcde","f":"The Razr and the DynaTAC were made by Motorola; the Razr V3 of 2004 was famous for its ultra-thin flip design.","o":["3310","Razr","N95","DynaTAC","1100"],"s":{"indices":[0,2,4]}},{"k":"text","i":"What nickname was given to big, heavy early mobile phones like the Motorola DynaTAC?","t":"Classic phones","e":"\ud83e\uddf1","f":"The DynaTAC 8000X went on sale in 1983, weighed about 800 g and took around 10 hours to charge.","s":{"accepted":["Brick","The brick","Brick phone","Bricks"]}},{"k":"number","i":"How many characters fit in a single classic SMS text message?","t":"SMS","e":"\u2709\ufe0f","f":"The 160-character limit was chosen by engineer Friedhelm Hillebrand.","s":{"value":160,"tolerance":0,"min":50,"max":300,"unit":"characters"}},{"k":"number","i":"About how many minutes of talk time did the Motorola DynaTAC 8000X offer on a full charge?","t":"Batteries","e":"\ud83d\udd0b","f":"The DynaTAC 8000X cost about $3,995 when it went on sale in 1983.","s":{"value":30,"tolerance":5,"min":5,"max":120,"unit":"minutes"}},{"k":"order","i":"Order these mobile milestones from oldest to newest.","t":"Timeline","e":"\u23f3","f":"In just 34 years, mobile phones went from brick-sized prototypes to touchscreen smartphones.","o":["First handheld mobile call","First text message","First emoji set","First iPhone"]}]},{"slug":"serbia-uncovered","title":"Serbia Uncovered","tagline":"Belgrade's fortress, Tesla and \u0107evapi: how well do you know Serbia?","emoji":"\ud83c\uddf7\ud83c\uddf8","gradient":["#b91c1c","#1e3a8a"],"categories":["culture","geo","food"],"countries":["RS"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":298,"items":[{"k":"choice","i":"What is the capital of Serbia?","t":"Cities","e":"\ud83c\udfd9\ufe0f","f":"Belgrade sits where the Sava river meets the Danube.","o":["Ni\u0161","Kragujevac","Belgrade","Novi Sad"],"s":{"index":2}},{"k":"choice","i":"Which famous inventor of alternating-current systems was born to a Serbian family?","t":"Famous people","e":"\u26a1","f":"Tesla was born in 1856 in Smiljan, in present-day Croatia, to Serbian parents.","o":["Thomas Edison","Guglielmo Marconi","Alessandro Volta","Nikola Tesla"],"s":{"index":3}},{"k":"text","i":"What are the grilled minced-meat rolls, popular across Serbia and the Balkans, called?","t":"Food","e":"\ud83c\udf62","f":"\u0106evapi are usually served in a flatbread called lepinja with chopped raw onions.","s":{"accepted":["\u0106evapi","Cevapi","\u0106evap\u010di\u0107i","Cevapcici"]}},{"k":"choice","i":"Belgrade Fortress stands in a large park known by what name?","t":"Landmarks","e":"\ud83c\udff0","f":"The name Kalemegdan comes from Turkish words meaning 'fortress' and 'field'.","o":["Kalemegdan","Top\u010dider","Ta\u0161majdan","Ada Ciganlija"],"s":{"index":0}},{"k":"truefalse","i":"Serbia is a landlocked country.","t":"Geography","e":"\ud83d\uddfa\ufe0f","f":"Despite having no coastline, Serbia has about 588 km of the Danube flowing through it.","a":true},{"k":"choice","i":"Which Serbian city hosts the EXIT music festival in the Petrovaradin Fortress?","t":"Festivals","e":"\ud83c\udfb6","f":"EXIT was first held in 2000 and is staged inside the 18th-century Petrovaradin Fortress above the Danube.","o":["Novi Sad","Ni\u0161","Belgrade","Subotica"],"s":{"index":0}},{"k":"multi","i":"Select all the alphabets commonly used to write Serbian.","t":"Language","e":"\ud83d\udd24","f":"Serbian is one of the few languages regularly written in two scripts, Cyrillic and Latin.","o":["Greek","Arabic","Cyrillic","Georgian","Latin"],"s":{"indices":[2,4]}},{"k":"order","i":"Order these famous Serbs by birth year, from earliest to latest.","t":"Famous people","e":"\ud83d\udcc5","f":"Mihajlo Pupin became a physics professor at Columbia University and won a Pulitzer Prize for his autobiography.","o":["Vuk Karad\u017ei\u0107","Nikola Tesla","Mihajlo Pupin","Milutin Milankovi\u0107"]},{"k":"number","i":"How many letters are in the Serbian Cyrillic alphabet?","t":"Language","e":"\ud83d\udd20","f":"Vuk Karad\u017ei\u0107 reformed the alphabet on the principle 'write as you speak', with one letter for each sound.","s":{"value":30,"tolerance":0,"min":20,"max":40,"unit":""}},{"k":"choice","i":"Which river forms the dramatic Iron Gates gorge on Serbia's border with Romania?","t":"Nature","e":"\ud83c\udfde\ufe0f","f":"The Iron Gates gorge is protected within Serbia's \u0110erdap National Park.","o":["Sava","Drina","Morava","Danube"],"s":{"index":3}},{"k":"order","i":"Order these Serbian cities from north to south.","t":"Cities","e":"\ud83e\udded","f":"Subotica, near the Hungarian border, is famous for its colourful Art Nouveau buildings.","o":["Subotica","Novi Sad","Belgrade","Ni\u0161"]},{"k":"truefalse","i":"Raspberries are one of Serbia's most famous farm exports.","t":"Food","e":"\ud83e\uded0","f":"Serbia is one of the world's biggest raspberry producers, especially around the town of Arilje.","a":true},{"k":"choice","i":"What is kajmak, often served with Serbian grilled meat?","t":"Food","e":"\ud83e\uddc8","f":"Kajmak is made by skimming the cream that forms on top of boiled milk and letting it mature.","o":["A spicy pepper relish","A creamy dairy spread","A flaky pastry","A bean soup"],"s":{"index":1}},{"k":"choice","i":"Which Serbian scientist explained the timing of ice ages through changes in Earth's orbit?","t":"Famous people","e":"\ud83e\uddca","f":"Today these long-term changes in Earth's orbit and tilt are called 'Milankovi\u0107 cycles'.","o":["Milutin Milankovi\u0107","Mihajlo Pupin","Nikola Tesla","Alfred Wegener"],"s":{"index":0}}]},{"slug":"nutrition-and-vitamins","title":"Nutrition Know-How","tagline":"Vitamins, minerals and what's really on your plate.","emoji":"\ud83e\udd66","gradient":["#16a34a","#0f766e"],"categories":["health","food"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":299,"items":[{"k":"choice","i":"Which vitamin does your skin make when exposed to sunlight?","t":"Vitamins","e":"\u2600\ufe0f","f":"Vitamin D helps your body absorb calcium, which keeps bones strong.","o":["Vitamin A","Vitamin C","Vitamin D","Vitamin K"],"s":{"index":2}},{"k":"choice","i":"A lack of which vitamin causes scurvy?","t":"Vitamins","e":"\ud83c\udf4b","f":"Sailors on long voyages once suffered from scurvy until citrus fruits were added to their diets.","o":["Vitamin C","Vitamin B12","Vitamin D","Vitamin E"],"s":{"index":0}},{"k":"multi","i":"Select all the foods that are good sources of protein.","t":"Protein","e":"\ud83e\udd5a","f":"Plant foods such as beans, lentils and tofu can also provide plenty of protein.","o":["Eggs","Lentils","Apples","Chicken","Cucumber"],"s":{"indices":[0,1,3]}},{"k":"truefalse","i":"Carrots contain beta-carotene, which the body turns into vitamin A.","t":"Vitamins","e":"\ud83e\udd55","f":"Vitamin A is important for healthy eyes, especially for seeing in dim light.","a":true},{"k":"choice","i":"Which mineral is especially important for strong bones and teeth?","t":"Minerals","e":"\ud83e\uddb4","f":"About 99% of the body's calcium is stored in the bones and teeth.","o":["Iron","Calcium","Sodium","Zinc"],"s":{"index":1}},{"k":"choice","i":"Which mineral helps red blood cells carry oxygen?","t":"Minerals","e":"\ud83e\ude78","f":"Beans, spinach, red meat and fortified cereals are all good sources of iron.","o":["Calcium","Potassium","Iodine","Iron"],"s":{"index":3}},{"k":"text","i":"What is the natural sugar found in milk called?","t":"Dairy","e":"\ud83e\udd5b","f":"People who are lactose intolerant make too little of the enzyme lactase, which digests lactose.","s":{"accepted":["Lactose"]}},{"k":"number","i":"Roughly what percentage of an adult's body weight is water?","t":"Hydration","e":"\ud83d\udca7","f":"Newborn babies are even wetter: about 75% of their body weight is water.","s":{"value":60,"tolerance":5,"min":10,"max":100,"unit":"%"}},{"k":"order","i":"Order these parts of the digestive system in the order food passes through them.","t":"Digestion","e":"\ud83c\udf4e","f":"Food usually takes from several hours to a couple of days to pass all the way through the digestive tract.","o":["Mouth","Esophagus","Stomach","Small intestine","Large intestine"]},{"k":"truefalse","i":"Dietary fiber is fully digested and absorbed in the small intestine.","t":"Fiber","e":"\ud83c\udf3e","f":"Fiber passes through largely undigested, helping keep digestion regular and feeding helpful gut bacteria.","a":false},{"k":"choice","i":"Which nutrient is the body's main source of quick energy?","t":"Energy","e":"\ud83c\udf5e","f":"The body breaks carbohydrates down into glucose, which cells use as fuel.","o":["Vitamins","Minerals","Carbohydrates","Fiber"],"s":{"index":2}},{"k":"multi","i":"Select all the foods that are rich in vitamin C.","t":"Vitamins","e":"\ud83e\udd5d","f":"Red bell peppers contain more vitamin C, weight for weight, than oranges.","o":["Oranges","Rice","Bell peppers","Butter","Kiwi fruit"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"Which vitamin is found almost only in animal foods, so vegans often get it from fortified foods or supplements?","t":"Vitamins","e":"\ud83d\udc8a","f":"Vitamin B12 is made by bacteria and helps keep nerves and blood cells healthy.","o":["Vitamin C","Vitamin B12","Vitamin K","Vitamin E"],"s":{"index":1}}]},{"slug":"logic-lab","title":"Logic Lab","tagline":"Bats, balls, snails and liars: brain-teasers that punish quick guesses.","emoji":"\ud83e\udde0","gradient":["#0369a1","#9333ea"],"categories":["puzzles","math"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":300,"items":[{"k":"number","i":"A bat and a ball cost $1.10 in total. The bat costs $1.00 more than the ball. How many cents does the ball cost?","t":"Classic traps","e":"\u26be","f":"If the ball were 10\u00a2, the bat would be $1.10 and the total $1.20. Ball 5\u00a2 + bat $1.05 = $1.10.","s":{"value":5,"tolerance":0,"min":0,"max":110,"unit":"\u00a2"}},{"k":"number","i":"If 5 machines take 5 minutes to make 5 widgets, how many minutes would 100 machines take to make 100 widgets?","t":"Rates","e":"\u2699\ufe0f","f":"Each machine makes one widget in 5 minutes, so 100 machines make 100 widgets in the same 5 minutes.","s":{"value":5,"tolerance":0,"min":0,"max":100,"unit":"min"}},{"k":"number","i":"A patch of lily pads doubles in size every day. It covers the whole lake on day 48. On which day was the lake half covered?","t":"Doubling","e":"\ud83e\udeb7","f":"Because it doubles daily, the lake was half covered just one day before it was full.","s":{"value":47,"tolerance":0,"min":0,"max":48,"unit":""}},{"k":"choice","i":"In a race, you overtake the runner in second place. What position are you in now?","t":"Classic traps","e":"\ud83c\udfc3","f":"You took the place of the person in second, so you're now second; the leader is still ahead.","o":["First","Third","Last","Second"],"s":{"index":3}},{"k":"number","i":"A clock takes 5 seconds to strike 6 o'clock (6 evenly spaced chimes). How many seconds does it take to strike 12?","t":"Gaps","e":"\ud83d\udd14","f":"6 chimes have 5 gaps of 1 second each; 12 chimes have 11 gaps, so 11 seconds, not 10.","s":{"value":11,"tolerance":0,"min":0,"max":30,"unit":"s"}},{"k":"number","i":"A drawer holds 10 black socks and 10 white socks, all mixed up. In the dark, how many must you take to be sure of a matching pair?","t":"Pigeonhole","e":"\ud83e\udde6","f":"With only two colours, any three socks must include at least two of the same colour.","s":{"value":3,"tolerance":0,"min":1,"max":20,"unit":""}},{"k":"text","i":"Mary's father has five daughters: Nana, Nene, Nini and Nono. What is the fifth daughter's name?","t":"Classic traps","e":"\ud83d\udc67","f":"The answer is in the question: the fifth daughter is Mary herself.","s":{"accepted":["Mary"]}},{"k":"choice","i":"Knights always tell the truth; knaves always lie. A says: 'We are both knaves.' What are A and B?","t":"Knights & knaves","e":"\ud83d\udee1\ufe0f","f":"A knight could never say that, so A is a knave. Since A is lying, they are not both knaves, so B is a knight.","o":["Both are knaves","Both are knights","A is a knight, B is a knave","A is a knave, B is a knight"],"s":{"index":3}},{"k":"order","i":"Max is shorter than Zoe. Ava is shorter than Max but taller than Leo. Order them from tallest to shortest.","t":"Deduction","e":"\ud83d\udccf","f":"Zoe is above Max, Max is above Ava, and Ava is above Leo.","o":["Zoe","Max","Ava","Leo"]},{"k":"number","i":"A snail at the bottom of a 10 m well climbs 3 m each day and slides back 2 m each night. On which day does it reach the top?","t":"Classic traps","e":"\ud83d\udc0c","f":"After 7 days and nights it is 7 m up; on day 8 it climbs the last 3 m and is out before it can slip back.","s":{"value":8,"tolerance":0,"min":1,"max":20,"unit":""}},{"k":"order","i":"Ana finished ahead of Ben. Cid finished right after Ben. Dee beat Ana. Eve came last. Order the five runners from first to last.","t":"Deduction","e":"\ud83c\udfc1","f":"Dee must beat Ana, who beats Ben, with Cid right behind Ben and Eve last: only one order fits.","o":["Dee","Ana","Ben","Cid","Eve"]},{"k":"truefalse","i":"If all bloops are razzies and all razzies are lazzies, then all bloops are definitely lazzies.","t":"Syllogisms","e":"\ud83d\udd17","f":"If group A sits inside group B, and B sits inside C, then A must sit inside C.","a":true},{"k":"choice","i":"It takes 3 minutes to boil one egg. How long does it take to boil 3 eggs in the same pot at the same time?","t":"Classic traps","e":"\ud83e\udd5a","f":"The eggs cook side by side, so they all take the same 3 minutes.","o":["3 minutes","6 minutes","9 minutes","1 minute"],"s":{"index":0}},{"k":"truefalse","i":"If some cats are black, then all black things must be cats.","t":"Syllogisms","e":"\ud83d\udc08\u200d\u2b1b","f":"'Some cats are black' tells you nothing about other black things: crows and coal are black too.","a":false}]},{"slug":"masterpiece-match","title":"Masterpiece Match","tagline":"Starry skies, melting clocks and a famous smile. Can you name the art?","emoji":"\ud83d\uddbc\ufe0f","gradient":["#1e40af","#b45309"],"categories":["art","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":301,"items":[{"k":"choice","i":"In which museum is the Mona Lisa displayed?","t":"Museums","e":"\ud83d\uddbc\ufe0f","f":"The Mona Lisa was stolen from the Louvre in 1911 and recovered two years later.","o":["Uffizi Gallery","The Louvre","The Prado","British Museum"],"s":{"index":1}},{"k":"choice","i":"Who painted 'The Starry Night' (1889)?","t":"Painters","e":"\ud83c\udf0c","f":"He painted it based on the view from his window at an asylum in Saint-R\u00e9my-de-Provence.","o":["Claude Monet","Paul Gauguin","Vincent van Gogh","Paul C\u00e9zanne"],"s":{"index":2}},{"k":"choice","i":"Who painted 'The Persistence of Memory' (1931), with its melting clocks?","t":"Surrealism","e":"\ud83d\udd70\ufe0f","f":"The painting is surprisingly small, about 24 by 33 cm.","o":["Salvador Dal\u00ed","Ren\u00e9 Magritte","Joan Mir\u00f3","Max Ernst"],"s":{"index":0}},{"k":"choice","i":"Michelangelo painted the ceiling of which chapel?","t":"Renaissance","e":"\u26ea","f":"He painted the ceiling between 1508 and 1512, mostly standing on scaffolding.","o":["Scrovegni Chapel","Brancacci Chapel","Sainte-Chapelle","Sistine Chapel"],"s":{"index":3}},{"k":"choice","i":"Edvard Munch, painter of 'The Scream', came from which country?","t":"Painters","e":"\ud83d\ude31","f":"Munch made several versions of The Scream, in paint, pastel and print.","o":["Norway","Sweden","Denmark","Finland"],"s":{"index":0}},{"k":"choice","i":"Which artist painted 'The Night Watch'?","t":"Dutch Golden Age","e":"\ud83d\udee1\ufe0f","f":"The huge group portrait hangs in the Rijksmuseum in Amsterdam.","o":["Frans Hals","Rembrandt","Jan Steen","Johannes Vermeer"],"s":{"index":1}},{"k":"choice","i":"Frida Kahlo, famous for her vivid self-portraits, came from which country?","t":"Painters","e":"\ud83c\udf3a","f":"Her family home in Mexico City, 'La Casa Azul' (the Blue House), is now a museum.","o":["Spain","Argentina","Mexico","Cuba"],"s":{"index":2}},{"k":"number","i":"In what year was Leonardo da Vinci born?","t":"Renaissance","e":"\ud83e\uddd1\u200d\ud83c\udfa8","f":"Leonardo was born near the town of Vinci in Tuscany, which is where his name comes from.","s":{"value":1452,"tolerance":0,"min":1400,"max":1550,"unit":""}},{"k":"truefalse","i":"Vincent van Gogh sold hundreds of paintings during his lifetime.","t":"Painters","e":"\ud83d\udcb0","f":"He is often said to have sold only one painting, 'The Red Vineyard', during his life.","a":false},{"k":"truefalse","i":"'Girl with a Pearl Earring' was painted by Johannes Vermeer.","t":"Dutch Golden Age","e":"\ud83d\udc8e","f":"Painted around 1665, it hangs in the Mauritshuis museum in The Hague.","a":true},{"k":"text","i":"Which French Impressionist painted a famous series of water lilies in his garden at Giverny?","t":"Impressionism","e":"\ud83e\udeb7","f":"Monet painted around 250 water lily pictures over the last decades of his life.","s":{"accepted":["Claude Monet","Monet"]}},{"k":"multi","i":"Select all the Dutch painters.","t":"Painters","e":"\ud83c\udf37","f":"Monet was French, Goya was Spanish and Munch was Norwegian.","o":["Rembrandt","Claude Monet","Johannes Vermeer","Francisco Goya","Vincent van Gogh","Edvard Munch"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these paintings from oldest to newest.","t":"Timeline","e":"\ud83d\udcc5","f":"They date from about 1503, 1642, 1665, 1889 and 1931.","o":["Mona Lisa","The Night Watch","Girl with a Pearl Earring","The Starry Night","The Persistence of Memory"]}]},{"slug":"animal-pals","title":"Animal Pals","tagline":"Moo, roar, splash! A friendly animal quiz for young explorers.","emoji":"\ud83d\udc3c","gradient":["#16a34a","#0e7490"],"categories":["kids","nature"],"countries":null,"difficulty":"Easy","minutes":3,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":302,"items":[{"k":"choice","i":"What do bees make?","t":"Insects","e":"\ud83d\udc1d","f":"Bees make honey from the sweet nectar they collect from flowers.","o":["Milk","Honey","Jam","Butter"],"s":{"index":1}},{"k":"choice","i":"What is a baby kangaroo called?","t":"Baby animals","e":"\ud83e\udd98","f":"A newborn joey is about the size of a jelly bean and grows inside its mum's pouch.","o":["Cub","Kid","Joey","Calf"],"s":{"index":2}},{"k":"choice","i":"Which animal is the tallest in the world?","t":"Amazing animals","e":"\ud83e\udd92","f":"A giraffe's long neck has seven bones, the same number as yours!","o":["Elephant","Camel","Giraffe","Horse"],"s":{"index":2}},{"k":"choice","i":"What does a giant panda mostly eat?","t":"Animal food","e":"\ud83d\udc3c","f":"Giant pandas spend around half of every day munching bamboo.","o":["Fish","Bamboo","Bananas","Grass"],"s":{"index":1}},{"k":"choice","i":"Which animal is known as the 'King of the Jungle'?","t":"Big cats","e":"\ud83e\udd81","f":"Lions actually live mostly on grassy plains called savannahs, not in jungles.","o":["Tiger","Gorilla","Elephant","Lion"],"s":{"index":3}},{"k":"choice","i":"What is the fastest animal on land?","t":"Amazing animals","e":"\ud83d\udc06","f":"A cheetah can sprint at around 100 km/h, as fast as a car on a motorway, but only for short bursts.","o":["Cheetah","Horse","Rabbit","Lion"],"s":{"index":0}},{"k":"truefalse","i":"Penguins can fly.","t":"Birds","e":"\ud83d\udc27","f":"Penguins can't fly, but they are super swimmers and use their wings like flippers.","a":false},{"k":"multi","i":"Select all the animals that can fly.","t":"Flying animals","e":"\ud83e\udd87","f":"Bats are the only mammals that can truly fly.","o":["Eagle","Bat","Elephant","Butterfly","Dog"],"s":{"indices":[0,1,3]}},{"k":"multi","i":"Select all the animals that live in the sea.","t":"Sea life","e":"\ud83d\udc19","f":"An octopus has three hearts and blue blood!","o":["Octopus","Camel","Dolphin","Squirrel","Starfish"],"s":{"indices":[0,2,4]}},{"k":"text","i":"What do we call a baby dog?","t":"Baby animals","e":"\ud83d\udc36","f":"Puppies are born with their eyes closed and open them when they are about two weeks old.","s":{"accepted":["Puppy","Pup","Puppies","Pups","A puppy"]}},{"k":"number","i":"How many legs does a spider have?","t":"Bugs","e":"\ud83d\udd77\ufe0f","f":"Spiders have eight legs, so they are not insects: insects have six.","s":{"value":8,"tolerance":0,"min":0,"max":12,"unit":""}},{"k":"order","i":"Put a frog's life cycle in order, starting from the beginning.","t":"Life cycles","e":"\ud83d\udc38","f":"Tadpoles live in water and breathe with gills before they grow legs and turn into frogs.","o":["Egg","Tadpole","Froglet","Frog"]},{"k":"order","i":"Order these animals from smallest to biggest.","t":"Sizes","e":"\ud83d\udc18","f":"A big African elephant can weigh about 6,000 kg, as much as 80 grown-ups!","o":["Ant","Mouse","Cat","Horse","Elephant"]}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> '18396fb181981bd5b96da2defbb9455e' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 12'; end $q$;
do $q$ declare d text := $d$[{"slug":"viva-espana","title":"\u00a1Viva Espa\u00f1a!","tagline":"Flamenco, paella and Gaud\u00ed: a sunny tour of Spain's culture and food.","emoji":"\ud83c\uddea\ud83c\uddf8","gradient":["#dc2626","#d97706"],"categories":["culture","food","travel"],"countries":["ES"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":303,"items":[{"k":"choice","i":"Which architect designed Barcelona's Sagrada Fam\u00edlia?","t":"Architecture","e":"\u26ea","f":"Construction of the Sagrada Fam\u00edlia began in 1882, and Gaud\u00ed devoted over 40 years of his life to it.","o":["Joan Mir\u00f3","Antoni Gaud\u00ed","Santiago Calatrava","Rafael Moneo"],"s":{"index":1}},{"k":"choice","i":"Which famous rice dish comes from Valencia?","t":"Food","e":"\ud83e\udd58","f":"Traditional Valencian paella is made with rabbit, chicken and green beans rather than seafood.","o":["Risotto","Pilaf","Paella","Jambalaya"],"s":{"index":2}},{"k":"choice","i":"What is gazpacho?","t":"Food","e":"\ud83c\udf45","f":"Gazpacho comes from Andalusia in southern Spain and is served chilled on hot summer days.","o":["A sweet pastry","A rice pudding","A cold tomato soup","A grilled sausage"],"s":{"index":2}},{"k":"text","i":"Which Spanish city is home to the Alhambra palace?","t":"Landmarks","e":"\ud83d\udd4c","f":"The Alhambra was built mainly by the Nasrid dynasty in the 13th and 14th centuries.","s":{"accepted":["Granada"]}},{"k":"truefalse","i":"La Tomatina, the famous tomato-throwing festival, takes place in the town of Bu\u00f1ol.","t":"Festivals","e":"\ud83c\udf45","f":"La Tomatina is held on the last Wednesday of August in Bu\u00f1ol, near Valencia.","a":true},{"k":"multi","i":"Select all the languages that have official status in parts of Spain.","t":"Language","e":"\ud83d\udde3\ufe0f","f":"Spanish (Castilian) is official everywhere, while Catalan, Basque and Galician are co-official in their regions.","o":["Catalan","Galician","Basque","Portuguese","Italian"],"s":{"indices":[0,1,2]}},{"k":"choice","i":"Which painter, born in M\u00e1laga, co-founded Cubism?","t":"Art","e":"\ud83c\udfa8","f":"Picasso developed Cubism together with the French painter Georges Braque in the early 1900s.","o":["Pablo Picasso","Diego Vel\u00e1zquez","Salvador Dal\u00ed","Francisco Goya"],"s":{"index":0}},{"k":"number","i":"In what year did Christopher Columbus first reach the Americas on a voyage sponsored by Spain?","t":"History","e":"\u26f5","f":"Columbus's voyage was funded by Queen Isabella I and King Ferdinand II.","s":{"value":1492,"tolerance":0,"min":1400,"max":1600,"unit":""}},{"k":"choice","i":"What is the name of Madrid's world-famous art museum, home to works by Vel\u00e1zquez and Goya?","t":"Art","e":"\ud83d\uddbc\ufe0f","f":"The Museo del Prado opened in 1819 and houses Vel\u00e1zquez's masterpiece 'Las Meninas'.","o":["The Uffizi","The Louvre","The Prado","The Hermitage"],"s":{"index":2}},{"k":"order","i":"Order these Spanish cities from north to south.","t":"Cities","e":"\ud83e\udded","f":"Bilbao's Guggenheim Museum, designed by Frank Gehry, opened in 1997 and is clad in titanium.","o":["Bilbao","Madrid","Valencia","Seville"]},{"k":"choice","i":"Which Andalusian art form is known for passionate singing, guitar and rhythmic footwork?","t":"Music","e":"\ud83d\udc83","f":"Flamenco was added to UNESCO's list of Intangible Cultural Heritage in 2010.","o":["Tango","Samba","Fado","Flamenco"],"s":{"index":3}},{"k":"truefalse","i":"The Canary Islands are located in the Mediterranean Sea.","t":"Geography","e":"\ud83c\udfdd\ufe0f","f":"The Canary Islands lie in the Atlantic Ocean off north-west Africa; the Balearic Islands are Spain's Mediterranean group.","a":false},{"k":"order","i":"Order these Spanish painters by birth year, from earliest to latest.","t":"Art","e":"\ud83d\udd8c\ufe0f","f":"Salvador Dal\u00ed, born in Figueres in 1904, is famous for the melting clocks of 'The Persistence of Memory'.","o":["Diego Vel\u00e1zquez","Francisco Goya","Pablo Picasso","Salvador Dal\u00ed"]},{"k":"choice","i":"What is the highest mountain in Spain?","t":"Mountains","e":"\ud83c\udf0b","f":"Mount Teide, a volcano on Tenerife in the Canary Islands, rises over 3,700 m; Mulhac\u00e9n is the mainland's highest.","o":["Veleta","Aneto","Teide","Mulhac\u00e9n"],"s":{"index":2}}]},{"slug":"medical-milestones","title":"Medical Milestones","tagline":"Vaccines, X-rays and penicillin: the breakthroughs that changed medicine.","emoji":"\ud83d\udc89","gradient":["#0891b2","#4338ca"],"categories":["health","history","science"],"countries":null,"difficulty":"Hard","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":304,"items":[{"k":"choice","i":"Which scientist discovered penicillin after noticing mould killing bacteria in a dish?","t":"Medicines","e":"\ud83e\uddeb","f":"Penicillin became the first widely used antibiotic in the 1940s.","o":["Louis Pasteur","Joseph Lister","Robert Koch","Alexander Fleming"],"s":{"index":3}},{"k":"number","i":"In what year was penicillin discovered?","t":"Medicines","e":"\ud83d\udc8a","f":"The mould that produced penicillin had landed on a dish left out while its discoverer was on holiday.","s":{"value":1928,"tolerance":0,"min":1850,"max":1980,"unit":""}},{"k":"choice","i":"Edward Jenner developed the first vaccine in 1796. Which disease did it protect against?","t":"Vaccines","e":"\ud83d\udc89","f":"Jenner used material from cowpox; the word 'vaccine' comes from 'vacca', Latin for cow.","o":["Polio","Measles","Smallpox","Tuberculosis"],"s":{"index":2}},{"k":"text","i":"Which French scientist gave his name to the process of heating milk to kill germs?","t":"Microbiology","e":"\ud83e\udd5b","f":"Louis Pasteur also developed early vaccines against rabies and anthrax.","s":{"accepted":["Louis Pasteur","Pasteur"]}},{"k":"number","i":"In what year did Wilhelm R\u00f6ntgen discover X-rays?","t":"Imaging","e":"\ud83e\ude7b","f":"One of R\u00f6ntgen's first X-ray images showed the bones of his wife's hand, complete with her ring.","s":{"value":1895,"tolerance":0,"min":1800,"max":1950,"unit":""}},{"k":"truefalse","i":"Smallpox was the first human disease to be eradicated worldwide.","t":"Vaccines","e":"\ud83c\udf0d","f":"The World Health Organization declared smallpox eradicated in 1980.","a":true},{"k":"order","i":"Order these medical breakthroughs from earliest to latest.","t":"Timeline","e":"\ud83d\udcc5","f":"The first human heart transplant was performed by Christiaan Barnard in Cape Town, South Africa, in 1967.","o":["First smallpox vaccine","Discovery of X-rays","Discovery of penicillin","DNA double helix described","First human heart transplant"]},{"k":"choice","i":"What does a stethoscope help a doctor do?","t":"Tools","e":"\ud83e\ude7a","f":"Ren\u00e9 Laennec invented the stethoscope in 1816; his first version was a rolled-up tube of paper.","o":["Measure body temperature","Listen to sounds inside the body","See inside bones","Measure blood sugar"],"s":{"index":1}},{"k":"multi","i":"Select all the diseases caused by viruses.","t":"Diseases","e":"\ud83e\udda0","f":"Antibiotics work against bacteria but not viruses, which is why they don't cure colds or flu.","o":["Influenza","Tuberculosis","Measles","Strep throat","Chickenpox"],"s":{"indices":[0,2,4]}},{"k":"choice","i":"Which hormone, first used to treat diabetes in 1922, controls blood sugar levels?","t":"Hormones","e":"\ud83e\ude78","f":"Insulin was discovered at the University of Toronto in 1921 by Frederick Banting and Charles Best.","o":["Insulin","Adrenaline","Cortisol","Melatonin"],"s":{"index":0}},{"k":"truefalse","i":"Florence Nightingale is known as a founder of modern nursing.","t":"Nursing","e":"\ud83c\udfee","f":"She became known as 'The Lady with the Lamp' for her night-time rounds caring for patients.","a":true},{"k":"choice","i":"Which British surgeon pioneered antiseptic surgery in the 1860s?","t":"Surgery","e":"\ud83e\uddfc","f":"The mouthwash Listerine was named in Joseph Lister's honour.","o":["John Snow","Joseph Lister","William Harvey","Edward Jenner"],"s":{"index":1}},{"k":"choice","i":"What did Karl Landsteiner discover in 1901 that made blood transfusions much safer?","t":"Blood","e":"\ud83c\udd70\ufe0f","f":"Landsteiner won the 1930 Nobel Prize in Physiology or Medicine for discovering human blood groups.","o":["White blood cells","Vitamins","Blood groups (A, B, O)","Antibiotics"],"s":{"index":2}}]},{"slug":"roman-numeral-rumble","title":"Roman Numeral Rumble","tagline":"I, V, X, L, C, D, M: can you count like a Roman?","emoji":"\ud83c\udfdb\ufe0f","gradient":["#b91c1c","#a16207"],"categories":["puzzles","math","history"],"countries":null,"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":305,"items":[{"k":"number","i":"What is XIV in ordinary numbers?","t":"Reading numerals","e":"\ud83d\udd1f","f":"X = 10 and IV = 4, because I before V means 5 \u2212 1.","s":{"value":14,"tolerance":0,"min":1,"max":50,"unit":""}},{"k":"number","i":"What number does the Roman numeral XL represent?","t":"Reading numerals","e":"\ud83e\uddf1","f":"X before L means 50 \u2212 10 = 40.","s":{"value":40,"tolerance":0,"min":1,"max":100,"unit":""}},{"k":"number","i":"What year is MCMLXXXIX?","t":"Years","e":"\ud83d\udcc6","f":"M = 1000, CM = 900, LXXX = 80 and IX = 9, giving 1989.","s":{"value":1989,"tolerance":0,"min":1900,"max":2000,"unit":""}},{"k":"text","i":"Write the number 9 in Roman numerals.","t":"Writing numerals","e":"\u270d\ufe0f","f":"A smaller numeral before a larger one means subtract: I before X is 10 \u2212 1.","s":{"accepted":["IX"]}},{"k":"text","i":"Write the year 2024 in Roman numerals.","t":"Writing numerals","e":"\ud83d\uddd3\ufe0f","f":"MM = 2000, XX = 20 and IV = 4.","s":{"accepted":["MMXXIV"]}},{"k":"choice","i":"Which Roman numeral stands for 500?","t":"Symbols","e":"\ud83d\udd23","f":"The seven symbols are I (1), V (5), X (10), L (50), C (100), D (500) and M (1000).","o":["C","L","D","M"],"s":{"index":2}},{"k":"choice","i":"Which of these Roman numerals is the largest?","t":"Comparing","e":"\u2696\ufe0f","f":"XC = 90, LXXX = 80, LXIX = 69 and XLIX = 49.","o":["LXXX","XLIX","XC","LXIX"],"s":{"index":2}},{"k":"truefalse","i":"Roman numerals include a symbol for zero.","t":"History","e":"0\ufe0f\u20e3","f":"Classical Roman numerals had no zero; medieval scholars sometimes wrote N, for 'nulla' (nothing).","a":false},{"k":"order","i":"Order these Roman numerals from smallest to largest.","t":"Comparing","e":"\ud83d\udcf6","f":"19, 21, 45, 54 and 99.","o":["XIX","XXI","XLV","LIV","XCIX"]},{"k":"multi","i":"Select all the Roman numerals that are even numbers.","t":"Reading numerals","e":"\ud83c\udfaf","f":"XVI = 16, XXXVIII = 38 and LXXIV = 74 are even; XXV = 25 and XIII = 13 are odd.","o":["XVI","XIII","XXV","XXXVIII","LXXIV"],"s":{"indices":[0,3,4]}},{"k":"number","i":"What is CDXLIV in ordinary numbers?","t":"Reading numerals","e":"\ud83e\udde0","f":"CD = 400, XL = 40 and IV = 4: three subtractions in one numeral.","s":{"value":444,"tolerance":0,"min":100,"max":1000,"unit":""}},{"k":"choice","i":"The NFL dropped Roman numerals only once, for Super Bowl 50. What numeral would it have been?","t":"Pop culture","e":"\ud83c\udfc8","f":"Organisers felt a lone 'L' looked awkward, so they used '50' and then went back to Roman numerals with LI.","o":["C","D","L","XL"],"s":{"index":2}},{"k":"text","i":"Clock faces with Roman numerals often show 4 o'clock not as IV but as\u2026","t":"Clocks","e":"\ud83d\udd53","f":"This tradition, sometimes called the 'clockmaker's four', is often said to balance the look of VIII opposite.","s":{"accepted":["IIII"]}},{"k":"number","i":"How many different letters are used in standard Roman numerals?","t":"Symbols","e":"\ud83d\udd24","f":"I, V, X, L, C, D and M are enough to write every number from 1 to 3,999 in standard form.","s":{"value":7,"tolerance":0,"min":1,"max":15,"unit":"letters"}}]},{"slug":"isms-of-art","title":"Isms of Art","tagline":"Impressionism, Cubism, Pop Art: sort out the movements that shaped art.","emoji":"\ud83c\udfa8","gradient":["#c026d3","#0891b2"],"categories":["art","history"],"countries":null,"difficulty":"Hard","minutes":5,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":306,"items":[{"k":"choice","i":"Which art movement takes its name from Claude Monet's painting 'Impression, Sunrise'?","t":"Movements","e":"\ud83c\udf05","f":"Impressionists often painted outdoors to capture changing light and weather.","o":["Expressionism","Impressionism","Fauvism","Realism"],"s":{"index":1}},{"k":"choice","i":"Salvador Dal\u00ed and Ren\u00e9 Magritte were leading figures of which movement?","t":"Movements","e":"\ud83d\udc18","f":"Surrealist artists drew inspiration from dreams and the unconscious mind.","o":["Cubism","Dada","Surrealism","Futurism"],"s":{"index":2}},{"k":"choice","i":"Andy Warhol was a leading figure of which movement?","t":"Movements","e":"\ud83e\udd6b","f":"His 'Campbell's Soup Cans' (1962) is made up of 32 canvases, one for each soup flavour.","o":["Pop Art","Minimalism","Abstract Expressionism","Op Art"],"s":{"index":0}},{"k":"choice","i":"Gothic cathedrals such as Notre-Dame de Paris are famous for pointed arches and which external supports?","t":"Architecture","e":"\ud83c\udff0","f":"Flying buttresses carry the weight of the roof outward, allowing taller walls and huge stained-glass windows.","o":["Geodesic domes","Cantilevers","Flying buttresses","Ionic columns"],"s":{"index":2}},{"k":"choice","i":"In which country did the Renaissance begin?","t":"Movements","e":"\ud83c\uddee\ud83c\uddf9","f":"Florence is often seen as the birthplace of the Renaissance in the 14th and 15th centuries.","o":["France","Italy","Spain","Netherlands"],"s":{"index":1}},{"k":"choice","i":"Which movement, led by Henri Matisse, was known for bold, unnatural colours?","t":"Movements","e":"\ud83e\udd81","f":"'Les Fauves' means 'the wild beasts' in French, a name given by a shocked critic.","o":["Cubism","Dada","Baroque","Fauvism"],"s":{"index":3}},{"k":"choice","i":"Which avant-garde 'anti-art' movement began in Zurich in 1916?","t":"Movements","e":"\ud83c\udfaa","f":"Dada began at the Cabaret Voltaire, a Zurich nightclub where artists staged playful performances.","o":["Dada","Futurism","Bauhaus","Romanticism"],"s":{"index":0}},{"k":"choice","i":"In which country was the Bauhaus school of art and design founded?","t":"Design","e":"\ud83d\udcd0","f":"Architect Walter Gropius founded the Bauhaus in Weimar in 1919.","o":["Austria","Germany","Netherlands","Switzerland"],"s":{"index":1}},{"k":"number","i":"In what year was the first Impressionist exhibition held in Paris?","t":"Impressionism","e":"\ud83d\udd8c\ufe0f","f":"A critic mocked the show by calling the artists 'Impressionists', and the name stuck.","s":{"value":1874,"tolerance":0,"min":1800,"max":1950,"unit":""}},{"k":"truefalse","i":"Jackson Pollock is famous for his 'drip' paintings.","t":"Movements","e":"\ud83d\udca7","f":"Pollock laid canvases on the floor and dripped or poured paint onto them; he was a key Abstract Expressionist.","a":true},{"k":"truefalse","i":"Art Nouveau came after Art Deco.","t":"Design","e":"\ud83c\udfd9\ufe0f","f":"Art Nouveau flourished around 1890\u20131910; Art Deco followed in the 1920s and 30s, as seen in New York's Chrysler Building.","a":false},{"k":"text","i":"Which movement, founded by Pablo Picasso and Georges Braque, broke subjects into geometric shapes?","t":"Movements","e":"\ud83d\udd37","f":"Cubist paintings often show an object from several viewpoints at once.","s":{"accepted":["Cubism","Cubist"]}},{"k":"multi","i":"Select all the Impressionist painters.","t":"Impressionism","e":"\ud83c\udfa8","f":"Degas is famous for his paintings and sculptures of ballet dancers.","o":["Claude Monet","Andy Warhol","Edgar Degas","Salvador Dal\u00ed","Pierre-Auguste Renoir"],"s":{"indices":[0,2,4]}},{"k":"order","i":"Order these art movements from earliest to latest.","t":"Timeline","e":"\ud83d\udcdc","f":"Roughly: Renaissance 1400s\u20131500s, Baroque 1600s, Impressionism 1870s, Cubism 1900s\u20131910s and Pop Art 1950s\u201360s.","o":["Renaissance","Baroque","Impressionism","Cubism","Pop Art"]}]},{"slug":"rainbows-shapes-stories","title":"Rainbows, Shapes & Stories","tagline":"Colours, corners and fairy tales: a gentle quiz for little learners.","emoji":"\ud83c\udf08","gradient":["#db2777","#7c3aed"],"categories":["kids","literature","math"],"countries":null,"difficulty":"Easy","minutes":3,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":307,"items":[{"k":"choice","i":"What colour do you get when you mix blue and yellow paint?","t":"Colours","e":"\ud83c\udfa8","f":"Blue and yellow make green, just like the colour of grass and leaves!","o":["Purple","Green","Orange","Brown"],"s":{"index":1}},{"k":"choice","i":"In 'Cinderella', what does Cinderella leave behind at the ball?","t":"Fairy tales","e":"\ud83d\udc60","f":"The prince searches the whole kingdom to find whose foot fits the slipper.","o":["A glove","A crown","A glass slipper","A necklace"],"s":{"index":2}},{"k":"choice","i":"Which fairy tale is about a girl who visits the house of three bears?","t":"Fairy tales","e":"\ud83d\udc3b","f":"Goldilocks tries three bowls of porridge: too hot, too cold, and just right!","o":["Goldilocks and the Three Bears","Snow White","Rapunzel","Hansel and Gretel"],"s":{"index":0}},{"k":"choice","i":"In 'Jack and the Beanstalk', what does Jack swap the family cow for?","t":"Fairy tales","e":"\ud83c\udf31","f":"The magic beans grow into a giant beanstalk that reaches all the way up into the clouds.","o":["Gold coins","Magic beans","A goose","A sword"],"s":{"index":1}},{"k":"choice","i":"Which shape has no corners at all?","t":"Shapes","e":"\u26aa","f":"A circle is perfectly round, like a coin, a plate or the full Moon.","o":["Square","Triangle","Rectangle","Circle"],"s":{"index":3}},{"k":"choice","i":"In 'The Three Little Pigs', which house can the wolf NOT blow down?","t":"Fairy tales","e":"\ud83d\udc37","f":"The third little pig worked hard to build a strong brick house.","o":["Straw","Sticks","Bricks","Leaves"],"s":{"index":2}},{"k":"truefalse","i":"Snow White makes friends with seven dwarfs.","t":"Fairy tales","e":"\ud83c\udf4e","f":"In Disney's 1937 film, the dwarfs have names like Happy, Sleepy and Grumpy.","a":true},{"k":"truefalse","i":"A square has five sides.","t":"Shapes","e":"\ud83d\udfe6","f":"A square has four equal sides and four corners.","a":false},{"k":"multi","i":"Select all the colours you can see in a rainbow.","t":"Colours","e":"\ud83c\udf08","f":"A rainbow appears when sunlight shines through raindrops and splits into different colours.","o":["Red","Black","Green","Violet","Brown"],"s":{"indices":[0,2,3]}},{"k":"text","i":"In the story of Pinocchio, what part of his body grows when he tells a lie?","t":"Stories","e":"\ud83e\udd25","f":"Pinocchio is a wooden puppet carved by Geppetto, and he dreams of becoming a real boy.","s":{"accepted":["Nose","His nose","The nose"]}},{"k":"number","i":"How many sides does an octagon have?","t":"Shapes","e":"\ud83d\uded1","f":"Many stop signs around the world are octagons, shapes with eight sides.","s":{"value":8,"tolerance":0,"min":3,"max":12,"unit":""}},{"k":"order","i":"Order these shapes from the fewest sides to the most sides.","t":"Shapes","e":"\ud83d\udd37","f":"Bees build the cells of their honeycomb in the shape of hexagons, which have six sides.","o":["Triangle","Square","Pentagon","Hexagon"]},{"k":"order","i":"Put these rainbow colours in order, starting from the top (outside) of the rainbow.","t":"Colours","e":"\ud83c\udf08","f":"Remember the rainbow's order with the name 'Roy G. Biv': red, orange, yellow, green, blue, indigo, violet.","o":["Red","Orange","Yellow","Green","Blue"]}]},{"slug":"portugal-unwrapped","title":"Portugal Unwrapped","tagline":"Explorers, tiles and custard tarts: how well do you know Portugal?","emoji":"\ud83c\uddf5\ud83c\uddf9","gradient":["#15803d","#b91c1c"],"categories":["travel","history","food"],"countries":["PT"],"difficulty":"Medium","minutes":4,"questions":10,"prompt":"True or false?","yes_label":"True","no_label":"False","sort":308,"items":[{"k":"choice","i":"What is the capital of Portugal?","t":"Cities","e":"\ud83c\udf09","f":"Lisbon's red 25 de Abril Bridge looks strikingly similar to San Francisco's Golden Gate Bridge.","o":["Coimbra","Porto","Lisbon","Faro"],"s":{"index":2}},{"k":"choice","i":"What are past\u00e9is de nata?","t":"Food","e":"\ud83e\udd67","f":"Past\u00e9is de nata were first made by monks at the Jer\u00f3nimos Monastery in Lisbon's Bel\u00e9m district.","o":["Grilled sardines","Sweet bread rolls","Custard tarts","Salted cod fritters"],"s":{"index":2}},{"k":"choice","i":"Which Portuguese explorer was the first European to reach India by sea?","t":"Explorers","e":"\ud83e\udded","f":"Vasco da Gama reached Calicut, India, in 1498 after sailing around Africa's Cape of Good Hope.","o":["Bartolomeu Dias","Ferdinand Magellan","Vasco da Gama","Pedro \u00c1lvares Cabral"],"s":{"index":2}},{"k":"text","i":"Which city on the Douro River is Portugal's second-largest?","t":"Cities","e":"\ud83c\udfd8\ufe0f","f":"Porto's historic Ribeira district on the Douro River is part of a UNESCO World Heritage Site.","s":{"accepted":["Porto","Oporto"]}},{"k":"choice","i":"What are azulejos, seen on many Portuguese buildings?","t":"Art","e":"\ud83d\udfe6","f":"The word azulejo comes from the Arabic for 'small polished stone', not from 'azul' (blue).","o":["Painted ceramic tiles","Wooden balconies","Iron lanterns","Stone fountains"],"s":{"index":0}},{"k":"truefalse","i":"Portugal is the westernmost country of mainland Europe.","t":"Geography","e":"\ud83c\udf05","f":"Cabo da Roca, near Lisbon, is the westernmost point of mainland Europe.","a":true},{"k":"choice","i":"Which soulful style of Portuguese music is closely associated with Lisbon?","t":"Music","e":"\ud83c\udfb6","f":"Am\u00e1lia Rodrigues, known as the 'Queen of Fado', made the genre famous around the world.","o":["Bossa nova","Fado","Morna","Flamenco"],"s":{"index":1}},{"k":"multi","i":"Select all the island groups that belong to Portugal.","t":"Islands","e":"\ud83c\udfdd\ufe0f","f":"The Azores and Madeira are autonomous regions of Portugal in the Atlantic Ocean.","o":["Azores","Cape Verde","Madeira","Canary Islands","Balearic Islands"],"s":{"indices":[0,2]}},{"k":"number","i":"In what year did Lisbon host the world's fair known as Expo '98?","t":"Modern history","e":"\ud83c\udf10","f":"Lisbon's Vasco da Gama Bridge, one of the longest in Europe, opened in 1998 just in time for the Expo.","s":{"value":1998,"tolerance":0,"min":1950,"max":2020,"unit":""}},{"k":"choice","i":"Which dried, salted fish is said to have a Portuguese recipe for every day of the year?","t":"Food","e":"\ud83d\udc1f","f":"Portuguese cooks often say there are 365 ways to cook bacalhau, though some claim over a thousand.","o":["Tuna","Mackerel","Bacalhau (salt cod)","Sardines"],"s":{"index":2}},{"k":"order","i":"Order these Portuguese cities from north to south.","t":"Cities","e":"\ud83e\udded","f":"Faro is the capital of the Algarve, Portugal's sunny southern coast famous for its cliffs and beaches.","o":["Braga","Porto","Coimbra","Lisbon","Faro"]},{"k":"choice","i":"Which Portuguese navigator led the first expedition to sail around the world, which was completed after his death?","t":"Explorers","e":"\ud83c\udf0d","f":"Magellan died in the Philippines in 1521; Juan Sebasti\u00e1n Elcano completed the voyage in 1522.","o":["Henry the Navigator","Bartolomeu Dias","Ferdinand Magellan","Vasco da Gama"],"s":{"index":2}},{"k":"truefalse","i":"Portugal produces about half of the world's cork.","t":"Nature","e":"\ud83c\udf33","f":"Cork is stripped from cork oak trees without cutting them down, and the bark grows back.","a":true},{"k":"text","i":"Which language is spoken in Brazil because of its history with Portugal?","t":"Language","e":"\ud83c\udde7\ud83c\uddf7","f":"Brazil has far more Portuguese speakers than Portugal itself.","s":{"accepted":["Portuguese"]}}]}]$d$; j jsonb; g jsonb; it jsonb; k text; begin if md5(d) <> 'f9a57a5ba01c00ca30149deed2ab9bc3' then raise exception 'BAD_HASH'; end if; j := d::jsonb; for g in select * from jsonb_array_elements(j) loop insert into public.games (slug, title, tagline, emoji, gradient, categories, countries, status, difficulty, minutes, questions, prompt, yes_label, no_label, sort) values (g->>'slug', g->>'title', g->>'tagline', g->>'emoji', array(select jsonb_array_elements_text(g->'gradient')), array(select jsonb_array_elements_text(g->'categories')), case when jsonb_typeof(g->'countries') = 'array' then array(select jsonb_array_elements_text(g->'countries')) end, 'live', g->>'difficulty', (g->>'minutes')::int, (g->>'questions')::int, g->>'prompt', g->>'yes_label', g->>'no_label', (g->>'sort')::int) on conflict (slug) do update set title = excluded.title, tagline = excluded.tagline, emoji = excluded.emoji, gradient = excluded.gradient, categories = excluded.categories, countries = excluded.countries, status = 'live', difficulty = excluded.difficulty, minutes = excluded.minutes, questions = excluded.questions, prompt = excluded.prompt, yes_label = excluded.yes_label, no_label = excluded.no_label, sort = excluded.sort, updated_at = now(); for it in select * from jsonb_array_elements(g->'items') loop k := it->>'k'; insert into public.quiz_questions (game_slug, item, qtype, emoji, kind, answer, options, solution, fact, active) values (g->>'slug', it->>'i', it->>'t', nullif(it->>'e', ''), k, case when k = 'truefalse' then (it->>'a')::boolean end, case when k in ('choice', 'multi', 'order') then it->'o' end, case when k in ('choice', 'multi', 'text', 'number') then it->'s' end, it->>'f', true) on conflict (game_slug, item) do update set qtype = excluded.qtype, emoji = excluded.emoji, kind = excluded.kind, answer = excluded.answer, options = excluded.options, solution = excluded.solution, fact = excluded.fact, active = true; end loop; end loop; raise notice 'CHUNK_OK 13'; end $q$;
